(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-war-1-e", [{"sp": "HDR", "t": "Ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους"}, {"sp": "HDR", "t": "Βιβλίον Αʹ", "st": "1"}, {"sp": "N", "t": "Ἐπειδὴ τὸν Ἰουδαίων πρὸς Ῥωμαίους πόλεμον συστάντα μέγιστον οὐ μόνον τῶν καθ’ ἡμᾶς, σχεδὸν δὲ καὶ ὧν ἀκοῇ παρειλήφαμεν ἢ πόλεων πρὸς πόλεις ἢ ἐθνῶν ἔθνεσι συρραγέντων, οἱ μὲν οὐ παρατυχόντες τοῖς πράγμασιν, ἀλλ’ ἀκοῇ συλλέγοντες εἰκαῖα καὶ ἀσύμφωνα διηγήματα σοφιστικῶς ἀναγράφουσιν, οἱ παραγενόμενοι δὲ ἢ κολακείᾳ τῇ πρὸς Ῥωμαίους ἢ μίσει τῷ πρὸς Ἰουδαίους καταψεύδονται τῶν πραγμάτων, περιέχει δὲ αὐτοῖς ὅπου μὲν κατηγορίαν ὅπου δὲ ἐγκώμιον τὰ συγγράμματα, τὸ δ’ ἀκριβὲς τῆς ἱστορίας οὐδαμοῦ, προυθέμην ἐγὼ τοῖς κατὰ τὴν Ῥωμαίων ἡγεμονίαν Ἑλλάδι γλώσσῃ μεταβαλὼν ἃ τοῖς ἄνω βαρβάροις τῇ πατρίῳ συντάξας ἀνέπεμψα πρότερον ἀφηγήσασθαι Ἰώσηπος Ματθίου παῖς ἐξ Ἱεροσολύμων ἱερεύς, αὐτός τε Ῥωμαίους πολεμήσας τὰ πρῶτα καὶ τοῖς ὕστερον παρατυχὼν ἐξ ἀνάγκης·", "st": "1.pr.1"}, {"sp": "N", "t": "γενομένου γάρ, ὡς ἔφην, μεγίστου τοῦδε τοῦ κινήματος ἐν Ῥωμαίοις μὲν ἐνόσει τὰ οἰκεῖα, Ἰουδαίων δὲ τὸ νεωτερίζον τότε τεταραγμένοις ἐπανέστη τοῖς καιροῖς ἀκμάζον κατά τε χεῖρα καὶ χρήμασιν, ὡς δι’ ὑπερβολὴν θορύβων τοῖς μὲν ἐν ἐλπίδι κτήσεως τοῖς δ’ ἐν ἀφαιρέσεως δέει γίνεσθαι τὰ πρὸς τὴν ἀνατολήν, ἐπειδὴ Ἰουδαῖοι μὲν ἅπαν τὸ ὑπὲρ Εὐφράτην ὁμόφυλον συνεπαρθήσεσθαι σφίσιν ἤλπισαν, Ῥωμαίους δὲ οἵ τε γείτονες Γαλάται παρεκίνουν καὶ τὸ Κελτικὸν οὐκ ἠρέμει, μεστὰ δ’ ἦν πάντα θορύβων μετὰ Νέρωνα, καὶ πολλοὺς μὲν βασιλειᾶν ὁ καιρὸς ἀνέπειθεν, τὰ στρατιωτικὰ δὲ ἤρα μεταβολῆς ἐλπίδι λημμάτων· ἄτοπον ἡγησάμενος περιιδεῖν πλαζομένην ἐπὶ τηλικούτοις πράγμασι τὴν ἀλήθειαν, καὶ Πάρθους μὲν καὶ Βαβυλωνίους Ἀράβων τε τοὺς πορρωτάτω καὶ τὸ ὑπὲρ Εὐφράτην ὁμόφυλον ἡμῖν Ἀδιαβηνούς τε γνῶναι διὰ τῆς ἐμῆς ἐπιμελείας ἀκριβῶς, ὅθεν τε ἤρξατο καὶ δι’ ὅσων ἐχώρησεν παθῶν ὁ πόλεμος καὶ ὅπως κατέστρεψεν, ἀγνοεῖν δὲ Ἕλληνας ταῦτα καὶ Ῥωμαίων τοὺς μὴ ἐπιστρατευσαμένους, ἐντυγχάνοντας ἢ κολακείαις ἢ πλάσμασι.", "st": "1.pr.2"}, {"sp": "N", "t": "Καίτοι γε ἱστορίας αὐτὰς ἐπιγράφειν τολμῶσιν, ἐν αἷς πρὸς τῷ μηδὲν ὑγιὲς δηλοῦν καὶ τοῦ σκοποῦ δοκοῦσιν ἔμοιγε διαμαρτάνειν. βούλονται μὲν γὰρ μεγάλους τοὺς Ῥωμαίους ἀποδεικνύειν, καταβάλλουσιν δὲ ἀεὶ τὰ Ἰουδαίων καὶ ταπεινοῦσιν· οὐχ ὁρῶ δέ, πῶς ἂν εἶναι μεγάλοι δοκοῖεν οἱ μικροὺς νενικηκότες· καὶ οὔτε τὸ μῆκος αἰδοῦνται τοῦ πολέμου οὔτε τὸ πλῆθος τῆς Ῥωμαίων καμούσης στρατιᾶς οὔτε τὸ μέγεθος τῶν στρατηγῶν, οἳ πολλὰ περὶ τοῖς Ἱεροσολύμοις ἱδρώσαντες οἶμαι ταπεινουμένου τοῦ κατορθώματος αὐτοῖς ἀδοξοῦσιν.", "st": "1.pr.3"}, {"sp": "N", "t": "Οὐ μὴν ἐγὼ τοῖς ἐπαίρουσι τὰ Ῥωμαίων ἀντιφιλονεικῶν αὔξειν τὰ τῶν ὁμοφύλων διέγνων, ἀλλὰ τὰ μὲν ἔργα μετ’ ἀκριβείας ἀμφοτέρων διέξειμι, τοὺς δ’ ἐπὶ τοῖς πράγμασι λόγους ἀνατίθημι τῇ διαθέσει καὶ τοῖς ἐμαυτοῦ πάθεσι διδοὺς ἐπολοφύρεσθαι ταῖς τῆς πατρίδος συμφοραῖς. ὅτι γὰρ αὐτὴν στάσις οἰκεία καθεῖλεν, καὶ τὰς Ῥωμαίων χεῖρας ἀκούσας καὶ τὸ πῦρ ἐπὶ τὸν ναὸν εἵλκυσαν οἱ Ἰουδαίων τύραννοι, μάρτυς αὐτὸς ὁ πορθήσας Καῖσαρ Τίτος, ἐν παντὶ τῷ πολέμῳ τὸν μὲν δῆμον ἐλεήσας ὑπὸ τῶν στασιαστῶν φρουρούμενον, πολλάκις δὲ ἑκὼν τὴν ἅλωσιν τῆς πόλεως ὑπερτιθέμενος καὶ διδοὺς τῇ πολιορκίᾳ χρόνον εἰς μετάνοιαν τῶν αἰτίων. εἰ δή τις ὅσα πρὸς τοὺς τυράννους ἢ τὸ λῃστρικὸν αὐτῶν κατηγορικῶς λέγοιμεν ἢ τοῖς δυστυχήμασι τῆς πατρίδος ἐπιστένοντες συκοφαντοίη, διδότω παρὰ τὸν τῆς ἱστορίας νόμον συγγνώμην τῷ πάθει· πόλιν μὲν γὰρ δὴ τῶν ὑπὸ Ῥωμαίοις πασῶν τὴν ἡμετέραν ἐπὶ πλεῖστόν τε εὐδαιμονίας συνέβη προελθεῖν καὶ πρὸς ἔσχατον συμφορῶν αὖθις καταπεσεῖν· τὰ γοῦν πάντων ἀπ’ αἰῶνος ἀτυχήματα πρὸς τὰ Ἰουδαίων ἡττῆσθαι δοκῶ κατὰ σύγκρισιν· καὶ τούτων αἴτιος οὐδεὶς ἀλλόφυλος, ὥστε ἀμήχανον ἦν ὀδυρμῶν ἐπικρατεῖν. εἰ δέ τις οἴκτου σκληρότερος εἴη δικαστής, τὰ μὲν πράγματα τῇ ἱστορίᾳ προσκρινέτω, τὰς δ’ ὀλοφύρσεις τῷ γράφοντι.", "st": "1.pr.4"}, {"sp": "N", "t": "Καίτοι γε ἐπιτιμήσαιμ’ ἂν αὐτὸς δικαίως τοῖς Ἑλλήνων λογίοις, οἳ τηλικούτων κατ’ αὐτοὺς πραγμάτων γεγενημένων, ἃ κατὰ σύγκρισιν ἐλαχίστους ἀποδείκνυσι τοὺς πάλαι πολέμους, τούτων μὲν κάθηνται κριταὶ τοῖς φιλοτιμουμένοις ἐπηρεάζοντες, ὧν εἰ καὶ τῷ λόγῳ πλεονεκτοῦσι, λείπονται τῇ προαιρέσει· αὐτοὶ δὲ τὰ Ἀσσυρίων καὶ Μήδων συγγράφουσιν ὥσπερ ἧττον καλῶς ὑπὸ τῶν ἀρχαίων συγγραφέων ἀπηγγελμένα. καίτοι τοσούτῳ τῆς ἐκείνων ἡττῶνται δυνάμεως ἐν τῷ γράφειν, ὅσῳ καὶ τῆς γνώμης· τὰ γὰρ κατ’ αὐτοὺς ἐσπούδαζον ἕκαστοι γράφειν, ὅπου καὶ τὸ παρατυχεῖν τοῖς πράγμασιν ἐποίει τὴν ἀπαγγελίαν ἐναργῆ καὶ τὸ ψεύδεσθαι παρ’ εἰδόσιν αἰσχρὸν ἦν. τό γε μὴν μνήμῃ τὰ προϊστορηθέντα διδόναι καὶ τὰ τῶν ἰδίων χρόνων τοῖς μετ’ αὐτὸν συνιστάνειν ἐπαίνου καὶ μαρτυρίας ἄξιον· φιλόπονος δὲ οὐχ ὁ μεταποιῶν οἰκονομίαν καὶ τάξιν ἀλλοτρίαν, ἀλλ’ ὁ μετὰ τοῦ καινὰ λέγειν καὶ τὸ σῶμα τῆς ἱστορίας κατασκευάζων ἴδιον. κἀγὼ μὲν ἀναλώμασι καὶ πόνοις μεγίστοις ἀλλόφυλος ὢν Ἕλλησί τε καὶ Ῥωμαίοις τὴν μνήμην τῶν κατορθωμάτων ἀνατίθημι· τοῖς δὲ γνησίοις πρὸς μὲν τὰ λήμματα καὶ τὰς δίκας κέχηνεν εὐθέως τὸ στόμα καὶ γλῶσσα λέλυται, πρὸς δὲ τὴν ἱστορίαν, ἔνθα χρὴ τἀληθῆ λέγειν καὶ μετὰ πολλοῦ πόνου τὰ πράγματα συλλέγειν, πεφίμωνται παρέντες τοῖς ἀσθενεστέροις καὶ μηδὲ γινώσκουσι τὰς πράξεις τῶν ἡγεμόνων γράφειν. τιμάσθω δὴ παρ’ ἡμῖν τὸ τῆς ἱστορίας ἀληθές, ἐπεὶ παρ’ Ἕλλησιν ἠμέληται.", "st": "1.pr.5"}, {"sp": "N", "t": "Ἀρχαιολογεῖν μὲν δὴ τὰ Ἰουδαίων, τίνες τε ὄντες καὶ ὅπως ἀπανέστησαν Αἰγυπτίων, χώραν τε ὅσην ἐπῆλθον ἀλώμενοι καὶ πόσα ἑξῆς κατέλαβον καὶ ὅπως μετανέστησαν, νῦν τε ἄκαιρον ᾠήθην εἶναι καὶ ἄλλως περιττόν, ἐπειδήπερ καὶ Ἰουδαίων πολλοὶ πρὸ ἐμοῦ τὰ τῶν προγόνων συνετάξαντο μετ’ ἀκριβείας καί τινες Ἑλλήνων ἐκεῖνα τῇ πατρίῳ φωνῇ μεταβαλόντες οὐ πολὺ τῆς ἀληθείας διήμαρτον. ὅπου δ’ οἵ τε τούτων συγγραφεῖς ἐπαύσαντο καὶ οἱ ἡμέτεροι προφῆται, τὴν ἀρχὴν ἐκεῖθεν ποιήσομαι τῆς συντάξεως· τούτων δὲ τὰ μὲν τοῦ κατ’ ἐμαυτὸν πολέμου διεξοδικώτερον καὶ μεθ’ ὅσης ἂν ἐξεργασίας δύνωμαι δίειμι, τὰ δὲ προγενέστερα τῆς ἐμῆς ἡλικίας ἐπιδραμῶ συντόμως,", "st": "1.pr.6"}, {"sp": "N", "t": "ὡς Ἀντίοχος ὁ κληθεὶς Ἐπιφανὴς ἑλὼν κατὰ κράτος Ἱεροσόλυμα καὶ κατασχὼν ἔτεσι τρισὶ καὶ μησὶν ἓξ ὑπὸ τῶν Ἀσαμωναίου παίδων ἐκβάλλεται τῆς χώρας, ἔπειθ’ ὡς οἱ τούτων ἔγγονοι περὶ τῆς βασιλείας διαστασιάσαντες εἵλκυσαν εἰς τὰ πράγματα Ῥωμαίους καὶ Πομπήιον. καὶ ὡς Ἡρώδης ὁ Ἀντιπάτρου κατέλυσε τὴν δυναστείαν αὐτῶν ἐπαγαγὼν Σόσσιον, ὅπως τε ὁ λαὸς μετὰ τὴν Ἡρώδου τελευτὴν κατεστασίασεν Αὐγούστου μὲν Ῥωμαίων ἡγεμονεύοντος, Κυιντιλίου δὲ Οὐάρου κατὰ τὴν χώραν ὄντος, καὶ ὡς ἔτει δωδεκάτῳ τῆς Νέρωνος ἀρχῆς ὁ πόλεμος ἀνερράγη τά τε συμβάντα κατὰ Κέστιον καὶ ὅσα κατὰ τὰς πρώτας ὁρμὰς ἐπῆλθον οἱ Ἰουδαῖοι τοῖς ὅπλοις,", "st": "1.pr.7"}, {"sp": "N", "t": "ὅπως τε τὰς περιοίκους ἐτειχίσαντο, καὶ ὡς Νέρων ἐπὶ τοῖς Κεστίου πταίσμασι δείσας περὶ τῶν ὅλων Οὐεσπασιανὸν ἐφίστησι τῷ πολέμῳ, καὶ ὡς οὗτος μετὰ τοῦ πρεσβυτέρου τῶν παίδων εἰς τὴν Ἰουδαίων χώραν ἐνέβαλεν ὅσῃ τε χρώμενος Ῥωμαίων στρατιᾷ καὶ ὅσοι σύμμαχοι ἐκόπησαν εἰς ὅλην τὴν Γαλιλαίαν, καὶ ὡς τῶν πόλεων αὐτῆς ἃς μὲν ὁλοσχερῶς καὶ κατὰ κράτος ἃς δὲ δι’ ὁμολογίας ἔλαβεν· ἔνθα δὴ καὶ τὰ περὶ τῆς Ῥωμαίων ἐν πολέμοις εὐταξίας καὶ τὴν ἄσκησιν τῶν ταγμάτων, τῆς τε Γαλιλαίας ἑκατέρας τὰ διαστήματα καὶ τὴν φύσιν καὶ τοὺς τῆς Ἰουδαίας ὅρους, ἔτι τε τῆς χώρας τὴν ἰδιότητα, λίμνας τε καὶ πηγὰς τὰς ἐν αὐτῇ, καὶ τὰ περὶ ἑκάστην πόλιν τῶν ἁλισκομένων πάθη μετὰ ἀκριβείας, ὡς εἶδον ἢ ἔπαθον, δίειμι. οὐδὲ γὰρ τῶν ἐμαυτοῦ τι συμφορῶν ἀποκρύψομαι μέλλων γε πρὸς εἰδότας ἐρεῖν.", "st": "1.pr.8"}, {"sp": "N", "t": "Ἔπειθ’ ὡς ἤδη καμνόντων Ἰουδαίοις τῶν πραγμάτων θνήσκει μὲν Νέρων, Οὐεσπασιανὸς δὲ ἐπὶ Ἱεροσολύμων ὡρμημένος ὑπὸ τῆς ἡγεμονίας ἀνθέλκεται· τά τε γενόμενα περὶ ταύτης αὐτῷ σημεῖα καὶ τὰς ἐπὶ Ῥώμης μεταβολάς, καὶ ὡς αὐτὸς ὑπὸ τῶν στρατιωτῶν ἄκων αὐτοκράτωρ ἀποδείκνυται, καὶ ἀποχωρήσαντος ἐπὶ διοικήσει τῶν ὅλων εἰς τὴν Αἴγυπτον ἐστασιάσθη τὰ τῶν Ἰουδαίων, ὅπως τε ἐπανέστησαν αὐτοῖς οἱ τύραννοι, καὶ τὰς τούτων πρὸς ἀλλήλους διαφοράς.", "st": "1.pr.9"}, {"sp": "N", "t": "Καὶ ὡς ἄρας ἀπὸ τῆς Αἰγύπτου Τίτος δεύτερον εἰς τὴν χώραν ἐνέβαλεν, ὅπως τε τὰς δυνάμεις καὶ ὅπου συνήγαγε καὶ ὁπόσας, καὶ ὅπως ἐκ τῆς στάσεως ἡ πόλις διέκειτο παρόντος αὐτοῦ, προσβολάς τε ὅσας ἐποιήσατο καὶ ὁπόσα χώματα, περιβόλους τε τῶν τριῶν τειχῶν καὶ τὰ μέτρα τούτων, τήν τε τῆς πόλεως ὀχυρότητα καὶ τοῦ ἱεροῦ καὶ τοῦ ναοῦ τὴν διάθεσιν, ἔτι δὲ τούτων καὶ τοῦ βωμοῦ τὰ μέτρα πάντα μετ’ ἀκριβείας, ἔθη τε ἑορτῶν ἔνια καὶ τὰς ἑπτὰ ἁγνείας καὶ τὰς τῶν ἱερέων λειτουργίας, ἔτι δὲ τὰς ἐσθῆτας τῶν ἱερέων καὶ τοῦ ἀρχιερέως, καὶ οἷον ἦν τοῦ ναοῦ τὸ ἅγιον, οὐδὲν οὔτε ἀποκρυπτόμενος οὔτε προστιθεὶς τοῖς πεφωραμένοις.", "st": "1.pr.10"}, {"sp": "N", "t": "Ἔπειτα διέξειμι τήν τε τῶν τυράννων πρὸς τοὺς ὁμοφύλους ὠμότητα καὶ τὴν Ῥωμαίων φειδὼ πρὸς τοὺς ἀλλοφύλους, καὶ ὁσάκις Τίτος σῶσαι τὴν πόλιν καὶ τὸν ναὸν ἐπιθυμῶν ἐπὶ δεξιὰς τοὺς στασιάζοντας προυκαλέσατο, διακρινῶ δὲ τὰ πάθη τοῦ δήμου καὶ τὰς συμφορὰς ὅσα τε ὑπὸ τοῦ πολέμου καὶ ὅσα ὑπὸ τῆς στάσεως καὶ ὅσα ὑπὸ τοῦ λιμοῦ κακωθέντες ἑάλωσαν. παραλείψω δὲ οὐδὲ τὰς τῶν αὐτομόλων ἀτυχίας οὐδὲ τὰς τῶν αἰχμαλώτων κολάσεις, ὅπως τε ὁ ναὸς ἄκοντος ἐνεπρήσθη Καίσαρος καὶ ὅσα τῶν ἱερῶν κειμηλίων ἐκ τοῦ πυρὸς ἡρπάγη τήν τε τῆς ὅλης πόλεως ἅλωσιν καὶ τὰ πρὸ ταύτης σημεῖα καὶ τέρατα καὶ τὴν αἰχμαλωσίαν τῶν τυράννων τῶν τε ἀνδραποδισθέντων τὸ πλῆθος καὶ εἰς ἣν ἕκαστοι τύχην διενεμήθησαν· καὶ ὡς Ῥωμαῖοι μὲν ἐπεξῆλθον τὰ λείψανα τοῦ πολέμου καὶ τὰ ἐρύματα τῶν χωρίων καθεῖλον, Τίτος δὲ πᾶσαν ἐπελθὼν τὴν χώραν κατεστήσατο, τήν τε ὑποστροφὴν αὐτοῦ τὴν εἰς Ἰταλίαν καὶ τὸν θρίαμβον.", "st": "1.pr.11"}, {"sp": "N", "t": "Ταῦτα πάντα περιλαβὼν ἐν ἑπτὰ βιβλίοις καὶ μηδεμίαν τοῖς ἐπισταμένοις τὰ πράγματα καὶ παρατυχοῦσι τῷ πολέμῳ καταλιπὼν ἢ μέμψεως ἀφορμὴν ἢ κατηγορίας, τοῖς γε τὴν ἀλήθειαν ἀγαπῶσιν, ἀλλὰ μὴ πρὸς ἡδονὴν ἀνέγραψα. ποιήσομαι δὲ ταύτην τῆς ἐξηγήσεως ἀρχήν, ἣν καὶ τῶν κεφαλαίων ἐποιησάμην.", "st": "1.pr.12"}, {"sp": "N", "t": "Στάσεως τοῖς δυνατοῖς Ἰουδαίων ἐμπεσούσης καθ’ ὃν καιρὸν Ἀντίοχος ὁ κληθεὶς Ἐπιφανὴς διεφέρετο περὶ ὅλης Συρίας πρὸς Πτολεμαῖον τὸν ἕκτον, ἡ φιλοτιμία δ’ ἦν αὐτοῖς περὶ δυναστείας ἑκάστου τῶν ἐν ἀξιώματι μὴ φέροντος τοῖς ὁμοίοις ὑποτετάχθαι, Ὀνίας μὲν εἷς τῶν ἀρχιερέων ἐπικρατήσας ἐξέβαλε τῆς πόλεως τοὺς Τωβία υἱούς. οἱ δὲ καταφυγόντες πρὸς Ἀντίοχον ἱκέτευσαν αὐτοῖς ἡγεμόσι χρώμενον εἰς τὴν Ἰουδαίαν ἐμβαλεῖν. πείθεται δ’ ὁ βασιλεὺς ὡρμημένος πάλαι, καὶ μετὰ πλείστης δυνάμεως αὐτὸς ὁρμήσας τήν τε πόλιν αἱρεῖ κατὰ κράτος καὶ πολὺ πλῆθος τῶν Πτολεμαίῳ προσεχόντων ἀναιρεῖ, ταῖς τε ἁρπαγαῖς ἀνέδην ἐπαφιεὶς τοὺς στρατιώτας αὐτὸς καὶ τὸν ναὸν ἐσύλησε καὶ τὸν ἐνδελεχισμὸν τῶν καθ’ ἡμέραν ἐναγισμῶν ἔπαυσεν ἐπ’ ἔτη τρία καὶ μῆνας ἕξ. ὁ δ’ ἀρχιερεὺς Ὀνίας πρὸς Πτολεμαῖον διαφυγὼν καὶ παρ’ αὐτοῦ λαβὼν τόπον ἐν τῷ Ἡλιοπολίτῃ νομῷ πολίχνην τε τοῖς Ἱεροσολύμοις ἀπεικασμένην καὶ ναὸν ἔκτισεν ὅμοιον· περὶ ὧν αὖθις κατὰ χώραν δηλώσομεν.", "st": "1.1.1"}, {"sp": "N", "t": "Ἀντιόχῳ γε μὴν οὔτε τὸ παρ’ ἐλπίδα κρατῆσαι τῆς πόλεως οὔτε αἱ ἁρπαγαὶ καὶ ὁ τοσοῦτος φόνος ἤρκεσεν, ὑπὸ δὲ ἀκρασίας παθῶν καὶ κατὰ μνήμην ὧν παρὰ τὴν πολιορκίαν ἔπαθεν ἠνάγκαζεν Ἰουδαίους καταλύσαντας τὰ πάτρια βρέφη τε αὐτῶν φυλάττειν ἀπερίτμητα καὶ σῦς ἐπιθύειν τῷ βωμῷ· πρὸς ἃ ἅπαντες μὲν ἠπείθουν, ἐσφάττοντο δὲ οἱ δοκιμώτατοι. καὶ Βακχίδης ὁ πεμφθεὶς ὑπὸ Ἀντιόχου φρούραρχος, τῇ φυσικῇ προσλαβὼν ὠμότητι τὰ ἀσεβῆ παραγγέλματα παρανομίας οὐδεμίαν κατέλιπεν ὑπερβολὴν καὶ κατ’ ἄνδρα τοὺς ἀξιολόγους αἰκιζόμενος καὶ κοινῇ καθ’ ἡμέραν ἐνδεικνύμενος ὄψιν ἁλώσεως τῇ πόλει, μέχρι ταῖς ὑπερβολαῖς τῶν ἀδικημάτων τοὺς πάσχοντας εἰς ἀμύνης τόλμαν ἠρέθισε.", "st": "1.1.2"}, {"sp": "N", "t": "Ματθίας γοῦν υἱὸς Ἀσαμωναίου τῶν ἱερέων εἷς ἀπὸ κώμης Μωδεεὶν ὄνομα, συνασπίσας μετὰ χειρὸς οἰκείας, πέντε γὰρ υἱεῖς ἦσαν αὐτῷ, κοπίσιν ἀναιρεῖ τὸν Βακχίδην. καὶ παραχρῆμα μὲν δείσας τὸ πλῆθος τῶν φρουρῶν εἰς τὰ ὄρη καταφεύγει· προσγενομένων δὲ ἀπὸ τοῦ δήμου πολλῶν ἀναθαρσήσας κάτεισι καὶ συμβαλὼν μάχῃ νικᾷ τε τοὺς Ἀντιόχου στρατηγοὺς καὶ τῆς Ἰουδαίας ἐξελαύνει. παρελθὼν δὲ ἀπὸ τῆς εὐπραγίας εἰς δυναστείαν καὶ διὰ τὴν ἀπαλλαγὴν τῶν ἀλλοφύλων ἄρξας τῶν σφετέρων ἑκόντων, τελευτᾷ Ἰούδᾳ τῷ πρεσβυτάτῳ τῶν παίδων καταλιπὼν τὴν ἀρχήν.", "st": "1.1.3"}, {"sp": "N", "t": "Ὁ δέ, οὐ γὰρ ἠρεμήσειν Ἀντίοχον ὑπελάμβανε, τάς τε ἐπιχωρίους συγκροτεῖ δυνάμεις, καὶ πρὸς Ῥωμαίους πρῶτος ἐποιήσατο φιλίαν, καὶ τὸν Ἐπιφανῆ πάλιν εἰς τὴν χώραν ἐμβάλλοντα μετὰ καρτερᾶς πληγῆς ἀνέστειλεν. ἀπὸ δὲ θερμοῦ τοῦ κατορθώματος ὥρμησεν ἐπὶ τὴν ἐν τῇ πόλει φρουράν, οὔπω γὰρ ἐκκέκοπτο, καὶ ἐκβαλὼν ἀπὸ τῆς ἄνω πόλεως συνωθεῖ τοὺς στρατιώτας εἰς τὴν κάτω· τοῦτο δὲ τοῦ ἄστεος τὸ μέρος Ἄκρα κέκληται· κυριεύσας δὲ τοῦ ἱεροῦ τόν τε χῶρον ἐκάθηρε πάντα καὶ περιετείχισε καὶ τὰ πρὸς τὰς λειτουργίας σκεύη καινὰ κατασκευάσας εἰς τὸν ναὸν εἰσήνεγκεν ὡς τῶν προτέρων μεμιαμμένων, βωμόν τε ᾠκοδόμησεν ἕτερον καὶ τῶν ἐναγισμῶν ἤρξατο. λαμβανούσης δὲ ἄρτι τὸ ἱερὸν κατάστημα τῆς πόλεως τελευτᾷ μὲν Ἀντίοχος, κληρονόμος δὲ τῆς βασιλείας αὐτοῦ καὶ τῆς πρὸς Ἰουδαίους ἀπεχθείας ὁ υἱὸς Ἀντίοχος γίνεται.", "st": "1.1.4"}, {"sp": "N", "t": "Συναγαγὼν γοῦν πεζῶν μὲν μυριάδας πέντε, ἱππεῖς δὲ πεντακισχιλίους, ἐλέφαντας δὲ ὀγδοήκοντα ἐμβάλλει διὰ τῆς Ἰουδαίας εἰς τὴν ὀρεινήν. Βηθσουρὸν μὲν οὖν πολίχνην αἱρεῖ, κατὰ δὲ τόπον, ὃς καλεῖται Βεθζαχαρία στενῆς οὔσης τῆς παρόδου Ἰούδας ὑπαντᾷ μετὰ τῆς δυνάμεως. πρὶν δὲ συνάψαι τὰς φάλαγγας Ἐλεάζαρος ὁ ἀδελφὸς αὐτοῦ προϊδὼν τὸν ὑψηλότατον τῶν ἐλεφάντων πύργῳ τε μεγάλῳ καὶ περιχρύσοις προτειχίσμασι κεκοσμημένον, ὑπολαβὼν ἐπ’ αὐτοῦ τὸν Ἀντίοχον εἶναι, τῶν τε ἰδίων ἐκτρέχει πολὺ καὶ διακόψας τὸ στῖφος τῶν πολεμίων ἐπὶ τὸν ἐλέφαντα διήνυσεν. ἐφικέσθαι μὲν οὖν τοῦ δοκοῦντος εἶναι βασιλέως οὐχ οἷός τε ἦν διὰ τὸ ὕψος, ὁ δὲ τὸ θηρίον ὑπὸ τὴν γαστέρα πλήξας ἐπικατέσεισεν ἑαυτῷ καὶ συντριβεὶς ἐτελεύτησεν, μηδὲν πλέον δράσας τοῦ τοῖς μεγάλοις ἐπιβαλέσθαι θέμενος εὐκλείας ἐν δευτέρῳ τὸ ζῆν. ὅ γε μὴν κυβερνῶν τὸν ἐλέφαντα ἰδιώτης ἦν· κἂν εἰ συνέβη δὲ εἶναι τὸν Ἀντίοχον, οὐδὲν πλέον ἤνυσεν ὁ τολμήσας τοῦ δοκεῖν ἐπ’ ἐλπίδι μόνῃ λαμπροῦ κατορθώματος ἑλέσθαι τὸν θάνατον. γίνεται δὲ καὶ κλῃδὼν τἀδελφῷ τῆς ὅλης παρατάξεως· καρτερῶς μὲν γὰρ οἱ Ἰουδαῖοι καὶ μέχρι πολλοῦ διηγωνίσαντο, πλήθει δὲ ὑπερέχοντες οἱ βασιλικοὶ καὶ δεξιᾷ χρησάμενοι τύχῃ κρατοῦσι, καὶ πολλῶν ἀναιρεθέντων τοὺς λοιποὺς ἔχων Ἰούδας εἰς τὴν Γοφνιτικὴν τοπαρχίαν φεύγει. Ἀντίοχος δὲ παρελθὼν εἰς Ἱεροσόλυμα καὶ καθίσας ὀλίγας ἡμέρας ἐν αὐτῇ κατὰ σπάνιν τῶν ἐπιτηδείων ἀπανίσταται, καταλιπὼν μὲν φρουρὰν ὅσην ἀποχρήσειν ὑπελάμβανε, τὴν δὲ λοιπὴν δύναμιν ἀπαγαγὼν χειμεριοῦσαν εἰς τὴν Συρίαν.", "st": "1.1.5"}, {"sp": "N", "t": "Πρὸς δὲ τὴν ὑποχώρησιν τοῦ βασιλέως Ἰούδας οὐκ ἠρέμει, προσγενομένων δ’ ἐκ τοῦ ἔθνους πολλῶν καὶ τοὺς διασωθέντας ἐκ τῆς μάχης ἐπισυγκροτήσας κατὰ κώμην Ἀκέδασαν συμβάλλει τοῖς Ἀντιόχου στρατηγοῖς, καὶ φανεὶς ἄριστος κατὰ τὴν μάχην πολλούς τε τῶν πολεμίων ἀποκτείνας ἀναιρεῖται καὶ μεθ’ ἡμέρας ὀλίγας ὁ ἀδελφὸς αὐτοῦ Ἰωάννης ἐπιβουλευθεὶς ὑπὸ τῶν τὰ Ἀντιόχου φρονούντων τελευτᾷ.", "st": "1.1.6"}, {"sp": "N", "t": "Διαδεξάμενος δὲ τοῦτον ὁ ἀδελφὸς Ἰωνάθης τά τε ἄλλα πρὸς τοὺς ἐπιχωρίους διὰ φυλακῆς ἦγεν ἑαυτὸν καὶ τῇ πρὸς Ῥωμαίους φιλίᾳ τὴν ἀρχὴν ἐκρατύνατο πρός τε τὸν Ἀντιόχου παῖδα διαλλαγὰς ἐποιήσατο. οὐ μήν τι τούτων ἤρκεσεν αὐτῷ πρὸς ἀσφάλειαν· Τρύφων γὰρ ὁ τύραννος, ἐπίτροπος μὲν ὢν τοῦ Ἀντιόχου παιδὸς ἐπιβουλεύων δ’ αὐτῷ καὶ πρόσθεν, ἀποσκευάζεσθαι τοὺς φίλους αὐτοῦ πειρώμενος ἥκοντα τὸν Ἰωνάθην σὺν ὀλίγοις εἰς Πτολεμαΐδα πρὸς Ἀντίοχον δόλῳ συλλαμβάνει καὶ δήσας ἐπὶ Ἰουδαίαν στρατεύει· εἶτ’ ἀπελαθεὶς ὑπὸ τοῦ Σίμωνος, ὃς ἦν ἀδελφὸς τοῦ Ἰωνάθου, καὶ πρὸς τὴν ἧτταν ὠργισμένος κτείνει τὸν Ἰωνάθην.", "st": "1.2.1"}, {"sp": "N", "t": "Σίμων δὲ γενναίως ἀφηγούμενος τῶν πραγμάτων αἱρεῖ μὲν Γάζαρά τε καὶ Ἰόππην καὶ Ἰάμνειαν τῶν προσοίκων, κατέσκαψε δὲ καὶ τὴν ἄκραν τῶν φρουρῶν κρατήσας. αὖθις δὲ γίνεται καὶ Ἀντιόχῳ σύμμαχος κατὰ Τρύφωνος, ὃν ἐν Δώροις πρὸ τῆς ἐπὶ Μήδους στρατείας ἐπολιόρκει. ἀλλ’ οὐκ ἐξεδυσώπησεν τὴν τοῦ βασιλέως πλεονεξίαν Τρύφωνα συνεξελών· μετ’ οὐ πολὺ γὰρ Ἀντίοχος Κενδεβαῖον τὸν αὐτοῦ στρατηγὸν μετὰ δυνάμεως δῃώσοντα τὴν Ἰουδαίαν ἔπεμψεν καὶ καταδουλωσόμενον Σίμωνα. ὁ δὲ καίτοι γε γηραλέος ὢν νεανικώτερον ἀφηγήσατο τοῦ πολέμου· τοὺς μέντοι γε υἱεῖς αὐτοῦ μετὰ τῶν ἐρρωμενεστάτων προεκπέμπει, αὐτὸς δὲ μοῖραν τῆς δυνάμεως ἀναλαβὼν ἐπῄει κατ’ ἄλλο μέρος. πολλοὺς δὲ πολλαχοῦ κἀν τοῖς ὄρεσι προλοχίσας πάσαις κρατεῖ ταῖς ἐπιβολαῖς καὶ νικήσας λαμπρῶς ἀρχιερεὺς ἀποδείκνυται καὶ τῆς Μακεδόνων ἐπικρατείας μετὰ ἑκατὸν καὶ ἑβδομήκοντα ἔτη Ἰουδαίους ἀπαλλάττει.", "st": "1.2.2"}, {"sp": "N", "t": "Θνήσκει δὲ καὶ αὐτὸς ἐπιβουλευθεὶς ἐν συμποσίῳ ὑπὸ Πτολεμαίου τοῦ γαμβροῦ, ὃς αὐτοῦ τήν τε γυναῖκα καὶ τοὺς δύο παῖδας ἐγκαθείρξας ἐπὶ τὸν τρίτον Ἰωάννην, ὃς καὶ Ὑρκανὸς ἐκαλεῖτο, τοὺς ἀναιρήσοντας ἔπεμψεν. προγνοὺς δὲ τὴν ἔφοδον ὁ νεανίσκος παραγενέσθαι εἰς τὴν πόλιν ἠπείγετο, πλεῖστον τῷ λαῷ πεποιθὼς κατά τε μνήμην τῶν πατρῴων κατορθωμάτων καὶ μῖσος τῆς Πτολεμαίου παρανομίας. ὥρμησε δὲ καὶ Πτολεμαῖος εἰσελθεῖν καθ’ ἑτέραν πύλην, ἐξεκρούσθη γε μὴν ὑπὸ τοῦ δήμου ταχέως δεδεγμένων ἤδη τὸν Ὑρκανόν. καὶ ὁ μὲν παραχρῆμα ἀνεχώρησεν εἴς τι τῶν ὑπὲρ Ἱεριχοῦντος ἐρυμάτων, ὃ Δαγὼν καλεῖται· κομισάμενος δὲ τὴν πατρῴαν ἀρχιερωσύνην Ὑρκανὸς καὶ θύσας τῷ θεῷ μετὰ τάχους ἐπὶ Πτολεμαῖον ὥρμησεν βοηθήσων τῇ μητρὶ καὶ τοῖς ἀδελφοῖς, καὶ προσβαλὼν τῷ φρουρίῳ τὰ μὲν ἄλλα κρείττων ἦν,", "st": "1.2.3"}, {"sp": "N", "t": "ἡττᾶτο δὲ δικαίου πάθους· ὁ γὰρ Πτολεμαῖος ὁπότε καταπονοῖτο, τήν τε μητέρα καὶ τοὺς ἀδελφοὺς αὐτοῦ προάγων ἐπὶ τοῦ τείχους εἰς εὐσύνοπτον ᾐκίζετο καὶ κατακρημνιεῖν, εἰ μὴ θᾶττον ἀπανασταίη, διηπείλει. πρὸς ἃ τὸν μὲν Ὑρκανὸν ὀργῆς πλείων οἶκτος εἰσῄει καὶ δέος, ἡ δὲ μήτηρ οὐδὲν οὔτε πρὸς τὰς αἰκίας οὔτε πρὸς τὸν ἀπειλούμενον αὐτῇ θάνατον ἐνδιδοῦσα χεῖρας ὤρεγε καὶ κατηντιβόλει τὸν παῖδα μήτι πρὸς τὴν αὐτῆς ὕβριν ἐπικλασθέντα φείσασθαι τοῦ δυσσεβοῦς, ὡς αὐτῇ γε κρείττονα τὸν ἐκ Πτολεμαίου θάνατον ἀθανασίας εἶναι δόντος δίκας ἐφ’ οἷς εἰς τὸν οἶκον αὐτῶν παρηνόμησεν. ὁ δὲ Ἰωάννης ὁπότε μὲν ἐνθυμηθείη τὸ παράστημα τῆς μητρὸς καὶ κατακούσειε τῆς ἱκεσίας, ὥρμητο προσβάλλειν, ἐπειδὰν δὲ κατίδοι τυπτομένην τε καὶ σπαραττομένην, ἐθηλύνετο καὶ τοῦ πάθους ὅλος ἦν. τριβομένης δὲ διὰ ταῦτα τῆς πολιορκίας ἐπέστη τὸ ἀργὸν ἔτος, ὃ κατὰ ἑπταετίαν ἀργεῖται παρὰ Ἰουδαίοις ὁμοίως ταῖς ἑβδομάσιν ἡμέραις. κἀν τούτῳ Πτολεμαῖος ἀνεθεὶς τῆς πολιορκίας ἀναιρεῖ τοὺς ἀδελφοὺς Ἰωάννου σὺν τῇ μητρὶ καὶ φεύγει πρὸς Ζήνωνα τὸν ἐπικληθέντα Κοτυλᾶν· Φιλαδελφείας δ’ ἦν τύραννος.", "st": "1.2.4"}, {"sp": "N", "t": "Ἀντίοχος δὲ κατ’ ὀργὴν ὧν ὑπὸ Σίμωνος ἔπαθεν, στρατεύσας εἰς τὴν Ἰουδαίαν ἐπολιόρκει τὸν Ὑρκανὸν προσκαθεζόμενος τοῖς Ἱεροσολύμοις. ὁ δὲ τὸν Δαυίδου τάφον ἀνοίξας, ὃς δὴ πλουσιώτατος βασιλέων ἐγένετο, καὶ ὑφελόμενος ὑπὲρ τρισχίλια τάλαντα χρημάτων τόν τε Ἀντίοχον ἀνίστησι τῆς πολιορκίας πείσας τριακοσίοις ταλάντοις καὶ δὴ καὶ ξενοτροφεῖν πρῶτος Ἰουδαίων ἐκ τῆς περιουσίας ἤρξατο.", "st": "1.2.5"}, {"sp": "N", "t": "Αὖθίς γε μὴν Ἀντίοχος ἐπὶ Μήδους στρατεύσας καιρὸν ἀμύνης αὐτῷ παρεῖχεν· εὐθέως γὰρ ὥρμησεν ἐπὶ τὰς ἐν Συρίᾳ πόλεις, κενάς, ὅπερ ἦν, ὑπολαμβάνων τῶν μαχιμωτέρων εὑρήσειν. Μεδάβην μὲν οὖν καὶ Σαμαγὰν ἅμα ταῖς πλησίον, ἔτι δὲ Σίκιμα καὶ Ἀργαρίζειν αὐτὸς αἱρεῖ, πρὸς αἷς τὸ Χουθαίων γένος, οἳ περιῴκουν τὸ εἰκασθὲν τῷ ἐν Ἱεροσολύμοις ἱερῷ. αἱρεῖ δὲ καὶ τῆς Ἰδουμαίας ἄλλας τε οὐκ ὀλίγας καὶ Ἀδωρεὸν καὶ Μάρισαν.", "st": "1.2.6"}, {"sp": "N", "t": "Προελθὼν δὲ καὶ μέχρι Σαμαρείας, ἔνθα νῦν ἐστιν Σεβαστὴ πόλις ὑπὸ Ἡρώδου κτισθεῖσα τοῦ βασιλέως, καὶ πάντοθεν αὐτὴν ἀποτειχίσας τοὺς υἱεῖς ἐπέστησε τῇ πολιορκίᾳ Ἀριστόβουλον καὶ Ἀντίγονον· ὧν οὐδὲν ἀνιέντων λιμοῦ μὲν εἰς τοσοῦτον προῆλθον οἱ κατὰ τὴν πόλιν, ὡς ἅψασθαι καὶ τῶν ἀηθεστάτων. ἐπικαλοῦνται δὲ βοηθὸν Ἀντίοχον τὸν ἐπικληθέντα Ἀσπένδιον· κἀκεῖνος ἑτοίμως ὑπακούσας ὑπὸ τῶν περὶ Ἀριστόβουλον ἡττᾶται. καὶ ὁ μὲν μέχρι Σκυθοπόλεως διωχθεὶς ὑπὸ τῶν ἀδελφῶν ἐκφεύγει, οἱ δὲ ἐπὶ τοὺς Σαμαρεῖς ὑποστρέψαντες τό τε πλῆθος πάλιν εἰς τὸ τεῖχος συγκλείουσιν καὶ τὴν πόλιν ἑλόντες αὐτήν τε κατασκάπτουσιν καὶ τοὺς ἐνοικοῦντας ἐξηνδραποδίσαντο. προχωρούντων δὲ τῶν κατορθωμάτων τὴν ὁρμὴν οὐ κατέψυξαν, ἀλλὰ προελθόντες ἅμα τῇ δυνάμει μέχρι τῆς Σκυθοπόλεως ταύτην τε κατέδραμον καὶ τὴν ἐντὸς Καρμήλου τοῦ ὄρους χώραν ἅπασαν κατενείμαντο.", "st": "1.2.7"}, {"sp": "N", "t": "Πρὸς δὲ τὰς εὐπραγίας αὐτοῦ τε Ἰωάννου καὶ τῶν παίδων φθόνος ἐγείρει στάσιν τῶν ἐπιχωρίων, καὶ πολλοὶ κατ’ αὐτῶν συνελθόντες οὐκ ἠρέμουν, μέχρι καὶ πρὸς φανερὸν πόλεμον ἐκριπισθέντες ἡττῶνται. τὸ λοιπὸν δ’ ἐπιβιοὺς ἐν εὐδαιμονίᾳ Ἰωάννης καὶ τὰ κατὰ τὴν ἀρχὴν κάλλιστα διοικήσας ἐν τρισὶν ὅλοις καὶ τριάκοντα ἔτεσιν ἐπὶ πέντε υἱοῖς τελευτᾷ, μακαριστὸς ὄντως καὶ κατὰ μηδὲν ἐάσας ἐφ’ ἑαυτῷ μεμφθῆναι τὴν τύχην. τρία γοῦν τὰ κρατιστεύοντα μόνος εἶχεν, τήν τε ἀρχὴν τοῦ ἔθνους καὶ τὴν ἀρχιερωσύνην καὶ προφητείαν· ὡμίλει γὰρ αὐτῷ τὸ δαιμόνιον ὡς μηδὲν τῶν μελλόντων ἀγνοεῖν, ὅς γε καὶ περὶ δύο τῶν πρεσβυτέρων υἱῶν ὅτι μὴ διαμενοῦσι κύριοι τῶν πραγμάτων προεῖδέν τε καὶ προεφήτευσεν· ὧν τὴν καταστροφὴν ἄξιον ἀφηγήσασθαι, παρ’ ὅσον τῆς πατρῴας εὐδαιμονίας ἀπέκλιναν.", "st": "1.2.8"}, {"sp": "N", "t": "Μετὰ γὰρ τὴν τοῦ πατρὸς τελευτὴν ὁ πρεσβύτερος αὐτῶν Ἀριστόβουλος τὴν ἀρχὴν εἰς βασιλείαν μετατιθεὶς περιτίθεται μὲν διάδημα πρῶτος μετὰ τετρακοσιοστὸν καὶ ἑβδομηκοστὸν πρῶτον ἔτος, πρὸς δὲ μῆνας τρεῖς, ἐξ οὗ κατῆλθεν ὁ λαὸς εἰς τὴν χώραν ἀπαλλαγεὶς τῆς ἐν Βαβυλῶνι δουλείας· τῶν δὲ ἀδελφῶν τὸν μὲν μεθ’ ἑαυτὸν Ἀντίγονον, ἐδόκει γὰρ ἀγαπᾶν, ἦγεν ἰσοτίμως, τοὺς δ’ ἄλλους εἵργνυσι δήσας. δεσμεῖ δὲ καὶ τὴν μητέρα διενεχθεῖσαν περὶ τῆς ἐξουσίας, ταύτην γὰρ κυρίαν τῶν ὅλων ὁ Ἰωάννης ἀπολελοίπει, καὶ μέχρι τοσαύτης ὠμότητος προῆλθεν, ὥστε καὶ λιμῷ διαφθεῖραι δεδεμένην.", "st": "1.3.1"}, {"sp": "N", "t": "Περιέρχεται δὲ αὐτῶν ἡ τίσις εἰς τὸν ἀδελφὸν Ἀντίγονον, ὃν ἠγάπα τε καὶ τῆς βασιλείας κοινωνὸν εἶχεν· κτείνει γὰρ καὶ τοῦτον ἐκ διαβολῶν, ἃς οἱ πονηροὶ τῶν κατὰ τὸ βασίλειον ἐνεσκευάσαντο. τὰ μὲν δὴ πρῶτα διηπίστει τοῖς λεγομένοις ὁ Ἀριστόβουλος ἅτε δὴ καὶ τὸν ἀδελφὸν ἀγαπῶν καὶ διδοὺς φθόνῳ τὰ πολλὰ τῶν λογοποιουμένων. ὡς δ’ ὁ Ἀντίγονος λαμπρὸς ἀπὸ στρατείας ἦλθεν εἰς τὴν ἑορτήν, ἐν ᾗ σκηνοποιεῖσθαι πάτριον τῷ θεῷ, συνέβη μὲν κατ’ ἐκείνας τὰς ἡμέρας νόσῳ χρήσασθαι τὸν Ἀριστόβουλον, τὸν δὲ Ἀντίγονον ἐπὶ τέλει τῆς ἑορτῆς ἀναβάντα μετὰ τῶν περὶ αὐτὸν ὁπλιτῶν ὡς ἐνῆν μάλιστα κεκοσμημένον προσκυνῆσαι τὸ πλέον ὑπὲρ τοῦ ἀδελφοῦ. κἀν τούτῳ προσιόντες οἱ πονηροὶ τῷ βασιλεῖ τήν τε πομπὴν τῶν ὁπλιτῶν ἐδήλουν καὶ τὸ παράστημα τοῦ Ἀντιγόνου μεῖζον ἢ κατ’ ἰδιώτην, ὅτι τε παρείη μετὰ μεγίστου συντάγματος ἀναιρήσων αὐτόν· οὐ γὰρ ἀνέχεσθαι τιμὴν μόνον ἐκ βασιλείας ἔχων, παρὸν αὐτὴν κατασχεῖν.", "st": "1.3.2"}, {"sp": "N", "t": "Τούτοις κατὰ μικρὸν ἄκων ἐπίστευσεν ὁ Ἀριστόβουλος, καὶ προνοῶν τοῦ μήθ’ ὑποπτεύων φανερὸς γενέσθαι καὶ προησφαλίσθαι πρὸς τὸ ἄδηλον καθίστησι μὲν τοὺς σωματοφύλακας ἔν τινι τῶν ὑπογαίων ἀλαμπεῖ, κατέκειτο δ’ ἐν τῇ βάρει πρότερον αὖθις δ’ Ἀντωνίᾳ μετονομασθείσῃ, προστάξας ἀνόπλου μὲν ἀπέχεσθαι, κτείνειν δὲ τὸν Ἀντίγονον, εἰ μετὰ τῶν ὅπλων προσίοι, καὶ πρὸς αὐτὸν ἔπεμψεν τοὺς προεροῦντας ἄνοπλον ἐλθεῖν. πρὸς τοῦτο πάνυ πανούργως ἡ βασίλισσα συντάσσεται μετὰ τῶν ἐπιβούλων· τοὺς γὰρ πεμφθέντας πείθουσιν τὰ μὲν παρὰ τοῦ βασιλέως σιωπῆσαι, λέγειν δὲ πρὸς τὸν Ἀντίγονον ὡς ὁ ἀδελφὸς ἀκούσας ὅπλα τε αὐτῷ παρεσκευακέναι κάλλιστα καὶ πολεμικὸν κόσμον ἐν τῇ Γαλιλαίᾳ διὰ μὲν τὴν ἀσθένειαν αὐτὸς ἐπιδεῖν ἕκαστα κωλυθείη, νῦν δ’ ἐπεὶ καὶ χωρίζεσθαι μέλλοις, θεάσαιτ’ ἂν ἥδιστά σε ἐν τοῖς ὅπλοις.", "st": "1.3.3"}, {"sp": "N", "t": "Ταῦτα ἀκούσας ὁ Ἀντίγονος, ἐνῆγεν δ’ ἡ τοῦ ἀδελφοῦ διάθεσις μηδὲν ὑποπτεύειν πονηρόν, ἐχώρει μετὰ τῶν ὅπλων ὡς πρὸς ἐπίδειξιν. γενόμενος δὲ κατὰ τὴν σκοτεινὴν πάροδον, Στράτωνος ἐκαλεῖτο πύργος, ὑπὸ τῶν σωματοφυλάκων ἀναιρεῖται, βέβαιον ἀποδείξας ὅτι πᾶσαν εὔνοιαν καὶ φύσιν κόπτει διαβολὴ καὶ οὐδὲν οὕτως τῶν ἀγαθῶν παθῶν ἰσχυρόν, ὃ τῷ φθόνῳ μέχρι παντὸς ἀντέχει.", "st": "1.3.4"}, {"sp": "N", "t": "Θαυμάσαι δ’ ἄν τις ἐν τούτῳ καὶ Ἰούδαν, Ἐσσαῖος ἦν γένος οὐκ ἔστιν ὅτε πταίσας ἢ ψευσθεὶς ἐν τοῖς προαπαγγέλμασιν, ὃς ἐπειδὴ καὶ τότε τὸν Ἀντίγονον ἐθεάσατο παριόντα διὰ τοῦ ἱεροῦ, πρὸς τοὺς γνωρίμους ἀνέκραγεν, ἦσαν δ’ οὐκ ὀλίγοι παρεδρεύοντες αὐτῷ τῶν μανθανόντων, παπαί, νῦν ἐμοὶ καλόν, ἔφη, τὸ θανεῖν, ὅτε μου προτέθνηκεν ἡ ἀλήθεια καί τι τῶν ὑπ’ ἐμοῦ προρρηθέντων διέψευσται· ζῇ γὰρ Ἀντίγονος οὑτοσὶ σήμερον ὀφείλων ἀνῃρῆσθαι. χωρίον δὲ αὐτῷ πρὸς σφαγὴν Στράτωνος πύργος εἵμαρτο· καὶ τοῦτο μὲν ἀπὸ ἑξακοσίων ἐντεῦθεν σταδίων ἐστίν, ὧραι δὲ τῆς ἡμέρας ἤδη τέσσαρες· ὁ δὴ χρόνος ἐκκρούει τὸ μάντευμα. ταῦτα εἰπὼν σκυθρωπὸς ἐπὶ συννοίας ὁ γέρων διεκαρτέρει, καὶ μετ’ ὀλίγον ἀνῃρημένος Ἀντίγονος ἠγγέλλετο κατὰ τὸ ὑπόγαιον χωρίον, ὃ δὴ καὶ αὐτὸ Στράτωνος ἐκαλεῖτο πύργος ὁμωνυμοῦν τῇ παραλίῳ Καισαρείᾳ. τοῦτο γοῦν τὸν μάντιν διετάραξεν.", "st": "1.3.5"}, {"sp": "N", "t": "Ἀριστοβούλῳ γε μὴν εὐθὺς ἡ περὶ τοῦ μύσους μεταμέλεια νόσον ἐνσκήπτει καὶ πρὸς ἔννοιαν τοῦ φόνου τὴν ψυχὴν ἔχων ἀεὶ τεταραγμένην συνετήκετο, μέχρι τῶν σπλάγχνων ὑπ’ ἀκράτου τῆς λύπης σπαραττομένων ἄθρουν αἷμα ἀναβάλλει. τοῦτό τις τῶν ἐν τῇ θεραπείᾳ παίδων ἐκφέρων δαιμονίῳ προνοίᾳ σφάλλεται καθ’ ὃν τόπον Ἀντίγονος ἔσφακτο καὶ φαινομένοις ἔτι τοῖς ἀπὸ τοῦ φόνου σπίλοις τὸ αἷμα τοῦ κτείναντος ἐπέχεεν. ἤρθη δ’ εὐθὺς οἰμωγὴ τῶν θεασαμένων ὥσπερ ἐπίτηδες τοῦ παιδὸς ἐκεῖ ἐπικατασπείσαντος τὸ αἷμα. τῆς δὲ βοῆς ἀκούσας ὁ βασιλεὺς τὴν αἰτίαν ἐπυνθάνετο καὶ μηδενὸς τολμῶντος εἰπεῖν μᾶλλον ἐνέκειτο μαθεῖν ἐθέλων· τέλος δὲ ἀπειλοῦντι καὶ βιαζομένῳ τἀληθὲς εἶπον. ὁ δὲ τοὺς ὀφθαλμοὺς ἐμπίπλησι δακρύων καὶ στενάξας ὅσον ἦν αὐτῷ δύναμις εἶπεν· οὐκ ἄρα θεοῦ μέγαν ὀφθαλμὸν ἐπ’ ἔργοις ἀθεμίτοις λήσειν ἔμελλον, ἀλλά με ταχεῖα μέτεισι δίκη φόνου συγγενοῦς. μέχρι τοῦ μοι, σῶμα ἀναιδέστατον, τὴν ἀδελφῷ καὶ μητρὶ κατάκριτον ψυχὴν καθέξεις; μέχρι τοῦ δ’ αὐτοῖς ἐπισπείσω κατὰ μέρος τοὐμὸν αἷμα; λαβέτωσαν ἀθρόον τοῦτο, καὶ μηκέτι ταῖς ἐκ τῶν ἐμῶν σπλάγχνων χοαῖς ἐπειρωνευέσθω τὸ δαιμόνιον. ταῦτα εἰπὼν εὐθέως τελευτᾷ βασιλεύσας οὐ πλεῖον ἐνιαυτοῦ.", "st": "1.3.6"}, {"sp": "N", "t": "Λύσασα δ’ ἡ γυνὴ τοὺς ἀδελφοὺς αὐτοῦ βασιλέα καθίστησιν Ἀλέξανδρον τὸν καὶ καθ’ ἡλικίαν καὶ μετριότητι προύχειν δοκοῦντα. ὁ δὲ παρελθὼν εἰς τὴν ἐξουσίαν τὸν ἕτερον μὲν τῶν ἀδελφῶν βασιλειῶντα κτείνει, τὸν δὲ καταλιμπανόμενον ἀγαπῶντα τὸ ζῆν δίχα πραγμάτων εἶχεν.", "st": "1.4.1"}, {"sp": "N", "t": "Γίνεται δ’ αὐτῷ καὶ πρὸς τὸν Λάθουρον ἐπικληθέντα Πτολεμαῖον συμβολὴ πόλιν Ἀσωχὶν ᾑρηκότα, καὶ πολλοὺς μὲν ἀνεῖλεν τῶν πολεμίων, ἡ δὲ νίκη πρὸς Πτολεμαῖον ἔρρεψεν. ἐπεὶ δ’ ὑπὸ τῆς μητρὸς Κλεοπάτρας διωχθεὶς εἰς Αἴγυπτον ἀνεχώρησεν, Ἀλέξανδρος Γαδάρων τε πολιορκίᾳ κρατεῖ καὶ Ἀμαθοῦντος, ὃ δὴ μέγιστον μὲν ἦν ἔρυμα τῶν ὑπὲρ Ἰορδάνην, τὰ τιμιώτατα δὲ τῶν Θεοδώρου τοῦ Ζήνωνος κτημάτων ἦν ἐν αὐτῷ. ἐπελθὼν δ’ ἐξαίφνης ὁ Θεόδωρος τά τε σφέτερα καὶ τὴν τοῦ βασιλέως ἀποσκευὴν αἱρεῖ, τῶν δ’ Ἰουδαίων εἰς μυρίους κτείνει. γίνεται δ’ ἐπάνω τῆς πληγῆς Ἀλέξανδρος καὶ τραπόμενος εἰς τὴν παράλιον αἱρεῖ Γάζαν τε καὶ Ῥάφειαν καὶ Ἀνθηδόνα τὴν αὖθις ὑπὸ Ἡρώδου τοῦ βασιλέως Ἀγριππιάδα ἐπικληθεῖσαν.", "st": "1.4.2"}, {"sp": "N", "t": "Ἐξανδραποδισαμένῳ δὲ ταύτας ἐπανίσταται τὸ Ἰουδαϊκὸν ἐν ἑορτῇ· μάλιστα γὰρ ἐν ταῖς εὐωχίαις αὐτῶν στάσις ἅπτεται. καὶ δοκεῖ μὴ ἂν κρείττων γενέσθαι τῆς ἐπιβουλῆς, εἰ μὴ τὸ ξενικὸν αὐτῷ παρεβοήθει· Πισίδαι καὶ Κίλικες ἦσαν· Σύρους γὰρ οὐκ ἐδέχετο μισθοφόρους διὰ τὴν ἔμφυτον αὐτῶν πρὸς τὸ ἔθνος ἀπέχθειαν. κτείνας δὲ τῶν ἐπαναστάντων ὑπὲρ ἑξακισχιλίους Ἀραβίας ἥπτετο καὶ ταύτης ἑλὼν Γαλααδίτας καὶ Μωαβίτας φόρον τε αὐτοῖς ἐπιτάξας ἀνέστρεψεν ἐπὶ Ἀμαθοῦν. Θεοδώρου δὲ πρὸς τὰς εὐπραγίας αὐτὸν καταπλαγέντος ἔρημον λαβὼν τὸ φρούριον κατέσκαψεν.", "st": "1.4.3"}, {"sp": "N", "t": "Ἔπειτα συμβαλὼν Ὀβαίδᾳ τῷ Ἀράβων βασιλεῖ προλοχίσαντι κατὰ τὴν Γαυλάνην ἐνέδρας αὐτῷ γενομένης πᾶσαν ἀποβάλλει τὴν στρατιὰν συνωσθεῖσαν κατὰ βαθείας φάραγγος καὶ πλήθει καμήλων συντριβεῖσαν. διαφυγὼν δ’ αὐτὸς εἰς Ἱεροσόλυμα τῷ μεγέθει τῆς συμφορᾶς πάλαι μισοῦν τὸ ἔθνος ἠρέθισεν εἰς ἐπανάστασιν. γίνεται δὲ καὶ τότε κρείττων καὶ μάχαις ἐπαλλήλοις οὐκ ἔλαττον πεντακισμυρίων Ἰουδαίων ἀνεῖλεν ἐν ἓξ ἔτεσιν· οὐ μὴν εὐφραίνετό γε ταῖς νίκαις τὴν ἑαυτοῦ βασιλείαν ἀναλίσκων· ὅθεν παυσάμενος τῶν ὅπλων λόγοις ἐπεχείρει διαλύεσθαι πρὸς τοὺς ὑποτεταγμένους. οἱ δὲ μᾶλλον ἐμίσουν τὴν μετάνοιαν αὐτοῦ καὶ τοῦ τρόπου τὸ ἀνώμαλον, πυνθανομένῳ τε τὸ αἴτιον, τί ἂν ποιήσας καταστείλειεν αὐτούς, ἀποθανών, ἔλεγον· νεκρῷ γὰρ ἂν διαλλαγῆναι μόλις τῷ τοσαῦτα δράσαντι. ἅμα δὲ καὶ τὸν Ἄκαιρον ἐπικληθέντα Δημήτριον ἐπεκαλοῦντο. ῥᾳδίως δὲ ὑπακούσαντος κατ’ ἐλπίδα μειζόνων καὶ μετὰ στρατιᾶς ἥκοντος συνέμισγον οἱ Ἰουδαῖοι τοῖς συμμάχοις περὶ Σίκιμα.", "st": "1.4.4"}, {"sp": "N", "t": "Δέχεται δ’ ἑκατέρους Ἀλέξανδρος ἱππεῦσι μὲν χιλίοις, μισθοφόροις δὲ πεζοῖς ὀκτακισχιλίοις· παρῆν δὲ αὐτῷ καὶ τὸ εὐνοοῦν Ἰουδαϊκὸν εἰς μυρίους. τῶν δ’ ἐναντίων ἱππεῖς μὲν ἦσαν τρισχίλιοι, πεζῶν δὲ μύριοι τετρακισχίλιοι. καὶ πρὶν εἰς χεῖρας ἐλθεῖν διακηρύσσοντες οἱ βασιλεῖς ἐπειρῶντο τῶν παρ’ ἀλλήλοις ἀποστάσεων, Δημήτριος μὲν τοὺς Ἀλεξάνδρου μισθοφόρους, Ἀλέξανδρος δὲ τοὺς ἅμα Δημητρίῳ Ἰουδαίους μεταπείσειν ἐλπίσας. ὡς δ’ οὔτε Ἰουδαῖοι θυμῶν οὔτε οἱ Ἕλληνες ἐπαύσαντο πίστεως, διεκρίνοντο ἤδη τοῖς ὅπλοις συμπεσόντες. κρατεῖ δὲ τῇ μάχῃ Δημήτριος καίτοι πολλὰ τῶν Ἀλεξάνδρου μισθοφόρων καὶ ψυχῆς ἔργα καὶ χειρὸς ἐπιδειξαμένων. χωρεῖ δὲ τὸ τέλος τῆς παρατάξεως παρὰ δόξαν ἀμφοτέροις· οὔτε γὰρ Δημητρίῳ παρέμειναν νικῶντι οἱ καλέσαντες, καὶ κατὰ οἶκτον τῆς μεταβολῆς Ἀλεξάνδρῳ προσεχώρησαν εἰς τὰ ὄρη καταφυγόντι Ἰουδαίων ἑξακισχίλιοι. ταύτην τὴν ῥοπὴν οὐκ ἤνεγκεν Δημήτριος, ἀλλ’ ὑπολαβὼν ἤδη μὲν ἀξιόμαχον εἶναι πάλιν Ἀλέξανδρον, μεταρρεῖν δὲ καὶ πᾶν τὸ ἔθνος εἰς αὐτόν, ἀνεχώρησεν.", "st": "1.4.5"}, {"sp": "N", "t": "Οὐ μὴν τό γε λοιπὸν πλῆθος ὑποχωρησάντων τῶν συμμάχων κατέθεντο τὰς διαφοράς, συνεχὴς δὲ πρὸς Ἀλέξανδρον ἦν αὐτοῖς ὁ πόλεμος, μέχρι πλείστους ἀποκτείνας τοὺς λοιποὺς ἀπήλασεν εἰς Βεμέσελιν πόλιν καὶ ταύτην καταστρεψάμενος αἰχμαλώτους ἀνήγαγεν εἰς Ἱεροσόλυμα. προύκοψεν δὲ αὐτῷ δι’ ὑπερβολὴν ὀργῆς εἰς ἀσέβειαν τὸ τῆς ὠμότητος· τῶν γὰρ ληφθέντων ὀκτακοσίους ἀνασταυρώσας ἐν μέσῃ τῇ πόλει γυναῖκάς τε καὶ τέκνα αὐτῶν ἀπέσφαξεν ταῖς ὄψεσι· καὶ ταῦτα πίνων καὶ συγκατακείμενος ταῖς παλλακίσιν ἀφεώρα. τοσαύτη δὲ κατάπληξις ἔσχεν τὸν δῆμον, ὥστε τῶν ἀντιστασιαστῶν κατὰ τὴν ἐπιοῦσαν νύκτα φυγεῖν ὀκτακισχιλίους ἔξω Ἰουδαίας ὅλης, οἷς ὅρος τῆς φυγῆς ὁ Ἀλεξάνδρου θάνατος κατέστη. τοιούτοις ἔργοις ὀψὲ καὶ μόλις ἡσυχίαν τῇ βασιλείᾳ πορίσας ἀνεπαύσατο τῶν ὅπλων.", "st": "1.4.6"}, {"sp": "N", "t": "Γίνεται δὲ πάλιν ἀρχὴ θορύβων Ἀντίοχος ὁ καὶ Διόνυσος ἐπικληθείς, Δημητρίου μὲν ἀδελφὸς ὤν, τελευταῖος δὲ τῶν ἀπὸ Σελεύκου· τοῦτον γὰρ δείσας στρατεύεσθαι ἐπὶ τοὺς Ἄραβας ὡρμημένον τὸ μὲν μεταξὺ τῆς ὑπὲρ Ἀντιπατρίδος παρωρείου καὶ τῶν Ἰόππης αἰγιαλῶν διαταφρεύει φάραγγι βαθείᾳ, πρὸ δὲ τῆς τάφρου τεῖχος ἤγειρεν ὑψηλὸν καὶ ξυλίνους πύργους ἐτεκτήνατο τὰς εὐμαρεῖς ἐμβολὰς ἀποφράττων. οὐ μὴν εἶρξαί γε τὸν Ἀντίοχον ἴσχυσεν· ἐμπρήσας γὰρ τοὺς πύργους καὶ τὴν τάφρον χώσας διήλαυνε μετὰ τῆς δυνάμεως. θέμενος δὲ ἐν δευτέρῳ τὴν πρὸς τὸν κωλύσαντα ἄμυναν εὐθὺς ἐπὶ τοὺς Ἄραβας ᾔει. τῶν δὲ ὁ βασιλεὺς ἀναχωρῶν εἰς τὰ χρησιμώτερα τῆς χώρας πρὸς τὴν μάχην, ἔπειτα τὴν ἵππον ἐξαίφνης ἐπιστρέψας, μυρία δ’ ἦν τὸν ἀριθμόν, ἀτάκτοις ἐπιπίπτει τοῖς περὶ τὸν Ἀντίοχον. καρτερᾶς δὲ μάχης γενομένης ἕως μὲν περιῆν Ἀντίοχος ἀντεῖχεν ἡ δύναμις αὐτοῦ καίπερ ἀνέδην ὑπὸ τῶν Ἀράβων φονευόμενοι· πεσόντος δέ, καὶ γὰρ προεκινδύνευεν ἀεὶ τοῖς ἡττωμένοις παραβοηθῶν, ἐγκλίνουσιν πάντες, καὶ τὸ μὲν πλεῖστον αὐτῶν ἐπί τε τῆς παρατάξεως κἀν τῇ φυγῇ διαφθείρεται, τοὺς δὲ λοιποὺς καταφυγόντας εἰς Κανὰ κώμην σπάνει τῶν ἐπιτηδείων ἀναλωθῆναι συνέβη πλὴν ὀλίγων ἅπαντας.", "st": "1.4.7"}, {"sp": "N", "t": "Ἐκ τούτου Δαμασκηνοὶ διὰ τὸ πρὸς Πτολεμαῖον τὸν Μενναίου μῖσος Ἀρέταν ἐπάγονται καὶ καθιστῶσιν κοίλης Συρίας βασιλέα. στρατεύεται δ’ οὗτος ἐπὶ τὴν Ἰουδαίαν καὶ μάχῃ νικήσας Ἀλέξανδρον κατὰ συνθήκας ἀνεχώρησεν. Ἀλέξανδρος δὲ Πέλλαν ἑλὼν ἐπὶ Γέρασαν ᾔει πάλιν τῶν Θεοδώρου κτημάτων γλιχόμενος, καὶ τρισὶ τοὺς φρουροὺς περιβόλοις ἀποτειχίσας διὰ μάχης τὸ χωρίον παραλαμβάνει. καταστρέφεται δὲ καὶ Γαυλάνην καὶ Σελεύκειαν καὶ τὴν Ἀντιόχου φάραγγα καλουμένην, πρὸς οἷς Γάμαλα φρούριον καρτερὸν ἑλών, τὸν ἄρχοντα Δημήτριον ἐν αὐτῷ παραλύσας ἐκ πολλῶν ἐγκλημάτων ἐπάνεισιν εἰς Ἰουδαίαν, τρία πληρώσας ἔτη τῆς στρατείας. ἀσμένως δ’ ὑπὸ τοῦ ἔθνους ἐδέχθη διὰ τὴν εὐπραγίαν, καὶ λαμβάνει τὴν ἀνάπαυσιν τοῦ πολεμεῖν ἀρχὴν νόσου. τεταρταίαις δὲ περιόδοις πυρετῶν ἐνοχλούμενος ᾠήθη διακρούσεσθαι τὴν νόσον πάλιν ἁψάμενος πραγμάτων. διὸ δὴ στρατείαις ἀκαίροις ἑαυτὸν ἐπιδιδοὺς καὶ βιαζόμενος παρὰ δύναμιν τὸ σῶμα πρὸς τὰς ἐνεργείας ἀπήλλαξεν. τελευτᾷ γοῦν ἐν μέσοις τοῖς θορύβοις στρεφόμενος βασιλεύσας ἑπτὰ πρὸς τοῖς εἴκοσιν ἔτη.", "st": "1.4.8"}, {"sp": "N", "t": "Καταλείπει δὲ τὴν βασιλείαν Ἀλεξάνδρᾳ τῇ γυναικὶ πεπεισμένος ταύτῃ μάλιστ’ ἂν ὑπακοῦσαι τοὺς Ἰουδαίους, ἐπειδὴ τῆς ὠμότητος αὐτοῦ μακρὰν ἀποδέουσα καὶ ταῖς παρανομίαις ἀνθισταμένη τὸν δῆμον εἰς εὔνοιαν προσηγάγετο. καὶ οὐ διήμαρτεν τῆς ἐλπίδος· ἐκράτησεν γὰρ τῆς ἀρχῆς τὸ γύναιον διὰ δόξαν εὐσεβείας· ἠκρίβου γὰρ δὴ μάλιστα τοῦ νόμου τὰ πάτρια καὶ τοὺς πλημμελοῦντας εἰς τοὺς ἱεροὺς νόμους ἐξ ἀρχῆς προεβάλλετο. δύο δ’ αὐτῇ παίδων ὄντων ἐξ Ἀλεξάνδρου τὸν μὲν πρεσβύτερον Ὑρκανὸν διά τε τὴν ἡλικίαν ἀποδείκνυσιν ἀρχιερέα καὶ ἄλλως ὄντα νωθέστερον ἢ ὥστε ἐνοχλεῖν περὶ τῶν ὅλων, τὸν δὲ νεώτερον Ἀριστόβουλον διὰ θερμότητα κατεῖχεν ἰδιώτην.", "st": "1.5.1"}, {"sp": "N", "t": "Παραφύονται δὲ αὐτῆς εἰς τὴν ἐξουσίαν Φαρισαῖοι, σύνταγμά τι Ἰουδαίων δοκοῦν εὐσεβέστερον εἶναι τῶν ἄλλων καὶ τοὺς νόμους ἀκριβέστερον ἀφηγεῖσθαι. τούτοις περισσὸν δή τι προσεῖχεν ἡ Ἀλεξάνδρα σεσοβημένη περὶ τὸ θεῖον. οἱ δὲ τὴν ἁπλότητα τῆς ἀνθρώπου κατὰ μικρὸν ὑπιόντες ἤδη καὶ διοικηταὶ τῶν ὅλων ἐγίνοντο διώκειν τε καὶ κατάγειν οὓς ἐθέλοιεν, λύειν τε καὶ δεσμεῖν. καθόλου δὲ αἱ μὲν ἀπολαύσεις τῶν βασιλείων ἐκείνων ἦσαν, τὰ δ’ ἀναλώματα καὶ αἱ δυσχέρειαι τῆς Ἀλεξάνδρας. δεινὴ δ’ ἦν τὰ μείζω διοικεῖν, δύναμίν τε ἀεὶ συγκροτοῦσα διπλασίονα κατέστησεν καὶ ξενικὴν συνήγαγεν οὐκ ὀλίγην, ὡς μὴ μόνον κρατύνεσθαι τὸ οἰκεῖον ἔθνος, φοβερὰν δὲ καὶ τοῖς ἔξωθεν εἶναι δυνάσταις. ἐκράτει δὲ τῶν μὲν ἄλλων αὐτή, Φαρισαῖοι δ’ αὐτῆς.", "st": "1.5.2"}, {"sp": "N", "t": "Διογένην γοῦν τινα τῶν ἐπισήμων φίλον Ἀλεξάνδρῳ γεγενημένον κτείνουσιν αὐτοὶ σύμβουλον ἐγκαλοῦντες γεγονέναι περὶ τῶν ἀνασταυρωθέντων ὑπὸ τοῦ βασιλέως ὀκτακοσίων. ἐνῆγον δὲ τὴν Ἀλεξάνδραν εἰς τὸ καὶ τοὺς ἄλλους διαχειρίσασθαι τῶν παροξυνάντων ἐπ’ ἐκείνους τὸν Ἀλέξανδρον· ἐνδιδούσης δ’ ὑπὸ δεισιδαιμονίας ἀνῄρουν οὓς ἐθέλοιεν αὐτοί. προσφεύγουσι δὲ Ἀριστοβούλῳ τῶν κινδυνευόντων οἱ προύχειν δοκοῦντες, κἀκεῖνος πείθει τὴν μητέρα φείσασθαι μὲν διὰ τὸ ἀξίωμα τῶν ἀνδρῶν, ἐκπέμψαι δ’ αὐτούς, εἰ μὴ καθαροὺς ὑπείληφεν, ἐκ τῆς πόλεως. οἱ μὲν οὖν δοθείσης ἀδείας ἐσκεδάσθησαν ἀνὰ τὴν χώραν· Ἀλεξάνδρα δὲ ἐκπέμψασα ἐπὶ Δαμασκὸν στρατιάν, πρόφασις δ’ ἦν Πτολεμαῖος ἀεὶ θλίβων τὴν πόλιν, ταύτην μὲν ὑπεδέξατο μηθὲν ἀξιόλογον ἐργασαμένην. Τιγράνην δὲ τὸν Ἀρμενίων βασιλέα προσκαθεζόμενον Πτολεμαΐδι καὶ πολιορκοῦντα Κλεοπάτραν συνθήκαις καὶ δώροις ὑπηγάγετο. φθάνει δ’ ἐκεῖνος ἀπαναστὰς διὰ τὰς οἴκοι ταραχὰς ἐμβεβληκότος εἰς τὴν Ἀρμενίαν Λευκόλλου.", "st": "1.5.3"}, {"sp": "N", "t": "Κἀν τούτῳ νοσούσης Ἀλεξάνδρας ὁ νεώτερος τῶν παίδων Ἀριστόβουλος τὸν καιρὸν ἁρπάσας μετὰ τῶν οἰκετῶν, εἶχεν δὲ πολλοὺς καὶ πάντας εὔνους διὰ τὴν θερμότητα, κρατεῖ μὲν τῶν ἐρυμάτων ἁπάντων, τοῖς δ’ ἐκ τούτων χρήμασιν μισθοφόρους ἀθροίσας ἑαυτὸν ἀποδείκνυσι βασιλέα. πρὸς ταῦτα ὀδυρόμενον τὸν Ὑρκανὸν ἡ μήτηρ οἰκτείρασα τήν τε γυναῖκα καὶ τοὺς παῖδας Ἀριστοβούλου καθείργνυσιν εἰς τὴν Ἀντωνίαν· φρούριον δ’ ἦν τῷ βορείῳ κλίματι τοῦ ἱεροῦ προσκείμενον, πάλαι μέν, ὡς ἔφην, βᾶρις ὀνομαζόμενον, αὖθις δὲ ταύτης τυχὸν τῆς προσηγορίας ἐπικρατήσαντος Ἀντωνίου, καθάπερ ἀπό τε τοῦ Σεβαστοῦ καὶ Ἀγρίππα Σεβαστὴ καὶ Ἀγριππιὰς πόλεις ἐπωνομάσθησαν. πρὶν δὲ ἐπεξελθεῖν Ἀλεξάνδρα τὸν Ἀριστόβουλον τῆς τἀδελφοῦ καταλύσεως τελευτᾷ διοικήσασα τὴν ἀρχὴν ἔτεσιν ἐννέα.", "st": "1.5.4"}, {"sp": "N", "t": "Καὶ κληρονόμος μὲν ἦν τῶν ὅλων Ὑρκανός, ᾧ καὶ ζῶσα τὴν βασιλείαν ἐνεχείρισεν, δυνάμει δὲ καὶ φρονήματι προεῖχεν ὁ Ἀριστόβουλος. γενομένης δὲ αὐτοῖς περὶ τῶν ὅλων συμβολῆς περὶ Ἱεριχοῦντα καταλιπόντες οἱ πολλοὶ τὸν Ὑρκανὸν μεταβαίνουσιν πρὸς τὸν Ἀριστόβουλον. ὁ δὲ μετὰ τῶν συμμεινάντων φθάνει συμφυγὼν ἐπὶ τὴν Ἀντωνίαν καὶ κυριεύσας τῶν πρὸς σωτηρίαν ὁμήρων· ταῦτα δ’ ἦν ἡ Ἀριστοβούλου γυνὴ μετὰ τῶν τέκνων. ἀμέλει πρὶν ἀνηκέστου πάθους διελύθησαν, ὥστε βασιλεύειν μὲν Ἀριστόβουλον, Ὑρκανὸν δὲ ἐκστάντα τῆς ἄλλης ἀπολαύειν τιμῆς ὥσπερ ἀδελφὸν βασιλέως. ἐπὶ τούτοις διαλλαγέντες ἐν τῷ ἱερῷ καὶ τοῦ λαοῦ περιεστῶτος φιλοφρόνως ἀλλήλους ἀσπασάμενοι διήμειψαν τὰς οἰκίας· Ἀριστόβουλος μὲν γὰρ εἰς τὰ βασίλεια, Ὑρκανὸς δὲ ἀνεχώρησεν εἰς τὴν Ἀριστοβούλου οἰκίαν.", "st": "1.6.1"}, {"sp": "N", "t": "Δέος δὲ τοῖς τε ἄλλοις τῶν Ἀριστοβούλου διαφόρων ἐμπίπτει παρ’ ἐλπίδα κρατήσαντος καὶ μάλιστα Ἀντιπάτρῳ πάλαι διαμισουμένῳ. γένος δ’ ἦν Ἰδουμαῖος προγόνων τε ἕνεκα καὶ πλούτου καὶ τῆς ἄλλης ἰσχύος πρωτεύων τοῦ ἔθνους. οὗτος ἅμα καὶ τὸν Ὑρκανὸν Ἀρέτᾳ προσφυγόντα τῷ βασιλεῖ τῆς Ἀραβίας ἀνακτήσασθαι τὴν βασιλείαν ἔπειθεν καὶ τὸν Ἀρέταν δέξασθαί τε τὸν Ὑρκανὸν καὶ καταγαγεῖν ἐπὶ τὴν ἀρχήν, πολλὰ μὲν τὸν Ἀριστόβουλον εἰς τὸ ἦθος διαβάλλων, πολλὰ δ’ ἐπαινῶν τὸν Ὑρκανὸν [παρῄνει δέξασθαι], καὶ ὡς πρέπον εἴη τὸν οὕτω λαμπρᾶς προεστῶτα βασιλείας ὑπερέχειν χεῖρα τῷ ἀδικουμένῳ· ἀδικεῖσθαι δὲ τὸν Ὑρκανὸν στερηθέντα τῆς κατὰ τὸ πρεσβεῖον αὐτῷ προσηκούσης ἀρχῆς. προκατασκευάσας δὲ ἀμφοτέρους, νύκτωρ ἀναλαβὼν τὸν Ὑρκανὸν ἀπὸ τῆς πόλεως ἀποδιδράσκει καὶ συντόνῳ φυγῇ χρώμενος εἰς τὴν καλουμένην Πέτραν διασώζεται· βασίλειον αὕτη τῆς Ἀραβίας ἐστίν. ἔνθα τῷ Ἀρέτᾳ τὸν Ὑρκανὸν ἐγχειρίσας καὶ πολλὰ μὲν καθομιλήσας, πολλοῖς δὲ δώροις ὑπελθὼν δοῦναι δύναμιν αὐτῷ πείθει τὴν κατάξουσαν αὐτόν· ἦν δ’ αὕτη πεζῶν τε καὶ ἱππέων πέντε μυριάδες, πρὸς ἣν οὐκ ἀντέσχεν Ἀριστόβουλος, ἀλλ’ ἐν τῇ πρώτῃ συμβολῇ λειφθεὶς εἰς Ἱεροσόλυμα συνελαύνεται. κἂν ἔφθη κατὰ κράτος ληφθείς, εἰ μὴ Σκαῦρος ὁ Ῥωμαίων στρατηγὸς ἐπαναστὰς αὐτῶν τοῖς καιροῖς ἔλυσε τὴν πολιορκίαν· ὃς ἐπέμφθη μὲν εἰς Συρίαν ἀπὸ Ἀρμενίας ὑπὸ Πομπηίου Μάγνου πολεμοῦντος πρὸς Τιγράνην, παραγενόμενος δὲ εἰς Δαμασκὸν ἑαλωκυῖαν προσφάτως ὑπὸ Μετέλλου καὶ Λολλίου καὶ τούτους μεταστήσας, ἐπειδὴ τὰ κατὰ τὴν Ἰουδαίαν ἐπύθετο, καθάπερ ἐφ’ ἕρμαιον ἠπείχθη.", "st": "1.6.2"}, {"sp": "N", "t": "Παρελθόντος γοῦν εἰς τὴν χώραν πρέσβεις εὐθέως ἧκον παρὰ τῶν ἀδελφῶν ἑκατέρου δεομένου βοηθεῖν αὐτῷ. γίνεται δ’ ἐπίπροσθεν τοῦ δικαίου τὰ παρὰ Ἀριστοβούλου τριακόσια τάλαντα· τοσοῦτον γὰρ λαβὼν Σκαῦρος ἐπικηρυκεύεται πρός τε Ὑρκανὸν καὶ τοὺς Ἄραβας ἀπειλῶν Ῥωμαίους καὶ Πομπήιον, εἰ μὴ λύσειαν τὴν πολιορκίαν. ἀνεχώρει δὲ ἐκ τῆς Ἰουδαίας εἰς Φιλαδέλφειαν Ἀρέτας καταπλαγείς, καὶ πάλιν εἰς Δαμασκὸν Σκαῦρος. Ἀριστοβούλῳ δ’ οὐκ ἀπέχρησεν τὸ μὴ ἁλῶναι, πᾶσαν δὲ τὴν δύναμιν ἐπισυλλέξας εἵπετο τοῖς πολεμίοις καὶ περὶ τὸν καλούμενον Παπυρῶνα συμβαλὼν αὐτοῖς ὑπὲρ ἑξακισχιλίους κτείνει, μεθ’ ὧν καὶ τὸν ἀδελφὸν τὸν Ἀντιπάτρου Φαλλίωνα.", "st": "1.6.3"}, {"sp": "N", "t": "Ὑρκανὸς δὲ καὶ Ἀντίπατρος τῶν Ἀράβων ἀφαιρεθέντες μετέφερον ἐπὶ τοὺς ἐναντίους τὴν ἐλπίδα, καὶ ἐπειδὴ Πομπήιος ἐπιὼν τὴν Συρίαν εἰς Δαμασκὸν ἧκεν, ἐπ’ αὐτὸν καταφεύγουσιν καὶ δίχα δωρεῶν αἷς καὶ πρὸς τὸν Ἀρέταν δικαιολογίαις χρώμενοι κατηντιβόλουν μισῆσαι μὲν τὴν Ἀριστοβούλου βίαν, κατάγειν δὲ ἐπὶ τὴν βασιλείαν τὸν καὶ τρόπῳ καὶ καθ’ ἡλικίαν προσήκοντα. οὐ μὴν οὐδ’ Ἀριστόβουλος ὑστέρει πεποιθὼς τῇ Σκαύρου δωροδοκίᾳ παρῆν τε καὶ αὐτὸς ὡς οἷόν τε βασιλικώτατα κεκοσμηκὼς ἑαυτόν. ἀδοξήσας δὲ πρὸς τὰς θεραπείας καὶ μὴ φέρων δουλεύειν ταῖς χρείαις ταπεινότερον τοῦ σχήματος ἀπὸ διὸς ἡλίου πόλεως χωρίζεται.", "st": "1.6.4"}, {"sp": "N", "t": "Πρὸς ταῦτ’ ἀγανακτήσας Πομπήιος πολλὰ καὶ τῶν περὶ Ὑρκανὸν ἱκετευόντων ὥρμησεν ἐπ’ Ἀριστόβουλον, ἀναλαβὼν τήν τε Ῥωμαϊκὴν δύναμιν καὶ πολλοὺς ἐκ τῆς Συρίας συμμάχους. ἐπεὶ δὲ παρελαύνων Πέλλαν καὶ Σκυθόπολιν ἧκεν εἰς Κορέας. ὅθεν ἡ Ἰουδαίων ἄρχεται χώρα κατὰ τὴν μεσόγειον ἀνιόντων, ἀκούσας συμπεφευγέναι τὸν Ἀριστόβουλον εἰς Ἀλεξάνδρειον, τοῦτο δ’ ἐστὶν φρούριον τῶν πάνυ φιλοτίμως ἐξησκημένων ὑπὲρ ὄρους ὑψηλοῦ κείμενον, πέμψας καταβαίνειν αὐτὸν ἐκέλευσεν. τῷ δ’ ἦν μὲν ὁρμὴ καλουμένῳ δεσποτικώτερον διακινδυνεύειν μᾶλλον ἢ ὑπακοῦσαι, καθεώρα δὲ τὸ πλῆθος ὀρρωδοῦν, καὶ παρῄνουν οἱ φίλοι σκέπτεσθαι τὴν Ῥωμαίων ἰσχὺν οὖσαν ἀνυπόστατον. οἷς πεισθεὶς κάτεισιν πρὸς Πομπήιον καὶ πολλὰ περὶ τοῦ δικαίως ἄρχειν ἀπολογηθεὶς ὑπέστρεψεν εἰς τὸ ἔρυμα. πάλιν τε τἀδελφοῦ προκαλουμένου καταβὰς καὶ διαλεχθεὶς περὶ τῶν δικαίων ἄπεισιν μὴ κωλύοντος τοῦ Πομπηΐου. μέσος δ’ ἦν ἐλπίδος καὶ δέους, καὶ κατῄει μὲν ὡς δυσωπήσων Πομπήιον πάντ’ ἐπιτρέπειν αὐτῷ, πάλιν δὲ ἀνέβαινεν εἰς τὴν ἄκραν, ὡς μὴ προκαταλύειν δόξειεν αὑτόν. ἐπεὶ μέντοι Πομπήιος ἐξίστασθαί τε τῶν φρουρίων ἐκέλευεν αὐτῷ καὶ παράγγελμα τῶν φρουράρχων ἐχόντων μόναις πειθαρχεῖν ταῖς αὐτογράφοις ἐπιστολαῖς, ἠνάγκαζεν αὐτὸν ἑκάστοις γράφειν ἐκχωρεῖν, ποιεῖ μὲν τὰ προσταχθέντα, ἀγανακτήσας δὲ ἀνεχώρησεν εἰς Ἱεροσόλυμα καὶ παρεσκευάζετο πολεμεῖν πρὸς Πομπήιον.", "st": "1.6.5"}, {"sp": "N", "t": "Ὁ δέ, οὐ γὰρ ἐδίδου χρόνον ταῖς παρασκευαῖς, εὐθέως εἵπετο, καὶ προσεπέρρωσεν τὴν ὁρμὴν ὁ Μιθριδάτου θάνατος ἀγγελθεὶς αὐτῷ περὶ Ἱεριχοῦντα, ἔνθα τῆς Ἰουδαίας τὸ πιότατον φοίνικά τε πάμπολυν καὶ βάλσαμον τρέφει. τοῦτο λίθοις ὀξέσιν ἐπιτέμνοντες τὰ πρέμνα συνάγουσιν κατὰ τὰς τομὰς ἐκδακρῦον. καὶ στρατοπεδευσάμενος ἐν τῷ χωρίῳ μίαν ἑσπέραν ἕωθεν ἠπείγετο πρὸς τὰ Ἱεροσόλυμα. καταπλαγεὶς δὲ τὴν ἔφοδον Ἀριστόβουλος ἱκέτης ἀπαντᾷ χρημάτων τε ὑποσχέσει καὶ τῷ μετὰ τῆς πόλεως ἐπιτρέπειν καὶ ἑαυτὸν χαλεπαίνοντα καταστέλλει τὸν Πομπήιον. οὐ μήν τι τῶν ὡμολογημένων ἐγένετο· τὸν γὰρ ἐπὶ τὴν κομιδὴν τῶν χρημάτων ἐκπεμφθέντα Γαβίνιον οἱ τὰ Ἀριστοβούλου φρονοῦντες οὐδὲ τῇ πόλει δέχονται.", "st": "1.6.6"}, {"sp": "N", "t": "Πρὸς ταῦτα ἀγανακτήσας Πομπήιος Ἀριστόβουλον μὲν ἐφρούρει, πρὸς δὲ τὴν πόλιν ἐλθὼν περιεσκόπει ὅπως δεῖ προσβαλεῖν, τήν τε ὀχυρότητα τῶν τειχῶν δυσμεταχείριστον ὁρῶν καὶ τὴν πρὸ τούτων φάραγγα φοβερὰν τό τε ἱερὸν ἐντὸς τῆς φάραγγος ὀχυρώτατα τετειχισμένον, ὥστε τοῦ ἄστεος ἁλισκομένου δευτέραν εἶναι καταφυγὴν τοῦτο τοῖς πολεμίοις.", "st": "1.7.1"}, {"sp": "N", "t": "Διαποροῦντος δ’ ἐπὶ πολὺν χρόνον στάσις τοῖς ἔνδον ἐμπίπτει, τῶν μὲν Ἀριστοβούλου πολεμεῖν ἀξιούντων καὶ ῥύεσθαι τὸν βασιλέα, τῶν δὲ τὰ Ὑρκανοῦ φρονούντων ἀνοίγειν Πομπηίῳ τὰς πύλας· πολλοὺς δὲ τούτους ἐποίει τὸ δέος ἀφορῶντας εἰς τὴν τῶν Ῥωμαίων εὐταξίαν. ἡττώμενον δὲ τὸ Ἀριστοβούλου μέρος εἰς τὸ ἱερὸν ἀνεχώρησεν καὶ τὴν συνάπτουσαν ἀπ’ αὐτοῦ τῇ πόλει γέφυραν ἀποκόψαντες ἀντισχεῖν εἰς ἔσχατον παρεσκευάζοντο. τῶν δὲ ἑτέρων δεχομένων Ῥωμαίους τῇ πόλει καὶ τὰ βασίλεια παραδιδόντων ἐπὶ μὲν ταῦτα Πομπήιος ἕνα τῶν ὑφ’ ἑαυτῷ στρατηγῶν Πείσωνα εἰσπέμπει μετὰ στρατιᾶς· ὃς διαλαβὼν φρουραῖς τὴν πόλιν, ἐπειδὴ τῶν εἰς τὸ ἱερὸν καταφυγόντων οὐδένα λόγοις ἔπειθεν συμβῆναι, τὰ πέριξ εἰς προσβολὰς εὐτρέπιζεν ἔχων τοὺς περὶ τὸν Ὑρκανὸν εἴς τε τὰς ἐπινοίας καὶ τὰς ὑπηρεσίας προθύμους.", "st": "1.7.2"}, {"sp": "N", "t": "Αὐτὸς δὲ κατὰ τὸ προσάρκτιον κλίμα τήν τε τάφρον ἔχου καὶ τὴν φάραγγα πᾶσαν ὕλην συμφορούσης τῆς δυνάμεως. χαλεπὸν δ’ ἦν τὸ ἀναπληροῦν διὰ βάθος ἄπειρον καὶ τῶν Ἰουδαίων πάντα τρόπον εἰργόντων ἄνωθεν, κἂν ἀτέλεστος ἔμεινεν τοῖς Ῥωμαίοις ὁ πόνος, εἰ μὴ τὰς ἑβδομάδας ἐπιτηρῶν ὁ Πομπήιος, ἐν αἷς παντὸς ἔργου διὰ τὴν θρησκείαν χεῖρας ἀπίσχουσιν Ἰουδαῖοι, τὸ χῶμα ὕψου τῆς κατὰ χεῖρα συμβολῆς εἴργων τοὺς στρατιώτας· ὑπὲρ μόνου γὰρ τοῦ σώματος ἀμύνονται τοῖς σαββάτοις. ἤδη δὲ ἀναπεπληρωμένης τῆς φάραγγος πύργους ὑψηλοὺς ἐπιστήσας τῷ χώματι καὶ προσαγαγὼν τὰς ἐκ Τύρου κομισθείσας μηχανὰς ἐπειρᾶτο τοῦ τείχους· ἀνέστελλον δὲ αἱ πετροβόλοι τοὺς καθύπερθεν κωλύοντας. ἀντεῖχον δ’ ἐπὶ πλεῖον οἱ κατὰ τοῦτο τὸ μέρος πύργοι μεγέθει τε καὶ κάλλει διαφέροντες.", "st": "1.7.3"}, {"sp": "N", "t": "Ἔνθα δὴ πολλὰ τῶν Ῥωμαίων κακοπαθούντων ὁ Πομπήιος τά τε ἄλλα τῆς καρτερίας τοὺς Ἰουδαίους ἀπεθαύμαζεν καὶ μάλιστα τοῦ μηδὲν παραλῦσαι· τῆς θρησκείας ἐν μέσοις τοῖς βέλεσιν ἀνειλημένους· ὥσπερ γὰρ εἰρήνης βαθείας κατεχούσης τὴν πόλιν αἵ τε θυσίαι καθ’ ἡμέραν καὶ οἱ ἐναγισμοὶ καὶ πᾶσα θεραπεία κατὰ τἀκριβὲς ἐξετελεῖτο τῷ θεῷ, καὶ οὐδὲ κατ’ αὐτὴν τὴν ἅλωσιν περὶ τῷ βωμῷ φονευόμενοι τῶν καθ’ ἡμέραν νομίμων εἰς τὴν θρησκείαν ἀπέστησαν. τρίτῳ γὰρ μηνὶ τῆς πολιορκίας μόλις ἕνα τῶν πύργων καταρρίψαντες εἰσέπιπτον εἰς τὸ ἱερόν. ὁ δὲ πρῶτος ὑπερβῆναι τολμήσας τὸ τεῖχος Σύλλα παῖς ἦν Φαῦστος Κορνήλιος καὶ μετ’ αὐτὸν ἑκατοντάρχαι δύο Φούριος καὶ Φάβιος. εἵπετο δὲ ἑκάστῳ τὸ ἴδιον στῖφος, καὶ περισχόντες πανταχοῦ τὸ ἱερὸν ἔκτεινον οὓς μὲν τῷ ναῷ προσφεύγοντας, οὓς δὲ ἀμυνομένους πρὸς ὀλίγον.", "st": "1.7.4"}, {"sp": "N", "t": "Ἔνθα πολλοὶ τῶν ἱερέων ξιφήρεις τοὺς πολεμίους ἐπιόντας βλέποντες ἀθορύβως ἐπὶ τῆς θρησκείας ἔμειναν, σπένδοντες δὲ ἀπεσφάττοντο καὶ θυμιῶντες καὶ τῆς πρὸς τὸ θεῖον θεραπείας ἐν δευτέρῳ τὴν σωτηρίαν τιθέμενοι. πλεῖστοι δ’ ὑπὸ τῶν ὁμοφύλων ἀντιστασιαστῶν ἀνῃροῦντο καὶ κατὰ τῶν κρημνῶν ἔρριπτον ἑαυτοὺς ἄπειροι· καὶ τὰ περὶ τὸ τεῖχος δ’ ἔνιοι μανιῶντες ἐν ταῖς ἀμηχανίαις ὑπέπρησαν καὶ συγκατεφλέγοντο. Ἰουδαίων μὲν οὖν ἀνῃρέθησαν μύριοι καὶ δισχίλιοι, Ῥωμαίων δὲ ὀλίγοι μὲν πάνυ νεκροί, τραυματίαι δ’ ἐγένοντο πλείους.", "st": "1.7.5"}, {"sp": "N", "t": "Οὐδὲν δὲ οὕτως ἐν ταῖς τότε συμφοραῖς καθήψατο τοῦ ἔθνους ὡς τὸ τέως ἀόρατον ἅγιον ἐκκαλυφθὲν ὑπὸ τῶν ἀλλοφύλων· παρελθὼν γοῦν σὺν τοῖς περὶ αὐτὸν ὁ Πομπήιος εἰς τὸν ναόν, ἔνθα μόνῳ θεμιτὸν ἦν παριέναι τῷ ἀρχιερεῖ, τὰ ἔνδον ἐθεάσατο, λυχνίαν τε καὶ λύχνους καὶ τράπεζαν καὶ σπονδεῖα καὶ θυμιατήρια, ὁλόχρυσα πάντα, πλῆθός τε ἀρωμάτων σεσωρευμένον καὶ τῶν ἱερῶν χρημάτων εἰς τάλαντα δισχίλια. οὔτε δὲ τούτων οὔτε ἄλλου τινὸς τῶν ἱερῶν κειμηλίων ἥψατο, ἀλλὰ καὶ μετὰ μίαν τῆς ἁλώσεως ἡμέραν καθᾶραι τὸ ἱερὸν τοῖς νεωκόροις προσέταξεν καὶ τὰς ἐξ ἔθους ἐπιτελεῖν θυσίας. αὖθις δ’ ἀποδείξας Ὑρκανὸν ἀρχιερέα τά τε ἄλλα προθυμότατον ἑαυτὸν ἐν τῇ πολιορκίᾳ παρασχόντα καὶ διότι τὸ κατὰ τὴν χώραν πλῆθος ἀπέστησεν Ἀριστοβούλῳ συμπολεμεῖν ὡρμημένον, ἐκ τούτων, ὅπερ ἦν προσῆκον ἀγαθῷ στρατηγῷ, τὸν λαὸν εὐνοίᾳ πλέον ἢ δέει προσηγάγετο. ἐν δὲ τοῖς αἰχμαλώτοις ἐλήφθη καὶ ὁ Ἀριστοβούλου πενθερός, ὁ δ’ αὐτὸς ἦν καὶ θεῖος αὐτῷ. καὶ τοὺς αἰτιωτάτους μὲν τοῦ πολέμου πελέκει κολάζει, Φαῦστον δὲ καὶ τοὺς μετ’ αὐτοῦ γενναίως ἀγωνισαμένους λαμπροῖς ἀριστείοις δωρησάμενος τῇ τε χώρᾳ καὶ τοῖς Ἱεροσολύμοις ἐπιτάσσει φόρον.", "st": "1.7.6"}, {"sp": "N", "t": "Ἀφελόμενος δὲ τοῦ ἔθνους καὶ τὰς ἐν κοίλῃ Συρίᾳ πόλεις, ἃς εἷλον, ὑπέταξεν τῷ κατ’ ἐκεῖνο Ῥωμαίων στρατηγῷ κατατεταγμένῳ καὶ μόνοις αὐτοὺς τοῖς ἰδίοις ὅροις περιέκλεισεν. ἀνακτίζει δὲ καὶ Γάδαρα ὑπὸ Ἰουδαίων κατεστραμμένην Γαδαρεῖ τινὶ τῶν ἰδίων ἀπελευθέρων Δημητρίῳ χαριζόμενος. ἠλευθέρωσεν δὲ ἀπ’ αὐτῶν καὶ τὰς ἐν τῇ μεσογείᾳ πόλεις, ὅσας μὴ φθάσαντες κατέσκαψαν, Ἵππον Σκυθόπολίν τε καὶ Πέλλαν καὶ Σαμάρειαν καὶ Ἰάμνειαν καὶ Μάρισαν Ἄζωτόν τε καὶ Ἀρέθουσαν, ὁμοίως δὲ καὶ τὰς παραλίους Γάζαν Ἰόππην Δῶρα καὶ τὴν πάλαι μὲν Στράτωνος πύργον καλουμένην, ὕστερον δὲ μετακτισθεῖσάν τε ὑφ’ Ἡρώδου βασιλέως λαμπροτάτοις κατασκευάσμασιν καὶ μετονομασθεῖσαν Καισάρειαν. ἃς πάσας τοῖς γνησίοις ἀποδοὺς πολίταις κατέταξεν εἰς τὴν Συριακὴν ἐπαρχίαν. παραδοὺς δὲ ταύτην τε καὶ τὴν Ἰουδαίαν καὶ τὰ μέχρις Αἰγύπτου καὶ Εὐφράτου Σκαύρῳ διέπειν καὶ δύο τῶν ταγμάτων, αὐτὸς διὰ Κιλικίας εἰς Ῥώμην ἠπείγετο τὸν Ἀριστόβουλον ἄγων μετὰ τῆς γενεᾶς αἰχμάλωτον. δύο δ’ ἦσαν αὐτῷ θυγατέρες καὶ δύο υἱεῖς, ὧν ὁ ἕτερος μὲν Ἀλέξανδρος ἐκ τῆς ὁδοῦ διαδιδράσκει, σὺν δὲ ταῖς ἀδελφαῖς ὁ νεώτερος Ἀντίγονος εἰς Ῥώμην ἐκομίζετο.", "st": "1.7.7"}, {"sp": "N", "t": "Κἀν τούτῳ Σκαῦρος εἰς τὴν Ἀραβίαν ἐμβαλὼν τῆς μὲν Πέτρας εἴργετο ταῖς δυσχωρίαις, ἐπόρθει δὲ τὰ πέριξ πολλὰ κἀν τούτῳ κακοπαθῶν· ἐλίμωττεν γὰρ ἡ στρατιά. καὶ πρὸς τοῦτο Ὑρκανὸς ἐπεβοήθει διὰ Ἀντιπάτου τὰ ἐπιτήδεια πέμπων. ὃν καὶ καθίησι Σκαῦρος ὄντα συνήθη πρὸς Ἀρέταν, ὅπως ἐπὶ χρήμασιν διαλύσαιτο τὸν πόλεμον. πείθεται δὲ ὁ Ἄραψ τριακόσια δοῦναι τάλαντα, κἀπὶ τούτοις Σκαῦρος ἐξῆγεν τῆς Ἀραβίας τὴν δύναμιν.", "st": "1.8.1"}, {"sp": "N", "t": "Ὁ δ’ ἀποδρὰς τῶν Ἀριστοβούλου παίδων Πομπήιον Ἀλέξανδρος χρόνῳ συναγαγὼν χεῖρα συχνὴν βαρὺς ἦν Ὑρκανῷ καὶ τὴν Ἰουδαίαν κατέτρεχεν, ἐδόκει τε ἂν καταλῦσαι ταχέως αὐτόν, ὅς γε ἤδη καὶ τὸ καταρριφθὲν ὑπὸ Πομπηίου τεῖχος ἐν Ἱεροσολύμοις ἀνακτίζειν ἐθάρρει προσελθών, εἰ μὴ Γαβίνιος εἰς Συρίαν πεμφθεὶς Σκαύρῳ διάδοχος τά τε ἄλλα γενναῖον ἀπέδειξεν ἑαυτὸν ἐν πολλοῖς καὶ ἐπ’ Ἀλέξανδρον ὥρμησεν. ὁ δὲ δείσας πρὸς τὴν ἔφοδον δύναμίν τε πλείω συνέλεγεν, ὡς γενέσθαι μυρίους μὲν ὁπλίτας χιλίους δὲ καὶ πεντακοσίους ἱππεῖς, καὶ τὰ ἐπιτήδεια τῶν χωρίων ἐτείχιζε Ἀλεξάνδρειόν τε καὶ Ὑρκάνειον καὶ Μαχαιροῦντα πρὸς τοῖς Ἀραβίοις ὄρεσιν.", "st": "1.8.2"}, {"sp": "N", "t": "Γαβίνιος δὲ μετὰ μέρους τῆς στρατιᾶς Μᾶρκον Ἀντώνιον προπέμψας αὐτὸς εἵπετο τὴν ὅλην ἔχων δύναμιν. οἱ δὲ περὶ τὸν Ἀντίπατρον ἐπίλεκτοι καὶ τὸ ἄλλο τάγμα τῶν Ἰουδαίων, ὧν Μάλιχος ἦρχεν καὶ Πειθόλαος, συμμίξαντες τοῖς περὶ Μᾶρκον Ἀντώνιον ἡγεμόσιν ὑπήντων Ἀλεξάνδρῳ. καὶ μετ’ οὐ πολὺ παρῆν ἅμα τῇ φάλαγγι Γαβίνιος. ἑνουμένην δὲ τὴν τῶν πολεμίων δύναμιν οὐχ ὑπομείνας Ἀλέξανδρος ἀνεχώρει καὶ πλησίον ἤδη Ἱεροσολύμων γενόμενος ἀναγκάζεται συμβαλεῖν καὶ κατὰ τὴν μάχην ἑξακισχιλίους ἀποβαλών, ὧν τρισχίλιοι μὲν ἔπεσον τρισχίλιοι δὲ ἐζωγρήθησαν, φεύγει σὺν τοῖς καταλειφθεῖσιν εἰς Ἀλεξάνδρειον.", "st": "1.8.3"}, {"sp": "N", "t": "Γαβίνιος δὲ πρὸς τὸ Ἀλεξάνδρειον ἐλθὼν ἐπειδὴ πολλοὺς εὗρεν ἐστρατοπεδευμένους, ἐπειρᾶτο συγγνώμης ὑποσχέσει περὶ τῶν ἡμαρτημένων πρὸ μάχης αὐτοὺς προσαγαγέσθαι· μηδὲν δὲ μέτριον φρονούντων ἀποκτείνας πολλοὺς τοὺς λοιποὺς ἀπέκλεισεν εἰς τὸ ἔρυμα. κατὰ ταύτην ἀριστεύει τὴν μάχην ὁ ἡγεμὼν Μᾶρκος Ἀντώνιος, πανταχοῦ μὲν γενναῖος ἀεὶ φανείς, οὐδαμοῦ δ’ οὕτως. Γαβίνιος δὲ τοὺς ἐξαιρήσοντας τὸ φρούριον καταλιπὼν αὐτὸς ἐπῄει τὰς μὲν ἀπορθήτους πόλεις καθιστάμενος, τὰς δὲ κατεστραμμένας ἀνακτίζων. συνεπολίσθησαν γοῦν τούτου κελεύσαντος Σκυθόπολίς τε καὶ Σαμάρεια καὶ Ἀνθηδὼν καὶ Ἀπολλωνία καὶ Ἰάμνεια καὶ Ῥάφεια Μάρισά τε καὶ Ἀδώρεος καὶ Γάβαλα καὶ Ἄζωτος καὶ ἄλλαι πολλαί, τῶν οἰκητόρων ἀσμένως ἐφ’ ἑκάστην συνθεόντων.", "st": "1.8.4"}, {"sp": "N", "t": "Μετὰ δὲ τὴν τούτων ἐπιμέλειαν ἐπανελθὼν πρὸς τὸ Ἀλεξάνδρειον ἐπέρρωσεν τὴν πολιορκίαν, ὥστε Ἀλέξανδρος ἀπογνοὺς περὶ τῶν ὅλων ἐπικηρυκεύεται πρὸς αὐτόν, συγγνωσθῆναί τε τῶν ἡμαρτημένων δεόμενος καὶ τὰ συλληφθέντα φρούρια παραδιδοὺς Ὑρκάνειον καὶ Μαχαιροῦντα· αὖθις δὲ καὶ τὸ Ἀλεξάνδρειον ἐνεχείρισεν. ἃ πάντα Γαβίνιος ἐναγούσης τῆς Ἀλεξάνδρου μητρὸς κατέστρεψεν, ὡς μὴ πάλιν ὁρμητήριον γένοιτο δευτέρου πολέμου· παρῆν δὲ μειλισσομένη τὸν Γαβίνιον κατὰ δέος τῶν ἐπὶ τῆς Ῥώμης αἰχμαλώτων, τοῦ τε ἀνδρὸς καὶ τῶν ἄλλων τέκνων. μετὰ δὲ ταῦτα εἰς Ἱεροσόλυμα Γαβίνιος Ὑρκανὸν καταγαγὼν καὶ τὴν τοῦ ἱεροῦ παραδοὺς κηδεμονίαν αὐτῷ καθίστατο τὴν ἄλλην πολιτείαν ἐπὶ προστασίᾳ τῶν ἀρίστων. διεῖλεν δὲ πᾶν τὸ ἔθνος εἰς πέντε συνόδους, τὸ μὲν Ἱεροσολύμοις προστάξας, τὸ δὲ Γαδάροις, οἱ δὲ ἵνα συντελῶσιν εἰς Ἀμαθοῦντα, τὸ δὲ τέταρτον εἰς Ἱεριχοῦντα κεκλήρωτο, καὶ τῷ πέμπτῳ Σέπφωρις ἀπεδείχθη πόλις τῆς Γαλιλαίας. ἀσμένως δὲ τῆς ἐξ ἑνὸς ἐπικρατείας ἐλευθερωθέντες τὸ λοιπὸν ἀριστοκρατίᾳ διῳκοῦντο.", "st": "1.8.5"}, {"sp": "N", "t": "Μετ’ οὐ πολύ γε μὴν αὐτοῖς ἀρχὴ γίνεται θορύβων Ἀριστόβουλος ἀποδρὰς ἐκ Ῥώμης, ὃς αὖθις πολλοὺς Ἰουδαίων ἐπισυνίστη, τοὺς μὲν ἐπιθυμοῦντας μεταβολῆς, τοὺς δὲ ἀγαπῶντας αὐτὸν πάλαι. καὶ τὸ μὲν πρῶτον καταλαβόμενος τὸ Ἀλεξάνδρειον ἀνατειχίζειν ἐπειρᾶτο· ὡς δὲ Γαβίνιος ὑπὸ Σισέννᾳ καὶ Ἀντωνίῳ καὶ Σερουιανῷ στρατιὰν ἔπεμψεν ἐπ’ αὐτόν. γνοὺς ἀνεχώρει ἐπὶ Μαχαιροῦντος. καὶ τὸν μὲν ἄχρηστον ὄχλον ἀπεφορτίσατο, μόνους δὲ ἐπήγετο τοὺς ὡπλισμένους ὄντας εἰς ὀκτακισχιλίους, ἐν οἷς καὶ Πειθόλαος ἦν ὁ ἐξ Ἱεροσολύμων ὑποστράτηγος αὐτομολήσας μετὰ χιλίων. Ῥωμαῖοι δ’ ἐπηκολούθουν, καὶ γενομένης συμβολῆς μέχρι πολλοῦ μὲν οἱ περὶ τὸν Ἀριστόβουλον διεκαρτέρουν γενναίως ἀγωνιζόμενοι, τέλος δὲ βιασθέντες ὑπὸ τῶν Ῥωμαίων πίπτουσι μὲν πεντακισχίλιοι, περὶ δὲ δισχιλίους ἀνέφυγον εἴς τινα λόφον, οἱ δὲ λοιποὶ χίλιοι σὺν Ἀριστοβούλῳ διακόψαντες τὴν φάλαγγα τῶν Ῥωμαίων εἰς Μαχαιροῦντα συνελαύνονται. ἔνθα δὴ τὴν πρώτην ἑσπέραν ὁ βασιλεὺς τοῖς ἐρειπίοις ἐναυλισάμενος ἐν ἐλπίσι μὲν ἦν ἄλλην συναθροίσειν δύναμιν ἀνοχὴν τοῦ πολέμου διδόντος καὶ τὸ φρούριον κακῶς ὠχύρου· προσπεσόντων δὲ Ῥωμαίων ἐπὶ δύο ἡμέρας ἀντισχὼν ὑπὲρ δύναμιν ἁλίσκεται καὶ μετ’ Ἀντιγόνου τοῦ παιδός, ὃς ἀπὸ Ῥώμης αὐτῷ συναπέδρα, δεσμώτης ἐπὶ Γαβίνιον ἀνήχθη καὶ ἀπὸ Γαβινίου πάλιν εἰς Ῥώμην. τοῦτον μὲν οὖν ἡ σύγκλητος εἷρξεν, τὰ τέκνα δ’ αὐτοῦ διῆγεν εἰς Ἰουδαίαν Γαβινίου δι’ ἐπιστολῶν δηλώσαντος τῇ Ἀριστοβούλου γυναικὶ τοῦτο ἀντὶ τῆς παραδόσεως τῶν ἐρυμάτων ὡμολογηκέναι.", "st": "1.8.6"}, {"sp": "N", "t": "Γαβινίῳ δ’ ἐπὶ Πάρθους ὡρμημένῳ στρατεύειν γίνεται Πτολεμαῖος ἐμπόδιον· ὃς ὑποστρέψας ἀπ’ Εὐφράτου κατῆγεν εἰς Αἴγυπτον ἐπιτηδείοις εἰς ἅπαντα χρώμενος κατὰ τὴν στρατείαν Ὑρκανῷ καὶ Ἀντιπάτρῳ· καὶ γὰρ χρήματα καὶ ὅπλα καὶ σῖτον καὶ ἐπικούρους Ἀντίπατρος προσῆγεν, καὶ τοὺς ταύτῃ Ἰουδαίους φρουροῦντας τὰς κατὰ τὸ Πηλούσιον ἐμβολὰς παρεῖναι Γαβίνιον ἔπεισεν. τῆς δ’ ἄλλης Συρίας πρὸς τὸν Γαβινίου χωρισμὸν κινηθείσης καὶ Ἰουδαίους πάλιν ἀπέστησεν Ἀλέξανδρος ὁ Ἀριστοβούλου, μεγίστην δὲ συγκροτήσας δύναμιν ὥρμητο πάντας τοὺς κατὰ τὴν χώραν Ῥωμαίους ἀνελεῖν. πρὸς ὃ Γαβίνιος δείσας, ἤδη δὲ παρῆν ἀπ’ Αἰγύπτου τοῖς τῇδε θορύβοις ἠπειγμένος, ἐπὶ τινὰς μὲν τῶν ἀφεστώτων Ἀντίπατρον προπέμψας μετέπεισεν, συνέμενον δὲ Ἀλεξάνδρῳ τρεῖς μυριάδες, κἀκεῖνος ὥρμητο πολεμεῖν. οὕτως ἔξεισιν πρὸς μάχην. ὑπήντων δὲ οἱ Ἰουδαῖοι, καὶ συμβαλόντων περὶ τὸ Ἰταβύριον ὄρος μύριοι μὲν ἀναιροῦνται, τὸ δὲ λοιπὸν πλῆθος ἐσκεδάσθη φυγῇ. καὶ Γαβίνιος ἐλθὼν εἰς Ἱεροσόλυμα πρὸς τὸ Ἀντιπάτρου βούλημα κατεστήσατο τὴν πολιτείαν. ἔνθεν ὁρμήσας Ναβαταίων τε μάχῃ κρατεῖ καὶ Μιθριδάτην καὶ Ὀρσάνην φυγόντας ἐκ Πάρθων κρύφα μὲν ἀπέπεμψεν, παρὰ δὲ τοῖς στρατιώταις ἔλεγεν ἀποδρᾶναι.", "st": "1.8.7"}, {"sp": "N", "t": "Κἀν τούτῳ Κράσσος αὐτῷ διάδοχος ἐλθὼν παραλαμβάνει Συρίαν. οὗτος εἰς τὴν ἐπὶ Πάρθους στρατείαν τόν τε ἄλλον τοῦ ἐν Ἱεροσολύμοις ναοῦ χρυσὸν πάντα περιεῖλεν καὶ τὰ δισχίλια τάλαντα ἦρεν, ὧν ἀπέσχετο Πομπήιος. διαβὰς δὲ τὸν Εὐφράτην αὐτός τε ἀπώλετο καὶ ὁ στρατὸς αὐτοῦ, περὶ ὧν οὐ νῦν καιρὸς λέγειν.", "st": "1.8.8"}, {"sp": "N", "t": "Πάρθους δὲ μετὰ τὸν Κράσσον ἐπιδιαβαίνειν εἰς Συρίαν ὡρμημένους ἀνέκοπτεν Κάσσιος εἰς τὴν ἐπαρχίαν διαφυγών. περιποιησάμενος δὲ αὐτὴν ἐπὶ Ἰουδαίους ἠπείγετο, καὶ Ταριχέας μὲν ἑλὼν εἰς τρεῖς μυριάδας Ἰουδαίων ἀνδραποδίζεται, κτείνει δὲ καὶ Πειθόλαον τοὺς Ἀριστοβούλου στασιαστὰς ἐπισυνιστάντα· τοῦ φόνου δὲ ἦν σύμβουλος Ἀντίπατρος. τούτῳ γήμαντι γυναῖκα τῶν ἐπισήμων ἐξ Ἀραβίας Κύπρον τοὔνομα τέσσαρες μὲν υἱεῖς γίνονται, Φασάηλος καὶ ὁ βασιλεὺς αὖθις Ἡρώδης, πρὸς οἷς Ἰώσηπος καὶ Φερώρας καὶ Σαλώμη θυγάτηρ. ἐξῳκειωμένος δὲ τοὺς πανταχοῦ δυνατοὺς φιλίαις τε καὶ ξενίαις μάλιστα προσηγάγετο τὸν Ἀράβων βασιλέα διὰ τὴν ἐπιγαμβρίαν, κἀπειδὴ τὸν πρὸς τὸν Ἀριστόβουλον ἀνείλετο πόλεμον, ἐκείνῳ παρακαταθήκην ἔπεμψεν τὰ τέκνα. Κάσσιος δὲ κατὰ συνθήκας ἡσυχάζειν Ἀλέξανδρον ἀναγκάσας ἐπὶ τὸν Εὐφράτην ὑπέστρεψεν Πάρθους διαβαίνειν ἀνείρξων, περὶ ὧν ἐν ἑτέροις ἐροῦμεν.", "st": "1.8.9"}, {"sp": "N", "t": "Καῖσαρ δὲ Πομπηίου καὶ τῆς συγκλήτου φυγόντων ὑπὲρ τὸν Ἰόνιον Ῥώμης καὶ τῶν ὅλων κρατήσας ἀνίησι μὲν τῶν δεσμῶν τὸν Ἀριστόβουλον, παραδοὺς δ’ αὐτῷ δύο τάγματα κατὰ τάχος ἔπεμψεν εἰς Συρίαν, ταύτην τε ῥᾳδίως ἐλπίσας καὶ τὰ περὶ τὴν Ἰουδαίαν δι’ αὐτοῦ προσάξεσθαι. φθάνει δ’ ὁ φθόνος καὶ τὴν Ἀριστοβούλου προθυμίαν καὶ τὰς Καίσαρος ἐλπίδας· φαρμάκῳ γοῦν ἀναιρεθεὶς ὑπὸ τῶν τὰ Πομπηίου φρονούντων μέχρι πολλοῦ μὲν οὐδὲ ταφῆς ἐν τῇ πατρῴᾳ χώρᾳ μετεῖχεν, ἔκειτο δὲ μέλιτι συντηρούμενος ὁ νεκρὸς αὐτοῦ, ἕως ὑπ’ Ἀντωνίου Ἰουδαίοις ἐπέμφθη τοῖς βασιλικοῖς μνημείοις ἐνταφησόμενος.", "st": "1.9.1"}, {"sp": "N", "t": "Ἀναιρεῖται δὲ καὶ ὁ υἱὸς αὐτοῦ Ἀλέξανδρος πελέκει ὑπὸ Σκιπίωνος ἐν Ἀντιοχείᾳ Πομπηίου τοῦτ’ ἐπιστείλαντος καὶ γενομένης κατηγορίας πρὸ τοῦ βήματος ὧν Ῥωμαίους ἔβλαψεν. τοὺς δ’ ἀδελφοὺς αὐτοῦ Πτολεμαῖος ὁ Μενναίου παραλαβών, ὃς ἐκράτει τῆς ὑπὸ τῷ Λιβάνῳ Χαλκίδος, Φιλιππίωνα τὸν υἱὸν ἐπ’ αὐτοὺς εἰς Ἀσκάλωνα πέμπει. κἀκεῖνος ἀποσπάσας τῆς Ἀριστοβούλου γυναικὸς Ἀντίγονον καὶ τὰς ἀδελφὰς αὐτοῦ πρὸς τὸν πατέρα ἀνήγαγεν. ἁλοὺς δ’ ἔρωτι γαμεῖ τὴν ἑτέραν καὶ μετὰ ταῦτα ὑπὸ τοῦ πατρὸς δι’ αὐτὴν κτείνεται· γαμεῖ γὰρ Πτολεμαῖος τὴν Ἀλεξάνδραν ἀνελὼν τὸν υἱὸν καὶ διὰ τὸν γάμον κηδεμονικώτερος αὐτὸς ἦν πρὸς τοὺς ἀδελφούς.", "st": "1.9.2"}, {"sp": "N", "t": "Ἀντίπατρος δὲ μετὰ τὴν Πομπηίου τελευτὴν μεταβὰς ἐθεράπευεν Καίσαρα, κἀπειδὴ Μιθριδάτης ὁ Περγαμηνὸς μεθ’ ἧς ἦγεν ἐπ’ Αἴγυπτον δυνάμεως εἰργόμενος τῶν κατὰ τὸ Πηλούσιον ἐμβολῶν ἐν Ἀσκάλωνι κατείχετο, τούς τε Ἄραβας ξένος ὢν ἔπεισεν ἐπικουρῆσαι καὶ αὐτὸς ἧκεν ἄγων Ἰουδαίων εἰς τρισχιλίους ὁπλίτας. παρώρμησεν δὲ καὶ τοὺς ἐν Συρίᾳ δυνατοὺς ἐπὶ τὴν βοήθειαν τόν τε ἔποικον τοῦ Λιβάνου Πτολεμαῖον καὶ Ἰάμβλιχον, δι’ οὓς αἱ ταύτῃ πόλεις ἑτοίμως συνεφήψαντο τοῦ πολέμου. καὶ θαρρῶν ἤδη Μιθριδάτης τῇ προσγενομένῃ δι’ Ἀντίπατρον ἰσχύι πρὸς τὸ Πηλούσιον ἐξελαύνει κωλυόμενός τε διελθεῖν ἐπολιόρκει τὴν πόλιν. γίνεται δὲ κἀν τῇ προσβολῇ διασημότατος Ἀντίπατρος· τὸ γὰρ κατ’ αὐτὸν μέρος τοῦ τείχους διαρρήξας πρῶτος εἰσεπήδησεν εἰς τὴν πόλιν μετὰ τῶν σὺν αὐτῷ.", "st": "1.9.3"}, {"sp": "N", "t": "Καὶ τὸ Πηλούσιον μὲν ἑάλω, πρόσω δ’ αὐτὸν ἰόντα εἶργον αὖθις οἱ τὴν Ὀνίου προσαγορευομένην χώραν κατέχοντες· ἦσαν δὲ Ἰουδαῖοι Αἰγύπτιοι. τούτους Ἀντίπατρος οὐ μόνον μὴ κωλύειν ἔπεισεν, ἀλλὰ καὶ τὰ ἐπιτήδεια τῇ δυνάμει παρασχεῖν· ὅθεν οὐδὲ οἱ κατὰ Μέμφιν ἔτι εἰς χεῖρας ἦλθον, ἑκούσιοι δὲ προσέθεντο Μιθριδάτῃ. κἀκεῖνος ἤδη τὸ Δέλτα περιελθὼν συνέβαλλεν τοῖς λοιποῖς Αἰγυπτίοις εἰς μάχην κατὰ χῶρον, ὃς Ἰουδαίων στρατόπεδον καλεῖται. κινδυνεύοντα δ’ αὐτὸν ἐν τῇ παρατάξει σὺν ὅλῳ τῷ δεξιῷ κέρατι ῥύεται περιελθὼν Ἀντίπατρος παρὰ τὸν αἰγιαλὸν τοῦ ποταμοῦ· τῶν γὰρ καθ’ ἑαυτὸν ἐκράτει τὸ λαιὸν ἔχων κέρας· ἔπειτα προσπεσὼν τοῖς διώκουσι Μιθριδάτην ἀπέκτεινεν πολλοὺς καὶ μέχρι τοσούτου τοὺς καταλειπομένους ἐδίωξεν ὡς καὶ τὸ στρατόπεδον αὐτῶν ἑλεῖν. ὀγδοήκοντα δὲ μόνους τῶν ἰδίων ἀπέβαλεν, καὶ Μιθριδάτης ἐν τῇ τροπῇ περὶ ὀκτακοσίους. σωθεὶς δ’ αὐτὸς παρ’ ἐλπίδα μάρτυς ἀβάσκανος γίνεται πρὸς Καίσαρα τῶν Ἀντιπάτρου κατορθωμάτων.", "st": "1.9.4"}, {"sp": "N", "t": "Ὁ δὲ τότε μὲν τὸν ἄνδρα τοῖς ἐπαίνοις καὶ ταῖς ἐλπίσιν εἰς τοὺς ὑπὲρ αὐτοῦ κινδύνους ἐπέρρωσεν, ἐν οἷς πᾶσιν παραβολώτατος ἀγωνιστὴς γενόμενος καὶ πολλὰ τρωθεὶς ἐφ’ ὅλου σχεδὸν τοῦ σώματος εἶχεν τὰ σημεῖα τῆς ἀρετῆς. αὖθις δὲ καταστησάμενος τὰ κατὰ τὴν Αἴγυπτον ὡς ἐπανῆκεν εἰς Συρίαν, πολιτείᾳ τε αὐτὸν τῇ Ῥωμαίων ἐδωρήσατο καὶ ἀτελείᾳ τῆς τε ἄλλης τιμῆς καὶ φιλοφρονήσεως ἕνεκεν ζηλωτὸν ἐποίησεν καὶ τὴν ἀρχιερωσύνην δὲ δι’ αὐτὸν ἐπεκύρωσεν Ὑρκανῷ.", "st": "1.9.5"}, {"sp": "N", "t": "Κατ’ αὐτὸ δὲ καὶ Ἀντίγονος ὁ Ἀριστοβούλου πρὸς τὸν Καίσαρα παρὼν γίνεται παραδόξως Ἀντιπάτρῳ μείζονος προκοπῆς αἴτιος· δέον γὰρ ἀποδύρεσθαι περὶ τοῦ πατρὸς πεφαρμάχθαι δοκοῦντος ἐκ τῶν πρὸς Πομπήιον διαφορῶν καὶ περὶ τἀδελφοῦ τὴν Σκιπίωνος ὠμότητα μέμφεσθαι καὶ μηδὲν εἰς τὸν ἔλεον παραμῖξαι φθονερὸν πάθος, ὁ δὲ ἐπὶ τούτοις Ὑρκανοῦ καὶ Ἀντιπάτρου κατηγόρει παρελθών, ὡς παρανομώτατα μὲν αὐτὸν μετὰ τῶν ἀδελφῶν πάσης ἀπελαύνοιεν τῆς πατρίου γῆς, πολλὰ δ’ εἰς τὸ ἔθνος αὐτοὶ διὰ κόρον ἐξυβρίζοιεν, καὶ ὅτι τὴν εἰς Αἴγυπτον συμμαχίαν οὐκ ἐπ’ εὐνοίᾳ αὐτῷ πέμψειαν, ἀλλὰ κατὰ δέος τῶν πάλαι διαφορῶν καὶ τὴν πρὸς τὸν Πομπήιον φιλίαν ἀποσκευαζόμενοι.", "st": "1.10.1"}, {"sp": "N", "t": "Πρὸς ταῦτα ὁ Ἀντίπατρος ἀπορρίψας τὴν ἐσθῆτα τὸ πλῆθος ἐπεδείκνυεν τῶν τραυμάτων, καὶ περὶ μὲν τῆς εἰς Καίσαρα εὐνοίας οὐκ ἔφη λόγου δεῖν αὐτῷ· κεκραγέναι γὰρ τὸ σῶμα σιωπῶντος· Ἀντιγόνου δὲ θαυμάζειν τὴν τόλμαν, εἰ πολεμίου Ῥωμαίων υἱὸς ὢν καὶ Ῥωμαίων δραπέτου καὶ τὸ νεωτεροποιὸς εἶναι καὶ στασιώδης αὐτὸς πατρῷον ἔχων, παρὰ τῷ Ῥωμαίων ἡγεμόνι κατηγορεῖν ἐπικεχείρηκεν ἑτέρων καὶ πειρᾶται τυχεῖν ἀγαθοῦ τινος, δέον ἀγαπᾶν ὅτι ζῇ· καὶ γὰρ νῦν ἐφίεσθαι πραγμάτων οὐ τοσοῦτον δι’ ἀπορίαν, ἀλλ’ ἵνα Ἰουδαίους διαστασιάσῃ παρελθὼν καὶ χρήσηται κατὰ τῶν δόντων ταῖς ἀφορμαῖς.", "st": "1.10.2"}, {"sp": "N", "t": "Τούτων Καῖσαρ ἀκούσας Ὑρκανὸν μὲν ἀξιώτερον τῆς ἀρχιερωσύνης ἀπεφήνατο, Ἀντιπάτρῳ δὲ δυναστείας αἵρεσιν ἔδωκεν. ὁ δ’ ἐπὶ τῷ τιμήσαντι τὸ μέτρον τῆς τιμῆς θέμενος πάσης ἐπίτροπος Ἰουδαίας ἀποδείκνυται καὶ προσεπιτυγχάνει τὰ τείχη τῆς πατρίδος ἀνακτίσαι κατεστραμμένα. τὰς μὲν δὴ τιμὰς ταύτας Καῖσαρ ἐπέστελλεν ἐν τῷ Καπετωλίῳ χαραχθῆναι τῆς τε αὐτοῦ δικαιοσύνης σημεῖον καὶ τῆς τἀνδρὸς ἐσομένας ἀρετῆς.", "st": "1.10.3"}, {"sp": "N", "t": "Ἀντίπατρος δὲ Καίσαρα προπέμψας ἐκ τῆς Συρίας εἰς Ἰουδαίαν ὑπέστρεψεν. καὶ πρῶτον μὲν τὸ τεῖχος ἀνεδείματο τῆς πατρίδος ὑπὸ Πομπηίου κατεστραμμένον καὶ τοὺς ἀνὰ τὴν χώραν θορύβους ἐπιὼν κατέστελλεν, ἀπειλητὴς ἅμα καὶ σύμβουλος ὢν ἑκάστοις, ὅτι τὰ μὲν Ὑρκανοῦ φρονοῦντες ἐν ὄλβῳ καὶ καθ’ ἡσυχίαν βιώσονται τῶν τε ἰδίων κτημάτων καὶ κοινῆς εἰρήνης ἀπολαύοντες· εἰ δὲ πείθοιντο ταῖς ψυχραῖς ἐλπίσιν τῶν νεωτερίζειν ἐπὶ κέρδεσιν οἰκείοις ἐθελόντων, ὡς αὐτόν τε πειράσουσιν ἀντὶ κηδεμόνος δεσπότην καὶ Ὑρκανὸν ἀντὶ βασιλέως τύραννον, Ῥωμαίους γε μὴν καὶ Καίσαρα πολεμίους ἀνθ’ ἡγεμόνων καὶ φίλων· οὐ γὰρ ἀνέξεσθαι μετακινούμενον ἐκ τῆς ἀρχῆς ὃν αὐτοὶ κατέστησαν. ἅμα δὲ ταῦτα λέγων καὶ δι’ αὑτοῦ καθίστατο τὴν χώραν ὁρῶν τὸν Ὑρκανὸν νωθῆ τε καὶ βασιλείας ἀτονώτερον. Φασάηλον μὲν δὴ τῶν παίδων τὸν πρεσβύτατον Ἱεροσολύμων καὶ τῶν πέριξ στρατηγὸν καθίστησιν, τὸν δὲ μετ’ αὐτὸν Ἡρώδην ἐπὶ τοῖς ἴσοις ἔστειλεν εἰς Γαλιλαίαν κομιδῇ νέον.", "st": "1.10.4"}, {"sp": "N", "t": "Ὁ δὲ ὢν φύσει δραστήριος ὕλην εὐθέως εὑρίσκει τῷ φρονήματι. καταλαβὼν οὖν Ἐζεκίαν τὸν ἀρχιλῃστὴν τὰ προσεχῆ τῇ Συρίᾳ κατατρέχοντα μετὰ μεγίστου στίφους αὐτόν τε συλλαβὼν ἀποκτείνει καὶ πολλοὺς τῶν λῃστῶν. ὃ δὴ μάλιστα τοῖς Σύροις ἡγεῖτο κεχαρισμένον· ὑμνεῖτο γοῦν ἀνά τε τὰς κώμας καὶ ἐν ταῖς πόλεσιν Ἡρώδης ὡς εἰρήνην αὐτοῖς καὶ τὰς κτήσεις ἀνασεσωκώς. γίνεται δ’ ἐκ τούτου καὶ Σέξτῳ Καίσαρι γνώριμος ὄντι συγγενεῖ τοῦ μεγάλου Καίσαρος καὶ διοικοῦντι τὴν Συρίαν. πρὸς δὲ τὸν ἀδελφὸν εὐδοκιμοῦντα καὶ Φασάηλος ἐφιλοτιμεῖτο τὴν ἀγαθὴν ἔριν τοὺς ἐν τοῖς Ἱεροσολύμοις εὐνουστέρους καθιστάμενος καὶ δι’ αὑτοῦ μὲν ἔχων τὴν πόλιν μηδὲν δὲ ἀπειροκάλως εἰς τὴν ἐξουσίαν ἐξυβρίζων. ἐντεῦθεν Ἀντιπάτρῳ θεραπεία τε ἦν ἐκ τοῦ ἔθνους βασιλικὴ καὶ τιμαὶ παρὰ πάντων ὡς δεσπότῃ τῶν ὅλων· οὐ μὴν αὐτὸς τῆς πρὸς Ὑρκανὸν εὐνοίας ἢ πίστεώς τι μετεκίνησεν.", "st": "1.10.5"}, {"sp": "N", "t": "Ἀμήχανον δ’ ἐν εὐπραγίαις φθόνον διαφυγεῖν· Ὑρκανὸς γοῦν ἤδη μὲν καὶ καθ’ ἑαυτὸν ἡσυχῆ πρὸς τὸ κλέος τῶν νεανίσκων ἐδάκνετο, μάλιστα δὲ ἐλύπει τὰ Ἡρώδου κατορθώματα καὶ κήρυκες ἐπάλληλοι τῆς καθ’ ἕκαστον εὐδοξίας προστρέχοντες πολλοὶ [δὲ] τῶν ἐν τοῖς βασιλείοις βασκάνων ἠρέθιζον, οἷς ἢ τὸ τῶν παίδων ἢ τὸ Ἀντιπάτρου σωφρονικὸν προσίστατο, λέγοντες ὡς Ἀντιπάτρῳ καὶ τοῖς υἱοῖς αὐτοῦ παραχωρήσας τῶν πραγμάτων καθέζοιτο τοὔνομα μόνον βασιλέως ἔχων ἔρημον ἐξουσίας. καὶ μέχρι τοῦ πλανηθήσεται καθ’ ἑαυτοῦ βασιλεῖς ἐπιτρέφων; οὐδὲ γὰρ εἰρωνεύεσθαι τὴν ἐπιτροπὴν αὐτοὺς ἔτι, φανεροὺς δὲ εἶναι δεσπότας παρωσαμένους ἐκεῖνον, εἴ γε μήτε ἐντολὰς δόντος μήτε ἐπιστείλαντος αὐτοῦ τοσούτους παρὰ τὸν τῶν Ἰουδαίων νόμον ἀνῄρηκεν Ἡρώδης· ὅν, εἰ μὴ βασιλεύς ἐστιν ἀλλ’ ἔτι ἰδιώτης, δεῖν ἐπὶ δίκην ἥκειν ἀποδώσοντα λόγον αὐτῷ τε καὶ τοῖς πατρίοις νόμοις, οἳ κτείνειν ἀκρίτους οὐκ ἐφιᾶσιν.", "st": "1.10.6"}, {"sp": "N", "t": "Τούτοις κατὰ μικρὸν Ὑρκανὸς ἐξεκαίετο καὶ τὴν ὀργὴν τελευταῖον ἐκρήξας ἐκάλει κριθησόμενον τὸν Ἡρώδην. ὁ δὲ καὶ τοῦ πατρὸς παραινοῦντος καὶ τῶν πραγμάτων διδόντων παρρησίαν ἀνῄει φρουραῖς διαλαβὼν πρότερον τὴν Γαλιλαίαν. ᾔει δὲ μετὰ καρτεροῦ στίφους, ὡς μήτε καταλύειν δόξειεν Ὑρκανὸν λαμπρὰν ἄγων δύναμιν μήτε γυμνὸς ἐμπέσοι τῷ φθόνῳ. Σέξτος δὲ Καῖσαρ δείσας περὶ τῷ νεανίᾳ, μή τι παρὰ τοῖς ἐχθροῖς ἀποληφθεὶς πάθῃ, πέμπει πρὸς Ὑρκανὸν τοὺς παραγγελοῦντας διαρρήδην ἀπολύειν Ἡρώδην τῆς φονικῆς δίκης. ὁ δὲ καὶ ἄλλως ὡρμημένος, ἠγάπα γὰρ Ἡρώδην, ἀποψηφίζεται.", "st": "1.10.7"}, {"sp": "N", "t": "Καὶ ὃς ὑπολαμβάνων ἄκοντος τοῦ βασιλέως διαφυγεῖν εἰς Δαμασκὸν ἀνεχώρησεν πρὸς Σέξτον παρασκευαζόμενος οὐδὲ αὖθις ὑπακοῦσαι καλοῦντι. καὶ πάλιν οἱ πονηροὶ παρώξυνον τὸν Ὑρκανὸν κατ’ ὀργήν τε οἴχεσθαι τὸν Ἡρώδην λέγοντες καὶ παρεσκευασμένον κατ’ αὐτοῦ· πιστεύων δ’ ὁ βασιλεὺς οὐκ εἶχεν ὅ τι χρὴ δρᾶν. ὡς ἑώρα μείζονα τὸν διάφορον. ἐπεὶ δὲ ὑπὸ Σέξτου Καίσαρος στρατηγὸς ἀνεδείχθη κοίλης Συρίας καὶ Σαμαρείας οὐ μόνον τε κατ’ εὔνοιαν τὴν ἐκ τοῦ ἔθνους ἀλλὰ καὶ δυνάμει φοβερὸς ἦν. εἰς ἔσχατον δέους κατέπεσεν Ὑρκανός, ὅσον οὔπω προσδοκῶν ἐπ’ αὐτὸν ὁρμήσειν μετὰ στρατιᾶς.", "st": "1.10.8"}, {"sp": "N", "t": "Καὶ οὐ διήμαρτεν τῆς οἰήσεως· ὁ γὰρ Ἡρώδης κατ’ ὀργὴν τῆς περὶ τὴν δίκην ἀπειλῆς στρατιὰν ἀθροίσας ἐπὶ Ἱεροσολύμων ἦγεν καταλύσων τὸν Ὑρκανόν. κἂν ἔφθη τοῦτο ποιήσας, εἰ μὴ προεξελθόντες ὅ τε πατὴρ καὶ ὁ ἀδελφὸς ἔκλασαν αὐτοῦ τὴν ὁρμὴν παρακαλοῦντες καὶ αὐτὸν ἀπειλῇ καὶ ἀνατάσει μόνῃ μετρῆσαι τὴν ἄμυναν, φείσασθαι δὲ τοῦ βασιλέως, ὑφ’ οὗ μέχρι τοσαύτης δυνάμεως προῆλθεν· δεῖν τε, εἰ κληθεὶς ἐπὶ δίκην παρώξυνται, καὶ περὶ τῆς ἀφέσεως εὐχαριστεῖν καὶ μὴ πρὸς μὲν τὸ σκυθρωπὸν ἀπαντᾶν, περὶ δὲ τῆς σωτηρίας ἀχάριστον εἶναι. εἰ δὲ δὴ λογιστέον εἴη καὶ πολέμου ῥοπὰς βραβεύεσθαι θεῷ, πλέον εἶναι τῆς στρατείας τὸ ἄδικον. διὸ δὴ καὶ περὶ τῆς νίκης οὐ χρὴ κατὰ πᾶν εὔελπιν εἶναι, μέλλοντά γε συμβαλεῖν βασιλεῖ καὶ συντρόφῳ καὶ πολλάκις μὲν εὐεργέτῃ, χαλεπῷ δὲ οὐδέποτε, πλὴν ὅσον πονηροῖς συμβούλοις χρώμενος ἐπισείσειεν αὐτῷ σκιὰν ἀδικήματος. πείθεται τούτοις Ἡρώδης ὑπολαβὼν εἰς τὰς ἐλπίδας αὔταρκες εἶναι καὶ τὸ τὴν ἰσχὺν ἐπιδείξασθαι τῷ ἔθνει.", "st": "1.10.9"}, {"sp": "N", "t": "Κἀν τούτῳ γίνεται περὶ Ἀπάμειαν ταραχὴ Ῥωμαίων καὶ πόλεμος ἐμφύλιος, Καικιλίου μὲν Βάσσου διὰ τὴν εἰς Πομπήιον εὔνοιαν δολοφονήσαντος Σέξτον Καίσαρα καὶ τὴν ἐκείνου δύναμιν παραλαβόντος, τῶν δ’ ἄλλων Καίσαρος στρατηγῶν ἐπὶ τιμωρίᾳ τοῦ φόνου μετὰ δυνάμεως συνελθόντων. οἷς καὶ διὰ τὸν ἀνῃρημένον καὶ διὰ τὸν περιόντα Καίσαρα φίλους ὄντας ἀμφοτέρους ὁ Ἀντίπατρος διὰ τῶν παίδων ἔπεμψεν συμμαχίαν. μηκυνομένου δὲ τοῦ πολέμου Μοῦρκος μὲν ἀπὸ τῆς Ἰταλίας Σέξτου παραγίνεται διάδοχος,", "st": "1.10.10"}, {"sp": "N", "t": "συνίσταται δὲ Ῥωμαίοις κατὰ τοῦτον τὸν καιρὸν ὁ μέγας πόλεμος Κασσίου καὶ Βρούτου κτεινάντων δόλῳ Καίσαρα κατασχόντα τὴν ἀρχὴν ἐπ’ ἔτη τρία καὶ μῆνας ἑπτά. μεγίστου δ’ ἐπὶ τῷ φόνῳ γενομένου κινήματος καὶ διαστασιασθέντων τῶν δυνατῶν ἕκαστος ἐλπίσιν οἰκείαις ἐχώρει πρὸς ὃ συμφέρειν ὑπελάμβανεν, καὶ δὴ καὶ Κάσσιος εἰς Συρίαν καταληψόμενος τὰς περὶ Ἀπάμειαν δυνάμεις. ἔνθα Βάσσῳ τε Μοῦρκον καὶ τὰ διεστῶτα τάγματα διαλλάξας ἐλευθεροῖ μὲν Ἀπάμειαν τῆς πολιορκίας, ἡγούμενος δ’ αὐτὸς τῆς στρατιᾶς ἐπῄει φορολογῶν τὰς πόλεις καὶ παρὰ δύναμιν τὰς εἰσπράξεις ποιούμενος.", "st": "1.11.1"}, {"sp": "N", "t": "Κελευσθὲν δὲ καὶ Ἰουδαίοις εἰσενεγκεῖν ἑπτακόσια τάλαντα δείσας Ἀντίπατρος τὴν ἀπειλὴν τοῦ Κασσίου τοῖς τε υἱοῖς διεῖλεν εἰσπράττειν τὰ χρήματα καί τισιν ἄλλοις τῶν ἐπιτηδείων κατὰ τάχος, ἐν οἷς καὶ Μαλίχῳ τινὶ τῶν διαφόρων· οὕτως ἤπειγεν ἡ ἀνάγκη. πρῶτος δ’ ἀπεμειλίξατο Κάσσιον Ἡρώδης τὴν ἑαυτοῦ μοῖραν ἐκ τῆς Γαλιλαίας κομίσας ἑκατὸν τάλαντα καὶ διὰ τοῦτο ἐν τοῖς μάλιστα φίλος ἦν. τοὺς δὲ λοιποὺς εἰς βραδυτῆτα κακίσας αὐταῖς ἐθυμοῦτο ταῖς πόλεσιν. Γόφνα γοῦν καὶ Ἀμμαοῦν καὶ δύο ἑτέρας τῶν ταπεινοτέρων ἐξανδραποδισάμενος ἐχώρει μὲν ὡς καὶ Μάλιχον ἀναιρήσων, ὅτι μὴ σπεύσας εἰσέπραξεν, ἐπέσχεν δὲ τὴν τούτου καὶ τὴν τῶν ἄλλων πόλεων ἀπώλειαν Ἀντίπατρος ταχέως ἑκατὸν ταλάντοις θεραπεύσας Κάσσιον.", "st": "1.11.2"}, {"sp": "N", "t": "Οὐ μὴν Μάλιχος ἀναχωρήσαντος Κασσίου τῆς χάριτος ἀπεμνημόνευσεν Ἀντιπάτρῳ, κατὰ δὲ τοῦ πολλάκις σωτῆρος ἐπιβουλὴν ἐνεσκευάζετο σπεύδων ἀνελεῖν τὸν ἐμπόδιον αὐτοῦ τοῖς ἀδικήμασιν Ἀντίπατρος δὲ τήν τε ἰσχὺν καὶ τὸ πανοῦργον τἀνδρὸς ὑποδείσας διαβαίνει τὸν Ἰορδάνην στρατὸν ἀθροίσων εἰς τὴν τῆς ἐπιβουλῆς ἄμυναν. φωραθεὶς δὲ Μάλιχος ἀναιδείᾳ τῶν Ἀντιπάτρου παίδων περιγίνεται· τόν τε γὰρ Ἱεροσολύμων φρουρὸν Φασάηλον καὶ Ἡρώδην πεπιστευμένον τὰ ὅπλα πολλαῖς ἀπολογίαις καὶ ὅρκοις ἐκγοητεύσας διαλλακτὰς αὐτῷ πρὸς τὸν πατέρα πείθει γίνεσθαι. πάλιν γοῦν ὑπ’ Ἀντιπάτρου σώζεται πείσαντος Μοῦρκον τὸν τότε στρατηγοῦντα Συρίας, ὃς ὥρμητο κτεῖναι Μάλιχον ἐφ’ οἷς ἐνεωτέρισεν.", "st": "1.11.3"}, {"sp": "N", "t": "Συστάντος δὲ τοῦ πρὸς Κάσσιον καὶ Βροῦτον πολέμου Καίσαρί τε τῷ νέῳ καὶ Ἀντωνίῳ Κάσσιος καὶ Μοῦρκος στρατιὰν ἀθροίσαντες ἐκ τῆς Συρίας, ἐπειδὴ μέγα μέρος εἰς τὰς χρείας Ἡρώδης ἔδοξε, τότε μὲν αὐτὸν Συρίας ἁπάσης ἐπιμελητὴν καθιστᾶσιν δύναμιν πεζήν τε καὶ ἱππικὴν δόντες, μετὰ δὲ τὴν τοῦ πολέμου κατάλυσιν ἀποδείξειν Κάσσιος ὑπέσχετο καὶ Ἰουδαίας βασιλέα. συνέβη δ’ Ἀντιπάτρῳ τήν τε ἰσχὺν τοῦ παιδὸς καὶ τὴν ἐλπίδα αἰτίαν ἀπωλείας γενέσθαι· ταῦτα γὰρ δείσας ὁ Μάλιχος διαφθείρει τινὰ τῶν βασιλικῶν οἰνοχόων χρήμασιν δοῦναι φάρμακον Ἀντιπάτρῳ. καὶ ὁ μὲν ἀγώνισμα τῆς Μαλίχου παρανομίας γενόμενος μετὰ τὸ συμπόσιον θνήσκει τά τε ἄλλα δραστήριος ἀνὴρ ἐν ἀφηγήσει πραγμάτων καὶ τὴν ἀρχὴν ἀνακτησάμενός τε Ὑρκανῷ καὶ διαφυλάξας·", "st": "1.11.4"}, {"sp": "N", "t": "Μάλιχος δὲ καθ’ ὑπόνοιαν τῆς φαρμακείας ὀργιζόμενον τὸ πλῆθος ἀρνούμενος ἔπειθεν καὶ δυνατώτερον ἑαυτὸν κατεσκεύαζεν ὁπλίτας συγκροτῶν· οὐ γὰρ ἠρεμήσειν Ἡρώδην ὑπελάμβανεν, ὃς δὴ καὶ παρῆν αὐτίκα στρατὸν ἄγων ἐπὶ τιμωρίᾳ τοῦ πατρός. Φασαήλου δὲ τἀδελφοῦ συμβουλεύσαντος αὐτῷ μὴ φανερῶς τὸν ἄνδρα μετιέναι, διαστασιάσειν γὰρ τὸ πλῆθος, τότε μὲν ἀπολογούμενόν τε προσίεται τὸν Μάλιχον καὶ τῆς ὑπονοίας ἀπολύειν ὡμολόγει, λαμπρὰν δὲ πομπὴν ἐπὶ τῷ πατρὶ κηδείας ἐτέλεσεν.", "st": "1.11.5"}, {"sp": "N", "t": "Τραπεὶς δ’ ἐπὶ Σαμάρειαν στάσει τεταραγμένην κατεστήσατο τὴν πόλιν· ἔπειτα καθ’ ἑορτὴν ὑπέστρεφεν εἰς Ἱεροσόλυμα τοὺς ὁπλίτας ἄγων. καὶ πέμπων Ὑρκανός, ἐνῆγεν γὰρ δεδοικὼς τὴν ἔφοδον Μάλιχος, ἐκώλυεν τοὺς ἀλλοφύλους εἰσαγαγεῖν ἐφ’ ἁγνεύοντας τοὺς ἐπιχωρίους. ὁ δὲ τῆς προφάσεως καταφρονήσας καὶ τοῦ προστάσσοντος εἰσέρχεται διὰ νυκτός. καὶ πάλιν Μάλιχος προσιὼν ἔκλαιεν Ἀντίπατρον· ἀνθυπεκρίνετο δὲ μόλις Ἡρώδης τὸν θυμὸν ἐπέχων καὶ Κασσίῳ δι’ ἐπιστολῶν τὴν τοῦ πατρὸς ἀναίρεσιν ἀπωδύρετο μισοῦντι καὶ ἄλλως Μάλιχον. ὁ δ’ αὐτῷ μετιέναι τὸν φονέα τοῦ πατρὸς ἀντεπιστείλας καὶ τοῖς ὑφ’ ἑαυτὸν χιλιάρχοις λάθρα προσέταξεν Ἡρώδῃ βοηθεῖν εἰς πρᾶξιν δικαίαν.", "st": "1.11.6"}, {"sp": "N", "t": "Καὶ ἐπειδὴ Λαοδίκειαν ἑλόντος αὐτοῦ συνῇσαν οἱ πανταχόθεν δυνατοὶ δωρεάς τε καὶ στεφάνους φέροντες, Ἡρώδης μὲν τοῦτον τῇ τιμωρίᾳ τὸν καιρὸν ἀφώρισεν, Μάλιχος δὲ ὑποπτεύσας, ὡς ἐν Τύρῳ γίνεται, τόν τε υἱὸν ὁμηρεύοντα παρὰ τοῖς Τυρίοις ὑπεξαγαγεῖν ἔγνω λάθρα καὶ αὐτὸς εἰς τὴν Ἰουδαίαν ἀποδρᾶναι παρεσκευάζετο· παρώξυνεν δ’ αὐτὸν ἡ τῆς σωτηρίας ἀπόγνωσις ἐνθυμεῖσθαι καὶ μείζονα· τό τε γὰρ ἔθνος ἐπαναστήσειν Ῥωμαίοις ἤλπισεν Κασσίου τῷ πρὸς Ἀντώνιον πολέμῳ περισπωμένου καὶ βασιλεύσειν αὐτὸς Ὑρκανὸν καταλύσας εὐμαρῶς.", "st": "1.11.7"}, {"sp": "N", "t": "Ἐπεγέλα δ’ ἄρα τὸ χρεὼν αὐτοῦ ταῖς ἐλπίσιν. ὁ γοῦν Ἡρώδης προϊδόμενος αὐτοῦ τὴν ὁρμὴν τόν τε Ὑρκανὸν κἀκεῖνον ἐπὶ δεῖπνον ἐκάλει, παρεστῶτας ἔπειτα τῶν οἰκετῶν τινας πρὸς αὑτὸν εἰσέπεμψεν ὡς ἐπὶ τὴν τοῦ δείπνου παρασκευήν, τῷ δὲ ὄντι προειπεῖν τοῖς χιλιάρχοις ἐξελθεῖν ἐπὶ τὴν ἐνέδραν. κἀκεῖνοι τῶν Κασσίου προσταγμάτων ἀναμνησθέντες ἐπὶ τὸν πρὸ τῆς πόλεως αἰγιαλὸν ἐξῄεσαν ξιφήρεις, ἔνθα περιστάντες τὸν Μάλιχον πολλοῖς τραύμασιν ἀναιροῦσιν. Ὑρκανὸς δὲ παραχρῆμα μὲν λυθεὶς ὑπ’ ἐκπλήξεως ἔπεσεν, μόλις δὲ ἀνενεγκὼν Ἡρώδην διηρώτα, τίς ὁ κτείνας εἴη Μάλιχον. ἀποκριναμένου δέ τινος τῶν χιλιάρχων τὸ Κασσίου πρόσταγμα, Κάσσιος ἄρα, ἔφη, κἀμὲ καὶ τὴν πατρίδα μου σώζει τὸν ἀμφοτέρων ἐπίβουλον ἀνελών. εἴτε δὲ φρονῶν Ὑρκανὸς οὕτως εἴθ’ ὑπὸ δέους ὁμόσε τῇ πράξει χωρῶν εἶπεν, ἄδηλον ἦν. ἀλλὰ γὰρ Μάλιχον μὲν οὕτως Ἡρώδης μετῆλθεν.", "st": "1.11.8"}, {"sp": "N", "t": "Κασσίου δὲ ἀναχωρήσαντος ἐκ Συρίας πάλιν στάσις ἐν Ἱεροσολύμοις γίνεται Ἕλικος μετὰ στρατιᾶς ἐπαναστάντος Φασαήλῳ καὶ κατὰ τὴν ὑπὲρ Μαλίχου τιμωρίαν ἀμύνεσθαι θέλοντος Ἡρώδην εἰς τὸν ἀδελφόν. Ἡρώδης δὲ ἔτυχεν μὲν ὢν παρὰ Φαβίῳ τῷ στρατηγῷ κατὰ Δαμασκόν, ὡρμημένος δὲ βοηθεῖν ὑπὸ νόσου κατείχετο. κἀν τούτῳ Φασάηλος καθ’ ἑαυτὸν Ἕλικος περιγενόμενος Ὑρκανὸν ὠνείδιζεν εἰς ἀχαριστίαν ὧν τε Ἕλικι συμπράξειεν, καὶ ὅτι περιορῴη τὸν ἀδελφὸν τὸν Μαλίχου τὰ φρούρια καταλαμβάνοντα· πολλὰ γὰρ δὴ κατείληπτο, καὶ τὸ πάντων ὀχυρώτατον Μασάδαν.", "st": "1.12.1"}, {"sp": "N", "t": "Οὐ μὴν αὐτῷ τι πρὸς τὴν Ἡρώδου βίαν ἤρκεσεν, ὃς ἀναρρωσθεὶς τά τε ἄλλα παραλαμβάνει κἀκεῖνον ἐκ τῆς Μασάδας ἱκέτην ἀφῆκεν. ἐξήλασεν δὲ καὶ ἐκ τῆς Γαλιλαίας Μαρίωνα τὸν Τυρίων τύραννον ἤδη τρία κατεσχηκότα τῶν ἐρυμάτων, τοὺς δὲ ληφθέντας Τυρίους ἔσωσεν μὲν πάντας, ἦσαν δ’ οὓς καὶ δωρησάμενος ἀπέπεμψεν εὔνοιαν ἑαυτῷ παρὰ τῆς πόλεως καὶ τῷ τυράννῳ μῖσος παρασκευαζόμενος. ὁ δὲ Μαρίων ἠξίωτο μὲν τῆς τυραννίδος ὑπὸ Κασσίου τυραννίσιν πᾶσαν διαλαβόντος τὴν Συρίαν, κατὰ δὲ τὸ πρὸς Ἡρώδην ἔχθος συγκατήγαγεν Ἀντίγονον τὸν Ἀριστοβούλου, καὶ τὸ πλέον διὰ Φάβιον, ὃν Ἀντίγονος χρήμασιν προσποιησάμενος βοηθὸν εἶχεν τῆς καθόδου· χορηγὸς δ’ ἦν ἁπάντων ὁ κηδεστὴς Πτολεμαῖος Ἀντιγόνῳ.", "st": "1.12.2"}, {"sp": "N", "t": "Πρὸς οὓς Ἡρώδης ἀντιπαραταξάμενος ἐπὶ τῶν ἐμβολῶν τῆς Ἰουδαίας κρατεῖ τῇ μάχῃ καὶ τὸν Ἀντίγονον ἐξελάσας ὑπέστρεψεν εἰς Ἱεροσόλυμα πᾶσιν ἀγαπητὸς ὢν ἐπὶ τῷ κατορθώματι· καὶ γὰρ οἱ μὴ προσέχοντες πάλαι τότε ᾠκείωντο διὰ τὴν πρὸς Ὑρκανὸν ἐπιγαμίαν αὐτῷ. πρότερον μὲν γὰρ ἦκτο γυναῖκα τῶν ἐπιχωρίων οὐκ ἄσημον, Δωρὶς ἐκαλεῖτο, ἐξ ἧς ἐγέννησεν Ἀντίπατρον, τότε δὲ γήμας τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου θυγατέρα, θυγατριδῆν δὲ Ὑρκανοῦ Μαριάμην οἰκεῖος τῷ βασιλεῖ γίνεται.", "st": "1.12.3"}, {"sp": "N", "t": "Ἐπεὶ δὲ Κάσσιον περὶ Φιλίππους ἀνελόντες ἀνεχώρησαν εἰς μὲν Ἰταλίαν Καῖσαρ ἐπὶ δὲ τῆς Ἀσίας Ἀντώνιος, πρεσβευομένων τῶν ἄλλων πόλεων πρὸς Ἀντώνιον εἰς Βιθυνίαν ἧκον καὶ Ἰουδαίων οἱ δυνατοὶ κατηγοροῦντες Φασαήλου καὶ Ἡρώδου, βίᾳ μὲν αὐτοὺς κρατεῖν τῶν πραγμάτων, ὄνομα δὲ μόνον περιεῖναι Ὑρκανῷ τίμιον. πρὸς ἃ παρὼν Ἡρώδης καὶ τεθεραπευκὼς οὐκ ὀλίγοις Ἀντώνιον χρήμασιν οὕτως διέθηκεν, ὡς μηδὲ λόγου τῶν ἐχθρῶν ἀνασχέσθαι.", "st": "1.12.4"}, {"sp": "N", "t": "καὶ τότε μὲν οὕτως διελύθησαν, αὖθις δὲ οἱ ἐν τέλει Ἰουδαίων ἑκατὸν ἄνδρες ἧκον εἰς τὴν πρὸς Ἀντιόχειαν Δάφνην ἐπ’ Ἀντώνιον ἤδη τῷ Κλεοπάτρας ἔρωτι δεδουλωμένον· οἳ προστησάμενοι τοὺς ἀξιώματι καὶ λόγῳ σφῶν δυνατωτάτους κατηγόρουν τῶν ἀδελφῶν. ὑπήντα δὲ Μεσσάλας ἀπολογούμενος συμπαρεστῶτος Ὑρκανοῦ διὰ τὸ κῆδος. καὶ Ἀντώνιος ἀκούσας ἑκατέρων Ὑρκανοῦ διεπυνθάνετο τοὺς ἐπιτηδειοτέρους ὄντας ἄρχειν· τοῦ δὲ τοὺς περὶ τὸν Ἡρώδην προκρίνοντος, ἡσθείς, ἦν γὰρ δὴ καὶ ξένος αὐτοῖς πατρῷος δεχθεὶς ὑπ’ Ἀντιπάτρου φιλοφρόνως ὅτε εἰς τὴν Ἰουδαίαν σὺν Γαβινίῳ παρέβαλλεν, τετράρχας ἀποδείκνυσιν τοὺς ἀδελφοὺς πᾶσαν διοικεῖν τὴν Ἰουδαίαν ἐπιτρέπων.", "st": "1.12.5"}, {"sp": "N", "t": "Προσαγανακτούντων δὲ τῶν πρέσβεων πεντεκαίδεκα μὲν συλλαβὼν εἵργνυσιν, οὓς καὶ ἀνελεῖν ὥρμησεν, τοὺς δὲ λοιποὺς μεθ’ ὕβρεως ἀπήλασεν. πρὸς ὃ μείζων ἐν τοῖς Ἱεροσολύμοις γίνεται ταραχή· χιλίους γοῦν πάλιν ἔπεμψαν πρέσβεις εἰς Τύρον, ἔνθα διέτριβεν Ἀντώνιος ἐπὶ Ἱεροσολύμων ὡρμημένος. ἐπὶ τούτους κεκραγότας ἐκπέμπει τὸν ἄρχοντα τῶν Τυρίων κολάζειν προστάξας οὓς ἂν λάβῃ, συγκατασκευάζειν δὲ τὴν ἀρχὴν τοῖς ὑπ’ αὐτοῦ κατασταθεῖσιν τετράρχαις.", "st": "1.12.6"}, {"sp": "N", "t": "Πρὸ δὲ τούτου πολλὰ παρῄνει προελθὼν ἐπὶ τὸν αἰγιαλὸν Ἡρώδης σὺν Ὑρκανῷ μήθ’ ἑαυτοῖς ἀπωλείας αἰτίους μήτε τῇ πατρίδι πολέμου γίνεσθαι φιλονεικοῦντας ἀκρίτως. τῶν δὲ ἔτι μᾶλλον ἀγανακτούντων Ἀντώνιος ἐκπέμψας ὁπλίτας πολλοὺς μὲν ἀπέκτεινεν, πολλοὺς δὲ ἔτρωσεν· ὧν οἵ τε πεσόντες ταφῆς καὶ οἱ τραυματίαι θεραπείας ἠξιώθησαν ὑπὸ Ὑρκανοῦ. οὐ μὴν οἱ διαφυγόντες ἠρέμουν, ἀλλὰ τὰ κατὰ τὴν πόλιν συνταράσσοντες παρώξυναν Ἀντώνιον ὥστε καὶ τοὺς δεσμώτας ἀποκτεῖναι.", "st": "1.12.7"}, {"sp": "N", "t": "Μετὰ δὲ ἔτη δύο Βαζαφράνου τοῦ Πάρθων σατράπου σὺν Πακόρῳ τῷ βασιλέως υἱῷ Συρίαν κατασχόντος Λυσανίας ἀναδεδεγμένος ἤδη τὴν ἀρχὴν τοῦ πατρὸς τελευτήσαντος, Πτολεμαῖος δ’ ἦν οὗτος ὁ Μενναίου, πείθει τὸν σατράπην ὑποσχέσει χιλίων ταλάντων καὶ πεντακοσίων γυναικῶν καταγαγεῖν ἐπὶ τὰ βασίλεια τὸν Ἀντίγονον, καταλῦσαι δὲ τὸν Ὑρκανόν. τούτοις ὑπαχθεὶς Πάκορος αὐτὸς μὲν ᾔει κατὰ τὴν παράλιον, Βαζαφράνην δὲ διὰ τῆς μεσογείου προσέταξεν ἐμβαλεῖν. τῶν δ’ ἐπιθαλαττίων Τύριοι Πάκορον οὐκ ἐδέξαντο καίτοι Πτολεμαιῶν καὶ Σιδωνίων δεδεγμένων. ὁ δ’ οἰνοχόῳ τινὶ τῶν βασιλικῶν ὁμωνύμῳ μοῖραν τῆς ἵππου παραδοὺς προεμβαλεῖν ἐκέλευσεν εἰς τὴν Ἰουδαίαν κατασκεψόμενόν τε τὰ τῶν πολεμίων καὶ πρὸς ἃ δέοι βοηθήσοντα Ἀντιγόνῳ.", "st": "1.13.1"}, {"sp": "N", "t": "Τῶν δὲ λῃζομένων τὸν Κάρμηλον πολλοὶ Ἰουδαῖοι συνδραμόντες πρὸς Ἀντίγονον προθύμους ἑαυτοὺς ἐπὶ τὴν εἰσβολὴν παρεῖχον. ὁ δὲ αὐτοὺς ἐπὶ τὸν καλούμενον Δρυμὸν προέπεμψεν τὸ χωρίον καταλαβεῖν· ἐν ᾧ γενομένης συμβολῆς ὠσάμενοι τοὺς πολεμίους καὶ διώξαντες ἐπὶ Ἱεροσολύμων ἔθεον γενόμενοί τε πλείους μέχρι τῶν βασιλείων προῆλθον. Ὑρκανοῦ δὲ καὶ Φασαήλου δεξαμένων αὐτοὺς καρτερῷ στίφει μάχη κατὰ τὴν ἀγορὰν συρρήγνυται, καθ’ ἣν τρεψάμενοι τοὺς πολεμίους οἱ περὶ Ἡρώδην κατακλείουσιν εἰς τὸ ἱερὸν καὶ φρουροὺς αὐτῶν ἄνδρας ἑξήκοντα ταῖς πλησίον οἰκίαις ἐγκατέστησαν. τούτους μὲν ὁ στασιάζων πρὸς τοὺς ἀδελφοὺς λαὸς ἐπελθὼν ἐμπίπρησιν, Ἡρώδης δὲ τοῦ δήμου πολλοὺς κατ’ ὀργὴν τῶν ἀπολωλότων ἀναιρεῖ συμβαλών, καὶ καθ’ ἡμέραν ἐπεκθεόντων ἀλλήλοις κατὰ λόχους φόνος ἦν ἀδιάλειπτος.", "st": "1.13.2"}, {"sp": "N", "t": "Ἐνστάσης δ’ ἑορτῆς, ἣ πεντηκοστὴ καλεῖται, τά τε περὶ τὸ ἱερὸν πάντα καὶ ἡ πόλις ὅλη πλήθους τῶν ἀπὸ τῆς χώρας ἀναπίμπλαται τὸ πλέον ὁπλιτῶν. καὶ Φασάηλος μὲν τὸ τεῖχος, Ἡρώδης δ’ οὐ μετὰ πολλῶν ἐφρούρει τὰ βασίλεια· καὶ τοῖς πολεμίοις ἐπεκδραμὼν ἀσυντάκτοις κατὰ τὸ προάστειον πλείστους μὲν ἀναιρεῖ, τρέπεται δὲ πάντας καὶ τοὺς μὲν εἰς τὴν πόλιν, τοὺς δὲ εἰς τὸ ἱερόν, τοὺς δὲ εἰς τὸ ἔξω χαράκωμα ἐγκλείει. κἀν τούτῳ διαλλακτὴν μὲν Ἀντίγονος παρακαλεῖ Πάκορον εἰσαφεῖναι, Φασάηλος δὲ πεισθεὶς τῇ τε πόλει καὶ ξενίᾳ τὸν Πάρθον εἰσδέχεται μετὰ πεντακοσίων ἱππέων, προφάσει μὲν ἥκοντα τοῦ παῦσαι τὴν στάσιν. τὸ δὲ ἀληθὲς Ἀντιγόνῳ βοηθόν. τὸν γοῦν Φασάηλον ἐνεδρεύων ἀνέπεισεν πρὸς Βαζαφράνην πρεσβεύσασθαι περὶ καταλύσεως, καίτοι γε πολλὰ ἀποτρέποντος Ἡρώδου καὶ παραινοῦντος ἀναιρεῖν τὸν ἐπίβουλον, ἀλλὰ μὴ ταῖς ἐπιβουλαῖς ἑαυτὸν ἐκδιδόναι, φύσει γὰρ ἀπίστους εἶναι τοὺς βαρβάρους, ἔξεισιν Ὑρκανὸν παραλαβών, καὶ Πάκορος, ὡς ἧττον ὑποπτεύοιτο, καταλιπὼν παρ’ Ἡρώδῃ τινὰς τῶν καλουμένων Ἐλευθέρων ἱππέων τοῖς λοιποῖς προέπεμψεν Φασάηλον.", "st": "1.13.3"}, {"sp": "N", "t": "Ὡς δ’ ἐγένοντο κατὰ τὴν Γαλιλαίαν, τοὺς μὲν ἐπιχωρίους ἀφεστῶτας κἀν τοῖς ὅπλοις ὄντας καταλαμβάνουσιν, τῷ σατράπῃ δὲ ἐνετύγχανον πανούργῳ σφόδρα καὶ ταῖς φιλοφρονήσεσιν τὴν ἐπιβουλὴν καλύπτοντι· δῶρα γοῦν δοὺς αὐτοῖς ἔπειτα ἀναχωροῦντας ἐλόχα. τοῖς δ’ αἴσθησις γίνεται τῆς ἐπιβουλῆς καταχθεῖσιν εἴς τι τῶν παραθαλασσίων χωρίων, ὃ καλεῖται Ἐκδίππων· ἐκεῖ γὰρ τήν τε ὑπόσχεσιν τῶν χιλίων ἤκουσαν ταλάντων καὶ ὡς Ἀντίγονος τὰς πλείστας τῶν παρ’ αὐτοῖς γυναικῶν ἐν ταῖς πεντακοσίαις καθοσιώσειεν Πάρθοις, ὅτι τε προλοχίζοιντο μὲν αὐτοῖς αἱ νύκτες ὑπὸ τῶν βαρβάρων ἀεί, πάλαι δ’ ἂν καὶ συνελήφθησαν, εἰ μὴ περιέμενον ἐν Ἱεροσολύμοις Ἡρώδην πρότερον λαβεῖν, ὡς μὴ προπυθόμενος τὰ κατ’ αὐτοὺς φυλάξαιτο. ταῦτ’ οὐκέτι λόγος ἦν μόνον, ἀλλὰ καὶ φυλακὰς ἤδη πόρρωθεν ἑαυτῶν ἔβλεπον.", "st": "1.13.4"}, {"sp": "N", "t": "Οὐ μὴν Φασάηλος καίτοι πολλὰ παραινοῦντος Ὀφελλίου φεύγειν, πέπυστο γὰρ οὗτος παρὰ Σαραμάλλα τοῦ πλουσιωτάτου τότε Σύρων τὴν σύνταξιν τῆς ἐπιβουλῆς ὅλην, καταλιπεῖν Ὑρκανὸν ὑπέμεινεν, ἀλλὰ τῷ σατράπῃ προσελθὼν ἄντικρυς ὠνείδιζεν τὴν ἐπιβουλὴν καὶ μάλισθ’ ὅτι γένοιτο τοιοῦτος χρημάτων ἕνεκεν· πλείω γε μὴν αὐτὸς ὑπὲρ σωτηρίας δώσειν ὧν Ἀντίγονος ὑπὲρ βασιλείας ὑπέσχετο. πρὸς ταῦτα πανούργως ὁ Πάρθος ἀπολογίαις τε καὶ ὅρκοις ἀποσκευασάμενος τὴν ὑποψίαν ᾤχετο πρὸς Πάκορον. εὐθέως δὲ τῶν καταλειφθέντων Πάρθων οἷς προσετέτακτο Φασάηλόν τε καὶ Ὑρκανὸν συνελάμβανον τά τε ἄλλα πρὸς τὴν ἐπιορκίαν καὶ τὸ ἄπιστον αὐτοῖς καταρωμένους.", "st": "1.13.5"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ τὸν Ἡρώδην ὁ πεμφθεὶς οἰνοχόος ἐπεβούλευε συλλαβεῖν ἔξω τοῦ τείχους ἀπατήσας προελθεῖν, ὥσπερ ἐντολὰς εἶχεν. ὁ δὲ ἀπ’ ἀρχῆς ὑποπτεύων τοὺς βαρβάρους καὶ τότε πεπυσμένος εἰς τοὺς πολεμίους ἐμπεπτωκέναι τὰ μηνύοντα τὴν ἐπιβουλὴν αὐτῷ γράμματα, προελθεῖν οὐκ ἠβούλετο καίτοι μάλα ἀξιοπίστως τοῦ Πακόρου φάσκοντος δεῖν αὐτὸν ὑπαντῆσαι τοῖς τὰς ἐπιστολὰς κομίζουσιν· οὔτε γὰρ ἑαλωκέναι τοῖς πολεμίοις αὐτὰς καὶ περιέχειν οὐκ ἐπιβουλήν, ἀλλ’ ὁπόσα διεπράξατο Φασάηλος. ἔτυχεν δὲ παρ’ ἄλλων προακηκοὼς τὸν ἀδελφὸν συνειλημμένον, καὶ προσῄει Ὑρκανοῦ θυγάτηρ Μαριάμμη, συνετωτάτη γυναικῶν, καταντιβολοῦσα μὴ προϊέναι μηδ’ ἐμπιστεύειν ἑαυτὸν ἤδη φανερῶς ἐπιχειροῦσι τοῖς βαρβάροις.", "st": "1.13.6"}, {"sp": "N", "t": "Ἔτι δὲ τῶν περὶ Πάκορον σκεπτομένων, πῶς ἂν κρύφα τὴν ἐπιβουλὴν ἀπαρτίσειαν, οὐ γὰρ ἐκ φανεροῦ οἷόν τε ἦν ἀνδρὸς οὕτω δυνατοῦ περιγενέσθαι, προλαβὼν Ἡρώδης μετὰ τῶν οἰκειοτάτων προσώπων νύκτωρ ἐπὶ Ἰδουμαίας ἐχώρει λάθρα τῶν πολεμίων. αἰσθόμενοι δ’ οἱ Πάρθοι κατεδίωκον. κἀκεῖνος τὴν μὲν μητέρα καὶ τοὺς ἀδελφοὺς καὶ τὴν καθωμολογημένην παῖδα μετὰ τῆς μητρὸς καὶ τοῦ νεωτάτου τῶν ἀδελφῶν προστάξας ὁδεύειν αὐτὸς ἀσφαλῶς μετὰ τῶν θεραπόντων ἀνέκοπτε τοὺς βαρβάρους· καὶ πολλοὺς κατὰ πᾶσαν προσβολὴν ἀποκτείνας εἰς Μασάδαν τὸ φρούριον ἠπείγετο.", "st": "1.13.7"}, {"sp": "N", "t": "Βαρυτέρους δὲ κατὰ τὴν φυγὴν Πάρθων Ἰουδαίους ἐπείρασεν, ἐνοχλήσαντας μὲν διηνεκῶς, ἀπὸ δὲ ἑξήκοντα τῆς πόλεως σταδίων καὶ παραταξαμένους ἐπιεικῶς πολὺν χρόνον. ἔνθα κρατήσας Ἡρώδης καὶ πολλοὺς αὐτῶν ἀποκτείνας αὖθις εἰς μνήμην τοῦ κατορθώματος ἔκτισεν τὸ χωρίον καὶ βασιλείοις πολυτελεστάτοις ἐκόσμησεν καὶ ἀκρόπολιν ὀχυρωτάτην ἀνεδείματο Ἡρώδειόν τε ἐκάλεσεν ἀπὸ ἑαυτοῦ. τηνικαῦτά γε μὴν φεύγοντι καθ’ ἡμέραν αὐτῷ προσεγίνοντο πολλοί, καὶ κατὰ Ῥῆσαν γενομένῳ τῆς Ἰδουμαίας Ἰώσηπος ἀδελφὸς ὑπαντήσας συνεβούλευεν τοὺς πολλοὺς τῶν ἑπομένων ἀποφορτίσασθαι· μὴ γὰρ ἂν τοσοῦτον ὄχλον δέξασθαι τὴν Μασάδαν. ἦσαν δὲ ὑπὲρ τοὺς ἐννακισχιλίους. πεισθεὶς Ἡρώδης τοὺς μὲν βαρυτέρους τῆς χρείας διαφῆκεν ἀνὰ τὴν Ἰδουμαίαν δοὺς ἐφόδια, μετὰ δὲ τῶν ἀναγκαιοτάτων τοὺς ἀλκιμωτάτους κατασχὼν εἰς τὸ φρούριον διασώζεται. καταλιπὼν δὲ ἐνταῦθα ταῖς γυναιξὶν ὀκτακοσίους φύλακας καὶ διαρκῆ τὰ ἐπιτήδεια πρὸς πολιορκίαν αὐτὸς εἰς τὴν Ἀραβικὴν Πέτραν ἠπείγετο.", "st": "1.13.8"}, {"sp": "N", "t": "Πάρθοι δ’ ἐν Ἱεροσολύμοις ἐφ’ ἁρπαγὴν τραπόμενοι τῶν φυγόντων εἰς τὰς οἰκίας εἰσέπιπτον καὶ τὸ βασίλειον ἀπεχόμενοι μόνων τῶν Ὑρκανοῦ χρημάτων· ἦν δ’ οὐ πλείω τριακοσίων ταλάντων. ἐπετύγχανον δὲ καὶ τῶν ἄλλων οὐχ ὅσοις ἤλπισαν· ὁ γὰρ Ἡρώδης ἐκ πολλοῦ τὴν ἀπιστίαν τῶν βαρβάρων ὑφορώμενος εἰς τὴν Ἰδουμαίαν τὰ λαμπρότατα τῶν κειμηλίων προανεσκεύαστο, καὶ τῶν αὐτῷ προσεχόντων ὁμοίως ἕκαστος. Πάρθοι δὲ μετὰ τὰς ἁρπαγὰς ἐπὶ τοσοῦτον ὕβρεως ἐχώρησαν ὡς ἐμπλῆσαι μὲν ἀκηρύκτου πολέμου τὴν χώραν ἅπασαν, ἀνάστατον δὲ ποιῆσαι τὴν Μαρισαίων πόλιν, μὴ μόνον δὲ καταστῆσαι βασιλέα Ἀντίγονον, ἀλλὰ καὶ παραδοῦναι αὐτῷ Φασάηλόν τε καὶ Ὑρκανὸν δεσμώτας αἰκίσασθαι. ὁ δὲ Ὑρκανοῦ μὲν προσπεσὼν αὐτὸς τὰ ὦτα λωβᾶται τοῖς ὀδοῦσιν, ὡς μηδὲ αὖθις ἐν μεταβολῇ ποτε δύναιτο τὴν ἀρχιερωσύνην ἀπολαβεῖν·", "st": "1.13.9"}, {"sp": "N", "t": "δεῖ γὰρ ὁλοκλήρους ἀρχιερᾶσθαι· τῆς Φασαήλου δὲ ἀρετῆς ὑστερίζει φθάσαντος πέτρᾳ προσρῆξαι τὴν κεφαλήν, ὡς καὶ σιδήρου καὶ χειρῶν εἴργετο. κἀκεῖνος μὲν Ἡρώδου γνήσιον ἑαυτὸν ἀποδείξας ἀδελφὸν καὶ Ὑρκανὸν ἀγεννέστατον, ἀνδρειότατα θνήσκει ποιησάμενος τὴν καταστροφὴν τοῖς κατὰ τὸν βίον ἔργοις πρέπουσαν· κατέχει δὲ καὶ ἄλλος λόγος, ὡς ἀνενέγκαι μὲν ἐκ τῆς τότε πληγῆς, πεμφθεὶς δὲ ἰατρὸς ὑπ’ Ἀντιγόνου θεραπεῦσαι δῆθεν αὐτὸν ἐμπλήσειεν τὸ τραῦμα δηλητηρίων φαρμάκων καὶ διαφθείρειεν αὐτόν. ὁπότερον δ’ ἂν ἀληθὲς ᾖ, τὴν ἀρχὴν ἔχει λαμπράν. φασὶν γοῦν αὐτὸν καὶ πρὶν ἐκπνεῦσαι πυθόμενον παρὰ γυναίου τινὸς ὡς Ἡρώδης διαπεφεύγοι, νῦν, εἰπεῖν, εὔθυμος ἄπειμι τὸν μετελευσόμενον τοὺς ἐχθροὺς καταλιπὼν ζῶντα.", "st": "1.13.10"}, {"sp": "N", "t": "Ὁ μὲν οὖν οὕτως τελευτᾷ. Πάρθοι δὲ καίτοι διημαρτηκότες ὧν μάλιστα ἐπεθύμουν γυναικῶν καθιστᾶσιν μὲν ἐν Ἱεροσολύμοις Ἀντιγόνῳ τὰ πράγματα, δεσμώτην δ’ Ὑρκανὸν ἀνάγουσιν εἰς τὴν Παρθυηνήν.", "st": "1.13.11"}, {"sp": "N", "t": "Ἡρώδης δὲ συντονώτερον ἤλαυνεν εἰς τὴν Ἀραβίαν ὡς ἔτι τἀδελφοῦ ζῶντος ἐπειγόμενος χρήματα παρὰ τοῦ βασιλέως λαβεῖν, οἷς μόνοις πείσειν ὑπὲρ Φασαήλου τὴν τῶν βαρβάρων ἤλπιζεν πλεονεξίαν. ἐλογίζετο γάρ, εἰ τῆς πατρῴας φιλίας ἀμνημονέστερος ὁ Ἄραψ γένοιτο καὶ τοῦ δοῦναι δωρεὰν μικρολογώτερος, δανείσασθαι παρ’ αὐτοῦ τὰ λύτρα ῥύσιον θεὶς τὸν τοῦ λυτρουμένου παῖδα· καὶ γὰρ ἐπήγετο τὸν ἀδελφιδοῦν ὄντα ἐτῶν ἑπτά· τάλαντα δ’ ἦν ἕτοιμος τριακόσια δοῦναι προστησάμενος Τυρίους παρακαλοῦντας. τὸ χρεὼν δ’ ἄρα τὴν αὐτοῦ σπουδὴν ἐφθάκει καὶ Φασαήλου τεθνηκότος εἰς κενὸν Ἡρώδης φιλάδελφος ἦν· οὐ μὴν οὐδὲ παρὰ Ἄραψιν εὑρίσκει φιλίαν οὖσαν. ὁ γοῦν βασιλεὺς αὐτῶν Μάλχος προπέμψας ἐκ τῆς χώρας κατὰ τάχος προσέτασσεν ἀναστρέφειν, προφάσει μὲν χρώμενος Πάρθοις, ἐπικηρυκεύσασθαι γὰρ αὐτοὺς ἐκβαλεῖν Ἡρώδην τῆς Ἀραβίας, τῷ δὲ ὄντι κατασχεῖν προαιρούμενος τὰ παρ’ Ἀντιπάτρου χρέα καὶ μηδὲν εἰς τὰς ἐκείνου δωρεὰς ἀντιπαρασχεῖν χρῄζουσιν τοῖς τέκνοις δυσωπεῖσθαι. συμβούλοις δ’ ἐχρῆτο τῆς ἀναιδείας τοῖς ὁμοίως ἀποστερεῖν τὰς Ἀντιπάτρου παρακαταθήκας θέλουσιν· ἦσαν δὲ τῶν περὶ αὐτὸν οἱ δυνατώτατοι.", "st": "1.14.1"}, {"sp": "N", "t": "Ἡρώδης μὲν δὴ πολεμίους τοὺς Ἄραβας εὑρὼν δι’ ἃ φιλτάτους ἤλπισεν καὶ τοῖς ἀγγέλοις ἀποκρινάμενος ὡς ὑπηγόρευε τὸ πάθος ὑπέστρεψεν ἐπ’ Αἰγύπτου. καὶ τὴν μὲν πρώτην ἑσπέραν κατά τι τῶν ἐπιχωρίων ἱερὸν αὐλίζεται τοὺς ὑπολειφθέντας ἀναλαβών, τῇ δ’ ἑξῆς εἰς Ῥινοκούρουρα προελθόντι τὰ περὶ τὴν τἀδελφοῦ τελευτὴν ἀπαγγέλλεται. προσλαβὼν δὲ πένθους ὅσον ἀπεθήκατο φροντίδων ᾔει προσωτέρω. καὶ δὴ βραδέως ὁ Ἄραψ μετανοήσας ἔπεμψεν διὰ τάχους τοὺς ἀνακαλέσοντας τὸν ὑβρισμένον. ἔφθανεν δὲ καὶ τούτους Ἡρώδης εἰς Πηλούσιον ἀφικόμενος, ἔνθα τῆς παρόδου μὴ τυγχάνων ὑπὸ τῶν ἐφορμούντων τοῖς ἡγεμόσιν ἐντυγχάνει· κἀκεῖνοι τήν τε φήμην καὶ τὸ ἀξίωμα τἀνδρὸς αἰδεσθέντες προπέμπουσιν αὐτὸν εἰς Ἀλεξάνδρειαν. ὁ δὲ παρελθὼν εἰς τὴν πόλιν ἐδέχθη μὲν λαμπρῶς ὑπὸ Κλεοπάτρας στρατηγὸν ἐλπιζούσης ἕξειν εἰς ἃ παρεσκευάζετο· διακρουσάμενος δὲ τὰς παρακλήσεις τῆς βασιλίδος καὶ μήτε τὴν ἀκμὴν τοῦ χειμῶνος ὑποδείσας μήτε τοὺς κατὰ τὴν Ἰταλίαν θορύβους ἐπὶ Ῥώμης ἔπλει.", "st": "1.14.2"}, {"sp": "N", "t": "Κινδυνεύσας δὲ περὶ Παμφυλίαν καὶ τοῦ φόρτου τὸ πλεῖον ἐκβαλὼν μόλις εἰς Ῥόδον διασώζεται σφόδρα τῷ πρὸς Κάσσιον πολέμῳ τετρυχωμένην, δεχθεὶς ὑπὸ Πτολεμαίου καὶ Σαπφινίου τῶν φίλων. καίπερ δὲ ὢν ἐν ἀπορίᾳ χρημάτων ναυπηγεῖται τριήρη μεγίστην, ἐν ᾗ μετὰ τῶν φίλων εἰς Βρεντέσιον καταπλεύσας κἀκεῖθεν εἰς Ῥώμην ἐπειχθεὶς πρώτῳ διὰ τὴν πατρῴαν φιλίαν ἐνετύγχανεν Ἀντωνίῳ καὶ τάς τε αὐτοῦ καὶ τοῦ γένους συμφορὰς ἐκδιηγεῖτο, ὅτι τε τοὺς οἰκειοτάτους ἐν φρουρίῳ καταλιπὼν πολιορκουμένους διὰ χειμῶνος πλεύσειεν ἐπ’ αὐτὸν ἱκέτης.", "st": "1.14.3"}, {"sp": "N", "t": "Ἀντωνίου δὲ ἥπτετο πρὸς τὴν μεταβολὴν οἶκτος, καὶ κατὰ μνήμην μὲν τῆς Ἀντιπάτρου ξενίας, τὸ δὲ ὅλον καὶ διὰ τὴν τοῦ παρόντος ἀρετὴν ἔγνω καὶ τότε βασιλέα καθιστᾶν Ἰουδαίων ὃν πρότερον αὐτὸς ἐποίησεν τετράρχην. ἐνῆγεν δὲ οὐκ ἔλαττον τῆς εἰς Ἡρώδην φιλοτιμίας ἡ πρὸς Ἀντίγονον διαφορά· τοῦτον γὰρ δὴ στασιώδη τε καὶ Ῥωμαίων ἐχθρὸν ὑπελάμβανεν. Καίσαρα μὲν οὖν εἶχεν ἑτοιμότερον αὐτοῦ τὰς Ἀντιπάτρου στρατείας ἀνανεούμενον, ἃς κατ’ Αἴγυπτον αὐτοῦ τῷ πατρὶ συνδιήνεγκεν, τήν τε ξενίαν καὶ τὴν ἐν ἅπασιν εὔνοιαν, ὁρῶντά γε μὴν καὶ τὸ Ἡρώδου δραστήριον· συνήγαγεν δὲ τὴν βουλήν, ἐν ᾗ Μεσσάλας καὶ μετ’ αὐτὸν Ἀτρατῖνος παραστησάμενοι τὸν Ἡρώδην τάς τε πατρῴας εὐεργεσίας καὶ τὴν αὐτοῦ πρὸς Ῥωμαίους εὔνοιαν διεξῄεσαν, ἀποδεικνύντες ἅμα καὶ πολέμιον τὸν Ἀντίγονον οὐ μόνον ἐξ ὧν διηνέχθη τάχιον, ἀλλ’ ὅτι καὶ τότε διὰ Πάρθων λάβοι τὴν ἀρχὴν Ῥωμαίους ὑπεριδών. τῆς δὲ συγκλήτου πρὸς ταῦτα κεκινημένης ὡς παρελθὼν Ἀντώνιος καὶ πρὸς τὸν κατὰ Πάρθων πόλεμον βασιλεύειν Ἡρώδην συμφέρειν ἔλεγεν, ἐπιψηφίζονται πάντες. λυθείσης δὲ τῆς βουλῆς Ἀντώνιος μὲν καὶ Καῖσαρ μέσον ἔχοντες Ἡρώδην ἐξῄεσαν, προῆγον δὲ σὺν ταῖς ἄλλαις ἀρχαῖς οἱ ὕπατοι θύσοντές τε καὶ τὸ δόγμα ἀναθήσοντες εἰς τὸ Καπετώλιον. τὴν δὲ πρώτην Ἡρώδῃ τῆς βασιλείας ἡμέραν Ἀντώνιος εἱστία.", "st": "1.14.4"}, {"sp": "N", "t": "Παρὰ δὲ τὸν χρόνον τοῦτον Ἀντίγονος ἐπολιόρκει τοὺς ἐν Μασάδᾳ, τοῖς μὲν ἄλλοις ἐπιτηδείοις διαρκουμένους, σπανίζοντας δὲ ὕδατος· διὸ καὶ Ἰώσηπος ἀδελφὸς Ἡρώδου σὺν διακοσίοις τῶν οἰκείων δρασμὸν ἐβουλεύετο εἰς Ἄραβας ἀκηκοὼς τῶν εἰς Ἡρώδην ἁμαρτημάτων Μάλχῳ μεταμέλειν. κἂν ἔφθη καταλιπὼν τὸ φρούριον, εἰ μὴ περὶ τὴν νύκτα τῆς ἐξόδου συνέβη πλεῖστον ὗσαι· τῶν γὰρ ἐκδοχείων ὕδατος ἀναπλησθέντων οὐκέτ’ ἔχρῃζεν φυγῆς, ἀλλ’ ἐπεξῄεσαν ἤδη τοῖς περὶ τὸν Ἀντίγονον καὶ τὰ μὲν φανερῶς συμπλεκόμενοι, τὰ δὲ λοχῶντες συχνοὺς διέφθειρον. οὐ μὴν ἐν ἅπασιν εὐστόχουν, ἔστιν δ’ ὅπου καὶ αὐτοὶ πταίοντες ἀνέστρεφον.", "st": "1.15.1"}, {"sp": "N", "t": "Κἀν τούτῳ Βεντίδιος ὁ Ῥωμαίων στρατηγὸς πεμφθεὶς ἐκ Συρίας Πάρθους ἀνείργειν μετ’ ἐκείνους εἰς Ἰουδαίαν παρέβαλεν λόγῳ μὲν ὡς βοηθήσων τοῖς περὶ Ἰώσηπον, ἔργῳ δ’ Ἀντίγονον ἀργυριούμενος. ἔγγιστα γοῦν Ἱεροσολύμων αὐλισάμενος ὡς ἐνεπλήσθη χρημάτων, αὐτὸς μὲν ἀνεχώρει μετὰ τῆς πλείστης δυνάμεως, Σίλωνα δὲ σὺν μέρει καταλέλοιπεν, ὡς μὴ κατάφωρον τὸ λῆμμα ποιήσειεν πάντας ἀπαναστήσας. Ἀντίγονος δὲ πάλιν ἐλπίζων Πάρθους ἐπαμυνεῖν καὶ Σίλωνα τέως ἐθεράπευεν, ὡς μηδὲν ἐνοχλοίη πρὸ τῆς ἐλπίδος.", "st": "1.15.2"}, {"sp": "N", "t": "Ἤδη δὲ Ἡρώδης καταπεπλευκὼς ἀπὸ τῆς Ἰταλίας εἰς Πτολεμαΐδα καὶ συναγηοχὼς δύναμιν οὐκ ὀλίγην ξένων τε καὶ ὁμοφύλων ἤλαυνεν διὰ τῆς Γαλιλαίας ἐπ’ Ἀντίγονον συλλαμβανόντων Βεντιδίου καὶ Σίλωνος, οὓς Δέλλιος ὑπ’ Ἀντωνίου πεμφθεὶς Ἡρώδην συγκαταγαγεῖν ἔπεισεν. ἐτύγχανεν δὲ Βεντίδιος μὲν ἐν ταῖς πόλεσιν τὰς διὰ Πάρθους ταραχὰς καθιστάμενος, Σίλων δὲ ἐν Ἰουδαίᾳ χρήμασιν ὑπ’ Ἀντιγόνου διεφθαρμένος. οὐ μὴν Ἡρώδης ἰσχύος ἠπόρει, προϊόντι δ’ αὐτῷ καθ’ ἡμέραν ηὐξεῖτο τὰ τῆς δυνάμεως, καὶ πλὴν ὀλίγων πᾶσα ἡ Γαλιλαία προσέθετο. προύκειτο μὲν οὖν τὸ ἀναγκαιότατον ἀγώνισμα Μασάδα καὶ τὸ ῥύσασθαι πρῶτον τοὺς οἰκείους ἐκ τῆς πολιορκίας, γίνεται δ’ ἐμπόδιον Ἰόππη· ταύτην γὰρ ἐχρῆν πολεμίαν οὖσαν ἐξελεῖν πρότερον, ὡς μὴ χωροῦντος ἐπὶ Ἱεροσολύμων κατὰ νώτου τι τοῖς ἐχθροῖς ἔρυμα καταλείποιτο. συνῆπτεν δὲ καὶ Σίλων ἀσμένως τῆς ἀπαναστάσεως πρόφασιν εὑρών, ᾧ προσέκειντο Ἰουδαῖοι διώκοντες. ἐπὶ τούτους Ἡρώδης ἐκδραμὼν μετ’ ὀλίγου στίφους τρέπεται ταχέως καὶ Σίλωνα διασώζει κακῶς ἀμυνόμενον.", "st": "1.15.3"}, {"sp": "N", "t": "Ἔπειτα Ἰόππην ἑλὼν πρὸς τὴν Μασάδα ῥυσόμενος τοὺς οἰκείους ἠπείγετο. καὶ τῶν ἐπιχωρίων οὓς μὲν πατρῴα φιλία προσῆγεν, οὓς δὲ τὸ αὐτοῦ κλέος, οὓς δὲ τῆς ἐξ ἀμφοῖν εὐεργεσίας ἀμοιβή, πλείστους γε μὴν ἐλπὶς ὡς ἐκ βασιλέως βεβαίου, δυσκίνητός τε ἤδη δύναμις ἤθροιστο. προϊόντα δ’ Ἀντίγονος ἐνήδρευεν τὰ ἐπιτήδεια τῶν παρόδων προλοχίζων, ἐν οἷς οὐδὲν ἢ μικρὰ τοὺς πολεμίους ἔβλαπτεν. Ἡρώδης δὲ τοὺς ἐκ Μασάδας οἰκείους παραλαβὼν ῥᾳδίως καὶ Ῥῆσαν τὸ φρούριον ᾔει πρὸς τὰ Ἱεροσόλυμα· συνῆπτε δ’ αὐτῷ τὸ μετὰ Σίλωνος στρατιωτικὸν καὶ πολλοὶ τῶν ἐκ τῆς πόλεως τὴν ἰσχὺν καταπλαγέντες.", "st": "1.15.4"}, {"sp": "N", "t": "Στρατοπεδευσαμένους δὲ κατὰ τὸ πρὸς δύσιν κλίμα τοῦ ἄστεος οἱ ταύτῃ φύλακες ἐτόξευόν τε καὶ ἐξηκόντιζον αὐτούς, ἄλλοι δὲ κατὰ στῖφος ἐκθέοντες ἀπεπειρῶντο τῶν προτεταγμένων. Ἡρώδης δὲ τὸ μὲν πρῶτον κηρύσσειν περὶ τὸ τεῖχος ἐκέλευεν ὡς ἐπ’ ἀγαθῷ τε παρείη τοῦ δήμου καὶ ἐπὶ σωτηρίᾳ τῆς πόλεως, μηδὲν μηδὲ τοὺς φανεροὺς ἐχθροὺς ἀμυνούμενος, δώσων δὲ καὶ τοῖς διαφορωτάτοις ἀμνηστίαν. ἐπεὶ δὲ ἀντιπαρηγοροῦντες οἱ περὶ τὸν Ἀντίγονον οὔτε κατακούειν τῶν κηρυγμάτων εἴων τινὰς οὔτε μεταβάλλεσθαι, τὸ λοιπὸν ἀμύνεσθαι τοὺς ἀπὸ τοῦ τείχους ἐπέτρεπεν τοῖς σφετέροις· οἱ δὲ ταχέως ἅπαντας ἀπὸ τῶν πύργων ἐτρέψαντο τοῖς βέλεσιν.", "st": "1.15.5"}, {"sp": "N", "t": "Ἔνθα δὴ καὶ Σίλων ἀπεκαλύψατο τὴν δωροδοκίαν· ἐπισκευασάμενος γὰρ πολλοὺς τῶν στρατιωτῶν σπάνιν ἐπιτηδείων ἀναβοᾶν καὶ χρήματα εἰς τροφὰς ἀπαιτεῖν ἀπάγειν τε σφᾶς χειμεριοῦντας εἰς τοὺς ἰδίους τόπους, ἐπειδὴ τὰ περὶ τὴν πόλιν ἦν ἔρημα πάντα τῶν περὶ Ἀντίγονον προανεσκευασμένων, ἐκίνει τε τὸ στρατόπεδον καὶ ἀναχωρεῖν ἐπειρᾶτο. Ἡρώδης δ’ ἐντυγχάνων τοῖς τε ὑπὸ τὸν Σίλωνα ἡγεμόσιν καὶ κατὰ πλῆθος τοῖς στρατιώταις ἐδεῖτο μὴ καταλιπεῖν αὐτὸν ὑπό τε Καίσαρος καὶ Ἀντωνίου καὶ τῆς συγκλήτου προπεμφθέντα· λύσειν γὰρ αὐθημερὸν αὐτῶν τὰς ἀπορίας. καὶ μετὰ τὴν δέησιν [εὐθέως] ὁρμήσας αὐτὸς εἰς τὴν χώραν τοσαύτην αὐτοῖς ἐπιτηδείων ἀφθονίαν ἐκόμισεν, ὡς πάσας ἀποκόψαι τὰς Σίλωνος προφάσεις, εἴς τε τὰς ἑξῆς ἡμέρας μὴ διαλιπεῖν τὴν χορηγίαν προνοούμενος ἐπέστελλεν τοῖς περὶ Σαμάρειαν, ᾠκείωτο δ’ ἡ πόλις αὐτῷ, σῖτον καὶ οἶνον καὶ ἔλαιον καὶ βοσκήματα κατάγειν εἰς Ἱεριχοῦντα. ταῦτ’ ἀκούσας Ἀντίγονος διέπεμψεν περὶ τὴν χώραν εἴργειν καὶ λοχᾶν τοὺς σιτηγοὺς κελεύων. οἱ δ’ ὑπήκουον, καὶ πολὺ πλῆθος ὁπλιτῶν ὑπὲρ τὴν Ἱεριχοῦντα συνηθροίσθη· διεκαθέζοντο δὲ ἐπὶ τῶν ὀρῶν παραφυλάσσοντες τοὺς τὰ ἐπιτήδεια ἐκκομίζοντας. οὐ μὴν Ἡρώδης ἠρέμει, δέκα δὲ σπείρας ἀναλαβών, ὧν πέντε μὲν Ῥωμαίων πέντε δὲ Ἰουδαίων ἦσαν ἔχουσαι καὶ μισθοφόρους μιγάδας πρὸς οἷς ὀλίγους τῶν ἱππέων, ἐπὶ τὴν Ἱεριχοῦντα παραγίνεται, καὶ τὴν μὲν πόλιν καταλελειμμένην εὑρίσκει, πεντακοσίους δὲ τὰ ἄκρα κατειληφότας σὺν γυναιξὶν καὶ γενεαῖς. αὐτοὺς μὲν οὖν ἀπολύει λαβών, Ῥωμαῖοι δ’ εἰσπεσόντες τὸ λοιπὸν ἄστυ διήρπασαν πλήρεις καταλαμβάνοντες τὰς οἰκίας παντοίων κειμηλίων. Ἱεριχοῦντος μὲν οὖν φρουρὰν ὁ βασιλεὺς καταλιπὼν ὑπέστρεψεν καὶ χειμεριοῦσαν τὴν Ῥωμαίων στρατιὰν εἰς τὰς προσκεχωρηκυίας διαφῆκεν Ἰδουμαίαν καὶ Γαλιλαίαν καὶ Σαμάρειαν. ἐπέτυχεν δὲ καὶ Ἀντίγονος παρὰ τῆς Σίλωνος δωροδοκίας ὑποδέξασθαι τοῦ στρατοῦ μοῖραν ἐν Λύδδοις θεραπεύων Ἀντώνιον.", "st": "1.15.6"}, {"sp": "N", "t": "Καὶ Ῥωμαῖοι μὲν ἐν ἀφθόνοις διῆγον ἀνειμένοι τῶν ὅπλων, Ἡρώδης δ’ οὐκ ἠρέμει, ἀλλὰ τὴν μὲν Ἰδουμαίαν δισχιλίοις πεζοῖς καὶ τετρακοσίοις ἱππεῦσιν διαλαμβάνει πέμψας τὸν ἀδελφὸν Ἰώσηπον, ὡς μή τι νεωτερισθείη πρὸς Ἀντίγονον αὐτὸς δὲ τὴν μητέρα καὶ ὅσους ἐκ Μασάδας οἰκείους ἐξήγαγεν μεταγαγὼν εἰς Σαμάρειαν καὶ καταστησάμενος ἀσφαλῶς ᾔει τὰ λοιπὰ τῆς Γαλιλαίας καταστρεψόμενος καὶ τὰς Ἀντιγόνου φρουρὰς ἐξελάσων.", "st": "1.16.1"}, {"sp": "N", "t": "Πρὸς δὲ τὴν Σέπφωριν ἐν νιφετῷ σφοδροτάτῳ διανύσας ἀκονιτὶ παραλαμβάνει τὴν πόλιν πρὸ τῆς ἐφόδου τῶν φυλάκων ἐκφυγόντων. ἔνθα τοὺς ἑπομένους ὑπὸ τοῦ χειμῶνος κακωθέντας ἀναλαβών, πολλὴ δ’ ἦν ἀφθονία τῶν ἐπιτηδείων, ἐπὶ τοὺς ἐν τοῖς σπηλαίοις ὥρμητο λῃστάς, οἳ πολλὴν τῆς χώρας κατατρέχοντες οὐκ ἐλάττω κακὰ πολέμου διετίθεσαν τοὺς ἐπιχωρίους. προπέμψας δὲ πεζῶν τρία τέλη καὶ μίαν ἴλην ἱππέων πρὸς Ἄρβηλα κώμην αὐτὸς μετὰ τεσσαράκοντα ἡμέρας ἐπῆλθεν μετὰ τῆς λοιπῆς δυνάμεως. οὐ μὴν πρὸς τὴν ἔφοδον ἔδεισαν οἱ πολέμιοι, μετὰ δὲ τῶν ὅπλων ἀπήντων ἐμπειρίαν μὲν πολεμικὴν ἔχοντες, τὸ δὲ θράσος λῃστρικόν. συμβαλόντες γοῦν τῷ σφετέρῳ δεξιῷ τὸ εὐώνυμον κέρας τῶν Ἡρώδου τρέπονται. περιελθὼν δὲ ταχέως Ἡρώδης ἐκ τοῦ καθ’ ἑαυτὸν δεξιοῦ προσεβοήθει καὶ τὸ μὲν οἰκεῖον ἐπέστρεφεν ἐκ τῆς φυγῆς, τοῖς δὲ διώκουσιν ἐμπίπτων ἀνέκοπτεν τὴν ὁρμὴν μέχρι τὰς κατὰ στόμα προσβολὰς μὴ φέροντες ἐξέκλιναν.", "st": "1.16.2"}, {"sp": "N", "t": "Ὁ δὲ ἕως Ἰορδάνου κτείνων εἵπετο καὶ πολὺ μὲν αὐτῶν μέρος διέφθειρεν, οἱ λοιποὶ δ’ ὑπὲρ τὸν ποταμὸν ἐσκεδάσθησαν, ὥστε τὴν Γαλιλαίαν ἐκκεκαθάρθαι φόβων, πλὴν καθόσον οἱ τοῖς σπηλαίοις ἐμφωλεύοντες ὑπελείποντο· κἀπὶ τούτοις ἔδει διατριβῆς. διὸ δὴ πρῶτον τοῖς στρατιώταις τὰς ἐκ τῶν πεπονημένων ἐπικαρπίας ἀπεδίδου διανέμων ἑκάστῳ δραχμὰς ἑκατὸν πεντήκοντα ἀργυρίου καὶ τοῖς ἡγεμόσιν πολυπλασίονα διέπεμψεν εἰς οὓς ἐχειμέριζον σταθμούς. Φερώρᾳ δὲ τῷ νεωτάτῳ τῶν ἀδελφῶν ἐπέστελλεν τῆς τε ἀγορᾶς αὐτοῖς ποιεῖσθαι πρόνοιαν καὶ τειχίζειν Ἀλεξάνδρειον. κἀκεῖνος ἀμφοτέρων ἐπεμελήθη.", "st": "1.16.3"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ περὶ μὲν Ἀθήνας διῆγεν Ἀντώνιος, Βεντίδιος δὲ ἐπὶ τὸν πρὸς Πάρθους πόλεμον Σίλωνά τε καὶ Ἡρώδην μετεπέμπετο καταστήσασθαι πρότερον ἐπιστέλλων τὰ περὶ Ἰουδαίαν. Ἡρώδης δὲ ἀσμένως Σίλωνα πρὸς Βεντίδιον ἀπολύσας αὐτὸς ἐπὶ τοὺς ἐν τοῖς σπηλαίοις ἐστράτευσεν. τὰ δὲ σπήλαια ταῦτα πρὸς ἀποκρήμνοις ὄρεσιν ἦν οὐδαμόθεν προσιτά, πλαγίας δὲ ἀνόδους μόνον ἔχοντα στενοτάτας. ἡ δὲ κατὰ μέτωπον αὐτῶν πέτρα κατέτεινεν εἰς βαθυτάτας φάραγγας ὄρθιος ἐπιρρέπουσα ταῖς χαράδραις, ὥστε τὸν βασιλέα μέχρι πολλοῦ μὲν ἀπορεῖν πρὸς τὸ ἀμήχανον τοῦ τόπου, τελευταῖον δ’ ἐπινοίᾳ χρήσασθαι σφαλερωτάτῃ. τοὺς γοῦν ἀλκίμους καθιμῶν ἐν λάρναξιν ἐνίει τοῖς στομίοις, οἱ δὲ ἀπέσφαττόν τε αὐτοὺς σὺν γενεαῖς καὶ πῦρ ἐνίεσαν τοῖς ἀμυνομένοις. βουληθεὶς δὲ ἐξ αὐτῶν καὶ περισῶσαί τινας Ἡρώδης ἐκήρυξεν ἀναχωρεῖν πρὸς αὐτόν. τῶν δὲ ἐθελουσίως μὲν οὐδεὶς προσέθετο, καὶ τῶν βιαζομένων δὲ πολλοὶ τῆς αἰχμαλωσίας προείλοντο θάνατον. ἔνθα καὶ τῶν γηραιῶν τις ἑπτὰ παίδων πατὴρ μετὰ τῆς μητρὸς δεομένους τοὺς παῖδας ἐπιτρέψαι σφίσιν ἐξελθεῖν ἐπὶ δεξιᾷ κτείνει τρόπῳ τοιῷδε· καθ’ ἕνα προϊέναι κελεύσας αὐτὸς ἵστατο ἐπὶ τὸ στόμιον καὶ τὸν ἀεὶ προϊόντα τῶν υἱῶν ἀπέσφαττεν. ἐξ ἀπόπτου δὲ Ἡρώδης ἐπιβλέπων τῷ τε πάθει συνείχετο καὶ τῷ πρεσβύτῃ δεξιὰν ὤρεγεν φείσασθαι τῶν τέκνων παρακαλῶν. ὁ δὲ πρὸς οὐδὲν ἐνδοὺς τῶν λεγομένων ἀλλὰ καὶ προσονειδίσας τὸν Ἡρώδην εἰς ταπεινότητα ἐπὶ τοῖς παισὶν ἀναιρεῖ καὶ τὴν γυναῖκα καὶ καταβαλὼν κατὰ τοῦ κρημνοῦ τοὺς νεκροὺς τελευταῖον ἑαυτὸν ἔρριψεν.", "st": "1.16.4"}, {"sp": "N", "t": "Χειροῦται μὲν οὕτως τὰ σπήλαια καὶ τοὺς ἐν αὐτοῖς Ἡρώδης· καταλιπὼν δὲ τοῦ στρατοῦ μοῖραν ὅσην ἀποχρήσειν ὑπελάμβανεν πρὸς τὰς ἐπαναστάσεις καὶ Θολεμαῖον ἐπ’ αὐτῆς ἐπὶ Σαμαρείας ὑπέστρεφεν, ὁπλίτας μὲν τρισχιλίους ἱππεῖς δ’ ἄγων ἑξακοσίους ἐπ’ Ἀντίγονον. ἔνθα πρὸς τὴν ἀποχώρησιν αὐτοῦ λαβόντες ἄδειαν οἷς ἔθος ἦν θορυβεῖν τὴν Γαλιλαίαν κτείνουσιν μὲν Θολεμαῖον τὸν στρατηγὸν ἀδοκήτως προσπεσόντες, ἐπόρθουν δὲ τὴν χώραν ποιούμενοι τὰς ἀναφυγὰς εἰς τὰ ἕλη καὶ τὰ δυσερεύνητα τῶν χωρίων. πυθόμενος δὲ Ἡρώδης τὴν ἐπανάστασιν διὰ τάχους ἐπεβοήθει καὶ πολὺ μὲν αὐτῶν πλῆθος διαφθείρει, τὰ φρούρια δὲ πάντα πολιορκίαις ἐξελὼν ἐπιτίμιον τῆς μεταβολῆς εἰσεπράξατο παρὰ τῶν πόλεων ἑκατὸν τάλαντα.", "st": "1.16.5"}, {"sp": "N", "t": "Ἤδη δὲ Πάρθων μὲν ἐξεληλαμένων, ἀνῃρημένου δὲ Πακόρου Βεντίδιος ἐπιστείλαντος Ἀντωνίου πέμπει συμμάχους Ἡρώδῃ κατ’ Ἀντιγόνου χιλίους ἱππεῖς καὶ δύο τάγματα. τούτων δὲ τὸν στρατηγὸν Μαχαιρᾶν Ἀντίγονος ἱκέτευσεν δι’ ἐπιστολῶν ἑαυτῷ βοηθὸν ἀφικέσθαι πολλά τε περὶ τῆς Ἡρώδου βίας ἀποδυρόμενος καὶ χρήματα δώσειν ὑπισχνούμενος. ὁ δέ, οὐ γὰρ κατεφρόνει τοῦ πέμψαντος ἄλλως τε καὶ πλείον’ Ἡρώδου διδόντος, εἰς μὲν τὴν προδοσίαν οὐχ ὑπήκουσεν, ὑποκρινόμενος δὲ φιλίαν κατάσκοπος ᾔει τῶν Ἀντιγόνου πραγμάτων Ἡρώδῃ μὴ πεισθεὶς ἀποτρέποντι. προαισθόμενος δ’ αὐτοῦ τὴν διάνοιαν Ἀντίγονος τήν τε πόλιν ἀπέκλεισεν καὶ ἀπὸ τῶν τειχῶν ὡς πολέμιον ἠμύνατο, μέχρις αἰδούμενος Μαχαιρᾶς εἰς Ἀμμαοῦντα πρὸς Ἡρώδην ἀναχωρεῖ καὶ πρὸς τὴν διαμαρτίαν θυμούμενος ὅσοις ἐπετύγχανεν Ἰουδαίοις ἀνῄρει, μηδεμίαν τῶν Ἡρωδείων φειδὼ ποιούμενος, ἀλλ’ ὡς Ἀντιγονείοις χρώμενος ἅπασιν.", "st": "1.16.6"}, {"sp": "N", "t": "Ἐφ’ οἷς χαλεπήνας Ἡρώδης ὥρμησεν μὲν ἀμύνασθαι Μαχαιρᾶν ὡς πολέμιον, κρατήσας δὲ τῆς ὀργῆς ἤλαυνεν πρὸς Ἀντώνιον κατηγορήσων τῆς Μαχαιρᾶ παρανομίας. ὁ δ’ ἐν διαλογισμῷ τῶν ἡμαρτημένων γενόμενος ταχέως μεταδιώκει τε τὸν βασιλέα καὶ πολλὰ δεηθεὶς ἑαυτῷ διαλλάττει. οὐ μὴν Ἡρώδης ἐπαύσατο τῆς πρὸς Ἀντώνιον ὁρμῆς· ἀκηκοὼς δ’ αὐτὸν μετὰ πολλῆς δυνάμεως προσπολεμοῦντα Σαμοσάτοις, πόλις δ’ ἐστὶν Εὐφράτου πλησίον καρτερά, θᾶττον ἠπείγετο τὸν καιρὸν ἐπιτήδειον ὁρῶν πρός τε ἐπίδειξιν ἀνδρείας καὶ τοῦ μᾶλλον ἀρέσασθαι τὸν Ἀντώνιον. γίνεται γοῦν ἐπελθὼν τέλος αὐτοῖς τῆς πολιορκίας, πολλοὺς μὲν τῶν βαρβάρων ἀποκτείνας, πολλὴν δὲ ἀποτεμόμενος λείαν, ὥστε τὸν μὲν Ἀντώνιον θαυμάζοντα καὶ πάλαι τῆς ἀρετῆς αὐτὸν τότε μᾶλλον οὕτως ἔχειν καὶ προσθεῖναι πολὺ ταῖς τε ἄλλαις τιμαῖς αὐτοῦ καὶ ταῖς εἰς τὴν βασιλείαν ἐλπίσιν, Ἀντίοχον δὲ τὸν βασιλέα ἀναγκασθῆναι παραδοῦναι τὰ Σαμόσατα.", "st": "1.16.7"}, {"sp": "N", "t": "Κἀν τούτῳ θραύεται τὰ κατὰ τὴν Ἰουδαίαν Ἡρώδου πράγματα. κατελελοίπει μὲν γὰρ Ἰώσηπον τὸν ἀδελφὸν ἐπὶ τῶν ὅλων παραγγείλας μηδὲν μέχρι τῆς ὑποστροφῆς αὐτοῦ παρακινεῖν πρὸς Ἀντίγονον· οὐ γὰρ δὴ βέβαιον εἶναι Μαχαιρῶν σύμμαχον ἐξ ὧν ἔδρασεν. ὁ δὲ ὡς ἤκουσεν ὄντα πορρωτάτω τὸν ἀδελφόν, ἀμελήσας τῶν παραγγελμάτων ἐπὶ Ἱεριχοῦντος ἐχώρει μετὰ πέντε σπειρῶν, ἃς συνέπεμψεν Μαχαιρᾶς· ᾔει δὲ τὸν σῖτον ἁρπάσων ἐν ἀκμῇ τοῦ θέρους. ἐπιθεμένων δὲ ἐν τοῖς ὄρεσιν καὶ ταῖς δυσχωρίαις τῶν ἐναντίων αὐτός τε θνήσκει μάλα γενναῖος ἐν τῇ μάχῃ φανείς, καὶ τὸ Ῥωμαϊκὸν πᾶν διαφθείρεται· νεοσύλλεκτοι γὰρ ἦσαν ἐκ τῆς Συρίας αἱ σπεῖραι, καὶ οὐδὲν αὐταῖς ἐνεκέκρατο τῶν πάλαι στρατιωτῶν καλουμένων ἐπαμύνειν τοῖς ἀπείροις πολέμου δυνάμενον.", "st": "1.17.1"}, {"sp": "N", "t": "Ἀντιγόνῳ δὲ οὐκ ἀπέχρησεν ἡ νίκη, προῆλθεν δὲ εἰς τοσοῦτον ὀργῆς, ὥστε καὶ νεκρὸν αἰκίσασθαι τὸν Ἰώσηπον· κρατήσας γοῦν τῶν σωμάτων ἀποτέμνει τὴν κεφαλὴν αὐτοῦ, καίτοι πεντήκοντα τάλαντα λύτρον αὐτῆς Φερώρα τἀδελφοῦ διδόντος. τὰ δὲ τῆς Γαλιλαίας μετὰ τὴν Ἀντιγόνου νίκην ἐνεωτερίσθη εἰς τοσοῦτον, ὥστε τοὺς τὰ Ἡρώδου φρονοῦντας τῶν δυνατῶν προαγαγόντες εἰς τὴν λίμνην κατέδυσαν οἱ προσέχοντες Ἀντιγόνῳ. μετεβάλλετο δὲ πολλὰ καὶ τῆς Ἰδουμαίας, ἔνθα Μαχαιρᾶς ἀνετείχιζέν τι τῶν ἐρυμάτων, Γιτθὰ καλεῖται. τούτων δὲ οὔπω πέπυστο Ἡρώδης· μετὰ γὰρ τὴν Σαμοσάτων ἅλωσιν Ἀντώνιος μὲν καταστήσας ἐπὶ τῆς Συρίας Σόσσιον καὶ προστάξας Ἡρώδῃ βοηθεῖν ἐπ’ Ἀντίγονον αὐτὸς εἰς Αἴγυπτον ἀνεχώρησεν, Σόσσιος δὲ δύο μὲν τάγματα προαπέστειλεν εἰς Ἰουδαίαν Ἡρώδῃ συμμαχῶν, αὐτὸς δὲ μετὰ τῆς λοιπῆς δυνάμεως ἠκολούθει σχεδόν.", "st": "1.17.2"}, {"sp": "N", "t": "Ὄντι δ’ Ἡρώδῃ κατὰ τὴν πρὸς Ἀντιόχειαν Δάφνην ὄνειροι σαφεῖς τὸν τἀδελφοῦ θάνατον προσημαίνουσιν, καὶ μετὰ ταραχῆς ἐκθορόντι τῆς κοίτης εἰσῄεσαν ἄγγελοι τῆς συμφορᾶς. ὁ δὲ ὀλίγον μὲν προσοιμώξας τῷ πάθει, τὸ πλεῖον δὲ τοῦ πένθους ὑπερθέμενος ἐπὶ τοὺς ἐχθροὺς ἠπείγετο ποιούμενος τὴν πορείαν ὑπὲρ δύναμιν. καὶ διανύσας ἐπὶ τὸν Λίβανον ὀκτακοσίους μὲν τῶν περὶ τὸ ὄρος προσλαμβάνει συμμάχους, Ῥωμαίων δὲ ἓν τάγμα ταύτῃ συνῆψεν. μεθ’ ὧν οὐ περιμείνας ἡμέραν εἰς τὴν Γαλιλαίαν ἐνέβαλεν τούς τε πολεμίους ὑπαντιάσαντας εἰς ὃ καταλελοίπεσαν χωρίον τρέπεται. καὶ προσέβαλλεν μὲν συνεχῶς τῷ φρουρίῳ, πρὶν δὲ ἑλεῖν χειμῶνι βιασθεὶς χαλεπωτάτῳ ταῖς πλησίον ἐνστρατοπεδεύεται κώμαις. ἐπεὶ δ’ αὐτῷ μετ’ ὀλίγας ἡμέρας καὶ τὸ δεύτερον παρὰ Ἀντωνίου τάγμα συνέμιξεν, δείσαντες τὴν ἰσχὺν οἱ πολέμιοι διὰ νυκτὸς ἐξέλιπον τὸ ἔρυμα.", "st": "1.17.3"}, {"sp": "N", "t": "Καὶ τὸ λοιπὸν διὰ Ἱεριχοῦντος ᾔει σπεύδων ᾗ τάχιστα τοὺς τἀδελφοῦ φονεῖς μετελθεῖν· ἔνθα καὶ δαιμόνιόν τι αὐτῷ συμβαίνει τέρας, ἐξ οὗ παρ’ ἐλπίδα σωθεὶς ἀνδρὸς θεοφιλεστάτου δόξαν ἀπηνέγκατο· πολλοὶ μὲν γὰρ αὐτῷ τῶν ἐν τέλει συνειστιάθησαν κατ’ ἐκείνην τὴν ἑσπέραν, διαλυθέντος δὲ τοῦ συμποσίου μετὰ τὸ πάντας ἐξελθεῖν ὁ οἶκος εὐθέως συνέπεσεν. τοῦτο καὶ κινδύνων καὶ σωτηρίας κοινὸν ἐπὶ τῷ μέλλοντι πολέμῳ κρίνας εἶναι σημεῖον ὑπὸ τὴν ἕω διεκίνει τὴν στρατιάν. καὶ τῶν ἐναντίων εἰς ἑξακισχιλίους ἀπὸ τῶν ὀρῶν κατατρέχοντες ἀπεπειρῶντο τῶν προτεταγμένων, κατὰ χεῖρα μὲν συμπλέκεσθαι τοῖς Ῥωμαίοις οὐ σφόδρα θαρροῦντες, πόρρωθεν δὲ χερμάσιν καὶ παλτοῖς ἔβαλλον, ὥστε συχνοὺς κατατιτρώσκειν. ἐν ᾧ καὶ αὐτὸς Ἡρώδης παρελαύνων παλτῷ κατὰ τὴν πλευρὰν ἀκοντίζεται.", "st": "1.17.4"}, {"sp": "N", "t": "Βουλόμενος δὲ Ἀντίγονος μὴ μόνον τόλμῃ τῶν σφετέρων ἀλλὰ καὶ πλήθει περιεῖναι δοκεῖν, Πάππον τινὰ τῶν ἑταίρων μετὰ στρατιᾶς ἐπὶ Σαμάρειαν περιπέμπει. τούτῳ μὲν οὖν ἦν Μαχαιρᾶς ἀγώνισμα, Ἡρώδης δὲ τὴν πολεμίαν καταδραμὼν πέντε μὲν πολίχνας καταστρέφεται, δισχιλίους δὲ τῶν ἐν αὐταῖς διαφθείρει καὶ τὰς οἰκίας ἐμπρήσας ὑπέστρεψεν ἐπὶ τὸ στρατόπεδον· ηὔλιστο δὲ περὶ τὴν καλουμένην Κανᾶ κώμην.", "st": "1.17.5"}, {"sp": "N", "t": "Προσεγίνετο δ’ αὐτῷ καθ’ ἡμέραν πολὺ πλῆθος Ἰουδαίων ἔκ τε αὐτῆς Ἱεριχοῦντος καὶ ἐκ τῆς ἄλλης χώρας, οἱ μὲν διὰ μῖσος τὸ πρὸς Ἀντίγονον, οἱ δὲ ἐπὶ τοῖς αὐτοῦ κατορθώμασιν κεκινημένοι· τούς γε μὴν πολλοὺς ἐνῆγεν ἐπιθυμία μεταβολῆς ἄλογος. καὶ ὁ μὲν ἠπείγετο συμβαλεῖν, οἱ δὲ περὶ Πάππον οὔτε πρὸς τὸ πλῆθος οὔτε πρὸς τὴν ὁρμὴν ὑποδείσαντες αὐτοῦ προθύμως ἀντεπεξῆλθον. γενομένης δὲ τῆς παρατάξεως τὰ μὲν ἄλλα μέρη πρὸς ὀλίγον ἀντέσχεν, Ἡρώδης δὲ κατὰ μνήμην τοῦ φονευθέντος ἀδελφοῦ παραβαλλόμενος, ὡς ἂν τίσαιτο τοὺς αἰτίους τοῦ φόνου, ταχέως τῶν καθ’ ἑαυτὸν ἐκράτει καὶ μετ’ ἐκείνους ἐπὶ τὸ συνεστὸς ἀεὶ τρεπόμενος ἅπαντας διώκει. φόνος δ’ ἦν πολύς, τῶν μὲν εἰς τὴν κώμην συνεξωθουμένων ἐξ ἧς ὥρμηντο, τοῦ δὲ προσκειμένου τοῖς ὑστάτοις καὶ κτείνοντος ἀπείρους. συνεισπίπτει δὲ τοῖς πολεμίοις εἴσω, καὶ πᾶσα μὲν ὁπλιτῶν οἰκία νένακτο, τὰ τέγη δ’ ἦν ὕπερθεν ἀμυνομένων κατάπλεα. κἀπειδὴ περιῆν τῶν ἔξωθεν, τὰς οἰκήσεις σπαράττων εἷλκεν τοὺς ἔνδοθεν. καὶ τοῖς μὲν πολλοῖς ἐπικατασείων τοὺς ὀρόφους ἀθρόους ἀνῄρει, τοὺς ὑποφεύγοντας δὲ τῶν ἐρειπίων οἱ στρατιῶται ξιφήρεις ἀνεδέχοντο, καὶ τοσοῦτον ἐσωρεύθη νεκρῶν πλῆθος, ὥστε τὰς ὁδοὺς ἀποφραγῆναι τοῖς κρατοῦσιν. ταύτην τὴν πληγὴν οὐκ ἤνεγκαν οἱ πολέμιοι· τὸ γοῦν ἐπισυλλεγόμενον αὐτῶν πλῆθος ὡς ἐθεάσατο τοὺς ἀνὰ τὴν κώμην διεφθαρμένους, εἰς φυγὴν διεσκεδάσθη, κἂν εὐθέως τῇ νίκῃ τεθαρρηκὼς Ἡρώδης ἐπὶ Ἱεροσολύμων ἤλασεν, εἰ μὴ χειμῶνι διεκωλύθη σφοδροτάτῳ. τοῦτ’ ἐμπόδιον ἐκείνῳ τε παντελοῦς κατορθώματος καὶ ἥττης Ἀντιγόνῳ κατέστη βουλευομένῳ καταλιπεῖν ἤδη τὴν πόλιν.", "st": "1.17.6"}, {"sp": "N", "t": "Ἡρώδης δὲ πρὸς ἑσπέραν [ἤδη] τοὺς φίλους κεκμηκότας ἐπὶ θεραπείᾳ τοῦ σώματος διαφεὶς καὶ αὐτὸς ὡς ἦν ἔτι θερμὸς ἐκ τῶν ὅπλων λουσόμενος ᾔει στρατιωτικώτερον· εἷς γοῦν αὐτῷ παῖς εἵπετο. καὶ πρὶν εἰς τὸ βαλανεῖον εἰσελθεῖν ἐναντίον αὐτοῦ τις ἐκτρέχει τῶν πολεμίων ξιφήρης, ἔπειτα δεύτερος καὶ τρίτος, ἑξῆς δὲ πλείους. οὗτοι καταπεφεύγεσαν μὲν ἐκ τῆς παρατάξεως εἰς τὸ βαλανεῖον ὡπλισμένοι, τέως δ’ ὑποπεπτηχότες καὶ διαλανθάνοντες ὡς ἐθεάσαντο τὸν βασιλέα, λυθέντες ὑπ’ ἐκπλήξεως αὐτὸν μὲν παρέτρεχον γυμνὸν ὄντα τρέμοντες, ἐπὶ δὲ τὰς ἐξόδους ἐχώρουν. τῶν μὲν οὖν ἄλλων οὐδεὶς παρῆν κατὰ τύχην ὁ συλληψόμενος τοὺς ἄνδρας, Ἡρώδῃ δ’ ἀπέχρη τὸ μηδὲν παθεῖν, ὥστε διαφεύγουσιν πάντες.", "st": "1.17.7"}, {"sp": "N", "t": "Τῇ δ’ ὑστεραίᾳ Πάππον μὲν τὸν Ἀντιγόνου στρατηγὸν καρατομήσας, ἀνῄρητο δ’ ἐπὶ τῆς παρατάξεως, πέμπει τὴν κεφαλὴν Φερώρᾳ τἀδελφῷ ποινὴν τοῦ φονευθέντος αὐτῶν ἀδελφοῦ· καὶ γὰρ οὗτος ἦν ὁ τὸν Ἰώσηπον ἀνελών. λωφήσαντος δὲ τοῦ χειμῶνος ἤλαυνεν ἐπὶ Ἱεροσολύμων καὶ μέχρι τοῦ τείχους ἀγαγὼν τὴν δύναμιν, συνήγετο δ’ αὐτῷ τρίτον ἔτος ἐξ οὗ βασιλεὺς ἐν Ῥώμῃ ἀπεδέδεικτο, πρὸ τοῦ ἱεροῦ στρατοπεδεύεται· ταύτῃ γὰρ ἦν ἐπίμαχον, καθ’ ὃ καὶ πρὶν εἷλεν Πομπήιος τὴν πόλιν. διελὼν δὲ εἰς ἔργα τὴν στρατιὰν καὶ τεμὼν τὰ προάστεια τρία μὲν ἐγείρειν χώματα καὶ πύργους ἐποικοδομεῖν αὐτοῖς κελεύει, καταλιπὼν δὲ τοὺς ἀνυτικωτάτους τῶν ἑταίρων ἐπὶ τῶν ἔργων αὐτὸς εἰς Σαμάρειαν ᾔει τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου μετιὼν θυγατέρα καθωμολογημένην ὡς ἔφαμεν αὐτῷ καὶ πάρεργον ποιούμενος τῆς πολιορκίας τὸν γάμον· ἤδη γὰρ ὑπερηφάνει τοὺς πολεμίους.", "st": "1.17.8"}, {"sp": "N", "t": "Γήμας δὲ ὑπέστρεψεν ἐπὶ Ἱεροσολύμων μετὰ μείζονος δυνάμεως· συνῆπτε δ’ αὐτῷ καὶ Σόσσιος μετὰ πλείστης στρατιᾶς ἱππέων τε καὶ πεζῶν, ἣν προεκπέμψας διὰ τῆς μεσογείου τὴν πορείαν αὐτὸς διὰ Φοινίκης ἐποιήσατο. συναθροισθείσης δὲ τῆς ὅλης δυνάμεως εἰς ἕνδεκα μὲν τέλη πεζῶν, ἱππεῖς δὲ ἑξακισχιλίους δίχα τῶν ἀπὸ Συρίας συμμάχων, οἳ μέρος οὐκ ὀλίγον ἦσαν, καταστρατοπεδεύονται τοῦ βορείου τείχους πλησίον, αὐτὸς μὲν πεποιθὼς τοῖς τῆς συγκλήτου δόγμασιν, δι’ ὧν βασιλεὺς ἀπεδέδεικτο, Σόσσιος δὲ Ἀντωνίῳ τῷ πέμψαντι τὴν ὑπ’ αὐτῷ στρατιὰν Ἡρώδῃ σύμμαχον.", "st": "1.17.9"}, {"sp": "N", "t": "Τῶν δ’ ἀνὰ τὴν πόλιν Ἰουδαίων τὸ πλῆθος ποικίλως ἐτετάρακτο· καὶ γὰρ περὶ τὸν ναὸν ἀθροιζόμενον τὸ ἀσθενέστερον ἐδαιμονία καὶ πολλὰ θειωδέστερον πρὸς τοὺς καιροὺς ἐλογοποίει, καὶ τῶν τολμηροτέρων κατὰ στῖφος ἦσαν λῃστεῖαι πολύτροποι, μάλιστα τὰ περὶ τὴν πόλιν ἁρπαζόντων ἐπιτήδεια καὶ μήτε ἵπποις μήτε ἀνδράσιν ὑπολειπομένων τροφήν. τοῦ γε μὴν μαχίμου τὸ εὐτακτότερον ἐτέτακτο πρὸς ἄμυναν τῆς πολιορκίας τούς τε χωννύντας εἶργον ἀπὸ τοῦ τείχους καὶ τοῖς ὀργάνοις ἀντιμηχανώμενον ἀεί τι κώλυμα καινότερον· ἐν οὐδενὶ δ’ οὕτως ὡς ἐν ταῖς μεταλλείαις περιῆσαν τῶν πολεμίων.", "st": "1.18.1"}, {"sp": "N", "t": "Τῷ δὲ βασιλεῖ πρὸς μὲν τὰς λῃστείας ἀντεπενοήθησαν λόχοι δι’ ὧν ἀνέστελλεν τὰς διεκδρομάς, πρὸς δὲ τὴν τῶν ἐπιτηδείων ἀπορίαν αἱ πόρρωθεν συγκομιδαί, τῶν δὲ μαχομένων περιῆν τῇ Ῥωμαίων ἐμπειρίᾳ καίτοι τόλμης οὐδεμίαν καταλιπόντων ὑπερβολήν· φανερῶς μέν γε συνερρήγνυντο τοῖς Ῥωμαίοις ἐπὶ προύπτῳ τῷ θανεῖν, διὰ δὲ τῶν ὑπονόμων ἐν μέσοις αὐτοῖς ἐξαπίνης ἐφαίνοντο, καὶ πρὶν κατασεισθῆναί τι τοῦ τείχους ἕτερον ἀντωχύρουν· καθόλου τε οὔτε χερσὶν οὔτ’ ἐπινοίαις ἔκαμνον εἰς ἔσχατον ἀντισχεῖν διεγνωκότες. ἀμέλει τηλικαύτης δυνάμεως περικαθεζομένης πέντε μησὶν διήνεγκαν τὴν πολιορκίαν, ἕως τῶν Ἡρώδου τινὲς ἐπιλέκτων ἐπιβῆναι τοῦ τείχους θαρσήσαντες εἰσπίπτουσιν εἰς τὴν πόλιν, ἐφ’ οἷς ἑκατοντάρχαι Σοσσίου. πρῶτα δὲ τὰ περὶ τὸ ἱερὸν ἡλίσκετο, καὶ τῆς δυνάμεως ἐπεισχυθείσης πανταχοῦ φόνος ἦν μυρίος, τῶν μὲν Ῥωμαίων τῇ τριβῇ τῆς πολιορκίας διωργισμένων, τοῦ δὲ περὶ Ἡρώδην Ἰουδαϊκοῦ μηδὲν ὑπολιπέσθαι σπουδάζοντος ἀντίπαλον. ἐσφάττοντο δὲ παμπληθεῖς ἔν τε τοῖς στενωποῖς καὶ κατὰ τὰς οἰκίας συνωθούμενοι καὶ τῷ ναῷ προσφεύγοντες· ἦν τε οὔτε νηπίων οὔτε γήρως ἔλεος οὔτε ἀσθενείας γυναικῶν, ἀλλὰ καίτοι περιπέμποντος τοῦ βασιλέως καὶ φείδεσθαι παρακαλοῦντος οὐδεὶς ἐκράτησεν τῆς δεξιᾶς, ἀλλ’ ὥσπερ μεμηνότες πᾶσαν ἡλικίαν ἐπεξῄεσαν. ἔνθα καὶ Ἀντίγονος μήτε τῆς πάλαι μήτε τῆς τότε τύχης ἔννοιαν λαβὼν κάτεισιν μὲν ἀπὸ τῆς βάρεως, προσπίπτει δὲ τοῖς Σοσσίου ποσίν. κἀκεῖνος μηδὲν αὐτὸν οἰκτείρας πρὸς τὴν μεταβολὴν ἐπεγέλασέν τε ἀκρατῶς καὶ Ἀντιγόνην ἐκάλεσεν· οὐ μὴν ὡς γυναῖκά γε καὶ φρουρᾶς ἐλεύθερον ἀφῆκεν, ἀλλ’ ὁ μὲν δεθεὶς ἐφυλάττετο.", "st": "1.18.2"}, {"sp": "N", "t": "Πρόνοια δ’ ἦν Ἡρώδῃ κρατοῦντι τῶν πολεμίων τότε κρατῆσαι καὶ τῶν ἀλλοφύλων συμμάχων· ὥρμητο γὰρ τὸ ξενικὸν πλῆθος ἐπὶ θέαν τοῦ τε ἱεροῦ καὶ τῶν κατὰ τὸν ναὸν ἁγίων. ὁ δὲ βασιλεὺς τοὺς μὲν παρακαλῶν τοῖς δ’ ἀπειλούμενος ἔστιν δ’ οὓς καὶ τοῖς ὅπλοις ἀνέστειλεν, ἥττης χαλεπωτέραν τὴν νίκην ὑπολαμβάνων, εἴ τι τῶν ἀθεάτων παρ’ αὐτῶν ὀφθείη. διεκώλυσεν δὲ ἤδη καὶ τὰς κατὰ τὴν πόλιν ἁρπαγάς, πολλὰ διατεινόμενος πρὸς Σόσσιον, εἰ χρημάτων τε καὶ ἀνδρῶν τὴν πόλιν Ῥωμαῖοι κενώσαντες καταλείψουσιν αὐτὸν ἐρημίας βασιλέα, καὶ ὡς ἐπὶ τοσούτων πολιτῶν φόνῳ βραχὺ καὶ τὴν τῆς οἰκουμένης ἡγεμονίαν ἀντάλλαγμα κρίνοι. τοῦ δὲ ἀντὶ τῆς πολιορκίας τὰς ἁρπαγὰς δικαίως τοῖς στρατιώταις ἐπιτρέπειν φαμένου, αὐτὸς ἔφη διανεμεῖν ἐκ τῶν ἰδίων χρημάτων τοὺς μισθοὺς ἑκάστοις. οὕτως τε τὴν λοιπὴν ἐξωνησάμενος πατρίδα τὰς ὑποσχέσεις ἐπλήρωσεν· λαμπρῶς μὲν γὰρ ἕκαστον στρατιώτην, ἀναλόγως δὲ τοὺς ἡγεμόνας, βασιλικώτατα δὲ αὐτὸν ἐδωρήσατο Σόσσιον, ὡς μηδένα χρημάτων ἀπελθεῖν δεόμενον. Σόσσιος δὲ χρυσοῦν ἀναθεὶς τῷ θεῷ στέφανον ἀνέζευξεν ἀπὸ Ἱεροσολύμων ἄγων δεσμώτην Ἀντίγονον Ἀντωνίῳ. τοῦτον μὲν οὖν φιλοψυχήσαντα μέχρις ἐσχάτου διὰ ψυχρᾶς ἐλπίδος ἄξιος τῆς ἀγεννείας πέλεκυς ἐκδέχεται.", "st": "1.18.3"}, {"sp": "N", "t": "βασιλεὺς δὲ Ἡρώδης διακρίνας τὸ κατὰ τὴν πόλιν πλῆθος τοὺς μὲν τὰ αὐτοῦ φρονήσαντας εὐνουστέρους ταῖς τιμαῖς καθίστατο, τοὺς δ’ Ἀντιγονείους ἀνῄρει. καὶ κατὰ σπάνιν ἤδη χρημάτων ὅσον εἶχεν κόσμον κατανομιστεύσας Ἀντωνίῳ καὶ τοῖς περὶ αὐτὸν ἀνέπεμψεν. οὐ μὴν εἰς ἅπαν ἐξωνήσατο τὸ μηδὲν παθεῖν· ἤδη γὰρ Ἀντώνιος τῷ Κλεοπάτρας ἔρωτι διεφθαρμένος ἥττων ἦν ἐν πᾶσιν τῆς ἐπιθυμίας, Κλεοπάτρα δὲ διεξελθοῦσα τὴν γενεὰν τὴν ἑαυτῆς ὡς μηδένα τῶν ἀφ’ αἵματος ὑπολείπεσθαι, τὸ λοιπὸν ἐπὶ τοὺς ἔξωθεν ἐφόνα, καὶ τοὺς ἐν τέλει Σύρων διαβάλλουσα πρὸς τὸν Ἀντώνιον ἀναιρεῖν ἔπειθεν ὡς ἂν τῶν κτήσεων ἑκάστου ῥᾳδίως γινομένη δεσπότις, ἔτι δὲ ἐκτείνουσα τὴν πλεονεξίαν ἐπὶ Ἰουδαίους καὶ Ἄραβας ὑπειργάζετο τοὺς ἑκατέρων βασιλεῖς Ἡρώδην καὶ Μάλχον ἀναιρεθῆναι.", "st": "1.18.4"}, {"sp": "N", "t": "Ἐν μέρει γοῦν τῶν προσταγμάτων ἐπινήψας Ἀντώνιος τὸ κτεῖναι μὲν ἄνδρας ἀγαθοὺς καὶ βασιλεῖς τηλικούτους ἀνόσιον ἡγήσατο, τὸ δὲ τούτων ἔγγιον φίλους διεκρούσατο, πολλὰ δὲ τῆς χώρας αὐτῶν ἀποτεμόμενος καὶ δὴ καὶ τὸν ἐν Ἱεριχοῦντι φοινικῶνα, ἐν ᾧ γεννᾶται τὸ βάλσαμον, δίδωσιν αὐτῇ πόλεις τε πλὴν Τύρου καὶ Σιδῶνος τὰς ἐντὸς Ἐλευθέρου ποταμοῦ πάσας. ὧν γενομένη κυρία καὶ προπέμψασα μέχρις Εὐφράτου τὸν Ἀντώνιον ἐπιστρατεύοντα Πάρθοις ἦλθεν εἰς Ἰουδαίαν δι’ Ἀπαμείας καὶ Δαμασκοῦ. κἀνταῦθα μεγάλαις μὲν αὐτῆς τὴν δυσμένειαν δωρεαῖς Ἡρώδης ἐκμειλίσσεται, μισθοῦται δὲ καὶ τὰ τῆς βασιλείας ἀπορραγέντα χωρία διακοσίων ταλάντων εἰς ἕκαστον ἐνιαυτόν, προπέμπει δ’ αὐτὴν μέχρι Πηλουσίου πάσῃ θεραπείᾳ καταχρώμενος. καὶ μετ’ οὐ πολὺ παρῆν ἐκ Πάρθων Ἀντώνιος ἄγων αἰχμάλωτον Ἀρταβάζην τὸν Τιγράνου παῖδα δῶρον Κλεοπάτρᾳ· μετὰ γὰρ τῶν χρημάτων καὶ τῆς λείας ἁπάσης ὁ Πάρθος εὐθὺς ἐχαρίσθη.", "st": "1.18.5"}, {"sp": "N", "t": "Τοῦ δ’ Ἀκτιακοῦ πολέμου συνερρωγότος παρεσκεύαστο μὲν Ἡρώδης Ἀντωνίῳ συνεξορμᾶν ἤδη τῶν τε ἄλλων τῶν κατὰ Ἰουδαίαν ἀπηλλαγμένος θορύβων καὶ κεκρατηκὼς Ὑρκανίας, ὃ δὴ χωρίον ἡ Ἀντιγόνου κατεῖχεν ἀδελφή. διεκλείσθη γε μὴν πανούργως ὑπὸ τῆς Κλεοπάτρας συμμετασχεῖν τῶν κινδύνων Ἀντωνίῳ· τοῖς γὰρ βασιλεῦσιν, ὡς ἔφαμεν, ἐπιβουλεύουσα πείθει τὸν Ἀντώνιον Ἡρώδῃ διαπιστεῦσαι τὸν πρὸς Ἄραβας πόλεμον, ἵν’ ἢ κρατήσαντος Ἀραβίας ἢ κρατηθέντος Ἰουδαίας γένηται δεσπότις καὶ θατέρῳ τῶν δυναστῶν καταλύσῃ τὸν ἕτερον.", "st": "1.19.1"}, {"sp": "N", "t": "Ἔρρεψεν μέντοι καθ’ Ἡρώδην τὸ βούλευμα· πρῶτον μὲν γὰρ ῥύσια κατὰ τῶν πολεμίων ἄγων καὶ πολὺ συγκροτήσας ἱππικὸν ἐπαφίησιν αὐτοῖς περὶ Διόσπολιν ἐκράτησέν τε καίτοι καρτερῶς ἀντιπαραταξαμένων. πρὸς δὲ τὴν ἧτταν μέγα γίνεται κίνημα τῶν Ἀράβων, καὶ συναθροισθέντες εἰς Κάναθα τῆς κοίλης Συρίας ἄπειροι τὸ πλῆθος τοὺς Ἰουδαίους ἔμενον. ἔνθα μετὰ τῆς δυνάμεως Ἡρώδης ἐπελθὼν ἐπειρᾶτο προμηθέστερον ἀφηγεῖσθαι τοῦ πολέμου καὶ στρατόπεδον ἐκέλευε τειχίζειν. οὐ μὴν ὑπήκουσεν τὸ πλῆθος, ἀλλὰ τῇ προτέρᾳ νίκῃ τεθαρρηκότες ὥρμησαν ἐπὶ τοὺς Ἄραβας καὶ πρὸς μὲν τὴν πρώτην ἐμβολὴν τραπέντας ἐδίωκον, ἐπιβουλεύεται δὲ Ἡρώδης ἐν τῇ διώξει τοὺς ἐκ τῶν Κανάθων ἐπιχωρίους ἀνέντος Ἀθηνίωνος, ὃς ἦν αὐτῷ τῶν Κλεοπάτρας στρατηγῶν αἰεὶ διάφορος· πρὸς γὰρ τὴν τούτων ἐπίθεσιν ἀναθαρρήσαντες οἱ Ἄραβες ἐπιστρέφονται καὶ συνάψαντες τὸ πλῆθος περὶ πετρώδη καὶ δύσβατα χωρία τοὺς Ἡρώδου τρέπονται πλεῖστόν τε αὐτῶν φόνον εἰργάσαντο. οἱ δὲ διασωθέντες ἐκ τῆς μάχης εἰς Ὄρμιζα καταφεύγουσιν, ὅπου καὶ τὸ στρατόπεδον αὐτῶν περισχόντες αὔτανδρον εἷλον οἱ Ἄραβες.", "st": "1.19.2"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ τῆς συμφορᾶς βοήθειαν ἄγων Ἡρώδης παρῆν τῆς χρείας ὑστέραν. ταύτης τῆς πληγῆς αἴτιον αὐτῷ τὸ τῶν ταξιάρχων ἀπειθὲς κατέστη· μὴ γὰρ ἐξαπιναίου τῆς συμβολῆς γενομένης οὐδ’ ἂν Ἀθηνίων εὗρεν καιρὸν ἐπιβουλῆς. ἐτιμωρήσατο μέντοι τοὺς Ἄραβας αὖθις ἀεὶ τὴν χώραν κατατρέχων, ὡς ἀνακαλέσασθαι τὴν μίαν αὐτοῖς νίκην πολλάκις. ἀμυνομένῳ δὲ τοὺς ἐχθροὺς ἐπιπίπτει συμφορὰ δαιμόνιος ἄλλη, κατ’ ἔτος μὲν τῆς βασιλείας ἕβδομον, ἀκμάζοντος δὲ τοῦ Ἀκτίου πολέμου. ἀρχομένου γὰρ ἔαρος ἡ γῆ σεισθεῖσα βοσκημάτων μὲν ἄπειρον πλῆθος ἀνθρώπων δὲ τρεῖς διέφθειρεν μυριάδας, τὸ δὲ στρατιωτικὸν ἔμεινεν ἀβλαβές· ὕπαιθρον γὰρ ηὐλίζετο. κἀν τούτῳ τοὺς Ἄραβας ἐπὶ μεῖζον θράσος ἦρεν ἡ φήμη προσλογοποιοῦσα τοῖς σκυθρωποῖς ἀεί τι χαλεπώτερον· ὡς γοῦν ἁπάσης Ἰουδαίας κατερριμμένης οἰηθέντες ἐρήμου τῆς χώρας κρατήσειν ὥρμησαν εἰς αὐτὴν προθυσάμενοι τοὺς πρέσβεις, οἳ παρὰ Ἰουδαίων ἔτυχον ἥκοντες πρὸς αὐτούς. πρὸς δὲ τὴν ἐμβολὴν καταπλαγὲν τὸ πλῆθος καὶ μεγέθει συμφορῶν ἐπαλλήλων ἔκλυτον συναγαγὼν Ἡρώδης ἐπειρᾶτο παρορμᾶν ἐπὶ τὴν ἄμυναν λέγων τοιάδε·", "st": "1.19.3"}, {"sp": "N", "t": "Παραλογώτατά μοι δοκεῖ τὸ παρὸν ὑμῶν καθάπτεσθαι δέος· πρὸς μέν γε τὰς δαιμονίους πληγὰς ἀθυμεῖν εἰκὸς ἦν, τὸ δ’ αὐτὸ καὶ πρὸς ἀνθρωπίνην ἔφοδον πάσχειν ἀνάνδρων. ἐγὼ γὰρ τοσοῦτον ἀποδέω κατεπτηχέναι τοὺς πολεμίους μετὰ τὸν σεισμόν, ὥσθ’ ὑπολαμβάνειν τὸν θεὸν Ἄραψιν δέλεαρ τοῦτο καθεικέναι τοῦ δοῦναι δίκας ἡμῖν· οὐ γὰρ τοσοῦτον ὅπλοις ἢ χερσὶν πεποιθότες ὅσον ταῖς αὐτομάτοις ἡμῶν συμφοραῖς ἧκον· σφαλερὰ δ’ ἐλπὶς οὐκ ἐξ οἰκείας ἰσχύος ἀλλ’ ἐξ ἀλλοτρίας ἠρτημένη κακοπραγίας. οὔτε δὲ τὸ δυστυχεῖν οὔτε τοὐναντίον ἐν ἀνθρώποις βέβαιον, ἀλλ’ ἔστιν ἰδεῖν ἐπαμειβομένην εἰς ἑκάτερα τὴν τύχην. καὶ τοῦτο μάθοιτ’ ἂν ἐξ οἰκείων ὑποδειγμάτων· τῇ γοῦν προτέρᾳ μάχῃ κρατούντων ἐκράτησαν ἡμῶν οἱ πολέμιοι, καὶ κατὰ τὸ εἰκὸς νῦν ἁλώσονται κρατήσειν δοκοῦντες· τὸ μὲν γὰρ ἄγαν πεποιθὸς ἀφύλακτον, οἱ φόβοι δὲ διδάσκουσιν προμήθειαν· ὥστε ἔμοιγε κἀκ τοῦ δεδοικότος ὑμῶν παρίσταται θαρρεῖν. ὅτε γὰρ ἐθρασύνεσθε πέρα τοῦ δέοντος καὶ κατὰ τῶν ἐχθρῶν παρὰ τὴν ἐμὴν γνώμην ἐξωρμήσατε, καιρὸν ἔσχεν ἡ Ἀθηνίωνος ἐνέδρα· νυνὶ δὲ ὁ ὄκνος ὑμῶν καὶ τὸ δοκοῦν ἄθυμον ἀσφάλειαν ἐμοὶ νίκης ἐγγυᾶται. χρὴ μέντοι γε μέχρι τοῦ μέλλειν οὕτως ἔχειν, ἐν δὲ τοῖς ἔργοις ἐγεῖραι τὰ φρονήματα καὶ πεῖσαι τοὺς ἀσεβεστάτους, ὡς οὔτ’ ἀνθρώπειόν τι κακὸν οὔτε δαιμόνιον ταπεινώσει ποτὲ τὴν Ἰουδαίων ἀνδραγαθίαν, ἐφ’ ὅσον τὰς ψυχὰς ἔχουσιν, οὐδὲ περιόψεταί τις Ἄραβα τῶν ἑαυτοῦ ἀγαθῶν δεσπότην γενόμενον, ὃν παρ’ ὀλίγον πολλάκις αἰχμάλωτον ἔλαβεν. μηδ’ ὑμᾶς ταρασσέτω τὰ τῶν ἀψύχων κινήματα μηδ’ ὑπολαμβάνετε τὸν σεισμὸν ἑτέρας συμφορᾶς τέρας γεγονέναι· φυσικὰ γὰρ τὰ τῶν στοιχείων πάθη καὶ οὐδὲν ἀνθρώποις πλέον ἢ τὴν ἐν ἑαυτοῖς βλάβην ἐπιφέρεται· λοιμοῦ μὲν γὰρ καὶ λιμοῦ καὶ τῶν χθονίων βρασμῶν προγένοιτ’ ἄν τι σημεῖον βραχύτερον, αὐτὰ δὲ ταῦτα περιγραφὴν ἔχει τὸ μέγεθος· ἐπεὶ τί δύναται μεῖζον ἡμᾶς τοῦ σεισμοῦ βλάψαι καὶ κρατήσας ὁ πόλεμος; τέρας μέντοι μέγιστον ἁλώσεως γέγονεν τοῖς ἐχθροῖς οὐκ αὐτομάτως οὐδὲ διὰ χειρὸς ἀλλοτρίας, οἳ πρέσβεις ἡμετέρους παρὰ τὸν πάντων ἀνθρώπων νόμον ὠμῶς ἀπέκτειναν καὶ τοιαῦτα τῷ θεῷ θύματα περὶ τοῦ πολέμου κατέστεψαν. ἀλλ’ οὐ διαφεύξονται τὸν μέγαν ὀφθαλμὸν αὐτοῦ καὶ τὴν ἀνίκητον δεξιάν, δώσουσιν δ’ ἡμῖν αὐτίκα δίκας, ἂν τοῦ πατρίου φρονήματος ἤδη σπάσαντες τιμωροὶ τῶν παρεσπονδημένων ἀναστῶμεν. ἴτω τις οὐχ ὑπὲρ γυναικὸς οὐδ’ ὑπὲρ τέκνων οὐδ’ ὑπὲρ κινδυνευούσης πατρίδος, ἀλλ’ ὑπὲρ τῶν πρέσβεων ἀμυνόμενος· ἐκεῖνοι στρατηγήσουσιν τοῦ πολέμου τῶν ζώντων ἄμεινον. προκινδυνεύσω δὲ κἀγὼ χρώμενος ὑμῖν πειθηνίοις· εὖ γὰρ ἴστε τὴν ἑαυτῶν ἀνδρείαν ἀνυπόστατον, ἐὰν μὴ προπετείᾳ τινὶ βλαβῆτε.", "st": "1.19.4"}, {"sp": "N", "t": "Τούτοις παρακροτήσας τὸν στρατὸν ὡς ἑώρα προθύμους, ἔθυεν τῷ θεῷ καὶ μετὰ τὴν θυσίαν διέβαινεν τὸν Ἰορδάνην ποταμὸν μετὰ τῆς δυνάμεως. στρατοπεδευσάμενος δὲ περὶ Φιλαδέλφειαν ἐγγὺς τῶν πολεμίων περὶ τοῦ μεταξὺ φρουρίου πρὸς αὐτοὺς ἠκροβολίζετο βουλόμενος ἐν τάχει συμβαλεῖν· ἔτυχον γὰρ κἀκεῖνοί τινας προπεπομφότες τοὺς καταληψομένους τὸ ἔρυμα. τούτους μὲν οὖν ἀπεκρούσαντο ταχέως οἱ πεμφθέντες ὑπὸ τοῦ βασιλέως καὶ τὸν λόφον κατέσχον, αὐτὸς δὲ καθ’ ἡμέραν προάγων τὴν δύναμιν εἰς μάχην παρετάσσετο καὶ προεκαλεῖτο τοὺς Ἄραβας. ὡς δ’ οὐδεὶς ἐπεξῄει, δεινὴ γάρ τις αὐτοὺς κατάπληξις εἶχε καὶ πρὸ τοῦ πλήθους ὁ στρατηγὸς Ἔλθεμος αὖος ἦν τῷ δέει, προσελθὼν ἐσπάραττεν αὐτῶν τὸ χαράκωμα. κἀν τούτῳ συναναγκασθέντες ἐξίασιν ἐπὶ τὴν μάχην ἄτακτοι καὶ πεφυρμένοι τοῖς ἱππεῦσιν οἱ πεζοί. πλήθει μὲν οὖν τῶν Ἰουδαίων περιῆσαν, ἐλείποντο δὲ ταῖς προθυμίαις καίτοι διὰ τὴν ἀπόγνωσιν τῆς νίκης ὄντες καὶ αὐτοὶ παράβολοι.", "st": "1.19.5"}, {"sp": "N", "t": "Διὸ μέχρι μὲν ἀντεῖχον οὐ πολὺς ἦν αὐτῶν φόνος, ὡς δ’ ὑπέδειξαν τὰ νῶτα, πολλοὶ μὲν ὑπὸ τῶν Ἰουδαίων πολλοὶ δὲ ὑπὸ σφῶν αὐτῶν συμπατούμενοι διεφθείροντο· πεντακισχίλιοι γοῦν ἔπεσον ἐν τῇ τροπῇ, τὸ δὲ λοιπὸν πλῆθος ἔφθη συνωσθὲν εἰς τὸ χαράκωμα. τούτους περισχὼν ἐπολιόρκει, καὶ μέλλοντας ἁλώσεσθαι τοῖς ὅπλοις προκατήπειγεν ἡ δίψα τῶν ὑδάτων ἐπιλειπόντων. ὑπερηφάνει δὲ πρεσβευομένους ὁ βασιλεὺς καὶ λύτρα διδόντων πεντακόσια τάλαντα μᾶλλον ἐνέκειτο. τοῦ δὲ δίψους ἐκκαίοντος ἐξιόντες κατὰ πλῆθος ἐνεχείριζον σφᾶς αὐτοὺς τοῖς Ἰουδαίοις ἑκόντες, ὡς πέντε μὲν ἡμέραις τετρακισχιλίους δεθῆναι, τῇ δ’ ἕκτῃ τὸ λειπόμενον πλῆθος ὑπ’ ἀπογνώσεως ἐξελθεῖν ἐπὶ μάχην· οἷς συμβαλὼν Ἡρώδης πάλιν εἰς ἑπτακισχιλίους κτείνει. τηλικαύτῃ πληγῇ τὴν Ἀραβίαν ἀμυνάμενος καὶ σβέσας τῶν ἀνδρῶν τὰ φρονήματα προύκοψεν ὥστε καὶ προστάτης ὑπὸ τοῦ ἔθνους αἱρεθῆναι.", "st": "1.19.6"}, {"sp": "N", "t": "Μεταλαμβάνει δὲ αὐτὸν εὐθέως ἡ περὶ τῶν ὅλων πραγμάτων φροντὶς διὰ τὴν πρὸς Ἀντώνιον φιλίαν Καίσαρος περὶ Ἄκτιον νενικηκότος. παρεῖχεν μέντοι δέους πλέον ἢ ἔπασχεν· οὔπω γὰρ ἑαλωκέναι Καῖσαρ Ἀντώνιον ἔκρινεν Ἡρώδου συμμένοντος. ὅ γε μὴν βασιλεὺς ὁμόσε χωρῆσαι τῷ κινδύνῳ διέγνω, καὶ πλεύσας εἰς Ῥόδον, ἔνθα διέτριβεν Καῖσαρ, πρόσεισιν αὐτῷ δίχα διαδήματος, τὴν μὲν ἐσθῆτα καὶ τὸ σχῆμα ἰδιώτης, τὸ δὲ φρόνημα βασιλεύς· μηδὲν γοῦν τῆς ἀληθείας ὑποστειλάμενος ἄντικρυς εἶπεν· ἐγώ, Καῖσαρ, ὑπὸ Ἀντωνίου βασιλεὺς γενόμενος ἐν πᾶσιν ὁμολογῶ γεγονέναι χρήσιμος Ἀντωνίῳ. καὶ οὐδὲ τοῦτ’ ἂν ὑποστειλαίμην εἰπεῖν, ὅτι πάντως ἄν με μετὰ τῶν ὅπλων ἐπείρασας εὐχάριστον, εἰ μὴ διεκώλυσαν Ἄραβες. καὶ συμμαχίαν μέντοι γε αὐτῷ κατὰ τὸ δυνατὸν καὶ σίτου πολλὰς ἔπεμψα μυριάδας, ἀλλ’ οὐδὲ μετὰ τὴν ἐν Ἀκτίῳ πληγὴν κατέλιπον τὸν εὐεργέτην, ἐγενόμην δὲ σύμβουλος ἄριστος, ὡς οὐκέτι χρήσιμος ἤμην σύμμαχος, μίαν εἶναι λέγων τῶν πταισθέντων διόρθωσιν τὸν Κλεοπάτρας θάνατον· ἣν ἀνελόντι καὶ χρήματα καὶ τείχη πρὸς ἀσφάλειαν καὶ στρατιὰν καὶ ἐμαυτὸν ὑπισχνούμην κοινωνὸν τοῦ πρὸς σὲ πολέμου. τοῦ δ’ ἄρα τὰς ἀκοὰς ἀπέφραξαν οἱ Κλεοπάτρας ἵμεροι καὶ θεὸς ὁ σοὶ τὸ κρατεῖν χαριζόμενος. συνήττημαι δ’ Ἀντωνίῳ καὶ τέθεικα μετὰ τῆς ἐκείνου τύχης τὸ διάδημα. πρὸς σὲ δὲ ἦλθον ἔχων τὴν ἀρετὴν τῆς σωτηρίας ἐλπίδα καὶ προλαβὼν ἐξετασθήσεσθαι, ποταπὸς φίλος, οὐ τίνος, ἐγενόμην.", "st": "1.20.1"}, {"sp": "N", "t": "Πρὸς ταῦτα Καῖσαρ ἀλλὰ σώζου γε, ἔφη, καὶ βασίλευε νῦν βεβαιότερον· ἄξιος γὰρ εἶ πολλῶν ἄρχειν οὕτω φιλίας προϊστάμενος. πειρῶ δὲ καὶ τοῖς εὐτυχεστέροις διαμένειν πιστός, ὡς ἔγωγε λαμπροτάτας ὑπὲρ τοῦ σοῦ φρονήματος ἐλπίδας ἔχω. καλῶς μέντοι γε ἐποίησεν Ἀντώνιος Κλεοπάτρᾳ πεισθεὶς μᾶλλον ἢ σοί· καὶ γὰρ σὲ κεκερδήκαμεν ἐκ τῆς ἀνοίας αὐτοῦ. κατάρχεις δ’, ὡς ἔοικεν, εὐποιίας δι’ ὧν μοι γράφει καὶ Βεντίδιος συμμαχίαν σε πεπομφέναι πρὸς τοὺς μονομάχους αὐτῷ. νῦν μὲν οὖν δόγματι τὸ βέβαιόν σοι τῆς βασιλείας ἐξαγγέλλω. πειράσομαι δὲ καὶ αὖθις ἀγαθόν τί σε ποιεῖν, ὡς μὴ ζητοίης Ἀντώνιον.", "st": "1.20.2"}, {"sp": "N", "t": "Τούτοις φιλοφρονησάμενος τὸν βασιλέα καὶ περιθεὶς αὐτῷ τὸ διάδημα δόγματι διεσήμαινεν τὴν δωρεάν, ἐν ᾧ πολλὰ μεγαλοφρόνως εἰς ἔπαινον τἀνδρὸς ἐφθέγξατο. ὁ δὲ δώροις ἐπιμειλιξάμενος αὐτὸν ἐξῃτεῖτό τινα τῶν Ἀντωνίου φίλων Ἀλεξᾶν ἱκέτην γενόμενον· ἐνίκα δὲ ἡ Καίσαρος ὀργὴ πολλὰ καὶ χαλεπὰ μεμφομένου τὸν ἐξαιτούμενον οἷς διεκρούσατο τὴν δέησιν. μετὰ δὲ ταῦτα πορευόμενον ἐπ’ Αἴγυπτον διὰ Συρίας Καίσαρα παντὶ τῷ βασιλικῷ πλούτῳ δεξάμενος Ἡρώδης τότε πρῶτον καὶ συνιππάσατο ποιουμένου περὶ Πτολεμαΐδα τῆς δυνάμεως ἐξέτασιν εἱστίασέν τε σὺν ἅπασιν τοῖς φίλοις· μεθ’ οὓς καὶ τῇ λοιπῇ στρατιᾷ πρὸς εὐωχίαν πάντα διέδωκεν. προυνόησεν δὲ καὶ διὰ τῆς ἀνύδρου πορευομένοις μέχρι Πηλουσίου παρασχεῖν ὕδωρ ἄφθονον ἐπανιοῦσί τε ὁμοίως, οὐδὲ ἔστιν ὅ τι τῶν ἐπιτηδείων ἐνεδέησεν τῇ δυνάμει. δόξα γοῦν αὐτῷ τε Καίσαρι καὶ τοῖς στρατιώταις παρέστη πολλῷ βραχυτέραν περιεῖναι Ἡρώδῃ βασιλείαν πρὸς ἃ παρέσχεν. διὰ τοῦτο, ὡς ἧκεν εἰς Αἴγυπτον ἤδη Κλεοπάτρας καὶ Ἀντωνίου τεθνεώτων, οὐ μόνον αὐτοῦ ταῖς ἄλλαις τιμαῖς, ἀλλὰ καὶ τῇ βασιλείᾳ προσέθηκεν τήν τε ὑπὸ Κλεοπάτρας ἀποτμηθεῖσαν χώραν καὶ ἔξωθεν Γάδαρα καὶ Ἵππον καὶ Σαμάρειαν, πρὸς δὲ τούτοις τῶν παραλίων Γάζαν καὶ Ἀνθηδόνα καὶ Ἰόππην καὶ Στράτωνος πύργον· ἐδωρήσατο δ’ αὐτῷ καὶ πρὸς φυλακὴν τοῦ σώματος τετρακοσίους Γαλάτας, οἳ πρότερον ἐδορυφόρουν Κλεοπάτραν. οὐδὲν δὲ οὕτως ἐνῆγεν αὐτὸν εἰς τὰς δωρεὰς ὡς τὸ μεγαλόφρον τοῦ λαμβάνοντος.", "st": "1.20.3"}, {"sp": "N", "t": "Μετὰ δὲ τὴν πρώτην ἀκτιάδα προστίθησιν αὐτοῦ τῇ βασιλείᾳ τόν τε Τράχωνα καλούμενον καὶ τὴν προσεχῆ Βαταναίαν τε καὶ τὴν Αὐρανῖτιν χώραν ἐξ αἰτίας τοιᾶσδε· Ζηνόδωρος ὁ τὸν Λυσανίου μεμισθωμένος οἶκον οὐ διέλειπεν ἐπαφεὶς τοὺς ἐκ τοῦ Τράχωνος λῃστὰς Δαμασκηνοῖς. οἱ δ’ ἐπὶ Οὐάρρωνα τὸν ἡγεμόνα τῆς Συρίας καταφυγόντες ἐδεήθησαν δηλῶσαι τὴν συμφορὰν αὐτῶν Καίσαρι· Καῖσαρ δὲ γνοὺς ἀντεπέστελλεν ἐξαιρεθῆναι τὸ λῃστήριον. στρατεύσας οὖν Οὐάρρων καθαίρει τε τῶν ἀνδρῶν τὴν γῆν καὶ ἀφαιρεῖται Ζηνόδωρον· ἣν ὕστερον Καῖσαρ, ὡς μὴ γένοιτο πάλιν ὁρμητήριον τοῖς λῃσταῖς ἐπὶ τὴν Δαμασκόν, Ἡρώδῃ δίδωσιν. κατέστησεν δὲ αὐτὸν καὶ Συρίας ὅλης ἐπίτροπον ἔτι δεκάτῳ πάλιν ἐλθὼν εἰς τὴν ἐπαρχίαν, ὡς μηδὲν ἐξεῖναι δίχα τῆς ἐκείνου συμβουλίας τοῖς ἐπιτρόποις διοικεῖν. ἐπεὶ δὲ ἐτελεύτα Ζηνόδωρος, προσένειμεν αὐτῷ καὶ τὴν μεταξὺ Τράχωνος καὶ τῆς Γαλιλαίας γῆν ἅπασαν. ὃ δὲ τούτων Ἡρώδῃ μεῖζον ἦν, ὑπὸ μὲν Καίσαρος ἐφιλεῖτο μετ’ Ἀγρίππαν, ὑπ’ Ἀγρίππα δὲ μετὰ Καίσαρα. ἔνθεν ἐπὶ πλεῖστον μὲν εὐδαιμονίας προύκοψεν, εἰς μεῖζον δ’ ἐξήρθη φρόνημα καὶ τὸ πλέον τῆς μεγαλονοίας ἐπέτεινεν εἰς εὐσέβειαν.", "st": "1.20.4"}, {"sp": "N", "t": "Πεντεκαιδεκάτῳ γοῦν ἔτει τῆς βασιλείας αὐτόν τε τὸν ναὸν ἐπεσκεύασεν καὶ περὶ αὐτὸν ἀνετειχίσατο χώραν τῆς οὔσης διπλασίονα, ἀμέτροις μὲν χρησάμενος τοῖς ἀναλώμασιν ἀνυπερβλήτῳ δὲ τῇ πολυτελείᾳ. τεκμήριον δὲ ἦσαν αἱ μεγάλαι στοαὶ περὶ τὸ ἱερὸν καὶ τὸ βόρειον ἐπ’ αὐτῷ φρούριον· ἃς μὲν γὰρ ἀνῳκοδόμησεν ἐκ θεμελίων, ὃ δ’ ἐπισκευάσας πλούτῳ δαψιλεῖ κατ’ οὐδὲν τῶν βασιλείων ἔλαττον Ἀντωνίαν ἐκάλεσεν εἰς τὴν Ἀντωνίου τιμήν. τό γε μὴν ἑαυτοῦ βασίλειον κατὰ τὴν ἄνω δειμάμενος πόλιν δύο τοὺς μεγίστους καὶ περικαλλεστάτους οἴκους, οἷς οὐδὲ ναός πῃ συνεκρίνετο, προσηγόρευσεν ἀπὸ τῶν φίλων τὸν μὲν Καισάρειον τὸν δὲ Ἀγρίππειον.", "st": "1.21.1"}, {"sp": "N", "t": "Ἀλλὰ γὰρ οὐκ οἴκοις μόνον αὐτῶν τὴν μνήμην καὶ τὰς ἐπικλήσεις περιέγραψεν, διέβη δὲ εἰς ὅλας πόλεις αὐτῷ τὸ φιλότιμον. ἐν μέν γε τῇ Σαμαρείτιδι πόλιν καλλίστῳ περιβόλῳ τειχισάμενος ἐπὶ σταδίους εἴκοσι καὶ καταγαγὼν ἑξακισχιλίους εἰς αὐτὴν οἰκήτορας, γῆν δὲ τούτοις προσνείμας λιπαρωτάτην καὶ ἐν μέσῳ τῷ κτίσματι ναόν τε ἐνιδρυσάμενος μέγιστον καὶ περὶ αὐτὸν τέμενος ἀποδείξας τῷ Καίσαρι τριῶν ἡμισταδίων, τὸ ἄστυ Σεβαστὴν ἐκάλεσεν· ἐξαίρετον δὲ τοῖς ἐν αὐτῷ παρέσχεν εὐνομίαν.", "st": "1.21.2"}, {"sp": "N", "t": "Ἐπὶ τούτοις δωρησαμένου τοῦ Καίσαρος αὐτὸν ἑτέρας προσθέσει χώρας, ὁ δὲ κἀνταῦθα ναὸν αὐτῷ λευκῆς μαρμάρου καθιδρύσατο παρὰ τὰς Ἰορδάνου πηγάς· καλεῖται δὲ Πάνειον ὁ τόπος· ἔνθα κορυφὴ μέν τις ὄρους εἰς ἄπειρον ὕψος ἀνατείνεται, παρὰ δὲ τὴν ὑπόρειον λαγόνα συνηρεφὲς ἄντρον ὑπανοίγει, δι’ οὗ βαραθρώδης κρημνὸς εἰς ἀμέτρητον ἀπορρῶγα βαθύνεται πλήθει τε ὕδατος ἀσαλεύτου καὶ τοῖς καθιμῶσίν τι πρὸς ἔρευναν γῆς οὐδὲν μῆκος ἐξαρκεῖ. τοῦ δὲ ἄντρου κατὰ τὰς ἔξωθεν ῥίζας ἀνατέλλουσιν αἱ πηγαί· καὶ γένεσις μέν, ὡς ἔνιοι δοκοῦσιν, ἔνθεν Ἰορδάνου, τὸ δ’ ἀκριβὲς ἐν τοῖς ἑξῆς δηλώσομεν.", "st": "1.21.3"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς καὶ ἐν Ἱεριχοῖ μεταξὺ Κύπρου τοῦ φρουρίου καὶ τῶν προτέρων βασιλείων ἄλλα κατασκευάσας ἀμείνω καὶ χρησιμώτερα πρὸς τὰς ἐπιδημίας ἀπὸ τῶν αὐτῶν ὠνόμασεν φίλων. καθόλου δὲ οὐκ ἔστιν εἰπεῖν ὅντινα τῆς βασιλείας ἐπιτήδειον τόπον τῆς πρὸς Καίσαρα τιμῆς γυμνὸν εἴασεν. ἐπεὶ δὲ τὴν ἰδίαν χώραν ἐπλήρωσεν ναῶν, εἰς τὴν ἐπαρχίαν αὐτοῦ τὰς τιμὰς ὑπερεξέχεεν καὶ πολλαῖς πόλεσιν ἐνιδρύσατο Καισάρεια.", "st": "1.21.4"}, {"sp": "N", "t": "Κατιδὼν δὲ κἀν τοῖς παραλίοις πόλιν ἤδη μὲν κάμνουσαν, Στράτωνος ἐκαλεῖτο πύργος, διὰ δὲ εὐφυίαν τοῦ χωρίου δέξασθαι δυναμένην τὸ φιλότιμον αὐτοῦ, πᾶσαν ἀνέκτισεν λευκῷ λίθῳ καὶ λαμπροτάτοις ἐκόσμησεν βασιλείοις, ἐν ᾗ μάλιστα τὸ φύσει μεγαλόνουν ἐπεδείξατο. μεταξὺ γὰρ Δώρων καὶ Ἰόππης, ὧν ἡ πόλις μέση κεῖται, πᾶσαν εἶναι συμβέβηκεν τὴν παράλιον ἀλίμενον, ὡς πάντα τὸν τὴν Φοινίκην ἐπ’ Αἰγύπτου παραπλέοντα σαλεύειν ἐν πελάγει διὰ τὴν ἐκ λιβὸς ἀπειλήν, ᾧ καὶ μετρίως ἐπαυρίζοντι τηλικοῦτον ἐπεγείρεται κῦμα πρὸς ταῖς πέτραις, ὥστε τὴν ὑποστροφὴν τοῦ κύματος ἐπὶ πλεῖστον ἐξαγριοῦν τὴν θάλασσαν. ἀλλ’ ὁ βασιλεὺς τοῖς ἀναλώμασιν καὶ τῇ φιλοτιμίᾳ νικήσας τὴν φύσιν μείζονα μὲν τοῦ Πειραιῶς λιμένα κατεσκεύασεν, ἐν δὲ τοῖς μυχοῖς αὐτοῦ βαθεῖς ὅρμους ἑτέρους.", "st": "1.21.5"}, {"sp": "N", "t": "Καθάπαν δ’ ἔχων ἀντιπράσσοντα τὸν τόπον ἐφιλονείκησεν πρὸς τὴν δυσχέρειαν, ὡς τὴν μὲν ὀχυρότητα τῆς δομήσεως δυσάλωτον εἶναι τῇ θαλάσσῃ, τὸ δὲ κάλλος ὡς ἐπὶ μηδενὶ δυσκόλῳ κεκοσμῆσθαι· συμμετρησάμενος γὰρ ὅσον εἰρήκαμεν τῷ λιμένι μέγεθος καθίει λίθους ἐπ’ ὀργυιὰς εἴκοσιν εἰς τὸ πέλαγος, ὧν ἦσαν οἱ πλεῖστοι μῆκος ποδῶν πεντήκοντα, βάθος ἐννέα, εὖρος δέκα, τινὲς δὲ καὶ μείζους. ἐπεὶ δὲ ἀνεπληρώθη τὸ ὕφαλον, οὕτως ἤδη τὸ ὑπερέχον τοῦ πελάγους τεῖχος ἐπὶ διακοσίους πόδας ηὐρύνετο· ὧν οἱ μὲν ἑκατὸν προδεδόμηντο πρὸς τὴν ἀνακοπὴν τοῦ κύματος, προκυμία γοῦν ἐκλήθη, τὸ δὲ λοιπὸν ὑπόκειται τῷ περιθέοντι λιθίνῳ τείχει. τοῦτο δὲ πύργοις τε διείληπται μεγίστοις, ὧν ὁ προύχων καὶ περικαλλέστατος ἀπὸ τοῦ Καίσαρος προγόνου Δρούσιον κέκληται,", "st": "1.21.6"}, {"sp": "N", "t": "ψαλίδες τε πυκναὶ πρὸς καταγωγὴν τῶν ἐνορμιζομένων καὶ τὸ πρὸ αὐτῶν πᾶν κύκλῳ νάγμα τοῖς ἀποβαίνουσιν πλατὺς περίπατος. ὁ δ’ εἴσπλους βόρειος, αἰθριώτατος γὰρ ἀνέμων τῷ τόπῳ βορέας· καὶ ἐπὶ τοῦ στόματος κολοσσοὶ τρεῖς ἑκατέρωθεν ὑπεστηριγμένοι κίοσιν, ὧν τοὺς μὲν ἐκ λαιᾶς χειρὸς εἰσπλεόντων πύργος ναστὸς ἀνέχει, τοὺς δὲ ἐκ δεξιοῦ δύο ὀρθοὶ λίθοι συνεζευγμένοι τοῦ κατὰ θάτερον χεῖλος πύργου μείζονες. προσεχεῖς δ’ οἰκίαι τῷ λιμένι λευκοῦ καὶ αὗται λίθου, καὶ κατατείνοντες ἐπ’ αὐτὸν οἱ στενωποὶ τοῦ ἄστεος πρὸς ἓν διάστημα μεμετρημένοι. καὶ τοῦ στόματος ἀντικρὺ ναὸς Καίσαρος ἐπὶ γηλόφου κάλλει καὶ μεγέθει διάφορος· ἐν δ’ αὐτῷ κολοσσὸς Καίσαρος οὐκ ἀποδέων τοῦ Ὀλυμπίασιν Διός, ᾧ καὶ προσείκασται, Ῥώμης δὲ ἴσος Ἥρᾳ τῇ κατ’ Ἄργος. ἀνέθηκεν δὲ τῇ μὲν ἐπαρχίᾳ τὴν πόλιν, τοῖς ταύτῃ δὲ πλοϊζομένοις τὸν λιμένα, Καίσαρι δὲ τὴν τιμὴν τοῦ κτίσματος· Καισάρειαν γοῦν ὠνόμασεν αὐτήν.", "st": "1.21.7"}, {"sp": "N", "t": "Τά γε μὴν λοιπὰ τῶν ἔργων, ἀμφιθέατρον καὶ θέατρον καὶ ἀγοράς, ἄξια τῆς προσηγορίας ἐνιδρύσατο. καὶ πενταετηρικοὺς ἀγῶνας καταστησάμενος ὁμοίως ἐκάλεσεν ἀπὸ τοῦ Καίσαρος, πρῶτος αὐτὸς ἆθλα μέγιστα προθεὶς ἐπὶ τῆς ἑκατοστῆς ἐνενηκοστῆς δευτέρας ὀλυμπιάδος, ἐν οἷς οὐ μόνον οἱ νικῶντες, ἀλλὰ καὶ οἱ μετ’ αὐτοὺς καὶ οἱ τρίτοι τοῦ βασιλικοῦ πλούτου μετελάμβανον. ἀνακτίσας δὲ καὶ Ἀνθηδόνα τὴν παράλιον καταρριφθεῖσαν ἐν πολέμῳ Ἀγρίππειον προσηγόρευσε· τοῦ δ’ αὐτοῦ φίλου δι’ ὑπερβολὴν εὐνοίας καὶ ἐπὶ τῆς πύλης ἐχάραξεν τὸ ὄνομα, ἣν αὐτὸς ἐν τῷ ναῷ κατεσκεύασεν.", "st": "1.21.8"}, {"sp": "N", "t": "Φιλοπάτωρ γε μήν, εἰ καί τις ἕτερος· καὶ γὰρ τῷ πατρὶ μνημεῖον κατέθηκεν πόλιν, ἣν ἐν τῷ καλλίστῳ τῆς βασιλείας πεδίῳ κτίσας ποταμοῖς τε καὶ δένδρεσιν πλουσίαν ὠνόμασεν Ἀντιπατρίδα, καὶ τὸ ὑπὲρ Ἱεριχοῦντος φρούριον ὀχυρότητι καὶ κάλλει διάφορον τειχίσας ἀνέθηκεν τῇ μητρὶ προσειπὼν Κύπρον. Φασαήλῳ δὲ τἀδελφῷ τὸν ἐν Ἱεροσολύμοις ὁμώνυμον πύργον, οὗ τό τε σχῆμα καὶ τὴν ἐν τῷ μεγέθει πολυτέλειαν διὰ τῶν ἑξῆς δηλώσομεν. καὶ πόλιν ἄλλην κτίσας κατὰ τὸν ἀπὸ Ἱεριχοῦς ἰόντων αὐλῶνα πρὸς βορέαν Φασαηλίδα ὠνόμασεν.", "st": "1.21.9"}, {"sp": "N", "t": "Παραδοὺς δ’ αἰῶνι τούς τε οἰκείους καὶ φίλους οὐδὲ τῆς ἑαυτοῦ μνήμης ἠμέλησεν, ἀλλὰ φρούριον μὲν ἐπιτειχίσας τῷ πρὸς Ἀραβίαν ὄρει προσηγόρευσεν Ἡρώδειον ἀφ’ ἑαυτοῦ, τὸν δὲ μαστοειδῆ κολωνὸν ὄντα χειροποίητον ἑξήκοντα σταδίων ἄπωθεν Ἱεροσολύμων ἐκάλεσεν μὲν ὁμοίως, ἐξήσκησεν δὲ φιλοτιμότερον. στρογγύλοις μὲν γὰρ τὴν ἄκραν πύργοις περιέσχεν, ἐπλήρωσεν δὲ τὸν περίβολον βασιλείοις πολυτελεστάτοις, ὡς μὴ μόνον τὴν ἔνδον τῶν οἰκημάτων ὄψιν εἶναι λαμπράν, ἀλλὰ καὶ τοῖς ἔξωθεν τοίχοις καὶ θριγκοῖς καὶ στέγαις περικεχύσθαι τὸν πλοῦτον δαψιλῆ· πόρρωθεν δὲ μεγίστοις ἀναλώμασιν ὑδάτων πλῆθος εἰσήγαγεν καὶ βαθμοῖς διακοσίοις λευκοτάτης μαρμάρου τὴν ἄνοδον διέλαβεν· ἦν γὰρ δὴ τὸ γήλοφον ἐπιεικῶς ὑψηλὸν καὶ πᾶν χειροποίητον. κατεσκεύασεν δὲ καὶ περὶ τὰς ῥίζας ἄλλα βασίλεια τήν τε ἀποσκευὴν καὶ τοὺς φίλους δέξασθαι δυνάμενα, ὥστε τῷ μὲν πάντα ἔχειν πόλιν εἶναι δοκεῖν τὸ ἔρυμα, τῇ περιγραφῇ δὲ βασίλειον.", "st": "1.21.10"}, {"sp": "N", "t": "Τοσαῦτα συγκτίσας πλείσταις καὶ τῶν ἔξω πόλεων τὸ μεγαλόψυχον ἐπεδείξατο. Τριπόλει μὲν γὰρ καὶ Δαμασκῷ καὶ Πτολεμαΐδι γυμνάσια, Βύβλῳ δὲ τεῖχος, ἐξέδρας τε καὶ στοὰς καὶ ναοὺς καὶ ἀγορὰς Βηρυτῷ κατασκευάσας καὶ Τύρῳ, Σιδῶνί γε μὴν καὶ Δαμασκῷ θέατρα, Λαοδικεῦσι δὲ τοῖς παραλίοις ὑδάτων εἰσαγωγήν, Ἀσκαλωνίταις δὲ βαλανεῖα καὶ κρήνας πολυτελεῖς, πρὸς δὲ περίστυλα θαυμαστὰ τήν τε ἐργασίαν καὶ τὸ μέγεθος· εἰσὶ δ’ οἷς ἄλση καὶ λειμῶνας ἀνέθηκεν. πολλαὶ δὲ πόλεις ὥσπερ κοινωνοὶ τῆς βασιλείας καὶ χώραν ἔλαβον παρ’ αὐτοῦ· γυμνασιαρχίαις δ’ ἄλλας ἐπετησίοις τε καὶ διηνεκέσιν ἐδωρήσατο προσόδους κατατάξας, ὥσπερ Κῴοις, ἵνα μηδέποτε ἐκλείπῃ τὸ γέρας. σῖτόν γε μὴν πᾶσιν ἐχορήγησεν τοῖς δεομένοις, καὶ τῇ Ῥόδῳ χρήματα μὲν εἰς ναυτικοῦ κατασκευὴν παρέσχεν πολλαχοῦ καὶ πολλάκις, ἐμπρησθὲν δὲ τὸ Πύθιον ἰδίοις ἀναλώμασιν ἄμεινον ἀνεδείματο. καὶ τί δεῖ λέγειν τὰς εἰς Λυκίους ἢ Σαμίους δωρεὰς ἢ τὴν δι’ ὅλης τῆς Ἰωνίας ἐν οἷς ἐδεήθησαν ἕκαστοι δαψίλειαν; ἀλλ’ Ἀθηναῖοι καὶ Λακεδαιμόνιοι Νικοπολῖταί τε καὶ τὸ κατὰ Μυσίαν Πέργαμον οὐ τῶν Ἡρώδου γέμουσιν ἀναθημάτων; τὴν δ’ Ἀντιοχέων τῶν ἐν Συρίᾳ πλατεῖαν οὐ φευκτὴν οὖσαν ὑπὸ βορβόρου κατέστρωσέν τε σταδίων εἴκοσι τὸ μῆκος οὖσαν ξεστῇ μαρμάρῳ καὶ πρὸς τὰς τῶν ὑετῶν ἀποφυγὰς ἐκόσμησεν ἰσομήκει στοᾷ.", "st": "1.21.11"}, {"sp": "N", "t": "Ταῦτα μὲν ἄν τις εἴποι ἴδια τῶν εὖ παθόντων δήμων ἑκάστου, τὸ δὲ Ἠλείοις χαρισθὲν οὐ μόνον κοινὸν τῆς Ἑλλάδος ἀλλ’ ὅλης τῆς οἰκουμένης δῶρον, εἰς ἣν ἡ δόξα τῶν Ὀλυμπίασιν ἀγώνων διικνεῖται. τούτους γὰρ δὴ καταλυομένους ἀπορίᾳ χρημάτων ὁρῶν καὶ τὸ μόνον λείψανον τῆς ἀρχαίας Ἑλλάδος ὑπορρέον, οὐ μόνον ἀγωνοθέτης ἧς ἐπέτυχεν πενταετηρίδος εἰς Ῥώμην παραπλέων ἐγένετο, ἀλλὰ καὶ πρὸς τὸ διηνεκὲς πόρους χρημάτων ἀπέδειξεν, ὡς μηδέποτε ἀγωνοθετοῦσαν αὐτοῦ τὴν μνήμην ἀπολιπεῖν. ἀνήνυτον ἂν εἴη χρεῶν διαλύσεις ἢ φόρων ἐπεξιέναι, καθάπερ Φασηλίταις καὶ Βαλανεώταις καὶ τοῖς περὶ τὴν Κιλικίαν πολιχνίοις τὰς ἐτησίους εἰσφορὰς ἐπεξεκούφισεν. πλεῖστόν γε μὴν αὐτοῦ τῆς μεγαλονοίας ἔθραυσεν ὁ φόβος, ὡς μὴ δόξειεν ἐπίφθονος ἤ τι θηρᾶσθαι μεῖζον εὐεργετῶν τὰς πόλεις πλέον τῶν ἐχόντων.", "st": "1.21.12"}, {"sp": "N", "t": "Ἐχρήσατο δὲ καὶ σώματι πρὸς τὴν ψυχὴν ἀναλόγῳ, κυνηγέτης μὲν ἄριστος ἀεὶ γενόμενος, ἐν ᾧ μάλιστα δι’ ἐμπειρίαν ἱππικῆς ἐπετύγχανεν· μιᾷ γοῦν ἡμέρᾳ ποτὲ τεσσαράκοντα θηρίων ἐκράτησεν· ἔστι δὲ καὶ συοτρόφος μὲν ἡ χώρα, τὸ πλέον δ’ ἐλάφων καὶ ὀνάγρων εὔπορος· πολεμιστὴς δ’ ἀνυπόστατος. πολλοὶ γοῦν κἀν ταῖς γυμνασίαις αὐτὸν κατεπλάγησαν ἀκοντιστήν τε ἰθυβολώτατον καὶ τοξότην εὐστοχώτατον ἰδόντες. πρὸς δὲ τοῖς ψυχικοῖς καὶ τοῖς σωματικοῖς προτερήμασιν ἐχρήσατο καὶ δεξιᾷ τύχῃ· καὶ γὰρ σπάνιον ἔπταισεν ἐν πολέμῳ, καὶ τῶν πταισμάτων οὐκ αὐτὸς αἴτιος, ἀλλ’ ἢ προδοσίᾳ τινῶν ἢ προπετείᾳ στρατιωτῶν ἐγένετο.", "st": "1.21.13"}, {"sp": "N", "t": "Τάς γε μὴν ὑπαίθρους εὐπραγίας ἡ τύχη τοῖς κατ’ οἶκον ἀνιαροῖς ἐνεμέσησεν, καὶ κακοδαιμονεῖν ἐκ γυναικὸς ἤρξατο περὶ ἣν μάλιστα ἐσπούδασεν. ἐπειδὴ γὰρ εἰς τὴν ἀρχὴν παρῆλθεν, ἀποπεμψάμενος ἣν ἰδιώτης ἦκτο γαμετήν, γένος ἦν ἐξ Ἱεροσολύμων Δωρὶς ὄνομα, γαμεῖ Μαριάμμην τὴν Ἀλεξάνδρου τοῦ Ἀριστοβούλου θυγατέρα, δι’ ἣν αὐτῷ στασιασθῆναι συνέβη τὸν οἶκον καὶ τάχιον μέν, μάλιστα δὲ μετὰ τὴν ἐκ Ῥώμης ἄφιξιν. πρῶτον μὲν γὰρ τὸν ἐκ τῆς Δωρίδος υἱὸν Ἀντίπατρον διὰ τοὺς ἐκ Μαριάμμης ἐφυγάδευσεν τῆς πόλεως μόναις ταῖς ἑορταῖς ἀφεὶς κατιέναι· ἔπειτα τὸν πάππον τῆς γυναικὸς Ὑρκανὸν ἐκ Πάρθων πρὸς αὐτὸν ἐλθόντα δι’ ὑπόνοιαν ἐπιβουλῆς ἀνεῖλεν, ὃν ᾐχμαλωτίσατο μὲν Βαζαφράνης καταδραμὼν Συρίαν, ἐξῃτήσαντο δὲ κατὰ οἶκτον οἱ ὑπὲρ Εὐφράτην ὁμοεθνεῖς. καὶ εἴ γε τούτοις ἐπείσθη παραινοῦσιν μὴ διαβῆναι πρὸς Ἡρώδην, οὐκ ἂν παραπώλετο· δέλεαρ δ’ αὐτῷ θανάτου τῆς υἱωνῆς ὁ γάμος κατέστη· τούτῳ γὰρ πεποιθὼς καὶ περισσόν τι τῆς πατρίδος ἐφιέμενος ἧκεν. παρώξυνεν δὲ Ἡρώδην οὐκ αὐτὸς ἀντιποιούμενος βασιλείας, ἀλλ’ ἐπεὶ τὸ βασιλεύειν ἐπέβαλλεν αὐτῷ.", "st": "1.22.1"}, {"sp": "N", "t": "Τῶν δὲ ἐκ Μαριάμμης πέντε τέκνων γενομένων δύο μὲν θυγατέρες, τρεῖς δ’ ἦσαν υἱεῖς. καὶ τούτων ὁ νεώτατος μὲν ἐν Ῥώμῃ παιδευόμενος τελευτᾷ, δύο δὲ τοὺς πρεσβυτάτους βασιλικῶς ἦγεν διά τε τὴν μητρῴαν εὐγένειαν καὶ ὅτι βασιλεύοντι γεγόνεισαν αὐτῷ. τὸ δὲ τούτων ἰσχυρότερον ὁ Μαριάμμης ἔρως συνήργει καθ’ ἡμέραν ἐκκαίων Ἡρώδην λαβρότερος, ὡς μηδενὸς τῶν διὰ τὴν στεργομένην λυπηρῶν αἰσθάνεσθαι· τοσοῦτον γὰρ ἦν μῖσος εἰς αὐτὸν τῆς Μαριάμμης, ὅσος ἐκείνου πρὸς αὐτὴν ἔρως. ἔχουσα δὲ τὴν μὲν ἀπέχθειαν ἐκ τῶν πραγμάτων εὔλογον, τὴν δὲ παρρησίαν ἐκ τοῦ φιλεῖσθαι, φανερῶς ὠνείδιζεν αὐτῷ τὰ κατὰ τὸν πάππον Ὑρκανὸν καὶ τὸν ἀδελφὸν Ἰωνάθην· οὐδὲ γὰρ τούτου καίπερ ὄντος παιδὸς ἐφείσατο, δοὺς μὲν αὐτῷ τὴν ἀρχιερωσύνην ἑπτακαιδεκαέτει, μετὰ δὲ τὴν τιμὴν κτείνας εὐθέως, ἐπειδὴ τὴν ἱερὰν ἐσθῆτα λαβόντι καὶ τῷ βωμῷ προσελθόντι καθ’ ἑορτὴν ἄθρουν ἐπεδάκρυσεν τὸ πλῆθος. πέμπεται μὲν οὖν ὁ παῖς διὰ νυκτὸς εἰς Ἱεριχοῦντα, ἐκεῖ δὲ κατ’ ἐντολὴν ὑπὸ τῶν Γαλατῶν βαπτιζόμενος ἐν κολυμβήθρᾳ τελευτᾷ.", "st": "1.22.2"}, {"sp": "N", "t": "Διὰ ταῦθ’ Ἡρώδην μὲν ὠνείδιζεν ἡ Μαριάμμη, καὶ τὴν ἀδελφὴν αὐτοῦ καὶ τὴν μητέρα δειναῖς ἐξύβριζεν λοιδορίαις. ἀλλ’ ὁ μὲν πεφίμωτο τοῖς ἱμέροις, δεινὴ δὲ τὰς γυναῖκας ἀγανάκτησις εἰσῄει, καὶ πρὸς ὃ μάλιστα κινήσειν τὸν Ἡρώδην ἔμελλον, εἰς μοιχείαν διέβαλλον αὐτήν, ἄλλα τε πολλὰ πρὸς τὸ πιθανὸν ἐνσκευαζόμεναι καὶ κατηγοροῦσαι διότι τὴν εἰκόνα τὴν ἑαυτῆς πέμψειεν εἰς Αἴγυπτον Ἀντωνίῳ καὶ δι’ ὑπερβολὴν ἀσελγείας ἀποῦσαν δείξειεν ἑαυτὴν ἀνθρώπῳ γυναικομανοῦντι καὶ βιάζεσθαι δυναμένῳ. τοῦθ’ ὥσπερ σκηπτὸς ἐμπεσὼν ἐτάραξεν Ἡρώδην, μάλιστα μὲν διὰ τὸν ἔρωτα ζηλοτύπως ἔχοντα, λογιζόμενον δὲ καὶ τὴν Κλεοπάτρας δεινότητα, δι’ ἣν Λυσανίας τε ὁ βασιλεὺς ἀνῄρητο καὶ Μάλχος ὁ Ἄραψ· οὐ γὰρ ἀφαιρέσει γαμετῆς ἐμέτρει τὸν κίνδυνον, ἀλλὰ θανάτῳ.", "st": "1.22.3"}, {"sp": "N", "t": "Μέλλων οὖν ἀποδημήσειν Ἰωσήπῳ τῷ ἀνδρὶ Σαλώμης τῆς ἀδελφῆς αὐτοῦ, πιστὸς δὲ ἦν καὶ διὰ τὸ κῆδος εὔνους, παρατίθεται τὴν γυναῖκα, κρύφα δοὺς ἐντολὰς ἀναιρεῖν αὐτήν, εἰ κἀκεῖνον Ἀντώνιος. ὁ δὲ Ἰώσηπος, οὔτι κακοήθως, ἀλλὰ τὸν ἔρωτα τοῦ βασιλέως παραστῆσαι τῇ γυναικὶ βουλόμενος, ὡς οὐδὲ ἀποθανὼν αὐτῆς ὑπομένοι διαζευχθῆναι, τὸ ἀπόρρητον ἐκφαίνει. κἀκείνη πρὸς ἐπανήκοντα τὸν Ἡρώδην πολλά τε περὶ τοῦ πρὸς αὐτὴν συμπαθοῦς ἐν ταῖς ὁμιλίαις ἐπομνύμενον, ὡς οὐδ’ ἐρασθείη ποτὲ γυναικὸς ἄλλης, πάνυ γοῦν, εἶπεν, ταῖς πρὸς τὸν Ἰώσηπον ἐντολαῖς ἐπεδείξω τὸν πρὸς ἡμᾶς ἔρωτα κτεῖναί με προστάξας.", "st": "1.22.4"}, {"sp": "N", "t": "Ἔκφρων εὐθέως ἀκούσας τὸ ἀπόρρητον ἦν, καὶ οὐκ ἄν ποτε τὸν Ἰώσηπον ἐξαγγεῖλαι τὴν ἐντολὴν φάμενος εἰ μὴ διαφθείρειεν αὐτήν, ἐνεθουσία τῷ πάθει καὶ τῆς κοίτης ἐξαλλόμενος ἀνέδην ἐν τοῖς βασιλείοις ἀνειλεῖτο. καὶ τοῦτον Σαλώμη ἡ ἀδελφὴ τὸν καιρὸν εἰς τὰς διαβολὰς ἁρπάσασα τὴν εἰς τὸν Ἰώσηπον ἐπεβεβαίωσεν ὑποψίαν. ὁ δ’ ὑπ’ ἀκράτου ζηλοτυπίας ἐκμανεὶς παραχρῆμα κτείνειν προσέταξεν ἀμφοτέρους. μετάνοια δ’ εὐθέως εἵπετο τῷ πάθει, καὶ τοῦ θυμοῦ πεσόντος ὁ ἔρως πάλιν ἀνεζωπυρεῖτο. τοσαύτη δ’ ἦν φλεγμονὴ τῆς ἐπιθυμίας ὡς μηδὲ τεθνάναι δοκεῖν αὐτήν, ὑπὸ δὲ κακώσεως ὡς ζώσῃ προσλαλεῖν, μέχρι τῷ χρόνῳ διδαχθεὶς τὸ πένθος ἀνάλογον τὴν λύπην ἔσχεν τῇ πρὸς περιοῦσαν διαθέσει.", "st": "1.22.5"}, {"sp": "N", "t": "Κληρονομοῦσι δὲ τῆς μητρῴας οἱ παῖδες ὀργῆς καὶ τοῦ μύσους ἔννοιαν λαμβάνοντες ὡς πολέμιον ὑφεώρων τὸν πατέρα, καὶ τὸ πρότερον μὲν ἐπὶ Ῥώμης παιδευόμενοι, πλέον δ’ ὡς εἰς Ἰουδαίαν ὑπέστρεψαν· συνηνδροῦτο δ’ αὐτῶν ταῖς ἡλικίαις ἡ διάθεσις. καὶ ἐπειδὴ γάμων ἔχοντες ὥραν ὁ μὲν τῆς τηθίδος Σαλώμης, ἣ τῆς μητρὸς αὐτῶν κατηγόρησεν, ὁ δ’ ἔγημεν Ἀρχελάου τοῦ Καππαδόκων βασιλέως θυγατέρα, προσελάμβανον ἤδη τῷ μίσει καὶ παρρησίαν. ἐκ δὲ τοῦ θράσους αὐτῶν ἀφορμὰς οἱ διαβάλλοντες ἐλάμβανον, καὶ φανερώτερον ἤδη τῷ βασιλεῖ διελέγοντό τινες ὡς ἐπιβουλεύοιτο μὲν ὑπ’ ἀμφοτέρων τῶν υἱῶν, ὁ δὲ Ἀρχελάῳ κηδεύσας καὶ φυγὴν παρασκευάζοιτο τῷ πενθερῷ πεποιθώς, ἵν’ ἐπὶ Καίσαρος αὐτοῦ κατηγορήσειεν. ἀναπλησθεὶς δὲ τῶν διαβολῶν Ἡρώδης ὥσπερ ἐπιτείχισμα τοῖς υἱοῖς κατάγει τὸν ἐκ τῆς Δωρίδος Ἀντίπατρον καὶ πάντα τρόπον προτιμᾶν ἄρχεται.", "st": "1.23.1"}, {"sp": "N", "t": "Τοῖς δ’ ἀφόρητος ἦν ἡ μεταβολή, καὶ τὸν ἐξ ἰδιώτιδος μητρὸς ὁρῶντες προκόπτοντα διὰ τὴν ἑαυτῶν εὐγένειαν οὐκ ἐκράτουν τῆς ἀγανακτήσεως, ἐφ’ ἑκάστου δὲ τῶν ἀνιαρῶν τὴν ὀργὴν ἐξέφαινον, ὥσθ’ οἱ μὲν καθ’ ἡμέραν προσίσταντο μᾶλλον, ὁ δ’ Ἀντίπατρος ἤδη καὶ δι’ αὑτὸν ἐσπουδάζετο, δεινότατος μὲν ὢν ἐν ταῖς πρὸς τὸν πατέρα κολακείαις, διαβολὰς δὲ κατὰ τῶν ἀδελφῶν ποικίλας ἐνσκευαζόμενος καὶ τὰ μὲν αὐτὸς λογοποιῶν, τὰ δὲ τοὺς ἐπιτηδείους φημίζειν καθιείς, μέχρι παντάπασιν τοὺς ἀδελφοὺς ἀπέρρηξεν τῆς βασιλικῆς ἐλπίδος· καὶ γὰρ ἐν ταῖς διαθήκαις καὶ φανερῶς αὐτὸς ἦν ἤδη διάδοχος· ὡς βασιλεὺς γοῦν ἐπέμφθη καὶ πρὸς Καίσαρα τῷ τε κόσμῳ καὶ ταῖς ἄλλαις θεραπείαις πλὴν διαδήματος χρώμενος. χρόνῳ δ’ ἐξίσχυσεν εἰσαγαγεῖν ἐπὶ τὴν Μαριάμμης κοίτην τὴν μητέρα. δυσὶ δ’ ὅπλοις κατὰ τῶν ἀδελφῶν χρώμενος, κολακείᾳ καὶ διαβολῇ, τὸν βασιλέα καὶ περὶ θανάτου τῶν υἱῶν ὑπειργάσατο.", "st": "1.23.2"}, {"sp": "N", "t": "Τὸν γοῦν Ἀλέξανδρον σύρας μέχρι Ῥώμης ὁ πατὴρ τῆς ἐφ’ ἑαυτῷ φαρμακείας ἔκρινεν ἐπὶ Καίσαρος. ὁ δ’ εὑρὼν μόλις ὀλοφυρμοῦ παρρησίαν καὶ δικαστὴν ἐμπειρότατον Ἀντιπάτρου καὶ Ἡρώδου φρονιμώτερον, τὰ μὲν ἁμαρτήματα τοῦ πατρὸς αἰδημόνως ὑπεστείλατο, τὰς δ’ αὐτοῦ διαβολὰς ἰσχυρῶς ἀπελύσατο. καθαρὸν δὲ καὶ τὸν ἀδελφὸν ἀποδείξας κοινωνοῦντα τῶν κινδύνων, οὕτως ἤδη τό τε Ἀντιπάτρου πανοῦργον καὶ τὴν αὐτῶν ἀτιμίαν ἀπωδύρετο. συνήργει δ’ αὐτῷ μετὰ καθαροῦ τοῦ συνειδότος ἡ περὶ λόγους ἰσχύς· ἦν γὰρ δὴ δεινότατος εἰπεῖν. καὶ τὸ τελευταῖον φάμενος ὡς τῷ πατρὶ κτείνειν αὐτοὺς ἔστιν † ἡδὺ καὶ προτίθεται τὸ ἔγκλημα, προήγαγεν μὲν εἰς δάκρυα πάντας, τὸν δὲ Καίσαρα διέθηκεν οὕτως ὡς ἀπογνῶναι μὲν αὐτῶν τὰ κατηγορημένα, διαλλάξαι δὲ Ἡρώδην εὐθέως. αἱ διαλλαγαὶ δ’ ἐπὶ τούτοις ἦσαν, ὥστε ἐκείνους μὲν τῷ πατρὶ πάντα πειθαρχεῖν, τὸν δὲ τὴν βασιλείαν καταλιπεῖν ᾧ βούλεται.", "st": "1.23.3"}, {"sp": "N", "t": "Μετὰ ταῦτα δ’ ἀπὸ Ῥώμης ὑπέστρεφεν ὁ βασιλεύς, τῶν μὲν ἐγκλημάτων ἀφιέναι τοὺς υἱοὺς δοκῶν, τῆς δ’ ὑπονοίας οὐκ ἀπηλλαγμένος· παρηκολούθει γὰρ Ἀντίπατρος ἡ τοῦ μίσους ὑπόθεσις. ἀλλ’ εἴς γε τὸ φανερὸν τὴν ἀπέχθειαν οὐκ ἐξέφερεν τὸν διαλλακτὴν αἰδούμενος. ὡς δὲ τὴν Κιλικίαν παραπλέων κατῆρεν εἰς Ἐλεοῦσαν, ἑστιᾷ μὲν αὐτὸν φιλοφρόνως Ἀρχέλαος ὑπὲρ τῆς τοῦ γαμβροῦ σωτηρίας εὐχαριστῶν καὶ ταῖς διαλλαγαῖς ἐφηδόμενος, ὡς ἂν καὶ τάχιον γεγραφὼς τοῖς ἐπὶ Ῥώμης φίλοις συλλαμβάνεσθαι περὶ τὴν δίκην Ἀλεξάνδρῳ· προπέμπει δὲ μέχρι Ζεφυρίου δῶρα δοὺς μέχρι τριάκοντα ταλάντων.", "st": "1.23.4"}, {"sp": "N", "t": "Ὡς δ’ εἰς Ἱεροσόλυμα Ἡρώδης ἀφικνεῖται, συναγαγὼν τὸν λαὸν καὶ τοὺς τρεῖς υἱοὺς παραστησάμενος ἀπελογεῖτο περὶ τῆς ἀποδημίας, καὶ πολλὰ μὲν εὐχαρίστει τῷ θεῷ, πολλὰ δὲ Καίσαρι καταστησαμένῳ τὸν οἶκον αὐτοῦ τεταραγμένον καὶ μεῖζόν τι τοῖς υἱοῖς βασιλείας παρασχόντι τὴν ὁμόνοιαν, ἣν αὐτός, ἔφη, συναρμόσω μᾶλλον· ὁ μὲν γὰρ ἐμὲ κύριον τῆς ἀρχῆς καὶ δικαστὴν διαδόχου κατέστησεν, ἐγὼ δὲ μετὰ τοῦ συμφέροντος ἐμαυτῷ κἀκεῖνον ἀμείβομαι. τούσδε τοὺς τρεῖς παῖδας ἀποδείκνυμι βασιλεῖς, καὶ τῆς γνώμης πρῶτον τὸν θεὸν σύμψηφον, ἔπειτα καὶ ὑμᾶς παρακαλῶ γενέσθαι. τῷ μὲν γὰρ ἡλικία, τοῖς δ’ εὐγένεια τὴν διαδοχὴν προξενεῖ, τό γε μὴν μέγεθος τῆς βασιλείας ἀρκεῖ καὶ πλείοσιν. οὓς δὲ Καῖσαρ μὲν ἥνωσεν, καθίστησιν δὲ πατήρ, ὑμεῖς τηρήσατε μήτε ἀδίκους μήτε ἀνωμάλους τὰς τιμὰς διδόντες, ἑκάστῳ δὲ κατὰ τὸ πρεσβεῖον· οὐ γὰρ τοσοῦτον εὐφρανεῖ τις τὸν παρ’ ἡλικίαν θεραπευόμενον, ὅσον ὀδυνήσει τὸν ἀτιμούμενον. οὕς γε μὴν ἑκάστῳ συνεῖναι δεήσει συγγενεῖς καὶ φίλους, ἐγὼ διανεμῶ καὶ τῆς ὁμονοίας ἐγγυητὰς ἐκείνους καταστήσομαι, σαφῶς ἐπιστάμενος ὅτι τὰς στάσεις καὶ τὰς φιλονεικίας γεννῶσιν αἱ τῶν συνδιατριβόντων κακοήθειαι, κἂν ὦσιν οὗτοι χρηστοί, τηροῦσιν τὰς στοργάς. ἀξιῶ δ’ οὐ μόνον τούτους ἀλλὰ καὶ τοὺς ἐν τῇ στρατιᾷ μου ταξιάρχους ἐν ἐμοὶ μόνον τὰς ἐλπίδας ἔχειν ἐπὶ τοῦ παρόντος· οὐ γὰρ βασιλείαν, ἀλλὰ τιμὴν βασιλείας τοῖς υἱοῖς παραδίδωμι, καὶ τῶν μὲν ἡδέων ὡς ἄρχοντες ἀπολαύσουσιν, τὸ βάρος δὲ τῶν πραγμάτων ἐμόν ἐστιν, κἂν μὴ θέλω. σκεπτέσθω δ’ ἕκαστος τήν τε ἡλικίαν μου καὶ τὴν ἀγωγὴν τοῦ βίου καὶ τὴν εὐσέβειαν· οὔτε γὰρ οὕτως εἰμὶ γέρων ὥστ’ ἂν ἀπελπισθῆναι ταχέως, οὔτε εἰς τρυφὴν ἐκδιαιτώμενος, ἣ καὶ νέους ἐπιτέμνεται· τὸ δὲ θεῖον οὕτως τεθεραπεύκαμεν ὥστ’ ἂν ἐπὶ μήκιστον βίου προελθεῖν. ὁ δὴ τοὺς ἐμοὺς παῖδας θεραπεύων ἐπὶ τῇ ἐμῇ καταλύσει δώσει μοι καὶ περὶ ἐκείνων δίκας· οὐ γὰρ ἐγὼ φθονῶν τοῖς ἐξ ἐμοῦ γεγενημένοις ἀνακόπτω τὴν εἰς αὐτοὺς φιλοτιμίαν, ἐπιστάμενος δὲ τοῖς νέοις γίνεσθαι τὰς σπουδὰς θράσους ἐφόδιον. εἴ γε μὴν ἕκαστος ἐνθυμηθείη τῶν προσιόντων, ὅτι χρηστὸς μὲν ὢν παρ’ ἐμοῦ λήψεται τὴν ἀμοιβήν, στασιάζων δὲ καὶ παρὰ τῷ θεραπευομένῳ τὸ κακόηθες ἀνόνητον ἕξει, πάντας οἶμαι τὰ ἐμὰ φρονήσειν, τουτέστιν τὰ τῶν ἐμῶν υἱῶν· καὶ γὰρ τούτοις συμφέρει κρατεῖν ἐμὲ κἀμοὶ τούτους ὁμονοεῖν. ὑμεῖς δέ, ὦ παῖδες ἀγαθοί, πρῶτον μὲν ἐνθυμούμενοι τὴν ἱερὰν φύσιν, ἧς καὶ παρὰ θηρίοις αἱ στοργαὶ μένουσιν, ἔπειτα τὸν ποιησάμενον ἡμῶν τὰς διαλλαγὰς Καίσαρα, τρίτον ἐμὲ τὸν ἐν οἷς ἔξεστιν ἐπιτάσσειν παρακαλοῦντα, μείνατε ἀδελφοί. δίδωμι δὲ ὑμῖν ἐσθῆτα ἤδη καὶ θεραπείαν βασιλικήν· ἐπεύχομαι δὲ καὶ τῷ θεῷ τηρῆσαι τὴν ἐμὴν κρίσιν, ἂν ὁμονοῆτε. ταῦτ’ εἰπὼν καὶ φιλοφρόνως ἕκαστον τῶν υἱῶν κατασπασάμενος διέλυσεν τὸ πλῆθος, τοὺς μὲν συνευχομένους τοῖς εἰρημένοις, ὅσοι δ’ ἐπεθύμουν μεταβολῆς, μηδ’ ἀκηκοέναι προσποιουμένους.", "st": "1.23.5"}, {"sp": "N", "t": "Συναπῄει δὲ τοῖς ἀδελφοῖς ἡ στάσις, καὶ χείρους τὰς ἐπ’ ἀλλήλοις ὑπονοίας ἔχοντες ἀπηλλάγησαν, Ἀλέξανδρος μὲν καὶ Ἀριστόβουλος ὀδυνώμενοι κεκυρωμένου Ἀντιπάτρῳ τοῦ πρεσβείου, Ἀντίπατρος δὲ καὶ τοῦ δευτερεύειν νεμεσῶν τοῖς ἀδελφοῖς. ἀλλ’ ὁ μὲν ποικιλώτατος ὢν τὸ ἦθος ἐχεμυθεῖν τε ᾔδει καὶ πολλῷ τῷ πανούργῳ τὸ πρὸς αὐτοὺς ἐκάλυπτε μῖσος, τοῖς δὲ δι’ εὐγένειαν πᾶν τὸ νοηθὲν ἦν ἐπὶ γλώσσης· καὶ παροξύνοντες μὲν ἐνέκειντο πολλοί, πλείους δὲ τῶν φίλων παρεδύοντο κατάσκοποι. πᾶν δὲ τὸ παρ’ Ἀλεξάνδρῳ λαληθὲν εὐθέως ἦν παρ’ Ἀντιπάτρῳ, καὶ μετὰ προσθήκης μετέβαινεν ἀπὸ Ἀντιπάτρου πρὸς Ἡρώδην· οὔτε γὰρ ἁπλῶς φθεγξάμενος ὁ νεανίας ἀνυπεύθυνος ἦν, ἀλλὰ εἰς διαβολὴν τὸ ῥηθὲν ἐστρέφετο, καὶ μετρίως παρρησιασαμένου μέγιστα τοῖς ἐλαχίστοις προσεπλάττετο. καθίει δ’ Ἀντίπατρος ἀεὶ τοὺς ἐρεθίσοντας, ὅπως αὐτῷ τὸ ψεῦδος ἔχοι τὰς ἀφορμὰς ἀληθεῖς· καὶ τῶν φημιζομένων ἕν τι διελεγχθὲν ἅπασιν πίστιν ἐπετίθει. καὶ τῶν μὲν αὐτοῦ φίλων ἢ φύσει στεγανώτατος ἦν ἕκαστος ἢ κατεσκευάζετο δωρεαῖς ὡς μηδὲν ἐκφέρεσθαι τῶν ἀπορρήτων, καὶ τὸν Ἀντιπάτρου βίον οὐκ ἂν ἥμαρτέν τις εἰπὼν κακίας μυστήριον· τοὺς δὲ Ἀλεξάνδρῳ συνόντας χρήμασιν διαφθείρων ἢ κολακείαις ὑπιὼν ἐς πάντα κατειργάσατο καὶ πεποιήκει προδότας καὶ τῶν πραττομένων ἢ λαλουμένων φῶρας. πάντα δὲ περιεσκεμμένως δραματουργῶν τὰς πρὸς Ἡρώδην ὁδοὺς ταῖς διαβολαῖς ἐποιεῖτο τεχνικωτάτας, αὐτὸς μὲν ἀδελφοῦ προσωπεῖον ἐπικείμενος, καθιεὶς δὲ μηνυτὰς ἑτέρους. κἀπειδὰν ἀπαγγελθείη τι κατ’ Ἀλεξάνδρου, παρελθὼν ὑπεκρίνετο καὶ διασύρειν τὸ ῥηθὲν ἀρξάμενος ἔπειτα κατεσκεύαζεν ἡσυχῆ καὶ πρὸς ἀγανάκτησιν ἐξεκαλεῖτο τὸν βασιλέα. πάντα δὲ εἰς ἐπιβουλὴν ἀνήγετο καὶ τὸ δοκεῖν τῇ σφαγῇ τοῦ πατρὸς ἐφεδρεύειν Ἀλέξανδρον· οὐδὲν γὰρ οὕτως πίστιν ἐχορήγει ταῖς διαβολαῖς, ὡς ἀπολογούμενος Ἀντίπατρος ὑπὲρ αὐτοῦ.", "st": "1.24.1"}, {"sp": "N", "t": "Τούτοις Ἡρώδης ἐξαγριούμενος ὅσον ὑφῄρει καθ’ ἡμέραν τῆς πρὸς τὰ μειράκια στοργῆς, τοσοῦτον Ἀντιπάτρῳ προσετίθει. συναπέκλιναν δὲ καὶ τῶν κατὰ τὸ βασίλειον οἱ μὲν ἑκόντες οἱ δ’ ἐξ ἐπιτάγματος, ὥσπερ Πτολεμαῖος ὁ τιμιώτατος τῶν φίλων, οἵ τε ἀδελφοὶ τοῦ βασιλέως καὶ πᾶσα ἡ γενεά· πάντα γὰρ Ἀντίπατρος ἦν, καὶ τὰ πικρότατον Ἀλεξάνδρῳ, πάντα ἦν ἡ Ἀντιπάτρου μήτηρ, σύμβουλος κατ’ αὐτῶν μητρυιᾶς χαλεπωτέρα καὶ πλεῖόν τι προγόνων μισοῦσα τοὺς ἐκ βασιλίδος. πάντες μὲν οὖν ἐπὶ ταῖς ἐλπίσιν ἐθεράπευον Ἀντίπατρον ἤδη, συναφίστα δ’ ἕκαστον τὰ τοῦ βασιλέως προστάγματα, παραγγείλαντος τοῖς τιμιωτάτοις μήτε προσιέναι μήτε προσέχειν τοῖς περὶ Ἀλέξανδρον. φοβερὸς δ’ ἦν οὐ μόνον τοῖς ἐκ τῆς βασιλείας, ἀλλὰ καὶ τοῖς ἔξωθεν φίλοις· οὐδενὶ γὰρ βασιλέων Καῖσαρ τοσαύτην ἔδωκεν ἐξουσίαν, ὥστε τὸν ἀπ’ αὐτοῦ φυγόντα καὶ μὴ προσηκούσης πόλεως ἐξαγαγεῖν. τὰ δὲ μειράκια τὰς μὲν διαβολὰς ἠγνόει, παρὸ καὶ μᾶλλον ἀφυλάκτως ἐνέπιπτον αὐταῖς· οὐδὲν γὰρ ὁ πατὴρ φανερῶς ἀπεμέμφετο· συνίει δὲ κατὰ μικρὸν ἀπὸ τοῦ ψύγματος καὶ πρὸς τὸ λυποῦν μᾶλλον ἐτραχύνετο. διέθηκεν δὲ πρὸς αὐτὰ καὶ τὸν θεῖον Φερώραν Ἀντίπατρος ἐχθρωδῶς καὶ τὴν τηθίδα Σαλώμην, ὡς ἂν † γαμετὴν οὖσαν, καθομιλῶν ἀεὶ καὶ παροξύνων. συνήργει δὲ καὶ πρὸς τὴν ταύτης ἀπέχθειαν ἡ Ἀλεξάνδρου γυνὴ Γλαφύρα γενεαλογοῦσα τὴν ἑαυτῆς εὐγένειαν, καὶ ὡς πασῶν τῶν κατὰ τὸ βασίλειον εἴη δεσπότις, κατὰ πατέρα μὲν ἀπὸ Τημένου, κατὰ μητέρα δὲ ἀπὸ Δαρείου τοῦ Ὑστάσπεως οὖσα. πολλὰ δὲ ὠνείδιζεν εἰς ἀγένειαν τήν τε ἀδελφὴν τὴν Ἡρώδου καὶ τὰς γυναῖκας, ὧν ἑκάστη δι’ εὐμορφίαν οὐκ ἀπὸ γένους ᾑρέθη. πολλαὶ δ’ ἦσαν, ὡς ἂν ἐφειμένου τε πατρίως Ἰουδαίοις γαμεῖν πλείους καὶ τοῦ βασιλέως ἡδομένου πλείοσιν, αἳ πᾶσαι διὰ τὸ μεγάλαυχον τὸ Γλαφύρας καὶ τὰς λοιδορίας ἐμίσουν Ἀλέξανδρον.", "st": "1.24.2"}, {"sp": "N", "t": "Τὴν δὲ δὴ Σαλώμην καίτοι πενθερὰν οὖσαν αὐτὸς Ἀριστόβουλος ἑαυτῷ διεστασίασεν ὠργισμένην καὶ πρόσθεν ἐπὶ ταῖς ἐκ Γλαφύρας βλασφημίαις· ὠνείδιζεν γὰρ τῇ γυναικὶ συνεχῶς τὴν ταπεινότητα, καὶ ὡς αὐτὸς μὲν ἰδιῶτιν, ὁ δ’ ἀδελφὸς αὐτοῦ Ἀλέξανδρος γήμαι βασιλίδα. τοῦτο κλαίουσα τῇ Σαλώμῃ διήγγειλεν ἡ θυγάτηρ, προσετίθει δ’ ὅτι καὶ τῶν ἄλλων ἀδελφῶν τὰς μὲν μητέρας ἀπειλοῖεν οἱ περὶ Ἀλέξανδρον, ἐπειδὰν παραλάβωσιν τὴν βασιλείαν, ἱστουργοὺς ἅμα ταῖς δούλαις ποιήσειν, αὐτοὺς δὲ κωμῶν γραμματεῖς, ἐπισκώπτοντες ὡς πεπαιδευμένους ἐπιμελῶς. πρὸς ἃ τὴν ὀργὴν οὐ κατασχοῦσα Σαλώμη πάντα διήγγειλεν Ἡρώδῃ· σφόδρα δ’ ἦν ἀξιόπιστος κατὰ γαμβροῦ λέγουσα. καί τις ἑτέρα διαβολὴ συνέδραμεν ἡ τὸν θυμὸν ὑπεκκαύσασα τοῦ βασιλέως· ἤκουσεν γὰρ αὐτοὺς ἀνακαλεῖσθαι μὲν συνεχῶς τὴν μητέρα καὶ κατοιμώζειν ἐπαρωμένους αὐτῷ, πολλάκις δ’ αὐτοῦ διαδιδόντος τῶν Μαριάμμης ἐσθήτων τινὰ ταῖς μεταγενεστέραις γυναιξὶν ἀπειλεῖν, ὡς ἀντὶ τῶν βασιλικῶν ἐν τάχει περιθήσουσιν αὐταῖς ἐκ τριχῶν πεποιημένας.", "st": "1.24.3"}, {"sp": "N", "t": "Διὰ ταῦτα καίτοι τὸ φρόνημα τῶν νεανίσκων ὑποδείσας, ὅμως οὐκ ἀπέκοπτε τὴν ἐλπίδα τῆς διορθώσεως, ἀλλὰ προσκαλεσάμενος αὐτούς, καὶ γὰρ εἰς Ῥώμην ἐκπλεύσειν ἔμελλεν, βραχέα μὲν ἠπείλησεν ὡς βασιλεύς, τὰ πολλὰ δὲ ἐνουθέτησεν ὡς πατήρ, καὶ φιλεῖν τοὺς ἀδελφοὺς παρεκάλει διδοὺς τῶν προημαρτημένων ἄφεσιν, εἰ πρὸς τὸ μέλλον ἀμείνους γένοιντο. οἱ δὲ τὰς μὲν διαβολὰς ἀπεσκευάζοντο ψευδεῖς εἶναι λέγοντες, πιστώσεσθαι δὲ τὴν ἀπολογίαν τοῖς ἔργοις ἔφασκον· δεῖν μέντοι κἀκεῖνον ἀποφράττειν τὰς λογοποιίας τῷ μὴ πιστεύειν ῥᾳδίως· οὐ γὰρ ἐπιλείψειν τοὺς καταψευσομένους αὐτῶν, ἕως ἂν ὁ πειθόμενος ᾖ.", "st": "1.24.4"}, {"sp": "N", "t": "Τούτοις ὡς πατέρα πείσαντες ταχέως τὸν μὲν ἐν χερσὶν φόβον διεκρούσαντο, τὴν δ’ εἰς τὰ μέλλοντα λύπην προσέλαβον· ἔγνωσαν γὰρ τήν τε Σαλώμην ἐχθρὰν καὶ τὸν θεῖον Φερώραν· ἦσαν δὲ βαρεῖς [μὲν] ἀμφότεροι καὶ χαλεποί, Φερώρας δὲ μείζων, ὃς πάσης μὲν ἐκοινώνει τῆς βασιλείας πλὴν διαδήματος, προσόδους δὲ ἰδίας εἶχεν ἑκατὸν τάλαντα, τὴν δὲ πέραν Ἰορδάνου πᾶσαν ἐκαρποῦτο χώραν λαβὼν παρὰ τἀδελφοῦ δῶρον, ὃς αὐτὸν ἐποίησεν καὶ τετράρχην αἰτησάμενος παρὰ Καίσαρος, βασιλικῶν τε γάμων ἠξίωσεν συνοικίσας ἀδελφὴν τῆς ἰδίας γυναικός· μετὰ δὲ τὴν ἐκείνης τελευτὴν καθωσίωσε τὴν πρεσβυτάτην τῶν ἑαυτοῦ θυγατέρων ἐπὶ προικὶ τριακοσίοις ταλάντοις. ἀλλ’ ἀπέδρα Φερώρας τὸν βασιλικὸν γάμον πρὸς ἔρωτα δούλης, ἐφ’ ᾧ χαλεπήνας Ἡρώδης τὴν μὲν θυγατέρα τῷ πρὸς Πάρθων ὕστερον ἀναιρεθέντι συνέζευξεν ἀδελφιδῷ· Φερώρᾳ δὲ μετ’ οὐ πολὺ τὴν ὀργὴν ἀνίει διδοὺς συγγνώμην τῇ νόσῳ.", "st": "1.24.5"}, {"sp": "N", "t": "Διεβάλλετο δὲ καὶ πάλαι μὲν ἔτι ζώσης τῆς βασιλίδος ἐπιβουλεύειν αὐτῷ φαρμάκοις, τότε δὲ πλεῖστοι μηνυταὶ προσῄεσαν, ὡς καίπερ φιλαδελφότατον ὄντα τὸν Ἡρώδην εἰς πίστιν ὑπαχθῆναι τῶν λεγομένων καὶ δέος. πολλοὺς δὲ τῶν ἐν ὑπονοίᾳ βασανίσας τελευταῖον ἦλθεν ἐπὶ τοὺς Φερώρου φίλους. ὧν ἐπιβουλὴν μὲν ἄντικρυς ὡμολόγησεν οὐδείς, ὅτι δὲ τὴν ἐρωμένην ἁρπασάμενος εἰς Πάρθους ἀποδρᾶναι παρεσκευάζετο, συμμέτοχοι δὲ τοῦ σκέμματος αὐτῷ καὶ τῆς φυγῆς Κοστόβαρος ὁ Σαλώμης ἀνήρ, ᾧ συνῴκισεν αὐτὴν ὁ βασιλεὺς ἐπὶ μοιχείᾳ τοῦ προτέρου διαφθαρέντος. ἦν δ’ ἐλευθέρα διαβολῆς οὐδὲ Σαλώμη· καὶ γὰρ αὐτῆς Φερώρας ἁδελφὸς κατηγόρει συνθήκας περὶ γάμου πρὸς Συλλαῖον τὸν Ὀβαίδα τοῦ Ἀράβων βασιλέως ἐπίτροπον, ὃς ἦν ἐχθρότατος Ἡρώδῃ. διελεγχθεῖσα δὲ καὶ τοῦτο καὶ πάνθ’ ὅσα Φερώρας ἐνεκάλει, συγγινώσκεται· καὶ αὐτὸν δὲ Φερώραν ὁ βασιλεὺς ἀπέλυσεν τῶν ἐγκλημάτων.", "st": "1.24.6"}, {"sp": "N", "t": "Μετέβαινεν δὲ ἐπ’ Ἀλέξανδρον ὁ χειμὼν τῆς οἰκίας καὶ περὶ τὴν ἐκείνου κεφαλὴν ὅλος ἀπηρείσατο. τρεῖς ἦσαν εὐνοῦχοι τιμιώτατοι τῷ βασιλεῖ, καὶ δῆλον ἐξ ὧν ἐλειτούργουν· τῷ μὲν γὰρ οἰνοχοεῖν προσετέτακτο, τῷ δὲ δεῖπνον προσφέρειν, ὁ δ’ αὐτὸν κατεκοίμιζέν τε καὶ συγκατεκλίνετο. τούτους εἰς τὰ παιδικὰ δώροις μεγάλοις ὑπηγάγετο ὁ Ἀλέξανδρος. μηνυθὲν δὲ τῷ βασιλεῖ διηλέγχοντο βασάνοις, καὶ τὴν μὲν συνουσίαν εὐθέως ὡμολόγουν, ἐξέφερον δὲ καὶ τὰς εἰς αὐτὴν ὑποσχέσεις, ὃν τρόπον ἀπατηθεῖεν ὑπὸ Ἀλεξάνδρου λέγοντος, ὡς οὐκ ἐν Ἡρώδῃ δέοι τὰς ἐλπίδας ἔχειν ἀναιδεῖ γέροντι καὶ βαπτομένῳ τὰς κόμας, εἰ μὴ διὰ τοῦτ’ αὐτὸν οἴονται καὶ νέον, αὐτῷ δὲ προσέχειν, ὃς καὶ παρὰ ἄκοντος διαδέξεται τὴν βασιλείαν οὐκ εἰς μακράν τε τοὺς μὲν ἐχθροὺς ἀμυνεῖται, τοὺς φίλους δ’ εὐδαίμονας ποιήσει καὶ μακαρίους, πρὸ πάντων δὲ αὐτούς· εἶναι δὲ καὶ θεραπείαν τῶν δυνατῶν περὶ τὸν Ἀλέξανδρον λαθραίαν, τούς τε ἡγεμόνας τοῦ στρατιωτικοῦ καὶ τοὺς ταξιάρχους κρύφα πρὸς αὐτὸν συνιέναι.", "st": "1.24.7"}, {"sp": "N", "t": "Ταῦτα τὸν Ἡρώδην οὕτως ἐξεφόβησεν, ὡς μηδὲ παραχρῆμα τολμῆσαι τὰς μηνύσεις ἐκφέρειν, ἀλλὰ κατασκόπους ὑποπέμπων νύκτωρ καὶ μεθ’ ἡμέραν ἕκαστα τῶν πραττομένων ἢ λεγομένων διηρεύνα καὶ τοὺς ἐν ταῖς ὑποψίαις εὐθέως ἀνῄρει. δεινῆς δὲ ἀνομίας ἐνεπλήσθη τὸ βασίλειον· κατὰ γὰρ ἔχθραν ἢ μῖσος ἴδιον ἕκαστος ἔπλασσεν τὰς διαβολάς, καὶ πολλοὶ πρὸς τοὺς διαφόρους φονῶντι τῷ βασιλικῷ θυμῷ κατεχρῶντο. καὶ τὸ μὲν ψεῦδος εἶχεν παραχρῆμα πίστιν, αἱ κολάσεις δὲ τῶν διαβολῶν ἦσαν ὠκύτεραι. κατηγορεῖτο γοῦν τις ἄρτι κατηγορήσας, καὶ τῷ πρὸς αὐτοῦ διελεγχθέντι συναπήγετο· τὰς γὰρ ἐξετάσεις τοῦ βασιλέως ὁ περὶ τῆς ψυχῆς κίνδυνος ἐπετέμνετο. προύβη δ’ εἰς τοσοῦτον πικρίας, ὡς μηδὲ τῶν ἀκαταιτιάτων τινὶ προσβλέπειν ἡμέρως, εἶναι δὲ καὶ τοῖς φίλοις ἀπηνέστατος· πολλοῖς γοῦν αὐτῶν ἀπεῖπεν τὸ βασίλειον, καὶ πρὸς οὓς οὐκ εἶχεν χειρὸς ἐξουσίαν τῷ λόγῳ χαλεπὸς ἦν. συνεπέβη δὲ Ἀντίπατρος ἐν ταῖς συμφοραῖς Ἀλεξάνδρῳ καὶ στῖφος ποιήσας τῶν συγγενῶν οὐκ ἔστιν ἥντινα διαβολὴν παρέλιπεν. προήχθη γέ τοι πρὸς τοσοῦτον δέος ὁ βασιλεὺς ὑπὸ τῆς τερατείας αὐτοῦ καὶ τῶν συνταγμάτων, ὡς ἐφεστάναι δοκεῖν αὐτῷ τὸν Ἀλέξανδρον ξιφήρη. συλλαβὼν οὖν αὐτὸν ἐξαπίνης ἔδησεν καὶ πρὸς βάσανον ἐχώρει τῶν φίλων αὐτοῦ. σιγῶντες δὲ ἀπέθνησκον πολλοὶ καὶ μηδὲν ὑπὲρ τὸ συνειδὸς εἰπόντες· οἱ δ’ ὑπὸ τῶν ἀλγηδόνων ψεύσασθαι βιασθέντες ἔλεγον, ὡς ἐπιβουλεύοι τε αὐτῷ μετὰ Ἀριστοβούλου τοῦ ἀδελφοῦ καὶ παραφυλάττει κυνηγοῦντα κτείνας εἰς Ῥώμην ἀποδρᾶναι. τούτοις καίπερ οὐ πιθανοῖς οὖσιν ἀλλ’ ὑπὸ τῆς ἀνάγκης ἐσχεδιασμένοις ὁ βασιλεὺς ἐπίστευσεν ἡδέως, παραμυθίαν λαμβάνων τοῦ δῆσαι τὸν υἱὸν τὸ μὴ δοκεῖν ἀδίκως.", "st": "1.24.8"}, {"sp": "N", "t": "Ὁ δ’ Ἀλέξανδρος ἐπεὶ τὸν πατέρα μεταπείθειν ἀμήχανον ἑώρα, τοῖς δεινοῖς ὁμόσε χωρεῖν διέγνω, καὶ τέσσαρας κατὰ τῶν ἐχθρῶν βίβλους συνταξάμενος προσωμολόγει μὲν τὴν ἐπιβουλήν, κοινωνοὺς δ’ ἀπεδείκνυεν τοὺς πλείστους αὐτῶν, πρὸ δὲ πάντων Φερώραν καὶ Σαλώμην· ταύτην γὰρ δὴ καὶ μιγῆναί ποτε αὐτῷ μὴ θέλοντι νύκτωρ εἰσβιασαμένην. αἵ τε οὖν βίβλοι παρῆσαν εἰς χεῖρας Ἡρώδῃ πολλὰ καὶ δεινὰ κατὰ τῶν δυνατωτάτων βοῶσαι, καὶ διὰ τάχους εἰς Ἰουδαίαν Ἀρχέλαος ἀφικνεῖται περὶ τῷ γαμβρῷ καὶ τῇ θυγατρὶ δείσας. γίνεται δὲ βοηθὸς αὐτοῖς μάλα προμηθὴς καὶ τέχνῃ τὴν τοῦ βασιλέως ἀπειλὴν διεκρούσατο. συμβαλὼν γὰρ εὐθέως αὐτῷ ποῦ ποτέ ἐστιν ὁ ἀλιτήριός μου γαμβρός, ἐβόα, ποῦ δὲ τὴν πατροκτόνον ὄψομαι κεφαλήν, ἣν ταῖς ἐμαυτοῦ χερσὶν διασπαράξω; προσθήσω δὲ καὶ τὴν θυγατέρα μου τῷ καλῷ νυμφίῳ· καὶ γὰρ εἰ μὴ κεκοινώνηκεν τοῦ σκέμματος, ὅτι τοιούτου γυνὴ γέγονεν, μεμίανται. θαυμάζω δὲ καὶ σὲ τὸν ἐπιβουλευθέντα τῆς ἀνεξικακίας, εἰ ζῇ μέχρι νῦν Ἀλέξανδρος· ἐγὼ γὰρ ἠπειγόμην ἀπὸ Καππαδοκίας ὡς τὸν μὲν εὑρήσων πάλαι δεδωκότα δίκας, μετὰ δὲ σοῦ περὶ τῆς θυγατρὸς ἐξετάσων, ἣν ἐκείνῳ γε πρὸς τὸ σὸν ἀξίωμα βλέπων ἐνεγγύησα. νῦν δὲ περὶ ἀμφοῖν ἡμῖν βουλευτέον, κἂν ᾖς πατὴρ λίαν ἢ τοῦ κολάζειν υἱὸν ἀτονώτερος ἐπίβουλον, ἀμείψωμεν τὰς δεξιὰς καὶ γενώμεθα τῆς ἀλλήλων ὀργῆς διάδοχοι.", "st": "1.25.1"}, {"sp": "N", "t": "Τούτοις περικομπήσας καίπερ παρατεταγμένον Ἡρώδην ὑπάγεται· δίδωσι γοῦν αὐτῷ τὰς συνταχθείσας ὑπ’ Ἀλεξάνδρου βίβλους ἀναγνῶναι καὶ καθ’ ἕκαστον ἐφιστὰς κεφάλαιον συνεσκέπτετο. λαμβάνει δ’ Ἀρχέλαος ἀφορμὴν τοῦ στρατηγήματος καὶ κατὰ μικρὸν εἰς τοὺς ἐγγεγραμμένους καὶ Φερώραν μετήγαγεν τὰς αἰτίας. ὡς δ’ ἑώρα πιστεύοντα τὸν βασιλέα, σκεπτέον, ἔφη, μή ποτε τὸ μειράκιον ὑπὸ τοσούτων εἴη πονηρῶν ἐπιβουλευόμενον, οὐχ ὑπὸ τοῦ μειρακίου σύ· καὶ γὰρ οὐχ ὁρᾶν αἰτίαν, ἐξ ἧς ἂν εἰς τηλικοῦτον μύσος προέπεσεν, ἀπολαύων μὲν ἤδη βασιλείας, ἐλπίζων δὲ καὶ διαδοχήν, εἰ μή τινες ἦσαν ἀναπείθοντες καὶ τὸ τῆς ἡλικίας εὔκολον ἐπὶ κακῷ μεταχειριζόμενοι. διὰ γὰρ τῶν τοιούτων ἐξαπατᾶσθαι μὲν οὐκ ἐφήβους μόνον ἀλλὰ καὶ γέροντας, οἴκους δὲ λαμπροτάτους καὶ βασιλείας ὅλας ἀνατρέπεσθαι.", "st": "1.25.2"}, {"sp": "N", "t": "Συνῄνει τοῖς λεγομένοις Ἡρώδης, καὶ τὴν μὲν πρὸς Ἀλέξανδρον ὀργὴν ἐπανίει πρὸς ὀλίγον, πρὸς δὲ Φερώραν παρωξύνετο· τῶν γὰρ τεσσάρων βίβλων οὗτος ἦν ὑπόθεσις. ὃς κατιδὼν τό τε τοῦ βασιλέως ὀξύρροπον καὶ τὴν Ἀρχελάου φιλίαν παρ’ αὐτῷ πάντων κρατοῦσαν, ὡς οὐκ ἐνῆν εὐσχήμονι σωτηρία, τὴν δι’ ἀναιδείας ἐπορίζετο· καταλείψας γοῦν Ἀλέξανδρον προσέφυγεν Ἀρχελάῳ. κἀκεῖνος οὐχ ὁρᾶν ἔφη, πῶς ἂν αὐτὸν ἐξαιτήσαιτο τοσούτοις ἐνεχόμενον ἐγκλήμασιν, ἐξ ὧν σαφῶς ἀποδείκνυται τοῦ βασιλέως ἐπίβουλος καὶ τῶν παρόντων τῷ μειρακίῳ κακῶν αἴτιος γεγονώς, εἰ μὴ βούλεται τὸ πανοῦργον καὶ τὰς ἀρνήσεις ἀφεὶς προσομολογῆσαι μὲν τὰ κατηγορημένα, συγγνώμην δ’ αἰτήσασθαι παρὰ τἀδελφοῦ καὶ φιλοῦντος· εἰς γὰρ τοῦτο πάντα τρόπον αὐτὸς συνεργήσειν.", "st": "1.25.3"}, {"sp": "N", "t": "Πείθεται Φερώρας, καὶ κατασκευάσας ἑαυτόν, ὡς ἂν οἰκτρότατος φανείη, μελαίνῃ τε ἐσθῆτι καὶ δακρύοις προσπίπτει τοῖς Ἡρώδου ποσίν, ὡς πολλάκις ἔτυχεν συγγνώμης αἰτούμενος καὶ μιαρὸν μὲν ἑαυτὸν ὁμολογῶν, δεδρακέναι γὰρ πάντα, ὅσα κατηγοροῖτο, παρακοπὴν δὲ φρενῶν καὶ μανίαν ὀδυρόμενος, ἧς αἴτιον εἶναι τὸν ἔρωτα τῆς γυναικὸς ἔλεγεν. παραστήσας δὴ κατήγορον καὶ μάρτυν ἑαυτοῦ Φερώραν Ἀρχέλαος οὕτως ἤδη παρῃτεῖτο καὶ τὴν Ἡρώδου κατέστελλεν ὀργὴν χρώμενος οἰκείοις ὑποδείγμασιν· καὶ γὰρ αὐτὸς πολλῷ χαλεπώτερα πάσχων ὑπὸ τἀδελφοῦ τῆς ἀμύνης ἐπίπροσθεν τίθεσθαι τὸ τῆς φύσεως δίκαιον· ἐν γὰρ ταῖς βασιλείαις ὥσπερ ἐν μεγάλοις σώμασιν ἀεί τι μέρος φλεγμαίνειν ὑπὸ τοῦ βάρους, ὅπερ ἀποκόπτειν μὲν οὐ χρῆναι, θεραπεύειν δὲ πρᾳότερον.", "st": "1.25.4"}, {"sp": "N", "t": "Πολλὰ τοιαῦτα λέγων Ἡρώδην μὲν ἐπὶ Φερώρᾳ μειλίσσεται, διέμενε δ’ αὐτὸς ἀγανακτῶν πρὸς Ἀλέξανδρον καὶ τὴν θυγατέρα διαζεύξας ἀπάξειν ἔφασκεν, ἕως περιέστησεν Ἡρώδην ἀντιπαρακαλεῖν ὑπὲρ τοῦ μειρακίου καὶ πάλιν αὐτῷ μνηστεύεσθαι τὴν θυγατέρα. σφόδρα δὲ ἀξιοπίστως Ἀρχέλαος ᾧ βούλεται συνοικίζειν αὐτὴν ἐπέτρεπεν πλὴν Ἀλεξάνδρου· περὶ πλείστου γὰρ ποιεῖσθαι τηρεῖν πρὸς αὐτὸν τὰ τῆς ἐπιγαμίας δίκαια. φαμένου δὲ τοῦ βασιλέως δῶρον ἕξειν παρ’ αὐτοῦ τὸν υἱόν, εἰ μὴ λύσειεν τὸν γάμον, ὄντων μὲν αὐτοῖς ἤδη καὶ τέκνων, στεργομένης δ’ οὕτως ὑπὸ τοῦ μειρακίου τῆς γυναικός, ἣν παραμένουσαν μὲν ἔσεσθαι δυσώπημα τῶν ἁμαρτημάτων, ἀπορραγεῖσαν δὲ αἰτίαν τῆς εἰς ἅπαντα ἀπογνώσεως· μαλακωτέρας γὰρ γίνεσθαι τὰς τόλμας πάθεσιν οἰκείοις περισπωμένας· κατανεύει μόλις Ἀρχέλαος διαλλάσσεταί τε καὶ διαλλάσσει τῷ νεανίσκῳ τὸν πατέρα· δεῖν μέντοι πάντως ἔφη πέμπειν αὐτὸν εἰς Ῥώμην Καίσαρι διαλεξόμενον· γεγραφέναι γὰρ αὐτὸς ἐκείνῳ περὶ πάντων.", "st": "1.25.5"}, {"sp": "N", "t": "Τὸ μὲν οὖν Ἀρχελάου στρατήγημα, δι’ οὗ τὸν γαμβρὸν ἐρρύσατο, πέρας εἶχεν, μετὰ δὲ τὰς διαλλαγὰς ἐν εὐωχίαις καὶ φιλοφρονήσεσιν διῆγον. ἀπιόντα δ’ αὐτὸν Ἡρώδης δωρεῖται ταλάντων ἑβδομήκοντα δώροις θρόνῳ τε χρυσῷ διαλίθῳ καὶ εὐνούχοις καὶ παλλακίδι, ἥτις ἐκαλεῖτο Παννυχίς, τῶν τε φίλων ἐτίμησεν κατ’ ἀξίαν ἕκαστον. ὁμοίως τε καὶ οἱ συγγενεῖς προστάξαντος τοῦ βασιλέως πάντες Ἀρχελάῳ δῶρα λαμπρὰ ἔδοσαν, προεπέμφθη τε ὑπό τε Ἡρώδου καὶ τῶν δυνατῶν ἕως Ἀντιοχείας.", "st": "1.25.6"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ εἰς τὴν Ἰουδαίαν παρέβαλεν ἀνὴρ πολὺ τῶν Ἀρχελάου στρατηγημάτων δυνατώτερος, ὃς οὐ μόνον τὰς ὑπ’ ἐκείνου πολιτευθείσας Ἀλεξάνδρῳ διαλλαγὰς ἀνέτρεψεν, ἀλλὰ καὶ ἀπωλείας αἴτιος αὐτῷ κατέστη. γένος ἦν Λάκων, Εὐρυκλῆς τοὔνομα, πόθῳ χρημάτων εἰς τὴν βασιλείαν εἰσφθαρείς· οὐ γὰρ ἀντεῖχεν ἔτι ἡ Ἑλλὰς αὐτοῦ τῇ πολυτελείᾳ. λαμπρὰ δ’ Ἡρώδῃ δῶρα προσενεγκὼν δέλεαρ ὧν ἐθηρᾶτο καὶ παραχρῆμα πολλαπλασίω λαβὼν οὐδὲν ἡγεῖτο τὴν καθαρὰν δόσιν, εἰ μὴ δι’ αἵματος ἐμπορεύσεται τὴν βασιλείαν. περιέρχεται γοῦν τὸν βασιλέα κολακείᾳ καὶ δεινότητι λόγων καὶ περὶ αὐτοῦ ψευδέσιν ἐγκωμίοις. ταχέως δὲ συνιδὼν τὸν Ἡρώδου τρόπον καὶ πάντα λέγων τε καὶ πράττων τὰ πρὸς ἡδονὴν αὐτῷ φίλος ἐν τοῖς πρώτοις γίνεται· καὶ γὰρ ὁ βασιλεὺς διὰ τὴν πατρίδα καὶ πάντες οἱ περὶ αὐτὸν ἡδέως προετίμων τὸν Σπαρτιάτην.", "st": "1.26.1"}, {"sp": "N", "t": "Ὁ δ’ ἐπεὶ τὰ σαθρὰ τῆς οἰκίας κατέμαθεν, τάς τε τῶν ἀδελφῶν διαφορὰς καὶ ὅπως διέκειτο πρὸς ἕκαστον ὁ πατήρ, Ἀντιπάτρου μὲν ξενίᾳ προκατείληπτο, φιλίᾳ δὲ Ἀλέξανδρον ὑποκρίνεται ψευσάμενος ἑταῖρον ἑαυτὸν εἶναι καὶ Ἀρχελάου πάλαι· διὸ δὴ καὶ ταχέως ὡς δεδοκιμασμένος ἐδέχθη, συνίστησιν δ’ αὐτὸν εὐθέως καὶ Ἀριστοβούλῳ τῷ ἀδελφῷ. πάντων δ’ ἀποπειραθεὶς τῶν προσώπων ἄλλον ἄλλως ὑπῄει, γίνεται δὲ προηγουμένως μισθωτὸς Ἀντιπάτρου καὶ προδότης Ἀλεξάνδρου, τῷ μὲν ὀνειδίζων, εἰ πρεσβύτατος ὢν περιόψεται τοὺς ἐφεδρεύοντας αὐτοῦ ταῖς ἐλπίσιν, Ἀλεξάνδρῳ δέ, εἰ γεγενημένος ἐκ βασιλίδος καὶ βασιλίδι συνοικῶν ἐάσει διαδέχεσθαι τὴν ἀρχὴν τὸν ἐξ ἰδιώτιδος, καὶ ταῦτα μεγίστην ἀφορμὴν ἔχων Ἀρχέλαον. ἦν δὲ πιστὸς τῷ μειρακίῳ σύμβουλος τὴν Ἀρχελάου φιλίαν πλασάμενος· διὸ μηδὲν ὑποστελλόμενος Ἀλέξανδρος τά τε κατ’ Ἀντίπατρον ἀπωδύρετο πρὸς αὐτὸν καὶ ὡς Ἡρώδης αὐτῶν τὴν μητέρα κτείνας οὐ παράδοξον εἰ καὶ αὐτοὺς ἀφαιρεῖται τὴν ἐκείνης βασιλείαν· ἐφ’ οἷς ὁ Εὐρυκλῆς οἰκτείρειν τε καὶ συναλγεῖν ὑπεκρίνετο. τὰ δ’ αὐτὰ καὶ τὸν Ἀριστόβουλον εἰπεῖν δελεάσας καὶ ταῖς κατὰ τοῦ πατρὸς μέμψεσιν ἐνδησάμενος ἀμφοτέρους ᾤχετο φέρων Ἀντιπάτρῳ τὰ ἀπόρρητα· προσεπιψεύδεται δ’ ἐπιβουλὴν ὡς ἐνεδρευόντων αὐτὸν τῶν ἀδελφῶν καὶ μόνον οὐκ ἐπιφερόντων ἤδη τὰ ξίφη. λαβὼν δ’ ἐπὶ τούτοις χρημάτων πλῆθος ἐπαινέτης ἦν Ἀντιπάτρου καὶ πρὸς τὸν πατέρα. τὸ δὲ τελευταῖον ἐργολαβήσας τὸν Ἀριστοβούλου καὶ Ἀλεξάνδρου θάνατον κατήγορος αὐτῶν ἐπὶ τοῦ πατρὸς γίνεται καὶ προσελθὼν ἀντιδιδόναι τὸ ζῆν ἔφασκεν Ἡρώδῃ τῶν εἰς αὐτὸν εὐεργεσιῶν καὶ τὸ φῶς ἀμοιβὴν τῆς ξενίας ἀντιπαρέχειν· πάλαι γὰρ ἐπ’ αὐτὸν ἠκονῆσθαι ξίφος καὶ τὴν Ἀλεξάνδρου τετονῶσθαι δεξιάν, ἐμποδὼν δ’ αὐτὸς γεγονέναι τῷ τάχει συνεργεῖν ὑποκριθείς· φάναι γὰρ τὸν Ἀλέξανδρον, ὡς οὐκ ἀγαπᾷ βασιλεύσας αὐτὸς Ἡρώδης ἐν ἀλλοτρίοις καὶ μετὰ τὸν τῆς μητρὸς αὐτῶν φόνον τὴν ἐκείνης ἀρχὴν σπαθήσας, ἀλλ’ ἔτι καὶ νόθον εἰσάγεται διάδοχον Ἀντιπάτρῳ τῷ φθόρῳ τὴν παππῴαν αὐτῶν βασιλείαν προτείνων. τιμωρήσειν γε μὴν αὐτὸς τοῖς Ὑρκανοῦ καὶ τοῖς Μαριάμμης δαίμοσιν· οὐδὲ γὰρ πρέπειν αὐτὸν διαδέξασθαι παρὰ τοιούτου πατρὸς τὴν ἀρχὴν δίχα φόνου. πολλὰ δ’ εἶναι τὰ παροξύνοντα καθ’ ἡμέραν, ὥστε μηδὲ λαλιᾶς τινα τρόπον ἀσυκοφάντητον καταλελεῖφθαι· περὶ μὲν γὰρ εὐγενείας ἑτέρων μνείας γενομένης αὐτὸς ἀλόγως ὑβρίζεσθαι, τοῦ πατρὸς λέγοντος ὁ μόνος εὐγενὴς Ἀλέξανδρος καὶ τὸν πατέρα δι’ ἀγένειαν ἀδοξῶν· κατὰ δὲ τὰς θήρας προσκρούειν μὲν σιωπῶν, ἐπαινέσας δὲ προσακούειν εἴρων. πανταχοῦ δ’ ἀμείλικτον εὑρίσκειν τὸν πατέρα καὶ μόνῳ φιλόστοργον Ἀντιπάτρῳ, δι’ ὃν ἡδέως καὶ τεθνήξεσθαι μὴ κρατήσας τῆς ἐπιβουλῆς. κτείναντι δὲ εἶναι σωτηρίας ἀφορμὴν πρῶτον μὲν Ἀρχέλαον ὄντα κηδεστήν, πρὸς ὃν διαφεύξεσθαι ῥᾳδίως, ἔπειτα Καίσαρα μέχρι νῦν ἀγνοοῦντα τὸν Ἡρώδου τρόπον· οὐ γὰρ ὡς πρότερον αὐτῷ παραστήσεσθαι πεφρικὼς τὸν ἐφεστῶτα πατέρα οὐδὲ φθέγξεσθαι περὶ τῶν ἑαυτοῦ μόνον ἐγκλημάτων, ἀλλὰ πρῶτον μὲν κηρύξειν τὰς τοῦ ἔθνους συμφορὰς καὶ τοὺς μέχρι ψυχῆς φορολογουμένους, ἔπειτ’ εἰς οἵας τρυφὰς καὶ πράξεις τὰ δι’ αἵματος πορισθέντα χρήματα ἀνηλώθη, τούς τε ἐξ ἡμῶν πλουτήσαντας οἷοι, καὶ τὰς θεραπευθείσας πόλεις ἐπὶ τίσιν. ζητήσειν δὲ καὶ τὸν πάππον ἐκεῖ καὶ τὴν μητέρα καὶ τὰ τῆς βασιλείας μύση πάντα κηρύξειν, ἐφ’ οἷς οὐ κριθήσεσθαι πατροκτόνος.", "st": "1.26.2"}, {"sp": "N", "t": "Τοιαῦτα κατ’ Ἀλεξάνδρου τερατευσάμενος Εὐρυκλῆς ἐπῄνει πολλὰ τὸν Ἀντίπατρον, ὡς ἄρα μόνος τε εἴη φιλοπάτωρ καὶ διὰ τοῦτο μέχρι νῦν τῆς ἐπιβουλῆς ἐμπόδιος. μήπω δὲ καλῶς ἐπὶ τοῖς πρώτοις ὁ βασιλεὺς κατεσταλμένος εἰς ἀνήκεστον ὀργὴν ἐξαγριοῦται. καὶ πάλιν λαβὼν καιρὸν Ἀντίπατρος ἑτέρους κατὰ τῶν ἀδελφῶν ὑπέπεμπεν κατηγόρους λέγειν, ὅτι Ἰουκούνδῳ καὶ Τυράννῳ λάθρα διαλέγοιντο τοῖς ἱππάρχοις μέν ποτε τοῦ βασιλέως γενομένοις, τότε δ’ ἔκ τινων προσκρουσμάτων ἀποπεπτωκόσι τῆς τάξεως. ἐφ’ οἷς Ἡρώδης ὑπεραγανακτήσας εὐθέως ἐβασάνισεν τοὺς ἄνδρας. ἀλλ’ οἱ μὲν οὐδὲν τῶν διαβληθέντων ὡμολόγουν, προεκομίσθη δέ τις πρὸς τὸν Ἀλεξανδρείου φρούραρχον ἐπιστολὴ παρὰ Ἀλεξάνδρου παρακαλοῦντος, ἵνα αὐτὸν δέξηται τῷ φρουρίῳ μετὰ Ἀριστοβούλου τοῦ ἀδελφοῦ κτείναντα τὸν πατέρα, καὶ παράσχῃ τοῖς ὅπλοις χρήσασθαι καὶ ταῖς ἄλλαις ἀφορμαῖς. ταύτην Ἀλέξανδρος μὲν ἔλεγεν τέχνασμα εἶναι Διοφάντου· γραμματεὺς δ’ ἦν ὁ Διόφαντος τοῦ βασιλέως, τολμηρὸς ἀνὴρ καὶ δεινὸς μιμήσασθαι πάσης χειρὸς γράμματα· πολλὰ γοῦν παραχαράξας τελευταῖον ἐπὶ τούτῳ [καὶ] κτείνεται. βασανίσας δὲ τὸν φρούραρχον Ἡρώδης οὐδὲν ἤκουσεν οὐδὲ παρ’ ἐκείνου τῶν διαβεβλημένων.", "st": "1.26.3"}, {"sp": "N", "t": "Ἀλλὰ καίτοι τοὺς ἐλέγχους εὑρίσκων ἀσθενεῖς τοὺς υἱοὺς ἐκέλευσεν τηρεῖν, ἔτι μέντοι λελυμένους, τὸν δὲ λυμεῶνα τῆς οἰκίας καὶ δραματουργὸν ὅλου τοῦ μύσους Εὐρυκλέα σωτῆρα καὶ εὐεργέτην καλῶν πεντήκοντα δωρεῖται ταλάντοις. ὁ δὲ τὴν ἀκριβῆ φήμην φθάσας εἰς Καππαδοκίαν ἀργυρίζεται καὶ παρὰ Ἀρχελάου, τολμήσας εἰπεῖν ὅτι καὶ διαλλάξειεν Ἡρώδην Ἀλεξάνδρῳ. διάρας δ’ εἰς τὴν Ἑλλάδα τοῖς ἐκ κακῶν κτηθεῖσιν εἰς ὅμοια κατεχρήσατο· δὶς γοῦν ἐπὶ Καίσαρος κατηγορηθεὶς ἐπὶ τῷ στάσεως ἐμπλῆσαι τὴν Ἀχαΐαν καὶ περιδύειν τὰς πόλεις φυγαδεύεται. κἀκεῖνον μὲν οὕτως ἡ Ἀλεξάνδρου καὶ Ἀριστοβούλου ποινὴ περιῆλθεν.", "st": "1.26.4"}, {"sp": "N", "t": "Ἄξιον δὲ ἀντιθεῖναι τὸν Κῷον Εὐάρεστον τῷ Σπαρτιάτῃ· καὶ γὰρ οὗτος ὢν ἐν τοῖς μάλιστα φίλοις Ἀλεξάνδρῳ καὶ κατὰ τὸν αὐτὸν Εὐρυκλεῖ καιρὸν ἐπιδημήσας πυνθανομένῳ τῷ βασιλεῖ περὶ ὧν ἐκεῖνος διέβαλλεν ὅρκοις τὸ μηδὲν ἀκηκοέναι τῶν μειρακίων ἐπιστώσατο. οὐ μὴν ὤνησέν γέ τι τοὺς ἀθλίους· μόνων γὰρ ἦν τῶν κακῶν ἀκροατὴς ἑτοιμότατος Ἡρώδης καὶ κεχαρισμένος αὐτῷ πᾶς ὁ συμπιστεύων καὶ συναγανακτῶν.", "st": "1.26.5"}, {"sp": "N", "t": "Παρώξυνεν δ’ αὐτοῦ καὶ Σαλώμη τὴν ἐπὶ τοῖς τέκνοις ὠμότητα· ταύτην γὰρ συνδήσασθαι τοῖς κινδύνοις ὁ Ἀριστόβουλος θέλων οὖσαν ἑκυρὰν καὶ τηθίδα, διαπέμπεται σώζειν ἑαυτὴν παραινῶν· παρεσκευάσθαι γὰρ βασιλέα κτείνειν αὐτὴν διαβληθεῖσαν ἐφ’ οἷς καὶ πρότερον, ὅτι Συλλαίῳ τῷ Ἄραβι γήμασθαι σπουδάζουσα λάθρα τὰ τοῦ βασιλέως ἀπόρρητα διαγγέλλοι πρὸς αὐτὸν ἐχθρὸν ὄντα. τοῦτο δ’ ὥσπερ τελευταία θύελλα χειμαζομένους τοὺς νεανίσκους ἐπεβάπτισεν· ἡ γὰρ Σαλώμη δραμοῦσα πρὸς βασιλέα τὴν παραίνεσιν ἐμήνυσεν. κἀκεῖνος οὐκέτι καρτερήσας δεσμεῖ μὲν ἀμφοτέρους τοὺς υἱεῖς καὶ διεχώρισεν ἀπ’ ἀλλήλων, πέμπει δὲ πρὸς Καίσαρα διὰ τάχους Οὐολούμνιόν τε τὸν στρατοπεδάρχην καὶ τῶν φίλων Ὄλυμπον ἐγγράφους τὰς μηνύσεις φέροντας. οἱ δ’ ὡς εἰς Ῥώμην πλεύσαντες ἀπέδοσαν τὰ ἀπὸ τοῦ βασιλέως γράμματα, σφόδρα μὲν ἠχθέσθη Καῖσαρ ἐπὶ τοῖς νεανίσκοις, οὐ μὴν ᾤετο δεῖν ἀφελέσθαι τὸν πατέρα τὴν περὶ τῶν υἱῶν ἐξουσίαν. ἀντιγράφει γοῦν κύριον μὲν αὐτὸν καθιστάς, εὖ μέντοι ποιήσειν λέγων, εἰ μετὰ κοινοῦ συνεδρίου τῶν τε ἰδίων συγγενῶν καὶ τῶν κατὰ τὴν ἐπαρχίαν ἡγεμόνων ἐξετάσειεν τὴν ἐπιβουλήν· κἂν μὲν ἐνέχωνται, κτείνειν, ἐὰν δὲ μόνον ὦσιν δρασμὸν βεβουλευμένοι, κολάζειν μετριώτερον.", "st": "1.27.1"}, {"sp": "N", "t": "Τούτοις Ἡρώδης πείθεται, καὶ παραγενόμενος εἰς Βηρυτόν, ἔνθα προσέταξεν Καῖσαρ, συνῆγε τὸ δικαστήριον. προκαθίζουσίν τε οἱ ἡγεμόνες γραφὲν αὐτοῖς ὑπὸ Καίσαρος, Σατορνῖνός τε καὶ οἱ περὶ Πεδάνιον πρέσβεις, σὺν οἷς [καὶ] Οὐολούμνιος ἐπίτροπος, ἔπειθ’ οἱ τοῦ βασιλέως συγγενεῖς καὶ φίλοι, Σαλώμη τε καὶ Φερώρας, μεθ’ οὓς οἱ πάσης Συρίας ἄριστοι πλὴν Ἀρχελάου τοῦ βασιλέως· τοῦτον γὰρ ὄντα κηδεστὴν Ἀλεξάνδρου δι’ ὑποψίας εἶχεν Ἡρώδης. τούς γε μὴν υἱοὺς οὐ προήγαγεν εἰς τὴν δίκην μάλα προμηθῶς· ᾔδει γάρ, ὅτι καὶ μόνον ὀφθέντες ἐλεηθήσονται πάντως· εἰ δὲ δὴ καὶ λόγου μεταλάβοιεν, ῥᾳδίως Ἀλέξανδρον ἀπολύσεσθαι τὰς αἰτίας. ἀλλ’ οἱ μὲν ἐν Πλατάνῃ κώμῃ Σιδωνίων ἐφρουροῦντο.", "st": "1.27.2"}, {"sp": "N", "t": "Καταστὰς δ’ ὁ βασιλεὺς ὡς πρὸς παρόντας διετείνετο κατηγόρει τε τὴν μὲν ἐπιβουλὴν ἀσθενῶς ὡς ἂν ἀπορούμενος εἰς αὐτὴν ἐλέγχων, λοιδορίας δὲ καὶ σκώμματα καὶ ὕβρεις καὶ πλημμελείας μυρίας εἰς αὐτόν, ἃ καὶ θανάτου χαλεπώτερα τοῖς συνέδροις ἀπέφηνεν. ἔπειτα μηδενὸς ἀντιλέγοντος ἐποικτισάμενος, ὡς αὐτὸς ἁλίσκοιτο καὶ νικῶν νίκην πικρὰν κατὰ τῶν τέκνων, ἐπηρώτα τὴν γνώμην ἑκάστου. καὶ πρῶτος Σατορνῖνος ἀπεφήνατο κατακρίνειν μὲν τῶν νεανίσκων, ἀλλ’ οὐ θάνατον· οὐ γὰρ εἶναι θεμιτὸν αὐτῷ τριῶν παρεστώτων τέκνων ἑτέρου τέκνοις ἀπώλειαν ἐπιψηφίσασθαι. σύμψηφοι δ’ αὐτῷ καὶ οἱ δύο πρεσβευταὶ γίνονται, καὶ τούτοις ἕτεροί τινες ἠκολούθησαν. Οὐολούμνιος δὲ τῆς σκυθρωπῆς ἀποφάσεως ἤρξατο, καὶ μετ’ αὐτὸν πάντες θάνατον κατακρίνουσιν τῶν μειρακίων, οἱ μὲν κολακεύοντες, οἱ δὲ μισοῦντες Ἡρώδην καὶ οὐδεὶς δι’ ἀγανάκτησιν. ἔνθα δὴ μετέωρος ἥ τε Συρία πᾶσα καὶ τὸ Ἰουδαϊκὸν ἦν ἐκδεχομένων τὸ τέλος τοῦ δράματος· οὐδεὶς μέντοι ὑπελάμβανεν ἔσεσθαι μέχρι τεκνοκτονίας ὠμὸν Ἡρώδην. ὁ δὲ σύρας τοὺς υἱοὺς εἰς Τύρον κἀκεῖθεν διαπλεύσας εἰς Καισάρειαν τρόπον ἀναιρέσεως τοῖς μειρακίοις ἐσκέπτετο.", "st": "1.27.3"}, {"sp": "N", "t": "Παλαιὸς δέ τις τοῦ βασιλέως στρατιώτης, ὄνομα Τίρων, ἔχων υἱὸν σφόδρα συνήθη καὶ φίλον Ἀλεξάνδρῳ καὶ αὐτὸς ἠγαπηκὼς ἰδίᾳ τὰ μειράκια, δι’ ὑπερβολὴν ἀγανακτήσεως ἔκφρων ἐγίνετο, καὶ τὸ μὲν πρῶτον ἐβόα περιιὼν πεπατῆσθαι τὸ δίκαιον, ἀπολωλέναι τὴν ἀλήθειαν, συγκεχύσθαι τὴν φύσιν, ἀνομίας γέμειν τὸν βίον, καὶ πάνθ’ ὅσα μὴ φειδομένῳ τοῦ ζῆν ὑπηγόρευε τὸ πάθος. τέλος δὲ καὶ τῷ βασιλεῖ τολμήσας προσελθεῖν ἀλλ’ ἐμοὶ μέν, ἔφη, κακοδαιμονέστατος εἶναι δοκεῖς, ὅστις κατὰ τῶν φιλτάτων πείθῃ τοῖς πονηροτάτοις, εἴ γε Φερώρα καὶ Σαλώμης καταγνοὺς πολλάκις θάνατον πιστεύεις τούτοις κατὰ τῶν τέκνων, οἵ σε τῶν γνησίων περικόπτοντες διαδόχων ἐπ’ Ἀντιπάτρῳ καταλείπουσι μόνῳ, τὸν ἑαυτοῖς εὐμεταχείριστον αἱρούμενοι βασιλέα. σκέψαι μέντοι γε, μή ποτε κἀκείνῳ γένηται μῖσος ἐν τοῖς στρατιώταις ὁ τῶν ἀδελφῶν θάνατος· οὐ γὰρ ἔστιν ὅστις οὐκ ἐλεεῖ τὰ μειράκια, τῶν δὲ ἡγεμόνων καὶ φανερῶς ἀγανακτοῦσιν πολλοί. ταῦθ’ ἅμα λέγων ὠνόμαζεν τοὺς ἀγανακτοῦντας. ὁ δὲ βασιλεὺς εὐθέως ἐκείνους τε καὶ αὐτὸν καὶ τὸν υἱὸν αὐτοῦ συνελάμβανεν.", "st": "1.27.4"}, {"sp": "N", "t": "Ἐφ’ ᾧ τῶν ἐκ τῆς αὐλῆς τις κουρέων, Τρύφων ὄνομα, προεκπηδήσας ἔκ τινος θεοβλαβείας ἑαυτοῦ μηνυτὴς γίνεται. κἀμὲ γάρ, ἔφη, Τίρων οὗτος ἀνέπειθεν, ὅταν θεραπεύω τῷ ξυρῷ σε διαχειρίσασθαι, μεγάλας τέ μοι παρ’ Ἀλεξάνδρου δωρεὰς ὑπισχνεῖτο. ταῦτ’ ἀκούσας Ἡρώδης τόν τε Τίρωνα σὺν τῷ παιδὶ καὶ τὸν κουρέα βασάνοις διήλεγχεν, καὶ τῶν μὲν ἀρνουμένων, τοῦ δὲ μηδὲν πλέον λέγοντος, στρεβλοῦν ἐκέλευσεν τὸν Τίρωνα σφοδρότερον. ὁ δ’ υἱὸς οἰκτείρας ὑπέσχετο τῷ βασιλεῖ πάντα μηνύσειν, εἰ χαρίσαιτο τὸν πατέρα αὐτῷ. κἀκείνου δόντος εἶπεν, ὡς ὁ πατὴρ αὐτοῦ πεισθεὶς Ἀλεξάνδρῳ θελήσειεν αὐτὸν ἀνελεῖν. τοῦθ’ οἱ μὲν εἰς ἀπαλλαγὴν τῆς τοῦ πατρὸς αἰκίας πεπλάσθαι, τινὲς δὲ ἀληθὲς ἔλεγον.", "st": "1.27.5"}, {"sp": "N", "t": "Ἡρώδης γε μὴν ἐν ἐκκλησίᾳ τῶν τε ἡγεμόνων καὶ Τίρωνος κατηγορήσας τὸν λαὸν ἐπ’ αὐτοὺς ἐστρατολόγησεν· αὐτόθι γοῦν ἀναιροῦνται μετὰ τοῦ κουρέως ξύλοις βαλλόμενοι καὶ λίθοις. πέμψας δὲ καὶ τοὺς υἱεῖς εἰς Σεβαστὴν οὖσαν οὐ πόρρω τῆς Καισαρείας προσέταξεν ἀποπνῖξαι. καὶ τελεσθέντος αὐτῷ ταχέως τοῦ προστάγματος τοὺς νεκροὺς εἰς Ἀλεξάνδρειον ἐκέλευσεν ἀνακομισθῆναι τὸ φρούριον συνταφησομένους Ἀλεξάνδρῳ τῷ μητροπάτορι. τὸ μὲν οὖν Ἀλεξάνδρου καὶ Ἀριστοβούλου τέλος τοιοῦτον.", "st": "1.27.6"}, {"sp": "N", "t": "Ἀντιπάτρῳ δὲ ἀδήριτον ἔχοντι τὴν διαδοχὴν μῖσος μὲν ἀφόρητον ἐκ τοῦ ἔθνους ἐπεγείρεται πάντων ἐπισταμένων, ὅτι τὰς διαβολὰς τοῖς ἀδελφοῖς πάσας ἐπισυντάξειεν οὗτος, ὑποικούρει δὲ καὶ δέος οὐ μέτριον αὐξανομένην ὁρῶντι τὴν τῶν ἀνῃρημένων γενεάν· ἦσαν γὰρ Ἀλεξάνδρῳ μὲν ἐκ Γλαφύρας υἱεῖς δύο Τιγράνης καὶ Ἀλέξανδρος, Ἀριστοβούλῳ δ’ ἐκ Βερνίκης τῆς Σαλώμης Ἡρώδης μὲν καὶ Ἀγρίππας καὶ Ἀριστόβουλος υἱοί, θυγατέρες δὲ Ἡρωδιὰς καὶ Μαριάμμη. τὴν μὲν οὖν Γλαφύραν μετὰ τῆς προικὸς Ἡρώδης ἀπέπεμψεν εἰς Καππαδοκίαν, ὡς ἀνεῖλεν Ἀλέξανδρον, τὴν Ἀριστοβούλου δὲ Βερνίκην συνῴκισεν θείῳ πρὸς μητρὸς Ἀντιπάτρου· τὴν γὰρ Σαλώμην οὖσαν διάφορον ἐξοικειούμενος ὁ Ἀντίπατρος τοῦτον ἐπραγματεύσατο τὸν γάμον. περιῄει δὲ καὶ τὸν Φερώραν δώροις τε καὶ ταῖς ἄλλαις θεραπείαις καὶ τοὺς Καίσαρος φίλους οὐκ ὀλίγα πέμπων ἐπὶ Ῥώμης χρήματα. οἵ γε μὴν περὶ Σατορνῖνον ἐν Συρίᾳ πάντες ἐνεπλήσθησαν τῶν ἀπ’ αὐτοῦ δωρεῶν. ἐμισεῖτο δὲ διδοὺς πλεῖον, ὡς ἂν οὐκ ἐκ τοῦ μεγαλοψύχου χαριζόμενος ἀλλ’ ἀναλίσκων κατὰ δέος. συνέβαινεν δὲ τοὺς μὲν λαμβάνοντας οὐδὲν μᾶλλον εὔνους γίνεσθαι, χαλεπωτέρους δ’ ἐχθροὺς οἷς μὴ διδοίη. λαμπροτέρας δὲ καθ’ ἡμέραν ἐποιεῖτο τὰς διαδόσεις ὁρῶν τὸν βασιλέα παρ’ ἃς αὐτὸς ἐλπίδας εἶχεν ἐπιμελούμενον τῶν ὀρφανῶν καὶ τὴν ἐπὶ τοῖς ἀνῃρημένοις μετάνοιαν ἐμφαίνοντα δι’ ὧν ἠλέει τοὺς ἐξ ἐκείνων.", "st": "1.28.1"}, {"sp": "N", "t": "Συναγαγὼν γάρ ποτε Ἡρώδης συγγενεῖς τε καὶ φίλους παραστησάμενός τε τὰ παιδία καὶ δακρύων ἐμπλήσας τοὺς ὀφθαλμοὺς εἶπεν· ἐμὲ τοὺς μὲν τούτων πατέρας δαίμων σκυθρωπὸς ἀφείλετο, ταῦτα δέ μοι μετὰ τῆς φύσεως συνίστησιν ἔλεος ὀρφανίας. πειρῶμαι δ’, εἰ καὶ πατὴρ ἐγενόμην ἀτυχέστατος, πάππος γοῦν γενέσθαι κηδεμονικώτερος καὶ μετ’ ἐμὲ ἡγεμόνας αὐτοῖς ἀπολιπεῖν τοὺς ἐμοὶ φιλτάτους. ἐγγυῶ δὲ τὴν μὲν σήν, ὦ Φερώρα, θυγατέρα τῷ πρεσβυτέρῳ τῶν ἀδελφῶν Ἀλεξάνδρου παίδων, ἵνα ᾖς αὐτῷ κηδεμὼν ἀναγκαῖος, τῷ δὲ σῷ παιδί, Ἀντίπατρε, τὴν Ἀριστοβούλου θυγατέρα· γένοιο γὰρ ἂν οὕτω πατὴρ τῆς ὀρφανῆς. καὶ τὴν ἀδελφὴν αὐτῆς ὁ ἐμὸς Ἡρώδης λήψεται πρὸς μητρὸς ὢν ἀρχιερέως πάππου. τὰ μὲν οὖν ἐμὰ ταύτην ἐχέτω τὴν κρίσιν, ἣν διακόψῃ μηδεὶς τῶν ἐμὲ φιλούντων· ἐπεύχομαι δὲ καὶ τῷ θεῷ συναρμόσαι τοὺς γάμους ἐπὶ συμφέροντι τῆς ἐμῆς βασιλείας καὶ τῶν ἐμῶν ἐκγόνων τά τε παιδία ταυτὶ γαληνοτέροις ἐπιδεῖν ὄμμασιν ἢ τοὺς πατέρας αὐτῶν.", "st": "1.28.2"}, {"sp": "N", "t": "[ἐπειδὴ] ταῦτα εἰπὼν ἀπεδάκρυσέν τε καὶ τῶν παίδων συνήρμοσεν τὰς δεξιάς, ἔπειτα κατασπασάμενος ἕκαστον φιλοφρόνως διέλυσεν τὸ συνέδριον. ἐπαχνώθη δ’ εὐθὺς Ἀντίπατρος καὶ δῆλος ἦν ἅπασιν ὀδυνώμενος· ὑπελάμβανεν γὰρ εἶναι παρὰ τῷ πατρὶ τὴν τῶν ὀρφανῶν τιμὴν ἑαυτοῦ κατάλυσιν αὖθίς τε κινδυνεύσειν περὶ τῶν ὅλων, εἰ πρὸς Ἀρχελάῳ καὶ Φερώραν ὄντα τετράρχην βοηθὸν ἔχοιεν οἱ Ἀλεξάνδρου παῖδες. συνελογίζετο δὲ τὸ ἑαυτοῦ μῖσος καὶ τὸν τῶν ὀρφανῶν ἔλεον ἐκ τοῦ ἔθνους, ὅση τε σπουδὴ ζώντων καὶ ὅση μνήμη παρὰ Ἰουδαίοις τῶν δι’ αὐτὸν ἀπολωλότων ἦν ἀδελφῶν. ἔγνω δὴ πάντα τρόπον διακόπτειν τὰς ἐγγύας.", "st": "1.28.3"}, {"sp": "N", "t": "Καὶ τὸ μὲν ὑπιέναι πανούργως ἔδεισε τὸν πατέρα χαλεπὸν ὄντα καὶ πρὸς τὰς ὑποψίας κινούμενον ὀξέως, ἐτόλμησεν δὲ προσελθὼν ἱκετεύειν ἄντικρυς μὴ στερίσκειν αὐτὸν ἧς ἠξίωσεν τιμῆς, μηδὲ αὐτῷ μὲν ὄνομα βασιλείας, δύναμιν δὲ ὑπάρχειν ἄλλοις· οὐ γὰρ κρατήσειν τῶν πραγμάτων, εἰ πρὸς Ἀρχελάῳ πάππῳ καὶ Φερώραν κηδεστὴν ὁ Ἀλεξάνδρου παῖς προσλάβοι. κατηντιβόλει δὲ πολλῆς οὔσης γενεᾶς κατὰ τὸ βασίλειον μεταθεῖναι τοὺς γάμους· ἦσαν γὰρ τῷ βασιλεῖ γυναῖκες μὲν ἐννέα, τέκνα δὲ ἐκ τούτων ἑπτά, αὐτὸς μὲν Ἀντίπατρος ἐκ Δωρίδος, Ἡρώδης δ’ ἐκ Μαριάμμης τῆς τοῦ ἀρχιερέως θυγατρός, Ἀντίπας δὲ καὶ Ἀρχέλαος ἐκ Μαλθάκης τῆς Σαμαρείτιδος, καὶ θυγάτηρ Ὀλυμπιάς, ἣν ὁ ἀδελφιδοῦς αὐτοῦ Ἰώσηπος εἶχεν, ἐκ δὲ τῆς Ἱεροσολυμίτιδος Κλεοπάτρας Ἡρώδης καὶ Φίλιππος, ἐκ δὲ Παλλάδος Φασάηλος. ἐγένοντο δ’ αὐτῷ καὶ ἄλλαι θυγατέρες Ῥωξάνη τε καὶ Σαλώμη, ἡ μὲν ἐκ Φαίδρας, ἡ δὲ ἐξ Ἐλπίδος. δύο δ’ εἶχεν ἀτέκνους, ἀνεψιάν τε καὶ ἀδελφιδῆν. χωρὶς δὲ τούτων δύο ἀδελφὰς Ἀλεξάνδρου καὶ Ἀριστοβούλου τὰς ἐκ Μαριάμμης. οὔσης δὲ πολυπροσώπου τῆς γενεᾶς ὁ Ἀντίπατρος ἐδεῖτο μετατεθῆναι τοὺς γάμους.", "st": "1.28.4"}, {"sp": "N", "t": "Χαλεπῶς δ’ ὁ βασιλεὺς ἠγανάκτησεν καταμαθὼν αὐτοῦ τὸ πρὸς τοὺς ὀρφανοὺς ἦθος, ἔννοιά τε αὐτῷ παρέστη περὶ τῶν ἀνῃρημένων, μή ποτε κἀκεῖνοι γένοιντο τῶν Ἀντιπάτρου διαβολῶν ἀγώνισμα. τότε μὲν οὖν πολλὰ πρὸς ὀργὴν ἀποκρινάμενος ἀπελαύνει τὸν Ἀντίπατρον, αὖθις δὲ ὑπαχθεὶς αὐτοῦ ταῖς κολακείαις μεθηρμόσατο, καὶ αὐτῷ μὲν τὴν Ἀριστοβούλου συνῴκισεν θυγατέρα, τὸν δὲ υἱὸν αὐτοῦ τῇ Φερώρα θυγατρί.", "st": "1.28.5"}, {"sp": "N", "t": "Καταμάθοι δ’ ἄν τις, ὅσον ἴσχυσεν ἐν τούτοις κολακεύων Ἀντίπατρος, ἐκ τοῦ Σαλώμην ἐν ὁμοίοις ἀποτυχεῖν. ταύτην γὰρ δὴ καίπερ οὖσαν ἀδελφὴν καὶ πολλὰ διὰ Λιουίας τῆς γυναικὸς Καίσαρος ἱκετεύουσαν γαμηθῆναι τῷ Ἄραβι Συλλαίῳ, διωμόσατο μὲν ἐχθροτάτην ἕξειν, εἰ μὴ παύσαιτο τῆς σπουδῆς, τὸ δὲ τελευταῖον ἄκουσαν Ἀλεξᾷ τινι τῶν φίλων συνῴκισεν καὶ τῶν θυγατέρων αὐτῆς τὴν μὲν τῷ Ἀλεξᾶ παιδί, τὴν δ’ ἑτέραν τῷ πρὸς μητρὸς Ἀντιπάτρου θείῳ. τῶν δ’ ἐκ Μαριάμμης θυγατέρων ἡ μὲν ἀδελφῆς υἱὸν Ἀντίπατρον εἶχεν, ἡ δὲ ἀδελφοῦ Φασάηλον.", "st": "1.28.6"}, {"sp": "N", "t": "Διακόψας δὲ τὰς τῶν ὀρφανῶν ἐλπίδας ὁ Ἀντίπατρος καὶ πρὸς τὸ συμφέρον αὐτῷ τὰς ἐπιγαμίας ποιησάμενος ὡς ἐπὶ βεβαίοις μὲν ὥρμει ταῖς ἐλπίσιν, προσλαβὼν δὲ τῇ κακίᾳ τὸ πεποιθὸς ἀφόρητος ἦν· τὸ γὰρ παρ’ ἑκάστῳ μῖσος ἀποσκευάσασθαι μὴ δυνάμενος ἐκ τοῦ φοβερὸς εἶναι τὴν ἀσφάλειαν ἐπορίζετο. συνήργει δὲ καὶ Φερώρας ὡς ἂν ἤδη καὶ βασιλεῖ βεβαίῳ. γίνεται δὲ καὶ γυναικῶν σύνταγμα κατὰ τὴν αὐλήν, ὃ νεωτέρους ἐκίνησεν θορύβους· ἡ γὰρ Φερώρα γυνὴ μετὰ τῆς μητρὸς καὶ τῆς ἀδελφῆς προσλαβοῦσα καὶ τὴν Ἀντιπάτρου μητέρα πολλὰ μὲν ἠσέλγαινεν κατὰ τὸ βασίλειον, ἐτόλμησεν δὲ καὶ τοῦ βασιλέως ὑβρίσαι δύο θυγατέρας, δι’ ἃ δὴ μάλιστα ταύτην ἐκεῖνος προβέβλητο· μισούμεναί γε μὴν ὑπ’ αὐτοῦ τῶν ἄλλων ἐπεκράτουν. μόνη δὲ τῆς ὁμονοίας αὐτῶν ἀντίπαλος ἦν Σαλώμη καὶ βασιλεῖ διέβαλλεν τὴν σύνοδον ὡς οὐκ ἐπ’ ἀγαθῷ τῶν αὐτοῦ πραγμάτων εἴη. γνοῦσαι δ’ ἐκεῖναι τὴν διαβολὴν καὶ ὡς ἀγανακτήσειεν Ἡρώδης, τῆς μὲν φανερᾶς συνόδου καὶ τῶν φιλοφρονήσεων ἐπαύσαντο, τοὐναντίον δ’ ὑπεκρίνοντο καὶ διαφέρεσθαι πρὸς ἀλλήλας ἀκούοντος βασιλέως· αἷς συνυπεκρίνετο καὶ Ἀντίπατρος ἐν τῷ φανερῷ προσκρούων Φερώρᾳ. συνουσίαι δὲ ἦσαν αὐτῶν λάθρα καὶ κῶμοι νυκτερινοί, τήν τε ὁμόνοιαν ἡ παρατήρησις ἐπέτεινεν. ἠγνόει δὲ οὐδὲν Σαλώμη τῶν πραττομένων καὶ πάντα Ἡρώδῃ διήγγελλεν.", "st": "1.29.1"}, {"sp": "N", "t": "Ἐξεκαίετο δ’ ἐκεῖνος εἰς ὀργὴν καὶ μάλιστα ἐπὶ τὴν Φερώρου γυναῖκα· ταύτην γὰρ πλέον ἡ Σαλώμη διέβαλλεν. ἀθροίσας οὖν συνέδριον τῶν τε φίλων καὶ συγγενῶν ἄλλα τε πολλὰ τῆς ἀνθρώπου κατηγόρει καὶ τὴν εἰς τὰς ἑαυτοῦ θυγατέρας ὕβριν, ὅτι τε Φαρισαίοις μὲν χορηγήσειεν μισθοὺς κατ’ αὐτοῦ καὶ τὸν ἀδελφὸν αὐτῷ κατασκευάσειεν πολέμιον ἐνδησαμένη φαρμάκοις. τελευταῖον δ’ εἰς Φερώραν ἀπέστρεφεν τὸν λόγον, δυοῖν θάτερον ἑλέσθαι λέγων, ἢ ἑαυτὸν ἀδελφὸν ἢ τὴν γυναῖκα. τοῦ δὲ θᾶττον ἀπολείψειν τὸ ζῆν ἢ τὴν γυναῖκα φήσαντος, οὐκ ἔχων ὅ τι χρὴ δρᾶν μετέβαινεν ἐπ’ Ἀντίπατρον, ᾧ παρήγγειλεν μήτε τῇ Φερώρα γυναικὶ μήτε αὐτῷ μήτ’ ἄλλῳ τινὶ τῶν ἐκείνης διαλέγεσθαι. ὁ δὲ φανερῶς μὲν οὐ μετέβαινεν τὸ πρόσταγμα, λάθρα δὲ διενυκτέρευεν σὺν ἐκείνοις. καὶ δεδοικὼς τὴν ἐπιτηροῦσαν Σαλώμην πραγματεύεται διὰ τῶν ἐπὶ τῆς Ἰταλίας φίλων τὴν εἰς Ῥώμην ἀποδημίαν αὑτῷ· γραψάντων γὰρ ἐκείνων δεῖν Ἀντίπατρον διὰ χρόνου πεμφθῆναι πρὸς Καίσαρα, ὁ δὲ οὔ τι μελλήσας ἐξέπεμψεν θεραπείαν τε λαμπρὰν καὶ πλεῖστα δοὺς χρήματα τήν τε διαθήκην κομίζειν, ἐν ᾗ βασιλεὺς μὲν Ἀντίπατρος ἐγέγραπτο, Ἀντιπάτρου δὲ Ἡρώδης διάδοχος ὁ ἐκ Μαριάμμης τῆς τοῦ ἀρχιερέως θυγατρὸς γεγονώς.", "st": "1.29.2"}, {"sp": "N", "t": "Ἔπλευσεν δὲ καὶ Συλλαῖος ὁ Ἄραψ ἐπὶ Ῥώμης, ἠμεληκὼς μὲν τῶν Καίσαρος προσταγμάτων, ἀνταγωνιούμενος δὲ πρὸς Ἀντίπατρον περὶ ὧν δεδίκαστο Νικολάῳ τάχιον. οὐ μικρὸς δ’ αὐτῷ καὶ πρὸς Ἀρέταν ἦν ἀγὼν τὸν ἑαυτοῦ βασιλέα· τούτου γὰρ ἄλλους τε φίλους ἀνῃρήκει καὶ Σόαιμον τῶν ἐν Πέτρᾳ δυνατωτάτων. πείσας δὲ πολλοῖς χρήμασιν Φάβατον τὸν Καίσαρος διοικητὴν ἐχρῆτο βοηθῷ καὶ καθ’ Ἡρώδου. πλείονα δὲ δοὺς Ἡρώδης ἀφίστησίν τε ἀπὸ Συλλαίου Φάβατον καὶ δι’ αὐτοῦ τὰ κελευσθέντα ὑπὸ Καίσαρος εἰσέπραττεν. ὁ δὲ μηδὲν ἀποδοὺς ἔτι καὶ κατηγόρει Φαβάτου παρὰ Καίσαρι, διοικητὴν εἶναι λέγων οὐ τῶν ἐκείνῳ, τῶν δὲ Ἡρώδῃ συμφερόντων. ἐφ’ οἷς ὀργισθεὶς Φάβατος, ἦν δ’ ἔτι παρὰ Ἡρώδῃ μάλιστα τιμώμενος, γίνεται προδότης Συλλαίου τῶν ἀπορρήτων τῷ τε βασιλεῖ φησιν, ὅτι Συλλαῖος διαφθείρειεν αὐτοῦ τὸν σωματοφύλακα Κόρινθον χρήμασιν, ὃν δεῖ φυλάττεσθαι. πείθεται δ’ ὁ βασιλεύς· καὶ γὰρ τέθραπτο μὲν ὁ Κόρινθος ἐν τῇ βασιλείᾳ, γένος δ’ ἦν Ἄραψ. συλλαμβάνει δ’ εὐθέως οὐκ αὐτὸν μόνον ἀλλὰ καὶ δύο ἑτέρους Ἄραβας εὑρὼν παρ’ αὐτῷ, τὸν μὲν φίλον Συλλαίου τὸν δὲ φύλαρχον. οἱ δὲ βασανιζόμενοι πεῖσαι Κόρινθον ὡμολόγησαν ἐπὶ πολλοῖς χρήμασιν Ἡρώδην ἀνελεῖν. οὗτοι μὲν οὖν ἀνακριθέντες καὶ παρὰ Σατορνίνῳ τῷ διέποντι τὴν Συρίαν ἀνεπέμφθησαν εἰς Ῥώμην.", "st": "1.29.3"}, {"sp": "N", "t": "Ἡρώδης δὲ οὐκ ἀνίει Φερώραν βιαζόμενος ἀπαλλαγῆναι τῆς γυναικὸς οὐδ’ ἐπενόει μηχανὴν δι’ ἧς ἂν τιμωρήσαιτο τὴν ἄνθρωπον πολλὰς τοῦ μίσους ἔχων αἰτίας, ἕως ὑπεραγανακτήσας σὺν αὐτῇ καὶ τὸν ἀδελφὸν ἐκβάλλει. Φερώρας δὲ ἀγαπήσας τὴν ὕβριν ἀπαλλάσσεται μὲν εἰς τὴν ἑαυτοῦ τετραρχίαν ὀμόσας ὅρον ἕξειν ἕνα τῆς φυγῆς τὸν Ἡρώδου θάνατον καὶ μηδέποτε πρὸς ζῶντα ὑποστρέψειν, ἐπανῆλθεν δὲ οὐδὲ πρὸς νοσοῦντα τὸν ἀδελφὸν καίτοι λιπαρῶς μεταπεμπόμενον· ἐβούλετο γὰρ αὐτῷ τινας ἐντολὰς καταλείψειν ὡς τεθνηξόμενος. ἀλλ’ ὁ μὲν παρ’ ἐλπίδα σώζεται, μετ’ οὐ πολὺ δὲ νοσεῖ Φερώρας, εὑρίσκετο δὲ Ἡρώδης μετριώτερος· καὶ γὰρ ἥκει πρὸς αὐτὸν καὶ συμπαθῶς ἐθεράπευεν. οὐ μὴν ὑπερίσχυσεν τοῦ πάθους· μετὰ γὰρ ἡμέρας ὀλίγας ἀποθνήσκει Φερώρας. ὃν καίπερ ἀγαπήσας Ἡρώδης μέχρι τελευταίας ἡμέρας ὅμως καὶ αὐτὸν ἀνελεῖν ἐφημίσθη φαρμάκῳ. τόν γε μὴν νεκρὸν εἰς Ἱεροσόλυμα κομίσας πένθος τε μέγιστον ὅλῳ τῷ ἔθνει κατήγγειλεν καὶ κηδείας ἠξίωσεν λαμπροτάτης. ἕνα μὲν δὴ τῶν Ἀλεξάνδρου καὶ Ἀριστοβούλου φονέων τοιοῦτον περιέρχεται τέλος.", "st": "1.29.4"}, {"sp": "N", "t": "Μετέβαινεν δ’ ἐπὶ τὸν αὐθέντην Ἀντίπατρον ἡ ποινὴ τὸν Φερώρα θάνατον ἀρχὴν λαβοῦσα. τῶν τούτου γάρ τινες ἀπελευθέρων κατηφεῖς τῷ βασιλεῖ προσελθόντες τὸν ἀδελφὸν αὐτοῦ διεφθάρθαι φαρμάκοις ἔλεγον· προσενεγκεῖν μὲν γὰρ αὐτῷ τι τὴν γυναῖκα τῶν οὐ συνήθως ἐσκευασμένων, φαγόντα δ’ εὐθέως εἰς τὴν νόσον καταπεσεῖν. ἀγηοχέναι τε πρὸ δυοῖν ἡμερῶν τὴν μητέρα αὐτῆς καὶ τὴν ἀδελφὴν γύναιον ἐκ τῆς Ἀραβίας φαρμάκων ἔμπειρον, ὅπως φίλτρον σκευάσῃ τῷ Φερώρᾳ, δεδωκέναι δὲ ἀντὶ τούτου θανάσιμον Συλλαίου πραγματευσαμένου· τούτῳ γὰρ ἦν γνώριμον.", "st": "1.30.1"}, {"sp": "N", "t": "Πληγεὶς οὖν ὁ βασιλεὺς ὑποψίαις πλείοσιν θεραπαίνας τε καί τινας τῶν ἐλευθέρων ἐβασάνιζεν. ἐβόα δέ τις ἐν ταῖς ἀλγηδόσιν θεὸς ὁ γῆν καὶ οὐρανὸν διέπων μετέλθοι τὴν τούτων ἡμῖν τῶν κακῶν αἰτίαν, τὴν Ἀντιπάτρου μητέρα. ταύτης τῆς ἀρχῆς ὁ βασιλεὺς λαβόμενος ἐπεξῄει πρόσω τὴν ἀλήθειαν. ἡ δὲ γυνὴ τήν τε φιλίαν τῆς Ἀντιπάτρου μητρὸς πρὸς Φερώραν καὶ τὰς ἐκείνου γυναῖκας ἐδήλου καὶ τὰς λαθραίας αὐτῶν συνόδους, ὅτι τε Φερώρας καὶ Ἀντίπατρος σὺν ἐκείναις πίνοιεν ὑποστρέφοντες ἀπὸ τοῦ βασιλέως δι’ ὅλης νυκτὸς μηδένα μήτε οἰκέτην μήτε θεράπαιναν ἐῶντες παρατυγχάνειν. μία δὴ τῶν ἐλευθέρων ταῦτα μηνύει.", "st": "1.30.2"}, {"sp": "N", "t": "Τὰς δὲ δούλας χωρὶς ἑκάστην Ἡρώδης ἐβασάνιζεν. ἐρρήθη δὲ παρὰ πάσαις τὰ προειρημένα σύμφωνα, καὶ διότι κατὰ συνθήκην Ἀντίπατρος μὲν εἰς Ῥώμην, Φερώρας δ’ ὑποχωρήσειεν εἰς τὴν Περαίαν· πολλάκις γὰρ αὐτοὺς διαλαλεῖν, ὡς μετ’ Ἀλέξανδρον καὶ Ἀριστόβουλον ἐπ’ αὐτοὺς Ἡρώδης μεταβήσεται καὶ τὰς ἑαυτῶν γυναῖκας. οὐ γὰρ φείσεσθαι μετὰ Μαριάμμην καὶ τοὺς ἐξ ἐκείνης ἑτέρου τινός, ὥστε ἄμεινον εἶναι φεύγειν ὡς πορρωτάτω τοῦ θηρίου. πολλάκις δὲ ἀποδυρόμενον πρὸς τὴν μητέρα τὸν Ἀντίπατρον εἰπεῖν, ὡς αὐτὸς μὲν εἴη πολιὸς ἤδη, νεάζοι δὲ καθ’ ἡμέραν ὁ πατήρ, φθάσαι δ’ ἂν τάχα καὶ τελευτήσας πρὶν ἄρξασθαι βασιλείας ἀληθοῦς. εἰ δὲ καί ποτε ἐκεῖνος τελευτήσειεν· πότε δ’ ἂν γένοιτο τοῦτο; παντάπασιν αὐτῷ τὴν ἀπόλαυσιν τῆς διαδοχῆς γίνεσθαι σύντομον. ὑποβλαστάνειν δὲ τὰς τῆς ὕδρας κεφαλάς, τοὺς Ἀριστοβούλου καὶ Ἀλεξάνδρου παῖδας. ἀφῃρῆσθαι δ’ αὐτὸν ὑπὸ τοῦ πατρὸς καὶ τὴν ἐπὶ τέκνοις ἐλπίδα· διάδοχον γὰρ οὐ τῶν αὐτοῦ τινα παίδων μετὰ τὴν τελευτήν, ἀλλὰ τὸν ἐκ Μαριάμμης Ἡρώδην γεγραφέναι. καὶ κατὰ τοῦτό γε παντάπασιν παραγηρᾶν οἰόμενον αὐτοῦ καὶ διαθήκας μενεῖν κυρίας· αὐτὸν γὰρ προνοήσειν μηδένα τῆς γενεᾶς ἀπολιπεῖν. ὄντα γε μὴν τῶν πώποτε πατέρων μισοτεκνότατον Ἡρώδην πολὺ μᾶλλον εἶναι μισάδελφον· δοῦναι γοῦν αὐτῷ πρῴην ἑκατὸν τάλαντα ἐπὶ τῷ μὴ διαλέγεσθαι Φερώρᾳ. τοῦ δὲ εἰπόντος τί γὰρ αὐτὸν ἐβλάπτομεν; ἀποκρίνασθαι τὸν Ἀντίπατρον εἴθε πάντα ἡμᾶς ἀφελόμενος γυμνοὺς ἐάσειεν ζῶντας. ἀλλ’ ἀμήχανον ἐκφυγεῖν οὕτω φονικὸν θηρίον, παρ’ ᾧ μηδὲ φιλεῖν τινας ἔξεστι φανερῶς. λάθρα γοῦν νῦν ἀλλήλοις σύνεσμεν, ἐξέσται δὲ φανερῶς, ἐὰν σχῶμέν ποτε ἀνδρῶν φρόνημα καὶ χεῖρας.", "st": "1.30.3"}, {"sp": "N", "t": "Ταῦτ’ ἔλεγον αἱ βασανιζόμεναι, καὶ ὅτι Φερώρας βουλεύσαιτο φυγεῖν μετ’ αὐτῶν εἰς Πέτραν. ἐπίστευσεν δ’ Ἡρώδης πᾶσιν τοῖς λεγομένοις ἐκ τῶν ἑκατὸν ταλάντων· μόνῳ γὰρ Ἀντιπάτρῳ διείλεκτο περὶ αὐτῶν. ἀποσκήπτει δ’ εἰς πρώτην ὁ θυμὸς Δωρίδα τὴν Ἀντιπάτρου μητέρα· καὶ γυμνώσας αὐτὴν παντὸς οὗ δεδώρητο κόσμου, πολλῶν δ’ ἦν ταλάντων, ἐκβάλλει δεύτερον. τὰς δὲ Φερώρου γυναῖκας ἀπὸ τῶν βασάνων ἐτημέλει διηλλαγμένος. ἐπτόητο δὲ τῷ φόβῳ καὶ πρὸς πᾶσαν ὑπόνοιαν ἐξερριπίζετο πολλούς τε τῶν οὐκ αἰτίων εἷλκεν εἰς βασάνους δεδοικώς, μή τινα τῶν αἰτίων παραλίπῃ.", "st": "1.30.4"}, {"sp": "N", "t": "Κἀν τούτῳ τρέπεται πρὸς τὸν Σαμαρείτην Ἀντίπατρον, ὃς ἦν ἐπίτροπος Ἀντιπάτρου. βασανίζων δὲ αὐτὸν ἤκουσεν ὅτι μετεπέμψατο μὲν Ἀντίπατρος ἐξ Αἰγύπτου δηλητήριον φάρμακον ἐπ’ αὐτὸν διά τινος τῶν ἑταίρων Ἀντιφίλου, λάβοι δὲ παρ’ ἐκείνου Θευδίων ὁ θεῖος Ἀντιπάτρου καὶ παραδοίη Φερώρᾳ· τούτῳ γὰρ ἐντείλασθαι τὸν Ἀντίπατρον Ἡρώδην ἀνελεῖν ἕως αὐτός ἐστιν ἐν Ῥώμῃ τῆς ὑπονοίας κεχωρισμένος· Φερώραν δὲ τῇ γυναικὶ παραθέσθαι τὸ φάρμακον. ταύτην ὁ βασιλεὺς μεταπεμψάμενος αὐτίκα τὸ ληφθὲν ἐκέλευσεν κομίζειν. ἡ δ’ ἔξεισι μὲν ὡς κομιοῦσα, ῥίπτει δ’ ἑαυτὴν ἀπὸ τοῦ τέγους τόν τε ἔλεγχον καὶ τὴν ἐκ τοῦ βασιλέως αἰκίαν φθάνουσα· προνοίᾳ δ’, ὡς ἔοικεν, θεοῦ μετιόντος Ἀντίπατρον οὐκ ἐπὶ κεφαλὴν ἀλλ’ ἐπὶ θάτερα πεσοῦσα διασώζεται. κομισθεῖσαν δ’ αὐτὴν ὁ βασιλεὺς ἀνακτησάμενος, κεκάρωτο γὰρ ἀπὸ τοῦ πτώματος, ἠρώτα δι’ ἣν αἰτίαν ῥίψειεν ἑαυτήν, εἰ μὲν εἴποι τἀληθές, ἀφήσειν πάσης τιμωρίας ἐπομνύμενος, εἰ δ’ ὑποστείλαιτο, δαπανήσειν αὐτῆς ἐν βασάνοις τὸ σῶμα καὶ μηδὲ τάφῳ καταλείψειν.", "st": "1.30.5"}, {"sp": "N", "t": "Πρὸς ταῦθ’ ἡ γυνὴ μικρὸν διαλιποῦσα καὶ τί γάρ, εἶπεν, ἔτι φείδομαι τῶν ἀπορρήτων Φερώρα τεθνεῶτος ἢ σώζουσα τὸν ἀπολέσαντα πάντας ἡμᾶς Ἀντίπατρον; ἄκουε, βασιλεῦ, καὶ μετὰ σοῦ θεὸς ὁ μάρτυς ἐμοὶ τῆς ἀληθείας πλανηθῆναι μὴ δυνάμενος· ὅτε ἀποθνήσκοντι Φερώρᾳ παρεκαθέζου δεδακρυμένος, τότε με προσκαλεσάμενος ἐκεῖνος ἦ πολύ γε, ἔφη, ὦ γύναι, τῆς εἰς ἐμαυτὸν διανοίας τοῦ ἀδελφοῦ διήμαρτον, τὸν οὕτως στέργοντα μισήσας καὶ κτεῖναι βουλευσάμενος τὸν οὕτως ἐπ’ ἐμοὶ μηδὲ τεθνεῶτί πω συγχεόμενον. ἀλλ’ ἐγὼ μὲν ἀπέχω τῆς ἀσεβείας τὸ ἐπιτίμιον, σὺ δ’ ὃ φυλάσσεις κατ’ αὐτοῦ φάρμακον ὑπ’ Ἀντιπάτρου καταλειφθὲν ἡμῖν φέρε καὶ βλέποντός μου ταχέως ἀφάνισον, ἵνα μὴ καὶ καθ’ ᾅδου φέροιμι τὸν ἀλάστορα. καὶ κελεύσαντος ἐκόμισα καὶ πλεῖστον μὲν εἰς τὸ πῦρ ὁρῶντος αὐτοῦ κατεκένωσα, βραχὺ δὲ ἐμαυτῇ πρὸς τὰ ἄδηλα καὶ τὸν ἐκ σοῦ φόβον ἐτήρησα.", "st": "1.30.6"}, {"sp": "N", "t": "Ταῦτ’ εἰποῦσα προκομίζει τὴν πυξίδα παντάπασιν ἔχουσαν τοῦ φαρμάκου βραχύ. βασιλεὺς δ’ ἐπὶ τὴν μητέρα τὴν Ἀντιφίλου καὶ τὸν ἀδελφὸν τὰς βασάνους μετέφερεν, κἀκεῖνοι τὸν Ἀντίφιλον κομίσαι τε ἀπ’ Αἰγύπτου τὴν πυξίδα ὡμολόγουν καὶ λαβεῖν παρ’ ἀδελφοῦ τὸ φάρμακον ἔφασκον ἰατρεύοντος ἐν Ἀλεξανδρείᾳ. περιιόντες δὲ οἱ Ἀλεξάνδρου καὶ Ἀριστοβούλου δαίμονες ἅπαν τὸ βασίλειον ἐρευνηταί τε καὶ μηνυταὶ τῶν ἀδήλων ἐγίνοντο τούς τε πορρωτάτω τῆς ὑποψίας ὄντας ἔσυρον εἰς τοὺς ἐλέγχους. εὑρίσκεται γοῦν καὶ ἡ τοῦ ἀρχιερέως θυγάτηρ Μαριάμμη τῆς ἐπιβουλῆς συνίστωρ· βασανιζόμενοι γὰρ τοῦτ’ ἀπέδειξαν αὐτῆς οἱ ἀδελφοί. βασιλεὺς δὲ τῆς μητρῴας τόλμης καὶ τὸν υἱὸν ἠμύνατο· τὸν γοῦν ἐξ αὐτῆς Ἡρώδην ὄντα διάδοχον Ἀντιπάτρου τῆς διαθήκης ἐξήλειψεν.", "st": "1.30.7"}, {"sp": "N", "t": "Ἐπὶ τούτοις καὶ Βάθυλλος εἰς τοὺς ἐλέγχους συνέδραμεν, ἡ τελευταία πίστις τῶν Ἀντιπάτρῳ βεβουλευμένων· ἦν μὲν γὰρ ἀπελεύθερος αὐτοῦ, κομίζων δ’ ἧκεν ἄλλο δηλητήριον ἰοὺς ἀσπίδων καὶ χυλοὺς ἑτέρων ἑρπετῶν, ἵνα εἰ τὸ πρῶτον ἀσθενήσει φάρμακον, τούτῳ Φερώρας μετὰ τῆς γυναικὸς ὁπλίσαιτο κατὰ τοῦ βασιλέως. πάρεργον δὲ τῆς ἐπὶ τὸν πατέρα τόλμης ἐκόμιζεν τὰς κατὰ τῶν ἀδελφῶν ἐσκευωρημένας ἐπιστολὰς ὑπ’ Ἀντιπάτρου· ἦσαν γὰρ Ἀρχέλαος καὶ Φίλιππος βασιλέως παῖδες ἐπὶ Ῥώμης παιδευόμενοι μειράκιά τε ἤδη καὶ φρονήματος μεστοί. τούτους ἐπανακύπτοντας αὐτοῦ ταῖς ἐλπίσιν ἀποσκευάσασθαι σπεύδων Ἀντίπατρος ἃς μὲν πλάττεται κατ’ αὐτῶν ἐπιστολὰς ἐξ ὀνόματος τῶν ἐπὶ Ῥώμης φίλων, οὓς δὲ ἔπειθεν γράψαι διαφθείρας χρήμασιν, ὡς πολλὰ μὲν βλασφημοῖεν τὸν πατέρα, φανερῶς δὲ Ἀλέξανδρον καὶ Ἀριστόβουλον ὀδύροιντο, πρὸς δὲ τὴν μετάκλησιν ἀγανακτοῖεν· ἤδη δ’ αὐτοὺς ὁ πατὴρ μετεπέμπετο, καὶ τοῦτο ἦν τὸ μάλιστα ταράσσον Ἀντίπατρον.", "st": "1.31.1"}, {"sp": "N", "t": "Ἔτι δὲ καὶ πρὸ τῆς ἀποδημίας ἐν Ἰουδαίᾳ μένων τοιαύτας κατ’ αὐτῶν ἐπὶ Ῥώμης ἠγόραζεν ἐπιστολὰς προσιών τε ὡς ἀνύποπτος εἴη τῷ πατρὶ περὶ τῶν ἀδελφῶν ἀπελογεῖτο, τὰ μὲν ψευδῆ λέγων εἶναι τῶν γραφομένων, ἃ δὲ νεότητος ἁμαρτήματα. τηνικαῦτά γε μὴν τοῖς γράφουσιν κατὰ τῶν ἀδελφῶν πλεῖστα δοὺς χρήματα συμφύρειν ἐπειρᾶτο τὸν ἔλεγχον, ἐσθῆτάς τε πολυτελεῖς καὶ στρωμνὰς ποικίλας ἐκπώματά τε ἀργυρᾶ καὶ χρυσᾶ συνωνούμενος ἄλλα τε πολλὰ τῶν κειμηλίων, ἵνα τῷ πλήθει τῆς εἰς ταῦτα δαπάνης τοὺς εἰς ἐκεῖνα μισθοὺς ἐγκαταγράψῃ· διακόσια γοῦν ἀναλώματος ἀνήνεγκεν τάλαντα, καὶ τούτων μεγίστη πρόφασις ἦν ἡ πρὸς Συλλαῖον δίκη. πάντων δ’ αὐτοῦ τότε καὶ τῶν βραχυτέρων ἐν τῷ μείζονι κακῷ διακαλυφθέντων, ὅθ’ αἱ μὲν βάσανοι πᾶσαι τὴν πατροκτονίαν, αἱ δ’ ἐπιστολαὶ δευτέρας ἀδελφοκτονίας κεκράγεσαν, ὅμως οὐδεὶς τῶν εἰς Ῥώμην ἀφικνουμένων ἀπήγγειλεν αὐτῷ τὰς ἐν Ἰουδαίᾳ τύχας καίτοι μεταξὺ τῶν ἐλέγχων καὶ τῆς ἐπανόδου διελθόντων ἑπτὰ μηνῶν· τοσοῦτον πρὸς αὐτὸν ἐκ πάντων μῖσος ἦν. τάχα καὶ τοὺς ἀπαγγέλλειν προῃρημένους οἱ τῶν ἀνῃρημένων δαίμονες ἀδελφῶν ἐφίμουν· γράφει γοῦν ἀπὸ Ῥώμης ἄφιξιν ἑαυτοῦ ταχεῖαν εὐαγγελιζόμενος, καὶ ὡς ὑπὸ Καίσαρος μετὰ τιμῆς ἀπολυθείη.", "st": "1.31.2"}, {"sp": "N", "t": "Ὁ βασιλεὺς δὲ εἰς χεῖρας λαβεῖν σπεύδων τὸν ἐπίβουλον καὶ δεδοικὼς μή ποτε προγνοὺς φυλάξηται, δι’ ἐπιστολῆς ἀνθυπεκρίνετο τά τε ἄλλα φιλοφρονούμενος καὶ σπεύδειν παρακαλῶν· θήσεσθαι γὰρ αὐτοῦ καὶ τὰς πρὸς τὴν μητέρα μέμψεις ἐπειχθέντος· οὐ γὰρ ἠγνόει τὴν ἐκβολὴν τῆς μητρὸς Ἀντίπατρος. πρότερον μὲν οὖν εἰλήφει τὴν περὶ τῆς Φερώρα τελευτῆς ἐπιστολὴν ἐν Τάραντι καὶ μέγιστον ἐποιήσατο πένθος, ὅ τινες ὡς ἐπὶ θείῳ καθύμνουν, ἦν δ’, ὡς ἔοικεν, ἐπὶ διαμαρτίᾳ τῆς ἐπιβουλῆς ἡ σύγχυσις καὶ οὐ Φερώραν κλαίοντος, ἀλλὰ τὸν ὑπηρέτην· ἤδη δὲ καὶ φόβος ἐπῄει τις αὐτὸν τῶν τετελεσμένων, μή ποτε φωραθείη τὸ φάρμακον. τότε δ’ ἐν Κιλικίᾳ λαβὼν ἣν προειρήκαμεν παρὰ τοῦ πατρὸς ἐπιστολὴν παραχρῆμα μὲν ἔσπευδεν, ὡς δὲ εἰς Κελένδεριν κατέπλει, λαμβάνει τις αὐτὸν ἔννοια τῶν περὶ τὴν μητέρα κακῶν προμαντευομένης ἤδη καὶ καθ’ ἑαυτὴν τῆς ψυχῆς. οἱ μὲν οὖν προμηθέστεροι τῶν φίλων συνεβούλευον μὴ πρότερον ἐμπίπτειν τῷ πατρὶ πρὶν πυθέσθαι σαφῶς δι’ ἃς αἰτίας ἐξέβαλεν αὐτοῦ τὴν μητέρα· δεδιέναι γάρ, μή ποτε προσθήκη γένοιτο τῶν κατ’ ἐκείνης διαβολῶν. οἱ δὲ ἀσκεπτότεροι καὶ τὴν πατρίδα σπεύδοντες ἰδεῖν μᾶλλον ἢ τὸ συμφέρον Ἀντιπάτρῳ σκοποῦντες, ἐπείγεσθαι παρῄνουν καὶ μὴ τῇ μελλήσει παρασχεῖν τῷ πατρὶ μὲν ὑποψίαν φαύλην, τοῖς διαβάλλουσι δὲ ἀφορμήν· καὶ γὰρ νῦν, εἴ τι κεκίνηται κατ’ αὐτοῦ, παρὰ τὴν ἀπουσίαν γέγονεν· μηδὲ γὰρ ἂν τολμῆσαι παρόντος· ἄτοπον δ’ εἶναι δι’ ἀδήλους ὑποψίας προδήλων ἀγαθῶν στερίσκεσθαι, καὶ μὴ θᾶττον ἀποδοῦναι μὲν ἑαυτὸν τῷ πατρί, κομίσασθαι δὲ τὴν βασιλείαν ἐπ’ αὐτῷ μόνῳ σαλεύουσαν. πείθεται τούτοις, ἐνῆγεν γὰρ τὸ δαιμόνιον, καὶ διαπεράσας εἰς τὸν Σεβαστὸν λιμένα τῆς Καισαρείας κατάγεται.", "st": "1.31.3"}, {"sp": "N", "t": "Παρυπήντησεν δ’ αὐτῷ παρὰ δόξαν ἐρημία πολλὴ πάντων ἐκτρεπομένων καὶ μηδενὸς προσιέναι τολμῶντος· ἐμισεῖτο μὲν γὰρ ἐπίσης, καὶ τότε φανῆναι τὸ μῖσος ἔσχεν παρρησίαν, πολλοὺς δὲ ὁ ἐκ τοῦ βασιλέως φόβος ἀπέστρεψεν, ἐπειδὴ πᾶσα πόλις ἤδη τῆς κατ’ Ἀντιπάτρου φήμης πεπλήρωτο καὶ μόνος ἠγνόει τὰ κατ’ αὐτὸν Ἀντίπατρος· οὔτε δὲ προεπέμφθη λαμπρότερόν τις ἐκείνου πλέοντος ἐπὶ Ῥώμης οὔτε ἀτιμότερον ὑπεδέχθη. ὁ δὲ ἤδη μὲν ἐνενόει τὰς οἴκοι συμφοράς, ἔτι δὲ ἐκ πανουργίας ὑπεκρύπτετο καὶ τῷ δέει τεθνηκὼς ἔνδοθεν σοβαρὸς εἶναι τὸ πρόσωπον ἐβιάζετο. φυγὴ δ’ οὐκέτι ἦν οὐδ’ ἐκ τῶν περιεχόντων ἀνάδυσις, καὶ σαφὲς μὲν οὐδὲ ἐκεῖ τι τῶν οἴκοθεν ἀπηγγέλλετο διὰ τὴν ἐκ τοῦ βασιλέως ἀπειλήν, ὑπελείπετο δὲ ἐλπὶς ἱλαρωτέρα, τάχα μὲν μηδὲν πεφωρᾶσθαι, τάχα δ’, εἴ τι καὶ πεφώραται, διασκευάσειν ἀναιδείᾳ καὶ δόλοις, ἅπερ ἦν αὐτῷ μόνα τὰ τῆς σωτηρίας ἐφόδια.", "st": "1.31.4"}, {"sp": "N", "t": "Φραξάμενος οὖν αὐτοῖς ἧκεν εἰς τὸ βασίλειον δίχα τῶν φίλων· οὗτοι γὰρ ὑβρισθέντες ἐπὶ τοῦ πρώτου πυλῶνος εἴρχθησαν· ἔτυχεν δ’ ἔνδον ὢν Οὔαρος ὁ τῆς Συρίας ἡγεμών. ὁ δὲ εἴσεισι πρὸς τὸν πατέρα καὶ τῇ τόλμῃ παρακροτήσας ἑαυτὸν ἤγγιζεν ὡς ἀσπασόμενος. κἀκεῖνος τὰς χεῖρας προβαλὼν καὶ τὴν κεφαλὴν παρακλίνας, ἔστιν, ἐξεβόησεν, καὶ τοῦτο πατροκτόνου τὸ περιπλέκεσθαί μοι θέλειν ἐν τηλικαύταις αἰτίαις ὄντα. φθείρου, δυσσεβεστάτη κεφαλή, μηδέ μου ψαύσῃς πρὶν ἀποσκευάσασθαι τὰ ἐγκλήματα. δίδωμι δέ σοι δικαστήριον καὶ δικαστὴν εὐκαίρως ἥκοντα Οὔαρον. ἴθι καὶ σκέπτου τὴν ἀπολογίαν εἰς αὔριον· παρέχω γάρ σου καιρὸν τοῖς πανουργεύμασιν. πρὸς ταῦτα μηδὲν ὑπ’ ἐκπλήξεως ἀποκρίνασθαι δυνηθεὶς αὐτὸς ὑπέστρεψεν, παραγενόμεναι δὲ πρὸς αὐτὸν ἐκδιηγήσαντο πάντας τοὺς ἐλέγχους ἥ τε μήτηρ καὶ ἡ γυνή. καὶ τότε μὲν ἀνανήψας ἐν σκέψει τῆς ἀπολογίας ἦν.", "st": "1.31.5"}, {"sp": "N", "t": "Τῇ δ’ ἐπιούσῃ συνέδριον μὲν ὁ βασιλεὺς ἀθροίζει τῶν συγγενῶν καὶ φίλων, εἰσκαλεῖ δὲ καὶ τοὺς Ἀντιπάτρου φίλους. προκαθέζεται δὲ αὐτὸς ἅμα Οὐάρῳ καὶ τοὺς μηνυτὰς πάντας ἐκέλευσεν εἰσαγαγεῖν, ἐν οἷς εἰσήχθησαν καὶ τῆς Ἀντιπάτρου μητρὸς οἰκέται τινὲς οὐ πρὸ πολλοῦ συνειλημμένοι, κομίζοντες γράμματα παρ’ αὐτῆς πρὸς τὸν υἱὸν τοιάδε· ἐπεὶ πεφώραται πάντα ἐκεῖνα τῷ πατρί σου, μὴ παραγίνου πρὸς αὐτόν, ἂν μή τινα πορίσῃ παρὰ τοῦ Καίσαρος δύναμιν. τούτων σὺν τοῖς ἄλλοις εἰσηγμένων Ἀντίπατρος εἰσέρχεται καὶ πεσὼν πρηνὴς πρὸ τῶν ποδῶν τοῦ πατρός, ἱκετεύω, πάτερ, ἔφη, μηδέν μου προκατεγνωκέναι, παρασχεῖν δέ μοι τὰς ἀκοὰς ἀκεραίους εἰς τὴν ἀπολογίαν· ἀποδείξω γὰρ ἐμαυτὸν καθαρόν, ἂν σὺ θέλῃς.", "st": "1.32.1"}, {"sp": "N", "t": "Ὁ δ’ αὐτῷ σιγᾶν ἐγκραγὼν πρὸς τὸν Οὔαρον εἶπεν· ἀλλ’ ὅτι μὲν καὶ σύ, Οὔαρε, καὶ πᾶς δικαστὴς ὅσιος Ἀντίπατρον ἐξώλη κρινεῖ, πέπεισμαι. δέδοικα δέ, μὴ κἀμοῦ μισήσῃς τὴν τύχην κἀμὲ κρίνῃς πάσης ἄξιον συμφορᾶς τοιούτους υἱοὺς γεγεννηκότα. χρὴ δέ με διὰ τοῦτο ἐλεεῖσθαι πλέον, ὅτι πρὸς οὕτω μιαροὺς καὶ φιλοστοργότατος πατὴρ ἐγενόμην. τοὺς μὲν γὰρ προτέρους βασιλείας τε ἔτι νέους ἀξιώσας καὶ πρὸς τοῖς ἐν Ῥώμῃ τροφείοις φίλους Καίσαρος, ζηλωτοὺς δὲ ποιήσας βασιλεῦσιν ἑτέροις, εὗρον ἐπιβούλους, οἳ τεθνήκασι τὸ πλέον Ἀντιπάτρῳ· νέῳ γὰρ ὄντι καὶ διαδόχῳ τούτῳ μάλιστα τὴν ἀσφάλειαν ἐποριζόμην. τὸ δὲ μιαρὸν τοῦτο θηρίον τῆς ἐμῆς ὑπερεμπλησθὲν ἀνεξικακίας ἤνεγκεν κατ’ ἐμοῦ τὸν κόρον· ἔδοξα γὰρ αὐτῷ πολὺν ζῆν χρόνον, καὶ τὸ ἐμὸν γῆρας ἐβαρύνθη βασιλεύς τε οὐχ ὑπέμεινεν εἰ μὴ διὰ πατροκτονίας γενέσθαι, δίκαια γοῦν βουλευσάμενος, ὅτι καταγαγὼν αὐτὸν ἀπὸ τῆς χώρας ἀπερριμμένον καὶ παρωσάμενος τοὺς ἐκ βασιλίδος μοι γεγενημένους ἀπέδειξα τῆς ἀρχῆς διάδοχον. ἐξομολογοῦμαί σοι, Οὔαρε, τὴν ἐμαυτοῦ φρενοβλάβειαν· ἐγὼ τοὺς υἱοὺς ἐκείνους κατ’ ἐμαυτοῦ παρώξυνα δικαίας αὐτῶν ἀποκόψας ἐλπίδας δι’ Ἀντίπατρον. καὶ τί μὲν ἐκείνους εὐεργέτησα τηλικοῦτον, ἡλίκον τοῦτον; ᾧ γε ζῶν μὲν ὀλίγου δεῖν παρεχώρησα τῆς ἐξουσίας, φανερῶς δὲ ταῖς διαθήκαις ἐνέγραψα τῆς ἀρχῆς διάδοχον καὶ πρόσοδον μὲν ἰδίᾳ πεντήκοντα ταλάντων ἔνειμα, τῶν δ’ ἐμῶν ἐχορήγησα χρημάτων ἀνέδην, πλέοντι δὲ νῦν εἰς Ῥώμην ἔδωκα τριακόσια τάλαντα, Καίσαρι δ’ ἐξ ὅλης τῆς γενεᾶς μόνον ὡς σωτῆρα τοῦ πατρὸς παρεθέμην. τί δ’ ἐκεῖνοι τοιοῦτον ἠσέβησαν, οἷον Ἀντίπατρος; ἢ τίς ἔλεγχος ἠνέχθη κατ’ αὐτῶν, ἡλίκος ἀποδείκνυσιν τοῦτον ἐπίβουλον; ἀλλὰ φθέγγεσθαί τι τετόλμηκεν ὁ πατροκτόνος καὶ πάλιν δόλοις τὴν ἀλήθειαν ἐπικαλύψειν ἐλπίζει. Οὔαρε, σοὶ φυλακτέον· ἐγὼ γὰρ οἶδα τὸ θηρίον καὶ προορῶμαι τὴν μέλλουσαν ἀξιοπιστίαν καὶ τὸν ἐπίπλαστον ὀλοφυρμόν· οὗτός ἐστιν ὁ παραινῶν ἐμοί ποτε φυλάττεσθαι ζῶντα Ἀλέξανδρον καὶ μὴ πᾶσιν πιστεύειν τὸ σῶμα· οὗτος ὁ μέχρι τῆς κοίτης εἰσάγων καὶ μή μέ τις ἐνεδρεύοι περιβλέπων· οὗτος ὁ ταμίας τῶν ὕπνων καὶ χορηγὸς τῆς ἀμεριμνίας, ὁ παραμυθούμενος τὴν ἐπὶ τοῖς ἀνῃρημένοις λύπην καὶ διακρίνων τὴν τῶν ζώντων εὔνοιαν ἀδελφῶν, ὁ ὑπερασπιστὴς ὁ ἐμός, ὁ σωματοφύλαξ. ὅταν ἀναμνησθῶ, Οὔαρε, τὸ πανοῦργον ἐν ἑκάστῳ καὶ τὴν ὑπόκρισιν, ἀπιστία με τοῦ ζῆν εἰσέρχεται καὶ θαυμάζω, πῶς βαρὺν οὕτως ἐπίβουλον διέφυγον. ἀλλ’ ἐπεὶ δαίμων τις ἐξερημοῖ τὸν ἐμὸν οἶκον καί μοι τοὺς φιλτάτους ἐπανίστησιν ἀεί, κλαύσομαι μὲν ἐγὼ τὴν ἄδικον εἱμαρμένην καὶ κατ’ ἐμαυτὸν στενάξω τὴν ἐρημίαν, διαφεύξεται δ’ οὐδεὶς διψήσας τοὐμὸν αἷμα, κἂν διὰ πάντων μου τῶν τέκνων ὁ ἔλεγχος ἔλθῃ.", "st": "1.32.2"}, {"sp": "N", "t": "Τοιαῦτα λέγων αὐτὸς μὲν ὑπὸ συγχύσεως ἐνεκόπη, Νικολάῳ δ’ ἑνὶ τῶν φίλων λέγειν τὰς ἀποδείξεις ἔνευσεν. μεταξὺ δ’ ὁ Ἀντίπατρος ἐπάρας τὴν κεφαλήν, ἔμενεν γὰρ δὴ βεβλημένος πρὸ τῶν ποδῶν τοῦ πατρός, ἐκβοᾷ· σύ, πάτερ, ὑπὲρ ἐμοῦ πεποίηκας τὴν ἀπολογίαν· πῶς γὰρ ἐγὼ πατροκτόνος, ὃν ὁμολογεῖς φύλακα διὰ παντὸς ἐσχηκέναι; τερατείαν δέ μου καὶ ὑπόκρισιν λέγεις τὴν εὐσέβειαν. πῶς ὁ πανοῦργος ἐν τοῖς ἄλλοις οὕτως ἄφρων ἐγενόμην, ὡς μὴ νοεῖν, ὅτι λαθεῖν οὐδ’ ἀνθρώπους ῥᾴδιον τηλικοῦτον μύσος ἐνσκευαζόμενον, τὸν δ’ ἀπ’ οὐρανοῦ δικαστὴν ἀμήχανον, ὃς ἐφορᾷ πάντα καὶ πανταχοῦ πάρεστιν; ἢ τὸ τῶν ἀδελφῶν τέλος ἠγνόουν, οὓς ὁ θεὸς οὕτως μετῆλθε τῆς εἰς σὲ κακοβουλίας; τί δέ με καὶ παρώξυνεν κατὰ σοῦ; βασιλείας ἐλπίς; ἀλλ’ ἐβασίλευον. ὑπόνοια μίσους; οὐ γὰρ ἐστεργόμην; φόβος ἐκ σοῦ τις ἄλλος· ἀλλὰ μὴν σὲ τηρῶν ἑτέροις φοβερὸς ἤμην. ἔνδεια χρημάτων; καὶ τίνι μᾶλλον ἐξῆν ἀναλίσκειν; εἰ γὰρ ἐξωλέστατος πάντων ἀνθρώπων ἐγενόμην καὶ θηρίου ψυχὴν εἶχον ἀνημέρου, πάτερ, οὐκ ἂν ταῖς σαῖς εὐεργεσίαις ἐνικήθην, ὃν κατήγαγες μέν, ὡς ἔφης αὐτός, προέκρινας δὲ τοσούτων τέκνων, ἀπέδειξας δὲ ζῶν βασιλέα, δι’ ὑπερβολὴν δὲ τῶν ἄλλων ἀγαθῶν ἐποίησας ἐπίφθονον; ὢ τάλας ἐγὼ τῆς πικρᾶς ἀποδημίας, ὡς πολὺν ἔδωκα καιρὸν τῷ φθόνῳ καὶ μακρὰν τοῖς ἐπιβουλεύουσι διωρίαν. σοὶ δέ, πάτερ, καὶ τοῖς σοῖς ἀγῶσιν ἀπεδήμουν, ἵνα μὴ Συλλαῖος τοῦ σοῦ γήρως καταφρονήσῃ. Ῥώμη μοι μάρτυς τῆς εὐσεβείας καὶ ὁ τῆς οἰκουμένης προστάτης Καῖσαρ, ὁ φιλοπάτορα πολλάκις με εἰπών. λάβε, πάτερ, τὰ παρ’ αὐτοῦ γράμματα. ταῦτα τῶν ἐνθάδε διαβολῶν πιστότερα, ταῦτα ἀπολογία μοι μόνη, τούτοις τῆς εἰς σὲ φιλοστοργίας τεκμηρίοις χρῶμαι. μέμνησο δὲ ὡς οὐχ ἑκὼν ἔπλεον ἐπιστάμενος τὴν ἐμφωλεύουσαν τῇ βασιλείᾳ κατ’ ἐμοῦ δυσμένειαν. σὺ δέ με, πάτερ, ἄκων ἀπώλεσας, ἀναγκάσας καιρὸν διαβολῆς δοῦναι τῷ φθόνῳ. πάρειμι δὲ ἐπὶ τοὺς ἐλέγχους, πάρειμι διὰ γῆς καὶ θαλάσσης οὐδὲν οὐδαμοῦ παθὼν ὁ πατροκτόνος. ἀλλὰ μήπω με τούτῳ φίλει τῷ τεκμηρίῳ· κατέγνωσμαι γὰρ καὶ παρὰ θεῷ καὶ παρὰ σοί, πάτερ. κατεγνωσμένος δὲ δέομαι μὴ ταῖς ἄλλων βασάνοις πιστεύειν, ἀλλὰ κατ’ ἐμοῦ φερέσθω τὸ πῦρ, ὁδευέτω διὰ τῶν ἐμῶν σπλάγχνων τὰ ὄργανα, μὴ φειδέσθω ὀλοφυρμὸς τοῦ μιαροῦ σώματος· εἰ γὰρ εἰμὶ πατροκτόνος, οὐκ ὀφείλω θνήσκειν ἀβασάνιστος. τοιαῦτα μετ’ ὀλοφυρμοῦ καὶ δακρύων ἐκβοῶν τούς τε ἄλλους ἅπαντας καὶ τὸν Οὔαρον εἰς οἶκτον προυκαλέσατο, μόνον δὲ ὁ θυμὸς Ἡρώδην ἄδακρυν διεκράτει τοὺς ἐλέγχους ἀληθεῖς ἐπιστάμενον.", "st": "1.32.3"}, {"sp": "N", "t": "Ἐν τούτῳ Νικόλαος τοῦ βασιλέως κελεύσαντος πολλὰ πρὸς τὸ πανοῦργον τὸ Ἀντιπάτρου προειπὼν καὶ τὸν ἐπ’ αὐτῷ διαχέας ἔλεον, ἔπειτα πικρὰν κατηγορίαν κατετείνατο, πάντα μὲν τὰ κατὰ τὴν βασιλείαν κακουργήματα περιτιθεὶς αὐτῷ, μάλιστα δὲ τὴν ἀναίρεσιν τῶν ἀδελφῶν, ἀποδεικνὺς ταῖς ἐκείνου διαβολαῖς ἀπολωλότας. ἐπιβουλεύειν δὲ αὐτὸν ἔλεγεν καὶ τοῖς περιοῦσιν ὡς ἐφέδροις τῆς διαδοχῆς· τὸν γὰρ παρασκευάσαντα πατρὶ φάρμακον ἦ πού γ’ ἂν ἀδελφῶν ἀποσχέσθαι. προελθὼν δ’ ἐπὶ τὸν ἔλεγχον τῆς φαρμακείας τάς τε μηνύσεις [ἑξῆς] ἐπεδείκνυεν καὶ περὶ Φερώρα κατεσχετλίαζεν, ὅτι κἀκεῖνον Ἀντίπατρος ποιήσειεν ἀδελφοκτόνον καὶ τοὺς φιλτάτους τῷ βασιλεῖ διαφθείρας ὅλον τοῦ μύσους ἀναπλήσειεν τὸν οἶκον, ἄλλα τε πολλὰ πρὸς τούτοις εἰπὼν καὶ ἀποδείξας καταπαύει τὸν λόγον.", "st": "1.32.4"}, {"sp": "N", "t": "Οὔαρος δὲ ἀπολογεῖσθαι κελεύσας τὸν Ἀντίπατρον, ὡς οὐδὲν πλέον εἰπὼν ἢ θεός ἐστίν μοι τοῦ μηδὲν ἀδικεῖν μάρτυς ἔκειτο σιγῶν, αἰτήσας τὸ φάρμακον δίδωσί τινι τῶν ἐπὶ θανάτῳ κατακρίτων δεσμώτῃ πιεῖν. τοῦ δὲ παραχρῆμα τελευτήσαντος ὁ μὲν ἀπορρήτους ποιήσας τὰς πρὸς Ἡρώδην ὁμιλίας καὶ τὰ περὶ τὸ συνέδριον Καίσαρι γράψας μετὰ μίαν ἡμέραν χωρίζεται. δεσμεῖ δὲ ὁ βασιλεὺς Ἀντίπατρον καὶ πρὸς Καίσαρα τοὺς δηλώσοντας τὴν συμφορὰν ἐξέπεμψεν.", "st": "1.32.5"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα καὶ κατὰ Σαλώμης ἐπίβουλος Ἀντίπατρος εὑρίσκεται· τῶν γὰρ Ἀντιφίλου τις οἰκετῶν ἧκεν ἐπιστολὰς κομίζων ἀπὸ Ῥώμης παρὰ Λιουίας θεραπαινίδος Ἀκμῆς τοὔνομα. καὶ παρὰ μὲν ταύτης ἐπέσταλτο βασιλεῖ τὰς παρὰ Σαλώμης ἐπιστολὰς ἐν τοῖς Λιουίας εὑρηκέναι γράμμασιν, πεπομφέναι δὲ αὐτῷ λάθρα δι’ εὔνοιαν. αἱ δὲ τῆς Σαλώμης λοιδορίας τε τοῦ βασιλέως περιεῖχον πικροτάτας καὶ κατηγορίαν μεγίστην. ταύτας δὲ πλάσας Ἀντίπατρος καὶ τὴν Ἀκμὴν διαφθείρας ἔπεισεν Ἡρώδῃ πέμψαι. διηλέγχθη δὲ ἐκ τῆς πρὸς αὐτὸν ἐπιστολῆς· καὶ γὰρ ἐκείνῳ τὸ γύναιον ἔγραψεν· ὡς ἐβουλήθης, ἔγραψά σου τῷ πατρὶ καὶ τὰς ἐπιστολὰς ἐκείνας ἔπεμψα πεπεισμένη τὸν βασιλέα μὴ φείσεσθαι τῆς ἀδελφῆς, ὅταν ἀναγνῷ. καλῶς δὲ ποιήσεις, ἐπειδὰν ἀπαρτισθῇ πάντα, μνημονεύσας ὧν ὑπέσχου.", "st": "1.32.6"}, {"sp": "N", "t": "Ταύτης φωραθείσης τῆς ἐπιστολῆς καὶ τῶν κατὰ Σαλώμης ἐνσκευασθεισῶν ἔννοια μὲν ἐμπίπτει τῷ βασιλεῖ τάχα καὶ κατ’ Ἀλεξάνδρου πλασθῆναι γράμματα, περιαλγὴς δ’ ἦν ὑπὸ τοῦ πάθους ὡς παρ’ ὀλίγον καὶ τὴν ἀδελφὴν ἀποκτείνας δι’ Ἀντίπατρον· οὐκέτι οὖν ἀνεβάλλετο λαβεῖν τιμωρίαν ὑπὲρ ἁπάντων. ὡρμημένος δ’ ἐπὶ τὸν Ἀντίπατρον ἐπεσχέθη νόσῳ χαλεπῇ· περὶ μέντοι τῆς Ἀκμῆς καὶ τῶν κατὰ Σαλώμης ἐσκευωρημένων ἐπέστειλεν Καίσαρι. τήν τε διαθήκην αἰτήσας μετέγραφεν, καὶ βασιλέα μὲν ἀπεδείκνυεν Ἀντίπαν ἀμελῶν τῶν πρεσβυτάτων Ἀρχελάου καὶ Φιλίππου· διαβεβλήκει γὰρ καὶ τούτους Ἀντίπατρος· Καίσαρι δὲ σὺν τοῖς διὰ χρημάτων δώροις χίλια τάλαντα, τῇ δὲ γυναικὶ καὶ τέκνοις αὐτοῦ καὶ φίλοις καὶ ἀπελευθέροις περὶ πεντακόσια, ἀπένειμεν δὲ καὶ τοῖς ἄλλοις ἅπασιν τῆς τε χώρας οὐκ ὀλίγα καὶ τῶν χρημάτων· λαμπροτάταις δὲ δωρεαῖς ἐτίμα Σαλώμην τὴν ἀδελφήν. ἐν μὲν οὖν ταῖς διαθήκαις ταῦτα διωρθώσατο.", "st": "1.32.7"}, {"sp": "N", "t": "Προῄει δ’ αὐτῷ πρὸς τὸ χαλεπώτερον ἡ νόσος ἅτε δὴ τῶν ἀρρωστημάτων ἐν γήρᾳ καὶ ἀθυμίᾳ ἐπιπεσόντων· ἦν μὲν γὰρ ἤδη σχεδὸν ἐτῶν ἑβδομήκοντα, τεταπείνωτο δὲ τὴν ψυχὴν ταῖς περὶ τῶν τέκνων συμφοραῖς, ὡς μηδ’ ἐν ὑγιείᾳ τι τῶν ἡδέων προσίεσθαι. τῆς νόσου δ’ ἦν ἐπίτασις ζῶν Ἀντίπατρος, ὃν οὐκ ἐν παρέργῳ, ῥαΐσας δὲ προῄρητο ἀνελεῖν.", "st": "1.33.1"}, {"sp": "N", "t": "Γίνεται δ’ ἐν ταῖς συμφοραῖς αὐτῷ καὶ δημοτική τις ἐπανάστασις. δύο ἦσαν σοφισταὶ κατὰ τὴν πόλιν μάλιστα δοκοῦντες ἀκριβοῦν τὰ πάτρια καὶ διὰ τοῦτο ἐν παντὶ τῷ ἔθνει μεγίστης ἠξιωμένοι δόξης, Ἰούδας τε υἱὸς Σεπφεραίου καὶ Ματθίας ἕτερος Μαργάλου. τούτοις οὐκ ὀλίγοι προσῄεσαν τῶν νέων ἐξηγουμένοις τοὺς νόμους, καὶ συνεῖχον ὁσημέραι τῶν ἡβώντων στρατόπεδον. οἳ τότε τὸν βασιλέα πυνθανόμενοι ταῖς ἀθυμίαις ὑπορρέοντα καὶ τῇ νόσῳ λόγον καθίεσαν εἰς τοὺς γνωρίμους, ὡς ἄρα καιρὸς ἐπιτηδειότατος εἴη τιμωρεῖν ἤδη τῷ θεῷ καὶ τὰ κατασκευασθέντα παρὰ τοὺς πατρίους νόμους ἔργα κατασπᾶν. ἀθέμιτον γὰρ εἶναι κατὰ τὸν ναὸν ἢ εἰκόνας ἢ προτομὰς ἢ ζῴου τινὸς ἐπώνυμον ἔργον εἶναι· κατεσκευάκει δ’ ὁ βασιλεὺς ὑπὲρ τὴν μεγάλην πύλην ἀετὸν χρυσοῦν· ὃν δὴ τότε παρῄνουν ἐκκόπτειν οἱ σοφισταί, καλὸν εἶναι λέγοντες, εἰ καί τις γένοιτο κίνδυνος, ὑπὲρ τοῦ πατρίου νόμου θνήσκειν· τοῖς γὰρ οὕτω τελευτῶσιν ἀθάνατόν τε τὴν ψυχὴν καὶ τὴν ἐν ἀγαθοῖς αἴσθησιν αἰώνιον παραμένειν, τοὺς δὲ ἀγενεῖς καὶ τῆς ἑαυτῶν σοφίας ἀπείρους ἀγνοοῦντας φιλοψυχεῖν καὶ πρὸ τοῦ δι’ ἀρετῆς τὸν ἐκ νόσου θάνατον αἱρεῖσθαι.", "st": "1.33.2"}, {"sp": "N", "t": "Ἅμα δὲ τοῖς ἐκείνων λόγοις διεφημίσθη καὶ θνήσκειν ὁ βασιλεύς, ὥστε θαρραλεώτερον ἥπτοντο τῆς ἐπιχειρήσεως οἱ νέοι. μέσης γοῦν ἡμέρας καὶ πολλῶν κατὰ τὸ ἱερὸν ἀναστρεφομένων σχοίνοις παχείαις καθιμήσαντες σφᾶς αὐτοὺς ἀπὸ τοῦ τέγους τὸν χρυσοῦν ἀετὸν ἐξέκοπτον πελέκεσιν. ἠγγέλθη δ’ εὐθέως τῷ βασιλέως στρατηγῷ, κἀκεῖνος μετὰ χειρὸς οὐκ ὀλίγης ἀναδραμὼν περὶ τεσσαράκοντα νεανίας συλλαμβάνει καὶ κατήγαγεν πρὸς βασιλέα. πυνθανομένῳ δ’ αὐτῷ πρῶτον, εἰ τολμήσειαν τὸν χρυσοῦν ἀετὸν ἐκκόπτειν, ὡμολόγουν. ἔπειτα, τίνος κελεύσαντος, ἀπεκρίναντο τοῦ πατρίου νόμου. τί δ’ οὕτως γεγήθασιν διερωτήσαντος, ἀναιρεῖσθαι μέλλοντες ἔλεγον, ὅτι πλειόνων ἀγαθῶν ἀπολαύσουσιν μετὰ τὴν τελευτήν.", "st": "1.33.3"}, {"sp": "N", "t": "Ἐπὶ τούτοις ὁ βασιλεὺς δι’ ὑπερβολὴν ὀργῆς κρείττων τῆς νόσου γενόμενος πρόεισιν εἰς ἐκκλησίαν, καὶ πολλὰ τῶν ἀνδρῶν κατηγορήσας ὡς ἱεροσύλων καὶ προφάσει τοῦ νόμου πειραζόντων τι μεῖζον ἠξίου κολάζειν ὡς ἀσεβεῖς. ὁ δὲ δῆμος δείσας μὴ διὰ πολλῶν ὁ ἔλεγχος ἔλθῃ, παρεκάλει πρῶτον μὲν τοὺς ὑποθεμένους τὴν πρᾶξιν, ἔπειτα τοὺς ἐν αὐτῇ συλληφθέντας κολάσαντα τοῖς λοιποῖς τὴν ὀργὴν ἀφιέναι. πείθεται μόλις ὁ βασιλεύς, καὶ τοὺς μὲν καθιμήσαντας ἑαυτοὺς ἅμα τοῖς σοφισταῖς κατέκαυσε ζῶντας, τοὺς λοιποὺς δὲ τῶν συλληφθέντων παρέδωκεν τοῖς ὑπηρέταις ἀνελεῖν.", "st": "1.33.4"}, {"sp": "N", "t": "Ἔνθεν αὐτοῦ τὸ σῶμα πᾶν ἡ νόσος διαλαβοῦσα ποικίλοις πάθεσιν ἐμερίζετο· πυρετὸς μὲν γὰρ ἦν οὐ λάβρος, κνησμὸς δὲ ἀφόρητος τῆς ἐπιφανείας ὅλης καὶ κόλου συνεχεῖς ἀλγηδόνες περί τε τοὺς πόδας ὥσπερ ὑδρωπιῶντος οἰδήματα τοῦ τε ἤτρου φλεγμονὴ καὶ δὴ αἰδοίου σηπεδὼν σκώληκας γεννῶσα, πρὸς τούτοις ὀρθόπνοια καὶ δύσπνοια καὶ σπασμοὶ πάντων τῶν μελῶν, ὥστε τοὺς ἐπιθειάζοντας ποινὴν εἶναι τῶν σοφιστῶν τὰ νοσήματα λέγειν. ὁ δὲ παλαίων τοσούτοις πάθεσιν ὅμως τοῦ ζῆν ἀντείχετο σωτηρίαν τε ἤλπιζεν καὶ θεραπείας ἐπενόει· διαβὰς γοῦν τὸν Ἰορδάνην τοῖς κατὰ Καλλιρρόην ἐχρῆτο θερμοῖς· ταῦτα δ’ ἔξεισι μὲν εἰς τὴν Ἀσφαλτῖτιν λίμνην, ὑπὸ γλυκύτητος δ’ ἐστὶ καὶ πότιμα. δόξαν δὲ ἐνταῦθα τοῖς ἰατροῖς ἐλαίῳ θερμῷ πᾶν ἀναθάλψαι τὸ σῶμα χαλασθὲν εἰς πλήρη πύελον ἐκλύει καὶ τοὺς ὀφθαλμοὺς ὡς τεθνεὼς ἀνέστρεψεν. θορύβου δὲ τῶν θεραπευόντων γενομένου πρὸς μὲν τὴν φωνὴν ἀνήνεγκεν, εἰς δὲ τὸ λοιπὸν ἀπογνοὺς τὴν σωτηρίαν τοῖς τε στρατιώταις ἀνὰ πεντήκοντα δραχμὰς ἐκέλευσεν διανεῖμαι καὶ πολλὰ χρήματα τοῖς ἡγεμόσι καὶ τοῖς φίλοις.", "st": "1.33.5"}, {"sp": "N", "t": "Αὐτὸς δὲ ὑποστρέφων εἰς Ἱεριχοῦντα παραγίνεται μελαγχολῶν ἤδη, καὶ μόνον οὐκ ἀπειλῶν αὐτῷ τῷ θανάτῳ προέκοπτεν εἰς ἐπιβολὴν ἀθεμίτου πράξεως· τοὺς γὰρ ἀφ’ ἑκάστης κώμης ἐπισήμους ἄνδρας ἐξ ὅλης Ἰουδαίας συναγαγὼν εἰς τὸν καλούμενον ἱππόδρομον ἐκέλευσεν συγκλεῖσαι. προσκαλεσάμενος δὲ Σαλώμην τὴν ἀδελφὴν καὶ τὸν ἄνδρα ταύτης Ἀλεξᾶν οἶδα, ἔφη, Ἰουδαίους τὸν ἐμὸν ἑορτάσοντας θάνατον, δύναμαι δὲ πενθεῖσθαι δι’ ἑτέρων καὶ λαμπρὸν ἐπιτάφιον ἔχειν, ἂν ὑμεῖς θελήσητε ταῖς ἐμαῖς ἐντολαῖς ὑπουργῆσαι. τούσδε τοὺς φρουρουμένους ἄνδρας ἐπειδὰν ἐκπνεύσω τάχιστα κτείνατε περιστήσαντες τοὺς στρατιώτας, ἵνα πᾶσα Ἰουδαία καὶ πᾶς οἶκος ἄκων ἐπ’ ἐμοὶ δακρύσῃ.", "st": "1.33.6"}, {"sp": "N", "t": "Ταῦτα ἐνετέλλετο, καὶ παρὰ τῶν ἐν Ῥώμῃ πρέσβεων ἧκον ἐπιστολαί, δι’ ὧν Ἀκμὴ μὲν ἀνῃρημένη κελεύσαντος Καίσαρος ἐδηλοῦτο, θανάτῳ δ’ Ἀντίπατρος κατάκριτος· ἔγραφόν γε μὴν ὡς, εἰ καὶ φυγαδεύειν αὐτὸν ἐθελήσειεν ὁ πατήρ, ἐπιτρέποι Καῖσαρ. ὁ δὲ βραχὺ μὲν πρὸς τὴν εὐθυμίαν ἀνήνεγκεν, αὖθις δέ, καὶ γὰρ ἐνδείᾳ τροφῆς καὶ βηχὶ σπασμώδει διετείνετο, τῶν ἀλγηδόνων ἡσσηθεὶς φθάσαι τὴν εἱμαρμένην ἐπεβάλλετο. λαβὼν δὲ μῆλον ᾔτησεν καὶ μαχαίριον, εἰώθει γὰρ ἀποτέμνων ἐσθίειν, ἔπειτα περιαθρήσας μή τις ὁ κωλύων εἴη, ἐπῆρεν τὴν δεξιὰν ὡς πλήξων ἑαυτόν. προσδραμὼν δὲ ἐκώλυσεν Ἀχίαβος ὁ ἀνεψιὸς αὐτοῦ τὴν χεῖρα κατασχών. οἰμωγὴ δ’ εὐθέως ἤρθη μεγίστη κατὰ τὸ βασίλειον ὡς οἰχομένου βασιλέως, καὶ ταχέως ἀκούσας Ἀντίπατρος ἀναθαρρεῖ τε καὶ γεγηθὼς τοὺς φύλακας ἱκέτευεν ἐπὶ χρήμασιν ἐξαφεῖναι λύσαντας αὐτόν. ὁ δὲ ἡγεμὼν οὐ μόνον ἐκώλυσεν, ἀλλὰ καὶ βασιλεῖ δραμὼν ἀνήγγειλεν τὴν ἐπιβουλήν. ἀνέκραγεν δ’ ἐκεῖνος ἰσχυρότερον τῆς νόσου καὶ παραχρῆμα πέμψας τοὺς δορυφόρους ἀποκτείνει τὸν Ἀντίπατρον. θάψαι δὲ τὸν νεκρὸν αὐτοῦ προστάξας ἐν Ὑρκανίᾳ πάλιν τὰς διαθήκας ἐπανορθοῦται, καὶ διάδοχον μὲν Ἀρχέλαον τὸν πρεσβύτατον υἱὸν ἀδελφὸν δὲ Ἀντιπάτρου γράφει, τετράρχην δὲ Ἀντίπαν.", "st": "1.33.7"}, {"sp": "N", "t": "Μετὰ δὲ τὴν ἀναίρεσιν τοῦ παιδὸς ἐπιβιοὺς πέντε ἡμέρας τελευτᾷ, βασιλεύσας ἀφ’ οὗ μὲν ἀποκτείνας Ἀντίγονον ἐκράτησεν τῶν πραγμάτων ἔτη τέσσαρα καὶ τριάκοντα, ἀφ’ οὗ δὲ ὑπὸ Ῥωμαίων ἀπεδείχθη βασιλεὺς ἑπτὰ καὶ τριάκοντα, καὶ κατὰ μὲν τὰ ἄλλα πάντα τύχῃ δεξιᾷ χρησάμενος, εἰ καί τις ἄλλος, ὅστις κατεκτήσατο βασιλείαν ἰδιώτης ὢν καὶ τοσούτῳ χρόνῳ φυλάξας ἰδίοις τέκνοις κατέλιπεν, ἐν δὲ τοῖς κατ’ οἶκον ἀτυχέστατος. πρὶν δὲ γνῶναι τὴν τελευτὴν αὐτοῦ τὸ στρατιωτικὸν προελθοῦσα μετὰ τἀνδρὸς ἡ Σαλώμη διαφῆκεν τοὺς δεσμώτας, οὓς κτείνειν ὁ βασιλεὺς ἐνετείλατο, μεταπεισθῆναι τὸν βασιλέα λέγουσα καὶ πάλιν ἀναπέμπειν ἕκαστον εἰς τὰ ἴδια. τούτων δ’ οἰχομένων ἐδήλουν ἤδη τοῖς στρατιώταις καὶ συνῆγον αὐτοὺς εἰς ἐκκλησίαν μετὰ τοῦ λοιποῦ πλήθους ἐν τῷ κατὰ Ἱεριχοῦντα ἀμφιθεάτρῳ. ἔνθα παρελθὼν Πτολεμαῖος ὁ καὶ τὸν σημαντῆρα δακτύλιον παρὰ τοῦ βασιλέως πεπιστευμένος τόν τε βασιλέα κατευδαιμονίζει καὶ τὸ πλῆθος παρακαλεῖ καὶ τὴν ἀπολειφθεῖσαν τοῖς στρατιώταις ἀνεγίνωσκεν ἐπιστολήν, ἐν ᾗ πολλὰ περὶ τῆς εἰς τὸν διάδοχον εὐνοίας παρεκάλει. μετὰ δὲ τὴν ἐπιστολὴν λύσας τὰς ἐπιδιαθήκας ἀνεγίνωσκεν, ἐν αἷς Φίλιππος μὲν τοῦ Τράχωνος καὶ τῶν γειτνιώντων χωρίων κληρονόμος, τετράρχης δ’, ὡς προείπαμεν, Ἀντίπας, βασιλεὺς δ’ Ἀρχέλαος ἀπεδείκνυτο. τούτῳ δὲ τόν τε δακτύλιον τὸν ἑαυτοῦ Καίσαρι φέρειν ἐνετέλλετο καὶ τὰς διοικήσεις τῆς βασιλείας σεσημασμένας· κύριον γὰρ ἁπάντων ὧν διατάξειεν καὶ βεβαιωτὴν τῶν διαθηκῶν εἶναι Καίσαρα· τά γε μὴν λοιπὰ κατὰ τὰς προτέρας διαθήκας φυλάττειν.", "st": "1.33.8"}, {"sp": "N", "t": "Βοὴ δ’ εὐθὺς ἐγένετο τῶν Ἀρχελάῳ συνηδομένων, καὶ κατὰ στῖφος οἱ στρατιῶται μετὰ τοῦ πλήθους προσιόντες ὑπισχνοῦντο μὲν τὴν ἑαυτῶν εὔνοιαν, συνηύχοντο δὲ καὶ τὴν παρὰ τοῦ θεοῦ, καὶ μετὰ ταῦτα πρὸς ταφὴν ἐτρέποντο τοῦ βασιλέως. παρέλιπεν δ’ οὐδὲν Ἀρχέλαος εἰς πολυτέλειαν, ἀλλὰ πάντα τὸν βασιλικὸν κόσμον προήνεγκεν συμπομπεύσοντα τῷ νεκρῷ· κλίνη μὲν γὰρ ὁλόχρυσος ἦν διάλιθος, στρωμνὴ δὲ ἁλουργὶς ποικίλη, τὸ σῶμα δ’ ἐπ’ αὐτῆς πορφύρᾳ κεκαλυμμένον, καὶ διάδημα μὲν ἐπέκειτο τῇ κεφαλῇ, στέφανος δ’ ὑπὲρ αὐτοῦ χρυσοῦς, τὸ δὲ σκῆπτρον παρὰ τὴν δεξιάν. καὶ περὶ τὴν κλίνην οἵ τε υἱεῖς καὶ τὸ πλῆθος τῶν συγγενῶν, ἐφ’ οἷς οἱ δορυφόροι καὶ τὸ Θρᾴκιον στῖφος Γερμανοί τε καὶ Γαλάται διεσκευασμένοι πάντες ὡς εἰς πόλεμον. προῆγεν δ’ ἡ λοιπὴ δύναμις ὡπλισμένη τοῖς ἡγεμόσιν καὶ ταξιάρχοις ἀκολουθοῦντες ἐν κόσμῳ, πεντακόσιοι δὲ ἐπ’ αὐτοῖς τῶν οἰκετῶν καὶ ἀπελευθέρων ἀρωματοφόροι. σταδίους δ’ ἐκομίσθη τὸ σῶμα ἑβδομήκοντα εἰς Ἡρώδειον, ὅπου κατὰ τὰς ἐντολὰς ἐτάφη. καὶ τὰ μὲν περὶ Ἡρώδην τοιοῦτον ἔσχεν πέρας.", "st": "1.33.9"}, {"sp": "HDR", "t": "Βιβλίον Βʹ", "st": "2"}, {"sp": "N", "t": "Ἀρχελάῳ δὲ νέων ἦρξε θορύβων ἡ τῆς ἐπὶ Ῥώμην ἀποδημίας ἀνάγκη. πενθήσας γὰρ ἡμέρας ἑπτὰ τὸν πατέρα καὶ τὴν ἐπιτάφιον ἑστίασιν πολυτελῆ τῷ πλήθει παρασχών· ἔθος δὲ τοῦτο παρὰ Ἰουδαίοις πολλοῖς πενίας αἴτιον διὰ τὸ πλῆθος ἑστιᾶν οὐκ ἄνευ ἀνάγκης· εἰ γὰρ παραλείποι τις, οὐχ ὅσιος· μεταλαμβάνει μὲν ἐσθῆτα λευκήν, πρόεισι δὲ εἰς τὸ ἱερόν, ἔνθα ποικίλαις αὐτὸν εὐφημίαις ὁ λαὸς ἐκδέχεται. κἀκεῖνος τὸ πλῆθος ἀφ’ ὑψηλοῦ βήματος καὶ χρυσοῦ θρόνου δεξιωσάμενος τῆς τε σπουδῆς, ἣν ἐνεδείξαντο περὶ τὴν κηδείαν τοῦ πατρός, εὐχαριστεῖ καὶ τῆς πρὸς αὐτὸν θεραπείας ὡς πρὸς βέβαιον ἤδη βασιλέα· φείδεσθαί γε μὴν οὐ μόνον ἔφη τῆς ἐξουσίας ἐπὶ τοῦ παρόντος, ἀλλὰ καὶ τῶν ὀνομάτων, ἕως ἂν αὐτῷ Καῖσαρ ἐπικυρώσῃ τὴν διαδοχήν, ὁ καὶ κατὰ τὰς διαθήκας τῶν ὅλων δεσπότης· οὐδὲ γὰρ ἐν Ἱεριχοῦντι τῆς στρατιᾶς τὸ διάδημα περιαπτούσης αὐτῷ δεδέχθαι· τοῦ μέντοι προθύμου καὶ τῆς εὐνοίας ὥσπερ τοῖς στρατιώταις οὕτω καὶ τῷ δήμῳ πλήρεις ἀποδώσειν τὰς ἀμοιβάς, ὁπόταν ὑπὸ τῶν κρατούντων βασιλεὺς ἀποδειχθῇ βέβαιος· σπουδάσειν γὰρ ἐν πᾶσιν πρὸς αὐτοὺς φανῆναι τοῦ πατρὸς ἀμείνων.", "st": "2.1.1"}, {"sp": "N", "t": "Ἐπὶ τούτοις ἡδόμενον τὸ πλῆθος εὐθέως ἀπεπειρᾶτο τῆς διανοίας αὐτοῦ μεγάλοις αἰτήμασιν· οἱ μὲν γὰρ ἐβόων ἐπικουφίζειν τὰς εἰσφοράς, οἱ δὲ ἀναιρεῖν τὰ τέλη, τινὲς δὲ ἀπολύειν τοὺς δεσμώτας. ἐπένευσε δ’ ἑτοίμως ἅπασι θεραπεύων τὸ πλῆθος. ἔπειτα θύσας ἐν εὐωχίᾳ μετὰ τῶν φίλων ἦν. ἔνθα δὴ περὶ δείλην ἀθροισθέντες οὐκ ὀλίγοι τῶν νεωτερίζειν προῃρημένων ἤρξαντο ἰδίου πένθους, ὅτε τὸ κοινὸν ἐπὶ τῷ βασιλεῖ πέπαυτο, κατολοφυρόμενοι τοὺς κολασθέντας ὑπὸ Ἡρώδου διὰ τὸν ἐκκοπέντα χρυσοῦν ἀετὸν τῆς πύλης τοῦ ναοῦ. ἦν δὲ τὸ πένθος οὐχ ὑπεσταλμένον, ἀλλ’ οἰμωγαὶ διαπρύσιοι καὶ θρῆνος ἐγκέλευστος κοπετοί τε περιηχοῦντες ὅλην τὴν πόλιν ὡς ἂν ἐπ’ ἀνδράσιν, οὓς ἔφασκον ὑπὲρ τῶν πατρίων νόμων καὶ τοῦ ναοῦ πυρὶ παραπολέσθαι. τιμωρεῖν δ’ αὐτοῖς ἀνεβόων ἐκ τῶν ὑφ’ Ἡρώδου τετιμημένων χρῆναι καὶ πρῶτον τὸν ὑπ’ ἐκείνου κατασταθέντα παύειν ἀρχιερέα· προσήκειν γὰρ αὐτοῖς εὐσεβέστερον αἱρεῖσθαι καὶ καθαρώτερον.", "st": "2.1.2"}, {"sp": "N", "t": "Πρὸς ἃ παρωξύνετο μὲν Ἀρχέλαος, ἐπεῖχε δὲ τὴν ἄμυναν ὑπὸ τῆς περὶ τὴν ἔξοδον ἐπείξεως, δεδοικὼς μή ποτε τὸ πλῆθος ἐκπολεμώσας κατασχεθείη τῷ κινήματι. διὸ πειθοῖ μᾶλλον ἢ βίᾳ καταστέλλειν ἐπειρᾶτο τοὺς νεωτερίζοντας καὶ τὸν στρατηγὸν ὑποπέμψας παύσασθαι παρεκάλει. τοῦτον εἰς τὸ ἱερὸν παρελθόντα πρὶν φθέγξασθαί τι λίθοις ἀπήλαυνον οἱ στασιασταὶ καὶ τοὺς μετ’ αὐτοῦ ἐπὶ σωφρονισμῷ προσιόντας, ἐνίει δὲ πολλοὺς ὁ Ἀρχέλαος, καὶ πάντα πρὸς ὀργὴν ἀπεκρίναντο δῆλοί τε ἦσαν οὐκ ἠρεμήσοντες εἰ πλήθους ἐπιλάβοιντο. καὶ δὴ τῆς τῶν ἀζύμων ἐνστάσης ἑορτῆς, ἣ πάσχα παρὰ Ἰουδαίοις καλεῖται πολύ τι θυμάτων πλῆθος ἐκδεχομένη, κάτεισι μὲν ἐκ τῆς χώρας λαὸς ἄπειρος ἐπὶ τὴν θρησκείαν, οἱ δὲ τοὺς σοφιστὰς πενθοῦντες ἐν τῷ ἱερῷ συνειστήκεσαν τροφὴν τῇ στάσει ποριζόμενοι. πρὸς ὃ δείσας Ἀρχέλαος πρὶν δι’ ὅλου τοῦ πλήθους διαδραμεῖν τὴν νόσον ὑποπέμπει μετὰ σπείρας χιλίαρχον προστάξας βίᾳ τοὺς ἐξάρχοντας τῆς στάσεως κατασχεῖν. πρὸς οὓς τὸ πλῆθος ἅπαν παροξύνεται καὶ τοὺς μὲν πολλοὺς τῆς σπείρας βάλλοντες λίθοις διέφθειρον, ὁ δὲ χιλίαρχος ἐκφεύγει τραυματίας μόλις. ἔπειθ’ οἱ μὲν ὡς μηδενὸς δεινοῦ γεγονότος ἐτρέποντο πρὸς θυσίαν· οὐ μὴν Ἀρχελάῳ δίχα φόνου καθεκτὸν ἔτι τὸ πλῆθος ἐφαίνετο, τὴν δὲ στρατιὰν ἐπαφίησιν αὐτοῖς ὅλην, τοὺς μὲν πεζοὺς διὰ τῆς πόλεως ἀθρόους, τοὺς δὲ ἱππεῖς ἀνὰ τὸ πεδίον· οἳ θύουσιν ἑκάστοις ἐξαίφνης προσπεσόντες διαφθείρουσι μὲν περὶ τρισχιλίους, τὸ δὲ λοιπὸν πλῆθος εἰς τὰ πλησίον ὄρη διεσκέδασαν. εἵποντο δὲ Ἀρχελάου κήρυκες κελεύοντες ἕκαστον ἀναχωρεῖν ἐπ’ οἴκου, καὶ πάντες ᾤχοντο τὴν ἑορτὴν ἀπολιπόντες.", "st": "2.1.3"}, {"sp": "N", "t": "Αὐτὸς δὲ μετὰ τῆς μητρὸς καὶ τῶν φίλων Ποπλᾶ καὶ Πτολεμαίου καὶ Νικολάου κατῄει πρὸς θάλασσαν καταλιπὼν ἐπίτροπόν τε τῶν βασιλείων καὶ κηδεμόνα τῶν οἰκείων Φίλιππον. συνεξῄει δ’ ἅμα τοῖς τέκνοις Σαλώμη καὶ τοῦ βασιλέως ἀδελφιδοῖ τε καὶ γαμβροί, τῷ μὲν δοκεῖν συναγωνιούμενοι περὶ τῆς διαδοχῆς Ἀρχελάῳ, τὸ δ’ ἀληθὲς κατηγορήσοντες περὶ τῶν κατὰ τὸ ἱερὸν παρανομηθέντων.", "st": "2.2.1"}, {"sp": "N", "t": "Συναντᾷ δ’ αὐτοῖς κατὰ τὴν Καισάρειαν Σαβῖνος ὁ τῆς Συρίας ἐπίτροπος εἰς Ἰουδαίαν ἀνιὼν ἐπὶ φυλακῇ τῶν Ἡρώδου χρημάτων. τοῦτον ἐπέσχεν προσωτέρω χωρεῖν ἐπελθὼν Οὔαρος, ὃν διὰ Πτολεμαίου πολλὰ δεηθεὶς Ἀρχέλαος μετεπέμψατο. τότε μὲν οὖν Σαβῖνος Οὐάρῳ χαριζόμενος οὔτ’ ἐπὶ τὰς ἄκρας ἔσπευσεν οὔτε τὰ ταμιεῖα τῶν πατρῴων χρημάτων ἀπέκλεισεν Ἀρχελάῳ, μέχρι δὲ τῆς Καίσαρος διαγνώσεως ἠρεμήσειν ὑπέσχετο καὶ διέτριβεν ἐπὶ τῆς Καισαρείας. ὡς δὲ τῶν ἐμποδιζόντων ὁ μὲν εἰς Ἀντιόχειαν ἀπῆρεν, Ἀρχέλαος δὲ εἰς Ῥώμην ἀνήχθη, διὰ τάχους ἐπὶ Ἱεροσολύμων ὁρμήσας παραλαμβάνει τὰ βασίλεια καὶ μεταπεμπόμενος τούς τε φρουράρχους καὶ διοικητὰς ἐπειρᾶτο διερευνᾶν τοὺς τῶν χρημάτων ἀναλογισμοὺς τάς τε ἄκρας παραλαμβάνειν. οὐ μὴν οἱ φύλακες τῶν Ἀρχελάου κατημέλουν ἐντολῶν, ἔμενον δὲ φρουροῦντες ἕκαστα καὶ τὴν φρουρὰν ἀνατιθέντες Καίσαρι μᾶλλον ἢ Ἀρχελάῳ.", "st": "2.2.2"}, {"sp": "N", "t": "Κἀν τούτῳ πάλιν Ἀντίπας ἀμφισβητῶν περὶ τῆς βασιλείας ἐπέξεισιν ἀξιῶν τῆς ἐπιδιαθήκης κυριωτέραν εἶναι τὴν διαθήκην, ἐν ᾗ βασιλεὺς αὐτὸς ἐγέγραπτο. συλλήψεσθαι δ’ αὐτῷ προϋπέσχετο Σαλώμη καὶ πολλοὶ τῶν σὺν Ἀρχελάῳ πλεόντων συγγενῶν. ἐπήγετο δὲ τὴν μητέρα καὶ τὸν ἀδελφὸν Νικολάου Πτολεμαῖον ῥοπὴν εἶναι δοκοῦντα διὰ τὴν παρὰ Ἡρώδῃ πίστιν· γεγόνει γὰρ δὴ τῶν φίλων ἐκείνου τιμιώτατος· πλεῖστον μέντοι πεποίθει διὰ δεινότητα λόγων Εἰρηναίῳ τῷ ῥήτορι, διὸ καὶ τοὺς νουθετοῦντας εἴκειν Ἀρχελάῳ κατὰ τὸ πρεσβεῖον καὶ τὰς ἐπιδιαθήκας διεκρούσατο. μεθίστατο δὲ ἐν Ῥώμῃ πάντων πρὸς αὐτὸν ἡ σπουδὴ τῶν συγγενῶν, οἷς διὰ μίσους ἦν Ἀρχέλαος, καὶ προηγουμένως ἕκαστος αὐτονομίας ἐπεθύμει στρατηγῷ Ῥωμαίων διοικουμένης, εἰ δὲ τοῦτο διαμαρτάνοι, βασιλεύειν Ἀντίπαν ἤθελεν.", "st": "2.2.3"}, {"sp": "N", "t": "Συνήργει δ’ αὐτοῖς εἰς τοῦτο καὶ Σαβῖνος δι’ ἐπιστολῶν κατηγορήσας μὲν Ἀρχελάου παρὰ Καίσαρι, πολλὰ δ’ ἐπαινέσας Ἀντίπαν. συντάξαντες δὲ τὰ ἐγκλήματα οἱ περὶ Σαλώμην ἐνεχείρισαν Καίσαρι, καὶ μετὰ τούτους Ἀρχέλαος τά τε κεφάλαια τῶν ἑαυτοῦ δικαίων γράψας καὶ τὸν δακτύλιον τοῦ πατρὸς καὶ τοὺς λόγους εἰσπέμπει διὰ Πτολεμαίου. προσκεψάμενος δὲ ὁ Καῖσαρ τὰ παρ’ ἀμφοῖν κατ’ ἰδίαν τό τε μέγεθος τῆς βασιλείας καὶ τὸ πλῆθος τῆς προσόδου, πρὸς οἷς τὸν ἀριθμὸν τῆς Ἡρώδου γενεᾶς, προαναγνοὺς δὲ καὶ τὰ παρὰ Οὐάρου καὶ Σαβίνου περὶ τούτων ἐπεσταλμένα, συνέδριον μὲν ἀθροίζει τῶν ἐν τέλει Ῥωμαίων, ἐν ᾧ καὶ τὸν ἐξ Ἀγρίππα καὶ Ἰουλίας τῆς θυγατρὸς θετὸν παῖδα Γάιον πρώτως ἐκάθισεν, ἀποδίδωσι δὲ λόγον αὐτοῖς.", "st": "2.2.4"}, {"sp": "N", "t": "Ἔνθα καταστὰς ὁ Σαλώμης υἱὸς Ἀντίπατρος, ἦν δὲ τῶν ἐναντιουμένων Ἀρχελάῳ δεινότατος εἰπεῖν, κατηγόρει φάσκων τοῖς μὲν λόγοις ἀμφισβητεῖν ἄρτι βασιλείας Ἀρχέλαον, τοῖς δ’ ἔργοις πάλαι γεγονέναι βασιλέα, κατειρωνεύεσθαι δὲ νῦν τῶν Καίσαρος ἀκοῶν, ὃν δικαστὴν τῆς διαδοχῆς οὐ περιέμεινεν, εἴ γε μετὰ τὴν Ἡρώδου τελευτὴν ἐγκαθέτους μὲν ὑποπέμψας τοὺς περιθήσοντας αὐτῷ τὸ διάδημα, προκαθίσας δ’ ἐπὶ τοῦ θρόνου καὶ χρηματίσας βασιλεὺς τάξεις τε τῆς στρατιᾶς ἀμείψας καὶ προκοπὰς χαρισάμενος, ἔτι δὲ τῷ δήμῳ πάντα κατανεύσας ὅσων ὡς παρὰ βασιλέως τυχεῖν ἠξίουν καὶ τοὺς ἐπὶ μεγίσταις αἰτίαις παρὰ τοῦ πατρὸς δεδεμένους λύσας, νῦν ἥκει παρὰ τοῦ δεσπότου σκιὰν αἰτησόμενος βασιλείας, ἧς ἥρπασεν ἑαυτῷ τὸ σῶμα, καὶ ποιῶν οὐ τῶν πραγμάτων ἀλλὰ τῶν ὀνομάτων κύριον Καίσαρα. προσωνείδιζεν δ’ ὡς καὶ τὸ πένθος κατειρωνεύσατο τοῦ πατρός, μεθ’ ἡμέραν μὲν ἐπισχηματίζων τὸ πρόσωπον εἰς λύπην, νύκτωρ δὲ μέχρις κώμων μεθυσκόμενος, ἐν ᾧ καὶ τὴν ταραχὴν τοῦ πλήθους ἐκ τῆς ἐπὶ τούτοις ἀγανακτήσεως ἔλεγεν γεγονέναι. καὶ τὸν ἀγῶνα τοῦ λόγου παντὸς ἐναπηρείσατο τῷ πλήθει τῶν περὶ τὸν ναὸν φονευθέντων, οὓς ἐληλυθέναι μὲν ἐφ’ ἑορτήν, παρὰ δὲ ταῖς ἰδίαις θυσίαις ὠμῶς ἀπεσφάχθαι· καὶ τοσοῦτον ἐν τῷ ἱερῷ σεσωρεῦσθαι νεκρῶν πλῆθος, ὅσον οὐδ’ ἂν ἀλλόφυλος ἐσώρευσεν πόλεμος ἐπελθὼν ἀκήρυκτος. ταύτην μέντοι τὴν ὠμότητα προσκεψάμενον αὐτοῦ καὶ τὸν πατέρα μηδ’ ἐλπίδος αὐτόν ποτε ἀξιῶσαι βασιλικῆς ἢ ὅτε χεῖρον τὴν ψυχὴν κάμνων τοῦ σώματος ἀκρατὴς ἦν ὑγιαίνοντος λογισμοῦ καὶ οὐδ’ ὃν ἔγραφεν ἐν ταῖς ἐπιδιαθήκαις ᾔδει διάδοχον, καὶ ταῦτα μηδὲν τὸν ἐν ταῖς διαθήκαις μέμψασθαι δυνάμενος, ἃς ἔγραψεν ὑγιαίνων μὲν τὸ σῶμα, καθαρὰν δὲ τὴν ψυχὴν ἔχων πάθους παντός. εἰ μέντοι καὶ κυριωτέραν τὴν τοῦ κάμνοντος κρίσιν τιθείη τις, ἀποκεχειροτονῆσθαι βασιλείας Ἀρχέλαον ὑφ’ ἑαυτοῦ τοῖς εἰς αὐτὴν παρανομηθεῖσιν· ποταπὸν γὰρ ἂν γενέσθαι λαβόντα τὴν ἀρχὴν παρὰ Καίσαρος τὸν πρὶν λαβεῖν τοσούτους ἀνῃρηκότα;", "st": "2.2.5"}, {"sp": "N", "t": "Πολλὰ τοιαῦτα διεξελθὼν Ἀντίπατρος καὶ τοὺς πλείστους τῶν συγγενῶν παραστησάμενος ἐφ’ ἑκάστῳ τῶν κατηγορημένων μάρτυρας καταπαύει τὸν λόγον. ἀνίσταται δὲ Νικόλαος ὑπὲρ Ἀρχελάου, καὶ τὸν μὲν ἐν τῷ ἱερῷ φόνον ἀναγκαῖον ἀπέφηνεν· πολεμίους γὰρ γεγονέναι τοὺς ἀνῃρημένους οὐ τῆς βασιλείας μόνον ἀλλὰ καὶ τοῦ δικάζοντος αὐτὴν Καίσαρος. τῶν δ’ ἄλλων ἐγκλημάτων συμβούλους ἀπεδείκνυεν αὐτοὺς τοὺς κατηγόρους γεγονέναι. τήν γε μὴν ἐπιδιαθήκην ἠξίου διὰ τοῦτο μάλιστα εἶναι κυρίαν, ὅτι βεβαιωτὴν ἐν αὐτῇ Καίσαρα καθίστατο τοῦ διαδόχου· ὁ γὰρ σωφρονῶν ὥστε τῷ δεσπότῃ τῶν ὅλων παραχωρεῖν τῆς ἐξουσίας οὐ δή που περὶ κληρονόμου κρίσιν ἐσφάλλετο, σωφρονῶν δ’ ᾑρεῖτο καὶ τὸν καθιστάμενον ὁ γινώσκων τὸν καθιστάντα.", "st": "2.2.6"}, {"sp": "N", "t": "Διεξελθόντος δὲ πάντα καὶ Νικολάου παρελθὼν Ἀρχέλαος προπίπτει τῶν Καίσαρος γονάτων ἡσυχῆ. κἀκεῖνος αὐτὸν μάλα φιλοφρόνως ἀναστήσας ἐνέφηνεν μὲν ὡς ἄξιος εἴη τῆς πατρῴας διαδοχῆς, οὐ μήν τι βέβαιον ἀπεφήνατο. διαλύσας δὲ τοὺς συνέδρους ἐκείνης τῆς ἡμέρας καθ’ ἑαυτὸν περὶ ὧν διήκουσεν ἐσκέπτετο, εἴτε χρὴ τῶν ἐν ταῖς διαθήκαις καταστῆσαί τινα διάδοχον, εἴτε καὶ πάσῃ τῇ γενεᾷ διανεῖμαι τὴν ἀρχήν· ἐδόκει γὰρ ἐπικουρίας τὸ πλῆθος τῶν προσώπων χρῄζειν.", "st": "2.2.7"}, {"sp": "N", "t": "Πρὶν δὲ ὁρίσαι τι περὶ τούτων Καίσαρα τελευτᾷ μὲν ἡ Ἀρχελάου μήτηρ Μαλθακὴ νοσήσασα, παρὰ Οὐάρου δ’ ἐκομίσθησαν ἐκ Συρίας ἐπιστολαὶ περὶ τῆς Ἰουδαίων ἀποστάσεως, ἣν προϊδόμενος ὁ Οὔαρος, ἀνέβη γὰρ μετὰ τὸν Ἀρχελάου πλοῦν εἰς Ἱεροσόλυμα τοὺς παρακινοῦντας καθέξων, ἐπειδὴ πρόδηλον ἦν τὸ πλῆθος οὐκ ἠρεμῆσον, ἓν τῶν τριῶν ἀπὸ Συρίας ταγμάτων, ὅπερ ἄγων ἧκεν, ἐν τῇ πόλει καταλείπει. καὶ αὐτὸς μὲν ὑπέστρεψεν εἰς Ἀντιόχειαν, ἐπελθὼν δὲ ὁ Σαβῖνος ἀφορμὴν αὐτοῖς παρέσχεν νεωτεροποιίας· τούς τε γὰρ φρουροὺς παραδιδόναι τὰς ἄκρας ἐβιάζετο καὶ πικρῶς τὰ βασιλικὰ χρήματα διηρεύνα, πεποιθὼς οὐ μόνον τοῖς ὑπὸ Οὐάρου καταλειφθεῖσι στρατιώταις, ἀλλὰ καὶ πλήθει δούλων ἰδίων, οὓς ἅπαντας ὁπλίσας ὑπηρέταις ἐχρῆτο τῆς πλεονεξίας. ἐνστάσης δὲ τῆς πεντηκοστῆς, οὕτω καλοῦσίν τινα ἑορτὴν Ἰουδαῖοι παρ’ ἑπτὰ γινομένην ἑβδομάδας καὶ τὸν ἀριθμὸν τῶν ἡμερῶν προσηγορίαν ἔχουσαν, οὐχ ἡ συνήθης θρησκεία συνήγαγεν τὸν δῆμον, ἀλλ’ ἡ ἀγανάκτησις. συνέδραμεν γοῦν πλῆθος ἄπειρον ἔκ τε τῆς Γαλιλαίας καὶ ἐκ τῆς Ἰδουμαίας Ἱεριχοῦντός τε καὶ τῆς ὑπὲρ Ἰορδάνην Περαίας, ὑπερεῖχεν δὲ πλήθει καὶ προθυμίαις ἀνδρῶν ὁ γνήσιος ἐξ αὐτῆς Ἰουδαίας λαός. διανείμαντες δὲ σφᾶς αὐτοὺς εἰς τρία μέρη τριχῆ στρατοπεδεύονται, πρός τε τῷ βορείῳ τοῦ ἱεροῦ κλίματι καὶ πρὸς τῷ μεσημβρινῷ κατὰ τὸν ἱππόδρομον, ἡ δὲ τρίτη μοῖρα πρὸς τοῖς βασιλείοις κατὰ δύσιν. περικαθεζόμενοι δὲ πανταχόθεν τοὺς Ῥωμαίους ἐπολιόρκουν.", "st": "2.3.1"}, {"sp": "N", "t": "Ὁ δὲ Σαβῖνος πρός τε τὸ πλῆθος αὐτῶν ὑποδείσας καὶ τὰ φρονήματα συνεχεῖς μὲν ἀγγέλους ἔπεμπεν πρὸς Οὔαρον ἐπαμύνειν ἐν τάχει δεόμενος ὡς εἰ βραδύνοι κατακοπησομένου τοῦ τάγματος· αὐτὸς δὲ ἐπὶ τὸν ὑψηλότατον τοῦ φρουρίου πύργον ἀναβάς, ὃς ἐκαλεῖτο Φασάηλος ἐπώνυμον ἔχων ἀδελφὸν Ἡρώδου διαφθαρέντα ὑπὸ Πάρθων, ἐντεῦθεν κατέσειεν τοῖς ἐν τῷ τάγματι στρατιώταις ἐπιχειρεῖν τοῖς πολεμίοις· δι’ ἔκπληξιν γὰρ οὐδ’ εἰς τοὺς σφετέρους καταβαίνειν ἐθάρρει. παραπεισθέντες δὲ οἱ στρατιῶται προπηδῶσιν εἰς τὸ ἱερὸν καὶ μάχην καρτερὰν τοῖς Ἰουδαίοις συνάπτουσιν, ἐν ᾗ μέχρι μὲν οὐδεὶς καθύπερθεν ἐπήμυνεν περιῆσαν ἐμπειρίᾳ πολέμου τῶν ἀπείρων· ἐπεὶ δὲ πολλοὶ Ἰουδαίων ἀναβάντες ἐπὶ τὰς στοὰς κατὰ κεφαλῆς αὐτῶν ἠφίεσαν τὰ βέλη, συνετρίβοντο πολλοὶ καὶ οὔτε τοὺς ἄνωθεν βάλλοντας ἀμύνεσθαι ῥᾴδιον ἦν οὔτε τοὺς συστάδην μαχομένους ὑπομένειν.", "st": "2.3.2"}, {"sp": "N", "t": "Καταπονούμενοι μὲν πρὸς ἀμφοτέρων ὑποπιμπρᾶσιν τὰς στοάς, ἔργα θαυμάσια μεγέθους τε καὶ πολυτελείας ἕνεκεν· οἱ δ’ ἐπ’ αὐτῶν ἐξαίφνης ὑπὸ τῆς φλογὸς περισχεθέντες πολλοὶ μὲν ἐν αὐτῇ διεφθάρησαν, πολλοὶ δὲ ὑπὸ τῶν πολεμίων πηδῶντες εἰς αὐτούς, τινὲς δ’ εἰς τοὐπίσω κατὰ τοῦ τείχους ἐκρημνίζοντο, ἔνιοι δ’ ὑπ’ ἀμηχανίας τοῖς ἰδίοις ξίφεσιν τὸ πῦρ ἔφθανον· ὅσοι δὲ καθερπύσαντες ἀπὸ τῶν τειχῶν ᾖξαν εἰς τοὺς Ῥωμαίους εὐμεταχείριστοι διὰ τὴν ἔκπληξιν ἦσαν. καὶ τῶν μὲν ἀπολωλότων, τῶν δ’ ὑπὸ τοῦ δέους σκεδασθέντων ἐρήμῳ τῷ τοῦ θεοῦ θησαυρῷ προσπεσόντες οἱ στρατιῶται περὶ τετρακόσια τάλαντα διήρπασαν, ὧν ὅσα μὴ διεκλάπη Σαβῖνος ἤθροισεν.", "st": "2.3.3"}, {"sp": "N", "t": "Ἰουδαίους δὲ ἥ τε τῶν ἔργων καὶ ἀνδρῶν φθορὰ πολὺ πλείους καὶ μαχιμωτέρους ἐπισυνέστησεν Ῥωμαίοις καὶ περισχόντες τὰ βασίλεια πάντας ἠπείλουν διαφθείρειν, εἰ μὴ θᾶττον ἀπίοιεν· ὑπισχνοῦντο γὰρ ἄδειαν τῷ Σαβίνῳ βουλομένῳ μετὰ τοῦ τάγματος ἐξιέναι. συνελάμβανον δ’ αὐτοῖς οἱ πλείους τῶν βασιλικῶν αὐτομολήσαντες. τὸ μέντοι πολεμικώτατον μέρος, Σεβαστηνοὶ τρισχίλιοι Ῥοῦφός τε καὶ Γρᾶτος ἐπὶ τούτοις, ὁ μὲν τοὺς πεζοὺς τῶν βασιλικῶν ὑπ’ αὐτὸν ἔχων, Ῥοῦφος δὲ τοὺς ἱππεῖς, ὢν ἑκάτερος καὶ χωρὶς ὑπηκόου δυνάμεως δι’ ἀλκὴν καὶ σύνεσιν πολέμου ῥοπή, προσέθεντο Ῥωμαίοις. Ἰουδαῖοι μὲν οὖν ἐνέκειντο τῇ πολιορκίᾳ τῶν τειχῶν ἅμα πειρώμενοι τοῦ φρουρίου καὶ τοῖς περὶ τὸν Σαβῖνον ἐμβοῶντες ἀπιέναι μηδ’ ἐμποδὼν αὐτοῖς γενέσθαι διὰ χρόνου πολλοῦ κομιζομένοις τὴν πάτριον αὐτονομίαν. Σαβίνῳ δ’ ἀγαπητὸν μὲν ἦν ὑπεξελθεῖν, ἠπίστει δὲ ταῖς ὑποσχέσεσιν καὶ τὸ πρᾷον αὐτῶν δέλεαρ εἰς ἐνέδραν ὑπώπτευεν· ἅμα δὲ καὶ τὴν ἀπὸ Οὐάρου βοήθειαν ἐλπίζων διέτριβεν τὴν πολιορκίαν.", "st": "2.3.4"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ τὰ κατὰ τὴν χώραν πολλαχόθεν ἐταράσσετο, καὶ συχνοὺς βασιλειᾶν ὁ καιρὸς ἀνέπειθεν. κατὰ μέν γε τὴν Ἰδουμαίαν δισχίλιοι τῶν ὑπὸ Ἡρώδῃ πάλαι στρατευσαμένων συστάντες ἔνοπλοι διεμάχοντο τοῖς βασιλικοῖς, οἷς Ἀχίαβος ἀνεψιὸς βασιλέως ἀπὸ τῶν ἐρυμνοτάτων χωρίων ἐπολέμει ὑποφεύγων τὴν ἐν τοῖς πεδίοις συμπλοκήν· ἐν δὲ Σεπφώρει τῆς Γαλιλαίας Ἰούδας υἱὸς Ἐζεκία τοῦ κατατρέχοντός ποτε τὴν χώραν ἀρχιλῃστοῦ καὶ χειρωθέντος ὑφ’ Ἡρώδου βασιλέως συστήσας πλῆθος οὐκ ὀλίγον ἀναρρήγνυσιν τὰς βασιλικὰς ὁπλοθήκας καὶ τοὺς περὶ αὐτὸν ὁπλίσας τοῖς τὴν δυναστείαν ζηλοῦσιν ἐπεχείρει.", "st": "2.4.1"}, {"sp": "N", "t": "Κατὰ δὲ τὴν Περαίαν Σίμων τις τῶν βασιλικῶν δούλων εὐμορφίᾳ σώματος καὶ μεγέθει πεποιθὼς περιτίθησιν μὲν ἑαυτῷ διάδημα, περιιὼν δὲ μεθ’ ὧν συνήθροισεν λῃστῶν τά τε ἐν Ἱεριχοῖ βασίλεια καταπίμπρησιν καὶ πολλὰς ἑτέρας τῶν πολυτελῶν ἐπαύλεις, ἁρπαγὰς ῥᾳδίως ἐκ τοῦ πυρὸς αὑτῷ ποριζόμενος. κἂν ἔφθη πᾶσαν οἴκησιν εὐπρεπῆ καταφλέξας, εἰ μὴ Γρᾶτος ὁ τῶν βασιλικῶν πεζῶν ἡγεμὼν τούς τε Τραχωνίτας τοξότας καὶ τὸ μαχιμώτατον τῶν Σεβαστηνῶν ἀναλαβὼν ὑπαντιάζει τὸν ἄνδρα. τῶν μὲν οὖν Περαίων συχνοὶ διεφθάρησαν ἐν τῇ μάχῃ, τὸν Σίμωνα δ’ αὐτὸν ἀναφεύγοντα δι’ ὀρθίου φάραγγος ὁ Γρᾶτος ὑποτέμνεται καὶ φεύγοντος ἐκ πλαγίου τὸν αὐχένα πλήξας ἀπέρραξε. κατεφλέγη δὲ καὶ τὰ πλησίον Ἰορδάνου βασίλεια κατὰ βηθαραμινενθα συστάντων ἑτέρων τινῶν ἐκ τῆς Περαίας.", "st": "2.4.2"}, {"sp": "N", "t": "Τότε καὶ ποιμήν τις ἀντιποιηθῆναι βασιλείας ἐτόλμησεν· Ἀθρογγαῖος ἐκαλεῖτο, προυξένει δ’ αὐτῷ τὴν ἐλπίδα σώματος ἰσχὺς καὶ ψυχὴ θανάτου καταφρονοῦσα, πρὸς δὲ τούτοις ἀδελφοὶ τέσσαρες ὅμοιοι. τούτων ἑκάστῳ λόχον ὑποζεύξας ἔνοπλον ὥσπερ στρατηγοῖς ἐχρῆτο καὶ σατράπαις ἐπὶ τὰς καταδρομάς, αὐτὸς δὲ καθάπερ βασιλεὺς τῶν σεμνοτέρων ἥπτετο πραγμάτων. τότε μὲν οὖν ἑαυτῷ περιτίθησιν διάδημα, διέμεινεν δ’ ὕστερον οὐκ ὀλίγον χρόνον τὴν χώραν κατατρέχων σὺν τοῖς ἀδελφοῖς· καὶ τὸ κτείνειν αὐτοῖς προηγούμενον ἦν Ῥωμαίους τε καὶ τοὺς βασιλικούς, διέφευγεν δὲ οὐδὲ Ἰουδαίων εἴ τις εἰς χεῖρας ἔλθοι φέρων κέρδος. ἐτόλμησαν δέ ποτε Ῥωμαίων λόχον ἄθρουν περισχεῖν κατ’ Ἀμμαοῦντα· σῖτα δ’ οὗτοι καὶ ὅπλα διεκόμιζον τῷ τάγματι. τὸν μὲν οὖν ἑκατοντάρχην αὐτῶν Ἄρειον καὶ τεσσαράκοντα τοὺς γενναιοτάτους κατηκόντισαν, οἱ δὲ λοιποὶ κινδυνεύοντες ταὐτὸ παθεῖν Γράτου σὺν τοῖς Σεβαστηνοῖς ἐπιβοηθήσαντος ἐξέφυγον. πολλὰ τοιαῦτα τοὺς ἐπιχωρίους καὶ τοὺς ἀλλοφύλους παρ’ ὅλον τὸν πόλεμον ἐργασάμενοι μετὰ χρόνον οἱ μὲν τρεῖς ἐχειρώθησαν, ὑπ’ Ἀρχελάου μὲν ὁ πρεσβύτατος, οἱ δ’ ἑξῆς δύο Γράτῳ καὶ Πτολεμαίῳ περιπεσόντες· ὁ δὲ τέταρτος Ἀρχελάῳ προσεχώρησεν κατὰ δεξιάν. τοῦτο μὲν δὴ τὸ τέλος ὕστερον αὐτοὺς ἐξεδέχετο, τότε δὲ λῃστρικοῦ πολέμου τὴν Ἰουδαίαν πᾶσαν ἐνεπίμπλασαν.", "st": "2.4.3"}, {"sp": "N", "t": "Οὐάρῳ δὲ δεξαμένῳ τὰ παρὰ Σαβίνου καὶ τῶν ἡγεμόνων γράμματα δεῖσαί τε περὶ τοῦ τάγματος ὅλου παρέστη καὶ σπεύδειν ἐπὶ τὴν βοήθειαν. ἀναλαβὼν δὴ τὰ λοιπὰ δύο τάγματα καὶ τὰς σὺν αὐτοῖς τέσσαρας ἴλας ἱππέων ἐπὶ Πτολεμαΐδος ᾔει, προστάξας ἐκεῖ καὶ τοὺς παρὰ τῶν βασιλέων καὶ δυναστῶν ἐπικούρους συνελθεῖν· προσέλαβεν δὲ καὶ παρὰ Βηρυτίων διερχόμενος τὴν πόλιν χιλίους καὶ πεντακοσίους ὁπλίτας. ἐπεὶ δ’ εἰς τὴν Πτολεμαΐδα τό τε ἄλλο συμμαχικὸν πλῆθος αὐτῷ παρῆν καὶ κατὰ τὸ πρὸς Ἡρώδην ἔχθος Ἀρέτας ὁ Ἄραψ οὐκ ὀλίγην ἄγων δύναμιν ἱππικήν τε καὶ πεζικήν, μέρος τῆς στρατιᾶς εὐθέως ἔπεμπεν εἰς τὴν Γαλιλαίαν γειτνιῶσαν τῇ Πτολεμαΐδι καὶ Γάιον ἡγεμόνα τῶν αὐτοῦ φίλων, ὃς τούς τε ὑπαντιάσαντας τρέπεται καὶ Σέπφωριν πόλιν ἑλὼν αὐτὴν μὲν ἐμπίπρησι, τοὺς δ’ ἐνοικοῦντας ἀνδραποδίζεται. μετὰ δὲ τῆς ὅλης δυνάμεως αὐτὸς Οὔαρος εἰς Σαμάρειαν ἐλάσας τῆς μὲν πόλεως ἀπέσχετο μηδὲν ἐν τοῖς τῶν ἄλλων θορύβοις παρακεκινηκυῖαν εὑρών, αὐλίζεται δὲ περί τινα κώμην Ἀροῦν καλουμένην· κτῆμα δὲ ἦν Πτολεμαίου καὶ διὰ τοῦτο ὑπὸ τῶν Ἀράβων διηρπάσθη μηνιόντων καὶ τοῖς Ἡρώδου φίλοις. ἔνθεν εἰς Σαπφὼ πρόεισιν κώμην ἑτέραν ἐρυμνήν, ἣν ὁμοίως διήρπασαν τάς τε προσόρους πάσας ὅσαις ἐπετύγχανον. πυρὸς δὲ καὶ φόνου πεπλήρωτο πάντα καὶ πρὸς τὰς ἁρπαγὰς τῶν Ἀράβων οὐδὲν ἀντεῖχεν. κατεφλέγη δὲ καὶ Ἀμμαοῦς φυγόντων τῶν οἰκητόρων, Οὐάρου δι’ ὀργὴν τῶν περὶ Ἄρειον ἀποσφαγέντων κελεύσαντος.", "st": "2.5.1"}, {"sp": "N", "t": "Ἐνθένδε εἰς Ἱεροσόλυμα προελθὼν ὀφθείς τε μόνον μετὰ τῆς δυνάμεως τὰ στρατόπεδα τῶν Ἰουδαίων διεσκέδασεν. καὶ οἱ μὲν ᾤχοντο φυγόντες ἀνὰ τὴν χώραν· δεξάμενοι δὲ αὐτὸν οἱ κατὰ τὴν πόλιν ἀπεσκευάζοντο τὰς αἰτίας τῆς ἀποστάσεως, αὐτοὶ μὲν οὐδὲν παρακινῆσαι λέγοντες, διὰ δὲ τὴν ἑορτὴν ἀναγκαίως δεξάμενοι τὸ πλῆθος συμπολιορκηθῆναι μᾶλλον Ῥωμαίοις ἢ συμπολεμῆσαι τοῖς ἀποστᾶσιν. προϋπηντήκεισαν δὲ αὐτῷ Ἰώσηπος ὁ ἀνεψιὸς Ἀρχελάου καὶ σὺν Γράτῳ Ῥοῦφος, ἄγοντες ἅμα τῷ βασιλικῷ στρατῷ καὶ τοὺς Σεβαστηνούς, οἵ τε ἀπὸ τοῦ Ῥωμαϊκοῦ τάγματος τὸν συνήθη τρόπον κεκοσμημένοι· Σαβῖνος μὲν γὰρ οὐδ’ εἰς ὄψιν ὑπομείνας ἐλθεῖν Οὐάρῳ προεξῆλθεν τῆς πόλεως ἐπὶ θάλασσαν. Οὔαρος δὲ κατὰ μοῖραν τῆς στρατιᾶς ἐπὶ τοὺς αἰτίους τοῦ κινήματος ἔπεμψεν περὶ τὴν χώραν, καὶ πολλῶν ἀγομένων τοὺς μὲν ἧττον θορυβώδεις φανέντας ἐφρούρει, τοὺς δὲ αἰτιωτάτους ἀνεσταύρωσεν περὶ δισχιλίους.", "st": "2.5.2"}, {"sp": "N", "t": "Ἠγγέλθη δ’ αὐτῷ κατὰ τὴν Ἰδουμαίαν ἔτι συμμένειν μυρίους ὁπλίτας. ὁ δὲ τοὺς μὲν Ἄραβας εὑρὼν οὐ συμμάχων ἦθος ἔχοντας, ἀλλ’ ἰδίῳ πάθει στρατευομένους καὶ πέρα τῆς ἑαυτοῦ προαιρέσεως τὴν χώραν κακοῦντας ἔχθει τῷ πρὸς Ἡρώδην ἀποπέμπεται, μετὰ δὲ τῶν ἰδίων ταγμάτων ἐπὶ τοὺς ἀφεστῶτας ἠπείγετο. κἀκεῖνοι πρὶν εἰς χεῖρας ἐλθεῖν Ἀχιάβου συμβουλεύσαντος σφᾶς αὐτοὺς παρέδοσαν, Οὔαρος δὲ τῷ πλήθει μὲν ἠφίει τὰς αἰτίας, τοὺς δὲ ἡγεμόνας ἐξετασθησομένους ἔπεμπεν ἐπὶ Καίσαρα. Καῖσαρ δὲ τοῖς μὲν ἄλλοις συνέγνω, τινὰς δὲ τῶν τοῦ βασιλέως συγγενῶν, ἦσαν γὰρ ἐν αὐτοῖς ἔνιοι προσήκοντες Ἡρώδῃ κατὰ γένος, κολάσαι προσέταξεν, ὅτι κατ’ οἰκείου βασιλέως ἐστρατεύσαντο. Οὔαρος μὲν οὖν τοῦτον τὸν τρόπον καταστησάμενος τὰ ἐν Ἱεροσολύμοις καὶ φρουρὰν καταλιπὼν τὸ καὶ πρότερον τάγμα εἰς Ἀντιόχειαν ἐπάνεισιν.", "st": "2.5.3"}, {"sp": "N", "t": "Ἀρχελάῳ δ’ ἐπὶ Ῥώμης πάλιν ἄλλη συνίσταται δίκη πρὸς Ἰουδαίους, οἳ πρὸ τῆς ἀποστάσεως ἐπιτρέψαντος Οὐάρου πρέσβεις ἐξεληλύθεσαν περὶ τῆς τοῦ ἔθνους αὐτονομίας· ἦσαν δὲ πεντήκοντα μὲν οἱ παρόντες, συμπαρίσταντο δὲ αὐτοῖς τῶν ἐπὶ Ῥώμης Ἰουδαίων ὑπὲρ ὀκτακισχιλίους. ἀθροίσαντος δὲ Καίσαρος συνέδριον τῶν ἐν τέλει Ῥωμαίων καὶ τῶν φίλων ἐν τῷ κατὰ τὸ Παλάτιον Ἀπόλλωνος ἱερῷ, κτίσμα δ’ ἦν ἴδιον αὐτοῦ θαυμασίῳ πολυτελείᾳ κεκοσμημένον, μετὰ μὲν τῶν πρεσβευτῶν τὸ Ἰουδαϊκὸν πλῆθος ἔστη, σὺν δὲ τοῖς φίλοις ἄντικρυς Ἀρχέλαος, τῶν δὲ τούτου συγγενῶν οἱ φίλοι παρ’ οὐδετέροις, συμπαρίστασθαι μὲν Ἀρχελάῳ διὰ μῖσος καὶ φθόνον οὐχ ὑπομένοντες, ὀφθῆναι δὲ μετὰ τῶν κατηγόρων ὑπὸ Καίσαρος αἰδούμενοι. τούτοις παρῆν καὶ Φίλιππος ἀδελφὸς Ἀρχελάου, προπεμφθεὶς κατ’ εὔνοιαν ὑπὸ Οὐάρου δυοῖν ἕνεκα, Ἀρχελάῳ τε συναγωνίσασθαι, κἂν διανέμῃ τὸν Ἡρώδου Καῖσαρ οἶκον πᾶσι τοῖς ἐγγόνοις, κλήρου τινὸς ἀξιωθῆναι.", "st": "2.6.1"}, {"sp": "N", "t": "Ἐπιτραπὲν δὲ λέγειν τοῖς κατηγόροις τὰς Ἡρώδου παρανομίας πρῶτον διεξῄεσαν, οὐ βασιλέα λέγοντες ἀλλὰ τῶν πώποτε τυραννησάντων ὠμότατον ἐνηνοχέναι τύραννον· πλείστων γοῦν ἀνῃρημένων ὑπ’ αὐτοῦ τοιαῦτα πεπονθέναι τοὺς καταλειφθέντας, ὥστε μακαρίζεσθαι τοὺς ἀπολωλότας· βεβασανικέναι γὰρ οὐ μόνον τὰ σώματα τῶν ὑποτεταγμένων ἀλλὰ καὶ τὰς πόλεις· τὰς μὲν γὰρ ἰδίας λελωβῆσθαι, τὰς δὲ τῶν ἀλλοφύλων κεκοσμηκέναι καὶ τὸ τῆς Ἰουδαίας αἷμα κεχαρίσθαι τοῖς ἔξωθεν δήμοις. ἀντὶ δὲ τῆς παλαιᾶς εὐδαιμονίας καὶ τῶν πατρίων νόμων πενίας τὸ ἔθνος καὶ παρανομίας ἐσχάτης πεπληρωκέναι, καθόλου δὲ πλείους ὑπομεμενηκέναι τὰς ἐξ Ἡρώδου συμφορὰς ἐν ὀλίγοις ἔτεσιν Ἰουδαίους ὧν ἐν παντὶ τῷ χρόνῳ μετὰ τὴν ἐκ Βαβυλῶνος ἀναχώρησιν ἔπαθον οἱ πρόγονοι Ξέρξου βασιλεύοντος ἀπαναστάντες. εἰς τοσοῦτον μέντοι μετριότητος καὶ τοῦ δυστυχεῖν ἔθους προελθεῖν, ὥστε ὑπομεῖναι τῆς πικρᾶς δουλείας καὶ διαδοχὴν αὐθαίρετον· Ἀρχέλαον γοῦν τὸν τηλικούτου τυράννου παῖδα μετὰ τὴν τοῦ πατρὸς τελευτὴν βασιλέα τε προσειπεῖν ἑτοίμως καὶ συμπενθῆσαι τὸν Ἡρώδου θάνατον αὐτῷ καὶ συνεύξασθαι περὶ τῆς διαδοχῆς. τὸν δ’ ὥσπερ ἀγωνιάσαντα, μὴ νόθος υἱὸς εἶναι δόξειεν Ἡρώδου, προοιμιάσασθαι τὴν βασιλείαν τρισχιλίων πολιτῶν φόνῳ, καὶ τοσαῦτα μὲν παρεστακέναι θύματα περὶ τῆς ἀρχῆς τῷ θεῷ, τοσούτοις δ’ ἐμπεπληκέναι νεκροῖς τὸ ἱερὸν ἐν ἑορτῇ. τοὺς μέντοι περιλειφθέντας ἐκ τοσούτων κακῶν εἰκότως ἐπεστράφθαι ποτὲ ἤδη πρὸς τὰς συμφορὰς καὶ πολέμου νόμῳ τὰς πληγὰς ἐθέλειν κατὰ πρόσωπον δέχεσθαι, δεῖσθαι δὲ Ῥωμαίων ἐλεῆσαι τά τε τῆς Ἰουδαίας λείψανα καὶ μὴ τὸ περισσὸν αὐτῆς ὑπορρῖψαι τοῖς ὠμῶς σπαράττουσιν, συνάψαντας δὲ τῇ Συρίᾳ τὴν χώραν αὐτῶν διοικεῖν ἐπ’ ἰδίοις ἡγεμόσιν· ἐπιδείξεσθαι γάρ, ὡς οἱ νῦν στασιώδεις διαβαλλόμενοι καὶ πολεμικοὶ φέρειν οἴδασιν μετρίους ἡγεμόνας. Ἰουδαῖοι μὲν οὖν ἐκ τῆς κατηγορίας κατέληξαν εἰς τοιαύτην ἀξίωσιν, ἀναστὰς δὲ Νικόλαος ἀπελύσατο μὲν τὰς εἰς τοὺς βασιλεῖς αἰτίας, κατηγόρει δὲ τοῦ ἔθνους τό τε δύσαρκτον καὶ τὸ δυσπειθὲς φύσει πρὸς τοὺς βασιλεῖς. συνδιέβαλλε δὲ καὶ τοὺς Ἀρχελάου συγγενεῖς, ὅσοι πρὸς τοὺς κατηγόρους ἀφεστήκεσαν.", "st": "2.6.2"}, {"sp": "N", "t": "Τότε μὲν οὖν Καῖσαρ ἀκούσας ἑκατέρων διέλυσε τὸ συνέδριον, μετὰ δ’ ἡμέρας ὀλίγας τὸ μὲν ἥμισυ τῆς βασιλείας Ἀρχελάῳ δίδωσιν ἐθνάρχην προσειπών, ὑποσχόμενος δὲ καὶ βασιλέα ποιήσειν, εἰ ἄξιον ἑαυτὸν παράσχοι, τὸ δὲ λοιπὸν ἥμισυ διελὼν εἰς δύο τετραρχίας δυσὶν ἑτέροις παισὶν Ἡρώδου δίδωσιν, τὴν μὲν Φιλίππῳ, τὴν δὲ Ἀντίπᾳ τῷ πρὸς Ἀρχέλαον ἀμφισβητοῦντι περὶ τῆς βασιλείας. ἐγένετο δὲ ὑπὸ τούτῳ μὲν ἥ τε Περαία καὶ Γαλιλαία, πρόσοδος διακόσια τάλαντα, Βατανέα δὲ καὶ Τράχων Αὐρανῖτίς τε καὶ μέρη τινὰ τοῦ Ζήνωνος οἴκου τὰ περὶ ἰννάνω, πρόσοδον ἔχοντα ταλάντων ἑκατόν, ὑπὸ Φιλίππῳ τέτακτο. τῆς Ἀρχελάου δ’ ἐθναρχίας Ἰδουμαία τε καὶ Ἰουδαία πᾶσα καὶ Σαμαρεῖτις ἦν κεκουφισμένη τετάρτῳ μέρει τῶν φόρων εἰς τιμὴν τοῦ μὴ μετὰ τῶν ἄλλων ἀποστῆναι. πόλεις δ’ ὑπηκόους παρέλαβεν Στράτωνος πύργον καὶ Σεβαστὴν καὶ Ἰόππην καὶ Ἱεροσόλυμα· τὰς γὰρ Ἑλληνίδας Γάζαν καὶ Γάδαρα καὶ Ἵππον ἀποτεμόμενος τῆς βασιλείας προσέθηκεν Συρίᾳ. πρόσοδος ἦν τῆς Ἀρχελάῳ δοθείσης χώρας τετρακοσίων ταλάντων. Σαλώμη δὲ πρὸς οἷς ὁ βασιλεὺς ἐν ταῖς διαθήκαις κατέλιπεν Ἰαμνείας τε καὶ Ἀζώτου καὶ Φασαηλίδος ἀποδείκνυται δεσπότις, χαρίζεται δ’ αὐτῇ Καῖσαρ καὶ τὰ ἐν Ἀσκάλωνι βασίλεια· συνήγετο δ’ ἐκ πάντων ἑξήκοντα προσόδου τάλαντα· τὸν δὲ οἶκον αὐτῆς ὑπὸ τὴν Ἀρχελάου τοπαρχίαν ἔταξεν. τῆς δ’ ἄλλης Ἡρώδου γενεᾶς ἕκαστος τὸ καταλειφθὲν ἐν ταῖς διαθήκαις ἐκομίζετο. δυσὶ δ’ αὐτοῦ θυγατράσι παρθένοις Καῖσαρ ἔξωθεν χαρίζεται πεντήκοντα μυριάδας ἀργυρίου καὶ συνῴκισεν αὐτὰς τοῖς Φερώρα παισίν. μετὰ δὲ τὸν οἶκον ἐπιδιένειμεν αὐτοῖς τὴν ἑαυτῷ καταλειφθεῖσαν ὑφ’ Ἡρώδου δωρεὰν οὖσαν χιλίων ταλάντων, εὐτελῆ τινα τῶν κειμηλίων εἰς τὴν τοῦ κατοιχομένου τιμὴν ἐξελόμενος.", "st": "2.6.3"}, {"sp": "N", "t": "Κἀν τούτῳ νεανίας τις Ἰουδαῖος μὲν τὸ γένος, τραφεὶς δὲ ἐν Σιδῶνι παρά τῳ τῶν Ῥωμαίων ἀπελευθέρῳ, δι’ ὁμοιότητα μορφῆς ψευδόμενος ἑαυτὸν Ἀλέξανδρον τὸν ἀναιρεθέντα ὑφ’ Ἡρώδου κατ’ ἐλπίδα τοῦ λήσειν ἧκεν εἰς Ῥώμην. συνεργὸς δ’ ἦν τις ὁμόφυλος αὐτῷ πάντα τὰ κατὰ τὴν βασιλείαν ἐπιστάμενος, ὑφ’ οὗ διδαχθεὶς ἔλεγεν, ὡς οἱ πεμφθέντες ἐπὶ τὴν ἀναίρεσιν αὐτοῦ τε καὶ Ἀριστοβούλου δι’ οἶκτον ἐκκλέψειαν αὐτοὺς ὁμοίων ὑποβολῇ σωμάτων. τούτοις γοῦν τοὺς ἐν Κρήτῃ Ἰουδαίους ἐξαπατήσας καὶ λαμπρῶς ἐφοδιασθεὶς διέπλευσεν εἰς Μῆλον· ἔνθα συναγείρας πολλῷ πλέον δι’ ὑπερβολὴν ἀξιοπιστίας ἀνέπεισεν καὶ τοὺς ἰδιοξένους εἰς Ῥώμην αὐτῷ συνεκπλεῦσαι. καταχθεὶς δὲ εἰς Δικαιάρχειαν δῶρά τε παμπληθῆ παρὰ τῶν ἐκεῖ Ἰουδαίων λαμβάνει καὶ καθάπερ βασιλεὺς ὑπὸ τῶν πατρῴων προεπέμφθη φίλων. προεληλύθει δ’ εἰς τοσοῦτον πίστεως τὸ τῆς μορφῆς ὅμοιον, ὥστε τοὺς ἑωρακότας Ἀλέξανδρον καὶ σαφῶς ἐπισταμένους διόμνυσθαι τοῦτον εἶναι. τό γε μὴν Ἰουδαϊκὸν ἐν τῇ Ῥώμῃ ἅπαν ἐξεχύθη πρὸς τὴν θέαν αὐτοῦ, καὶ πλῆθος ἄπειρον ἦν περὶ τοὺς στενωπούς, δι’ ὧν ἐκομίζετο· καὶ γὰρ προῆλθον εἰς τοσοῦτον φρενοβλαβείας οἱ Μήλιοι, ὥστε φορείῳ τε αὐτὸν κομίζειν καὶ θεραπείαν βασιλικὴν ἰδίοις παρασχεῖν ἀναλώμασιν.", "st": "2.7.1"}, {"sp": "N", "t": "Καῖσαρ δὲ γινώσκων [ἀκριβῶς] τοὺς Ἀλεξάνδρου χαρακτῆρας, κατηγόρητο γὰρ ὑφ’ Ἡρώδου παρ’ αὐτῷ, συνεώρα μὲν καὶ πρὶν ἰδεῖν τὸν ἄνθρωπον τὴν τῆς ὁμοιότητος ἀπάτην, διδοὺς δέ τι καὶ πίστεως ταῖς ἱλαρωτέραις ἐλπίσιν Κέλαδόν τινα πέμπει τῶν σαφῶς ἐπισταμένων Ἀλέξανδρον, κελεύσας ἀγαγεῖν αὐτῷ τὸν νεανίσκον. ὁ δὲ ὡς εἶδεν, ἐτεκμήρατο μὲν τάχιστα καὶ τὰς διαφορὰς τοῦ προσώπου τό τε ὅλον σῶμα σκληρότερόν τε καὶ δουλοφανὲς καταμαθὼν ἐνόησεν πᾶν τὸ σύνταγμα, πάνυ δὲ αὐτὸν παρώξυνεν ἡ τόλμα τῶν παρ’ αὐτοῦ λεγομένων· τοῖς γὰρ πυνθανομένοις περὶ Ἀριστοβούλου σώζεσθαι μὲν κἀκεῖνον ἔλεγεν, ἀπολελεῖφθαι δὲ ἐπίτηδες ἐν Κύπρῳ τὰς ἐπιβουλὰς φυλασσόμενον· ἧττον γὰρ ἐπιχειρεῖσθαι διεζευγμένους. ἀπολαβόμενος οὖν αὐτὸν κατ’ ἰδίαν μισθόν, ἔφη, παρὰ Καίσαρος ἔχεις τὸ ζῆν τοῦ μηνῦσαι τὸν ἀναπείσαντά σε πλανᾶσθαι τηλικαῦτα. κἀκεῖνος αὐτῷ δηλώσειν εἰπὼν ἕπεται πρὸς Καίσαρα καὶ τὸν Ἰουδαῖον ἐνδείκνυται καταχρησάμενον αὐτοῦ τῇ ὁμοιότητι πρὸς ἐργασίαν· τοσαῦτα γὰρ εἰληφέναι δῶρα καθ’ ἑκάστην πόλιν ὅσα ζῶν Ἀλέξανδρος οὐκ ἔλαβεν. γελάσας δὲ Καῖσαρ ἐπὶ τούτοις τὸν μὲν ψευδαλέξανδρον δι’ εὐεξίαν σώματος ἐγκατέταξεν τοῖς ἐρέταις, τὸν ἀναπείσαντα δὲ ἐκέλευσεν ἀναιρεθῆναι· Μηλίοις δ’ ἤρκεσεν ἐπιτίμιον τῆς ἀνοίας τὰ ἀναλώματα.", "st": "2.7.2"}, {"sp": "N", "t": "Παραλαβὼν δὲ τὴν ἐθναρχίαν Ἀρχέλαος καὶ κατὰ μνήμην τῶν πάλαι διαφορῶν οὐ μόνον Ἰουδαίοις ἀλλὰ καὶ Σαμαρεῦσι χρησάμενος ὠμῶς, πρεσβευσαμένων ἑκατέρων κατ’ αὐτοῦ πρὸς Καίσαρα ἔτει τῆς ἀρχῆς ἐνάτῳ φυγαδεύεται μὲν αὐτὸς εἰς Βίενναν πόλιν τῆς Γαλλίας, ἡ οὐσία δ’ αὐτοῦ τοῖς Καίσαρος θησαυροῖς ἐγκατατάσσεται. πρὶν κληθῆναι δ’ αὐτὸν ὑπὸ τοῦ Καίσαρος ὄναρ ἰδεῖν φασιν τοιόνδε· ἔδοξεν ὁρᾶν στάχυς ἐννέα πλήρεις καὶ μεγάλους ὑπὸ βοῶν καταβιβρωσκομένους. μεταπεμψάμενος δὲ τοὺς μάντεις καὶ τῶν Χαλδαίων τινὰς ἐπυνθάνετο, τί σημαίνειν δοκοῖεν. ἄλλων δ’ ἄλλως ἐξηγουμένων Σίμων τις Ἐσσαῖος τὸ γένος ἔφη τοὺς μὲν στάχυς ἐνιαυτοὺς νομίζειν, βόας δὲ μεταβολὴν πραγμάτων διὰ τὸ τὴν χώραν ἀροτριῶντας ἀλλάσσειν· ὥστε βασιλεύσειν μὲν αὐτὸν τὸν τῶν ἀσταχύων ἀριθμόν, ἐν ποικίλαις δὲ πραγμάτων μεταβολαῖς γενόμενον τελευτήσειν. ταῦτα ἀκούσας Ἀρχέλαος μετὰ πέντε ἡμέρας ἐπὶ τὴν δίκην ἐκλήθη.", "st": "2.7.3"}, {"sp": "N", "t": "Ἄξιον δὲ μνήμης ἡγησάμην καὶ τὸ τῆς γυναικὸς αὐτοῦ Γλαφύρας ὄναρ, ἥπερ ἦν θυγάτηρ μὲν Ἀρχελάου τοῦ Καππαδόκων βασιλέως, γυνὴ δὲ Ἀλεξάνδρου γεγονυῖα τὸ πρῶτον, ὃς ἦν ἀδελφὸς Ἀρχελάου περὶ οὗ διέξιμεν, υἱὸς δὲ Ἡρώδου τοῦ βασιλέως, ὑφ’ οὗ καὶ ἀνῃρέθη, καθάπερ δεδηλώκαμεν. μετὰ δὲ τὸν ἐκείνου θάνατον συνῴκησεν Ἰόβᾳ τῷ βασιλεύοντι Λιβύης, οὗ τελευτήσαντος ἐπανελθοῦσαν αὐτὴν καὶ χηρεύουσαν παρὰ τῷ πατρὶ θεασάμενος ὁ ἐθνάρχης Ἀρχέλαος ἐπὶ τοσοῦτον ἔρωτος ἦλθεν, ὥστε παραχρῆμα τὴν συνοικοῦσαν αὐτῷ Μαριάμμην ἀποπεμψάμενος ἐκείνην ἀγαγέσθαι. παραγενομένη τοίνυν εἰς Ἰουδαίαν μετ’ ὀλίγον τῆς ἀφίξεως χρόνον ἔδοξεν ἐπιστάντα τὸν Ἀλέξανδρον αὐτῇ λέγειν ἀπέχρη μὲν ὁ κατὰ Λιβύην σοι γάμος, σὺ δὲ οὐκ ἀρκεσθεῖσα τούτῳ πάλιν ἐπὶ τὴν ἐμὴν ἀνακάμπτεις ἑστίαν, τρίτον ἄνδρα καὶ ταῦτα τὸν ἀδελφόν, ὦ τολμηρά, τὸν ἐμὸν ᾑρημένη. πλὴν οὐ περιόψομαι τὴν ὕβριν, ἀπολήψομαι δέ σε καὶ μὴ θέλουσαν. τοῦτο διηγησαμένη τὸ ὄναρ μόλις δύο ἡμέρας ἐβίω.", "st": "2.7.4"}, {"sp": "N", "t": "Τῆς δὲ Ἀρχελάου χώρας εἰς ἐπαρχίαν περιγραφείσης ἐπίτροπος τῆς ἱππικῆς παρὰ Ῥωμαίοις τάξεως Κωπώνιος πέμπεται μέχρι τοῦ κτείνειν λαβὼν παρὰ Καίσαρος ἐξουσίαν. ἐπὶ τούτου τις ἀνὴρ Γαλιλαῖος Ἰούδας ὄνομα εἰς ἀπόστασιν ἐνῆγε τοὺς ἐπιχωρίους κακίζων, εἰ φόρον τε Ῥωμαίοις τελεῖν ὑπομενοῦσιν καὶ μετὰ τὸν θεὸν οἴσουσι θνητοὺς δεσπότας. ἦν δ’ οὗτος σοφιστὴς ἰδίας αἱρέσεως οὐδὲν τοῖς ἄλλοις προσεοικώς.", "st": "2.8.1"}, {"sp": "N", "t": "Τρία γὰρ παρὰ Ἰουδαίοις εἴδη φιλοσοφεῖται, καὶ τοῦ μὲν αἱρετισταὶ Φαρισαῖοι, τοῦ δὲ Σαδδουκαῖοι, τρίτον δέ, ὃ δὴ καὶ δοκεῖ σεμνότητα ἀσκεῖν, Ἐσσηνοὶ καλοῦνται, Ἰουδαῖοι μὲν γένος ὄντες, φιλάλληλοι δὲ καὶ τῶν ἄλλων πλέον. οὗτοι τὰς μὲν ἡδονὰς ὡς κακίαν ἀποστρέφονται, τὴν δὲ ἐγκράτειαν καὶ τὸ μὴ τοῖς πάθεσιν ὑποπίπτειν ἀρετὴν ὑπολαμβάνουσιν. καὶ γάμου μὲν παρ’ αὐτοῖς ὑπεροψία, τοὺς δ’ ἀλλοτρίους παῖδας ἐκλαμβάνοντες ἁπαλοὺς ἔτι πρὸς τὰ μαθήματα συγγενεῖς ἡγοῦνται καὶ τοῖς ἤθεσιν αὐτῶν ἐντυποῦσι, τὸν μὲν γάμον καὶ τὴν ἐξ αὐτοῦ διαδοχὴν οὐκ ἀναιροῦντες, τὰς δὲ τῶν γυναικῶν ἀσελγείας φυλαττόμενοι καὶ μηδεμίαν τηρεῖν πεπεισμένοι τὴν πρὸς ἕνα πίστιν.", "st": "2.8.2"}, {"sp": "N", "t": "Καταφρονηταὶ δὲ πλούτου, καὶ θαυμάσιον αὐτοῖς τὸ κοινωνικόν, οὐδὲ ἔστιν εὑρεῖν κτήσει τινὰ παρ’ αὐτοῖς ὑπερέχοντα· νόμος γὰρ τοὺς εἰς τὴν αἵρεσιν εἰσιόντας δημεύειν τῷ τάγματι τὴν οὐσίαν, ὥστε ἐν ἅπασιν μήτε πενίας ταπεινότητα φαίνεσθαι μήθ’ ὑπεροχὴν πλούτου, τῶν δ’ ἑκάστου κτημάτων ἀναμεμιγμένων μίαν ὥσπερ ἀδελφοῖς ἅπασιν οὐσίαν εἶναι. κηλῖδα δ’ ὑπολαμβάνουσι τὸ ἔλαιον, κἂν ἀλειφθῇ τις ἄκων, σμήχεται τὸ σῶμα· τὸ γὰρ αὐχμεῖν ἐν καλῷ τίθενται λευχειμονεῖν τε διαπαντός. χειροτονητοὶ δ’ οἱ τῶν κοινῶν ἐπιμεληταὶ καὶ ἀδιαίρετοι πρὸς ἁπάντων εἰς τὰς χρείας ἕκαστοι.", "st": "2.8.3"}, {"sp": "N", "t": "Μία δ’ οὐκ ἔστιν αὐτῶν πόλις ἀλλ’ ἐν ἑκάστῃ μετοικοῦσιν πολλοί. καὶ τοῖς ἑτέρωθεν ἥκουσιν αἱρετισταῖς πάντ’ ἀναπέπταται τὰ παρ’ αὐτοῖς ὁμοίως ὥσπερ ἴδια, καὶ πρὸς οὓς οὐ πρότερον εἶδον εἰσίασιν ὡς συνηθεστάτους· διὸ καὶ ποιοῦνται τὰς ἀποδημίας οὐδὲν μὲν ὅλως ἐπικομιζόμενοι, διὰ δὲ τοὺς λῃστὰς ἔνοπλοι. κηδεμὼν δ’ ἐν ἑκάστῃ πόλει τοῦ τάγματος ἐξαιρέτως τῶν ξένων ἀποδείκνυται ταμιεύων ἐσθῆτα καὶ τὰ ἐπιτήδεια. καταστολὴ δὲ καὶ σχῆμα σώματος ὅμοιον τοῖς μετὰ φόβου παιδαγωγουμένοις παισίν. οὔτε δὲ ἐσθῆτας οὔτε ὑποδήματα ἀμείβουσι πρὶν διαρραγῆναι τὸ πρότερον παντάπασιν ἢ δαπανηθῆναι τῷ χρόνῳ. οὐδὲν δ’ ἐν ἀλλήλοις οὔτ’ ἀγοράζουσιν οὔτε πωλοῦσιν, ἀλλὰ τῷ χρῄζοντι διδοὺς ἕκαστος τὰ παρ’ αὐτῷ τὸ παρ’ ἐκείνου χρήσιμον ἀντικομίζεται· καὶ χωρὶς δὲ τῆς ἀντιδόσεως ἀκώλυτος ἡ μετάληψις αὐτοῖς παρ’ ὧν ἂν θέλωσιν.", "st": "2.8.4"}, {"sp": "N", "t": "Πρός γε μὴν τὸ θεῖον εὐσεβεῖς ἰδίως· πρὶν γὰρ ἀνασχεῖν τὸν ἥλιον οὐδὲν φθέγγονται τῶν βεβήλων, πατρίους δέ τινας εἰς αὐτὸν εὐχὰς ὥσπερ ἱκετεύοντες ἀνατεῖλαι. καὶ μετὰ ταῦτα πρὸς ἃς ἕκαστοι τέχνας ἴσασιν ὑπὸ τῶν ἐπιμελητῶν διαφίενται, καὶ μέχρι πέμπτης ὥρας ἐργασάμενοι συντόνως πάλιν εἰς ἓν συναθροίζονται χωρίον, ζωσάμενοί τε σκεπάσμασιν λινοῖς οὕτως ἀπολούονται τὸ σῶμα ψυχροῖς ὕδασιν, καὶ μετὰ ταύτην τὴν ἁγνείαν εἰς ἴδιον οἴκημα συνίασιν, ἔνθα μηδενὶ τῶν ἑτεροδόξων ἐπιτέτραπται παρελθεῖν· αὐτοί τε καθαροὶ καθάπερ εἰς ἅγιόν τι τέμενος παραγίνονται τὸ δειπνητήριον. καὶ καθισάντων μεθ’ ἡσυχίας ὁ μὲν σιτοποιὸς ἐν τάξει παρατίθησι τοὺς ἄρτους, ὁ δὲ μάγειρος ἓν ἀγγεῖον ἐξ ἑνὸς ἐδέσματος ἑκάστῳ παρατίθησιν. προκατεύχεται δ’ ὁ ἱερεὺς τῆς τροφῆς, καὶ γεύσασθαί τινα πρὶν τῆς εὐχῆς ἀθέμιτον· ἀριστοποιησάμενος δ’ ἐπεύχεται πάλιν· ἀρχόμενοί τε καὶ παυόμενοι γεραίρουσι θεὸν ὡς χορηγὸν τῆς ζωῆς. ἔπειθ’ ὡς ἱερὰς καταθέμενοι τὰς ἐσθῆτας πάλιν ἐπ’ ἔργα μέχρι δείλης τρέπονται. δειπνοῦσι δ’ ὁμοίως ὑποστρέψαντες συγκαθεζομένων τῶν ξένων, εἰ τύχοιεν αὐτοῖς παρόντες. οὔτε δὲ κραυγή ποτε τὸν οἶκον οὔτε θόρυβος μιαίνει, τὰς δὲ λαλιὰς ἐν τάξει παραχωροῦσιν ἀλλήλοις. καὶ τοῖς ἔξωθεν ὡς μυστήριόν τι φρικτὸν ἡ τῶν ἔνδον σιωπὴ καταφαίνεται, τούτου δ’ αἴτιον ἡ διηνεκὴς νῆψις καὶ τὸ μετρεῖσθαι παρ’ αὐτοῖς τροφὴν καὶ ποτὸν μέχρι κόρου.", "st": "2.8.5"}, {"sp": "N", "t": "Τῶν μὲν οὖν ἄλλων οὐκ ἔστιν ὅ τι μὴ τῶν ἐπιμελητῶν προσταξάντων ἐνεργοῦσι, δύο δὲ ταῦτα παρ’ αὐτοῖς αὐτεξούσια, ἐπικουρία καὶ ἔλεος· βοηθεῖν τε γὰρ τοῖς ἀξίοις, ὁπόταν δέωνται, καὶ καθ’ ἑαυτοὺς ἐφίεται καὶ τροφὰς ἀπορουμένοις ὀρέγειν. τὰς δὲ εἰς τοὺς συγγενεῖς μεταδόσεις οὐκ ἔξεστι ποιεῖσθαι δίχα τῶν ἐπιτρόπων. ὀργῆς ταμίαι δίκαιοι, θυμοῦ καθεκτικοί, πίστεως προστάται, εἰρήνης ὑπουργοί. καὶ πᾶν μὲν τὸ ῥηθὲν ὑπ’ αὐτῶν ἰσχυρότερον ὅρκου, τὸ δὲ ὀμνύειν αὐτοῖς περιίσταται χεῖρον τῆς ἐπιορκίας ὑπολαμβάνοντες· ἤδη γὰρ κατεγνῶσθαί φασιν τὸν ἀπιστούμενον δίχα θεοῦ. σπουδάζουσι δ’ ἐκτόπως περὶ τὰ τῶν παλαιῶν συντάγματα μάλιστα τὰ πρὸς ὠφέλειαν ψυχῆς καὶ σώματος ἐκλέγοντες· ἔνθεν αὐτοῖς πρὸς θεραπείαν παθῶν ῥίζαι τε ἀλεξητήριον καὶ λίθων ἰδιότητες ἀνερευνῶνται.", "st": "2.8.6"}, {"sp": "N", "t": "Τοῖς δὲ ζηλοῦσιν τὴν αἵρεσιν αὐτῶν οὐκ εὐθὺς ἡ πάροδος, ἀλλ’ ἐπὶ ἐνιαυτὸν ἔξω μένοντι τὴν αὐτὴν ὑποτίθενται δίαιταν ἀξινάριόν τε καὶ τὸ προειρημένον περίζωμα καὶ λευκὴν ἐσθῆτα δόντες. ἐπειδὰν δὲ τούτῳ τῷ χρόνῳ πεῖραν ἐγκρατείας δῷ, πρόσεισιν μὲν ἔγγιον τῇ διαίτῃ καὶ καθαρωτέρων τῶν πρὸς ἁγνείαν ὑδάτων μεταλαμβάνει, παραλαμβάνεται δὲ εἰς τὰς συμβιώσεις οὐδέπω. μετὰ γὰρ τὴν τῆς καρτερίας ἐπίδειξιν δυσὶν ἄλλοις ἔτεσιν τὸ ἦθος δοκιμάζεται καὶ φανεὶς ἄξιος οὕτως εἰς τὸν ὅμιλον ἐγκρίνεται. πρὶν δὲ τῆς κοινῆς ἅψασθαι τροφῆς ὅρκους αὐτοῖς ὄμνυσι φρικώδεις, πρῶτον μὲν εὐσεβήσειν τὸ θεῖον, ἔπειτα τὰ πρὸς ἀνθρώπους δίκαια φυλάξειν καὶ μήτε κατὰ γνώμην βλάψειν τινὰ μήτε ἐξ ἐπιτάγματος, μισήσειν δ’ ἀεὶ τοὺς ἀδίκους καὶ συναγωνιεῖσθαι τοῖς δικαίοις· τὸ πιστὸν ἀεὶ πᾶσιν παρέξειν, μάλιστα δὲ τοῖς κρατοῦσιν· οὐ γὰρ δίχα θεοῦ περιγενέσθαι τινὶ τὸ ἄρχειν· κἂν αὐτὸς ἄρχῃ, μηδέποτε ἐξυβρίσειν εἰς τὴν ἐξουσίαν μηδ’ ἐσθῆτί τινι ἢ πλείονι κόσμῳ τοὺς ὑποτεταγμένους ὑπερλαμπρύνεσθαι. τὴν ἀλήθειαν ἀγαπᾶν ἀεὶ καὶ τοὺς ψευδομένους προβάλλεσθαι· χεῖρας κλοπῆς καὶ ψυχὴν ἀνοσίου κέρδους καθαρὰν φυλάξειν καὶ μήτε κρύψειν τι τοὺς αἱρετιστὰς μήθ’ ἑτέροις αὐτῶν τι μηνύσειν, κἂν μέχρι θανάτου τις βιάζηται. πρὸς τούτοις ὄμνυσιν μηδενὶ μὲν μεταδοῦναι τῶν δογμάτων ἑτέρως ἢ ὡς αὐτὸς μετέλαβεν, ἀφέξεσθαι δὲ λῃστείας καὶ συντηρήσειν ὁμοίως τά τε τῆς αἱρέσεως αὐτῶν βιβλία καὶ τὰ τῶν ἀγγέλων ὀνόματα. τοιούτοις μὲν ὅρκοις τοὺς προσιόντας ἐξασφαλίζονται.", "st": "2.8.7"}, {"sp": "N", "t": "Τοὺς δ’ ἐπ’ ἀξιοχρέοις ἁμαρτήμασιν ἁλόντας ἐκβάλλουσι τοῦ τάγματος. ὁ δ’ ἐκκριθεὶς οἰκτίστῳ πολλάκις μόρῳ διαφθείρεται· τοῖς γὰρ ὅρκοις καὶ τοῖς ἔθεσιν ἐνδεδεμένος οὐδὲ τῆς παρὰ τοῖς ἄλλοις τροφῆς δύναται μεταλαμβάνειν, ποηφαγῶν δὲ καὶ λιμῷ τὸ σῶμα τηκόμενος διαφθείρεται. διὸ δὴ πολλοὺς ἐλεήσαντες ἐν ταῖς ἐσχάταις ἀναπνοαῖς ἀνέλαβον, ἱκανὴν ἐπὶ τοῖς ἁμαρτήμασιν αὐτῶν τὴν μέχρι θανάτου βάσανον ἡγούμενοι.", "st": "2.8.8"}, {"sp": "N", "t": "Περὶ δὲ τὰς κρίσεις ἀκριβέστατοι καὶ δίκαιοι, καὶ δικάζουσι μὲν οὐκ ἐλάττους τῶν ἑκατὸν συνελθόντες, τὸ δ’ ὁρισθὲν ὑπ’ αὐτῶν ἀκίνητον. σέβας δὲ μέγα παρ’ αὐτοῖς μετὰ τὸν θεὸν τοὔνομα τοῦ νομοθέτου, κἂν βλασφημήσῃ τις εἰς τοῦτον κολάζεται θανάτῳ. τοῖς δὲ πρεσβυτέροις ὑπακούουσιν καὶ τοῖς πλείοσιν ἐν καλῷ· δέκα γοῦν συγκαθεζομένων οὐκ ἂν λαλήσειέν τις ἀκόντων τῶν ἐννέα. καὶ τὸ πτύσαι δὲ εἰς μέσους ἢ τὸ δεξιὸν μέρος φυλάσσονται καὶ ταῖς ἑβδομάσιν ἔργων ἐφάπτεσθαι διαφορώτατα Ἰουδαίων ἁπάντων· οὐ μόνον γὰρ τροφὰς ἑαυτοῖς πρὸ μιᾶς ἡμέρας παρασκευάζουσιν, ὡς μὴ πῦρ ἐναύοιεν ἐκείνην τὴν ἡμέραν, ἀλλ’ οὐδὲ σκεῦός τι μετακινῆσαι θαρροῦσιν οὐδὲ ἀποπατεῖν. ταῖς δ’ ἄλλαις ἡμέραις βόθρον ὀρύσσοντες βάθος ποδιαῖον τῇ σκαλίδι, τοιοῦτον γάρ ἐστιν τὸ διδόμενον ὑπ’ αὐτῶν ἀξινίδιον τοῖς νεοσυστάτοις, καὶ περικαλύψαντες θοιμάτιον, ὡς μὴ τὰς αὐγὰς ὑβρίζοιεν τοῦ θεοῦ, θακεύουσιν εἰς αὐτόν. ἔπειτα τὴν ἀνορυχθεῖσαν γῆν ἐφέλκουσιν εἰς τὸν βόθρον· καὶ τοῦτο ποιοῦσι τοὺς ἐρημοτέρους τόπους ἐκλεγόμενοι. καίπερ δὴ φυσικῆς οὔσης τῆς τῶν λυμάτων ἐκκρίσεως ἀπολούεσθαι μετ’ αὐτὴν καθάπερ μεμιασμένοις ἔθιμον.", "st": "2.8.9"}, {"sp": "N", "t": "Διῄρηνται δὲ κατὰ χρόνον τῆς ἀσκήσεως εἰς μοίρας τέσσαρας, καὶ τοσοῦτον οἱ μεταγενέστεροι τῶν προγενεστέρων ἐλαττοῦνται, ὥστ’ εἰ ψαύσειαν αὐτῶν, ἐκείνους ἀπολούεσθαι καθάπερ ἀλλοφύλῳ συμφυρέντας. καὶ μακρόβιοι μέν, ὡς τοὺς πολλοὺς ὑπὲρ ἑκατὸν παρατείνειν ἔτη, διὰ τὴν ἁπλότητα τῆς διαίτης ἔμοιγε δοκεῖν καὶ τὴν εὐταξίαν, καταφρονηταὶ δὲ τῶν δεινῶν, καὶ τὰς μὲν ἀλγηδόνας νικῶντες τοῖς φρονήμασιν, τὸν δὲ θάνατον, εἰ μετ’ εὐκλείας πρόσεισι, νομίζοντες ἀθανασίας ἀμείνονα. διήλεγξεν δὲ αὐτῶν ἐν ἅπασιν τὰς ψυχὰς ὁ πρὸς Ῥωμαίους πόλεμος, ἐν ᾧ στρεβλούμενοί τε καὶ λυγιζόμενοι καιόμενοί τε καὶ κλώμενοι καὶ διὰ πάντων ὁδεύοντες τῶν βασανιστηρίων ὀργάνων, ἵν’ ἢ βλασφημήσωσιν τὸν νομοθέτην ἢ φάγωσίν τι τῶν ἀσυνήθων, οὐδέτερον ὑπέμειναν παθεῖν, ἀλλ’ οὐδὲ κολακεῦσαί ποτε τοὺς αἰκιζομένους ἢ δακρῦσαι. μειδιῶντες δὲ ἐν ταῖς ἀλγηδόσιν καὶ κατειρωνευόμενοι τῶν τὰς βασάνους προσφερόντων εὔθυμοι τὰς ψυχὰς ἠφίεσαν ὡς πάλιν κομιούμενοι.", "st": "2.8.10"}, {"sp": "N", "t": "Καὶ γὰρ ἔρρωται παρ’ αὐτοῖς ἥδε ἡ δόξα, φθαρτὰ μὲν εἶναι τὰ σώματα καὶ τὴν ὕλην οὐ μόνιμον αὐτῶν, τὰς δὲ ψυχὰς ἀθανάτους ἀεὶ διαμένειν, καὶ συμπλέκεσθαι μὲν ἐκ τοῦ λεπτοτάτου φοιτώσας αἰθέρος ὥσπερ εἱρκταῖς τοῖς σώμασιν ἴυγγί τινι φυσικῇ κατασπωμένας, ἐπειδὰν δὲ ἀνεθῶσι τῶν κατὰ σάρκα δεσμῶν, οἷα δὴ μακρᾶς δουλείας ἀπηλλαγμένας τότε χαίρειν καὶ μετεώρους φέρεσθαι. καὶ ταῖς μὲν ἀγαθαῖς ὁμοδοξοῦντες παισὶν Ἑλλήνων ἀποφαίνονται τὴν ὑπὲρ ὠκεανὸν δίαιταν ἀποκεῖσθαι καὶ χῶρον οὔτε ὄμβροις οὔτε νιφετοῖς οὔτε καύμασι βαρυνόμενον, ἀλλ’ ὃν ἐξ ὠκεανοῦ πραῢς ἀεὶ ζέφυρος ἐπιπνέων ἀναψύχει· ταῖς δὲ φαύλαις ζοφώδη καὶ χειμέριον ἀφορίζονται μυχὸν γέμοντα τιμωριῶν ἀδιαλείπτων. δοκοῦσι δέ μοι κατὰ τὴν αὐτὴν ἔννοιαν Ἕλληνες τοῖς τε ἀνδρείοις αὐτῶν, οὓς ἥρωας καὶ ἡμιθέους καλοῦσιν, τὰς μακάρων νήσους ἀνατεθεικέναι, ταῖς δὲ τῶν πονηρῶν ψυχαῖς καθ’ ᾅδου τὸν ἀσεβῶν χῶρον, ἔνθα καὶ κολαζομένους τινὰς μυθολογοῦσιν, Σισύφους καὶ Ταντάλους Ἰξίονάς τε καὶ Τιτυούς, πρῶτον μὲν ἀιδίους ὑφιστάμενοι τὰς ψυχάς, ἔπειτα εἰς προτροπὴν ἀρετῆς καὶ κακίας ἀποτροπήν. τούς τε γὰρ ἀγαθοὺς γίνεσθαι κατὰ τὸν βίον ἀμείνους ἐλπίδι τιμῆς καὶ μετὰ τὴν τελευτήν, τῶν τε κακῶν ἐμποδίζεσθαι τὰς ὁρμὰς δέει προσδοκώντων, εἰ καὶ λάθοιεν ἐν τῷ ζῆν, μετὰ τὴν διάλυσιν ἀθάνατον τιμωρίαν ὑφέξειν. ταῦτα μὲν οὖν Ἐσσηνοὶ περὶ ψυχῆς θεολογοῦσιν ἄφυκτον δέλεαρ τοῖς ἅπαξ γευσαμένοις τῆς σοφίας αὐτῶν καθιέντες.", "st": "2.8.11"}, {"sp": "N", "t": "Εἰσὶν δ’ ἐν αὐτοῖς οἳ καὶ τὰ μέλλοντα προγινώσκειν ὑπισχνοῦνται, βίβλοις ἱεραῖς καὶ διαφόροις ἁγνείαις καὶ προφητῶν ἀποφθέγμασιν ἐμπαιδοτριβούμενοι· σπάνιον δ’ εἴ ποτε ἐν ταῖς προαγορεύσεσιν ἀστοχοῦσιν.", "st": "2.8.12"}, {"sp": "N", "t": "Ἔστιν δὲ καὶ ἕτερον Ἐσσηνῶν τάγμα, δίαιταν μὲν καὶ ἔθη καὶ νόμιμα τοῖς ἄλλοις ὁμοφρονοῦν, διεστὼς δὲ τῇ κατὰ γάμον δόξῃ· μέγιστον γὰρ ἀποκόπτειν οἴονται τοῦ βίου μέρος, τὴν διαδοχήν, τοὺς μὴ γαμοῦντας, μᾶλλον δέ, εἰ πάντες τὸ αὐτὸ φρονήσειαν, ἐκλιπεῖν ἂν τὸ γένος τάχιστα. δοκιμάζοντες μέντοι τριετίᾳ τὰς γαμετάς, ἐπειδὰν τρὶς καθαρθῶσιν εἰς πεῖραν τοῦ δύνασθαι τίκτειν, οὕτως ἄγονται. ταῖς δ’ ἐγκύμοσιν οὐχ ὁμιλοῦσιν, ἐνδεικνύμενοι τὸ μὴ δι’ ἡδονὴν ἀλλὰ τέκνων χρείαν γαμεῖν. λουτρὰ δὲ ταῖς γυναιξὶν ἀμπεχομέναις ἐνδύματα, καθάπερ τοῖς ἀνδράσιν ἐν περιζώματι. τοιαῦτα μὲν ἔθη τοῦδε τοῦ τάγματος.", "st": "2.8.13"}, {"sp": "N", "t": "Δύο δὲ τῶν προτέρων Φαρισαῖοι μὲν οἱ μετὰ ἀκριβείας δοκοῦντες ἐξηγεῖσθαι τὰ νόμιμα καὶ τὴν πρώτην ἀπάγοντες αἵρεσιν εἱμαρμένῃ τε καὶ θεῷ προσάπτουσι πάντα, καὶ τὸ μὲν πράττειν τὰ δίκαια καὶ μὴ κατὰ τὸ πλεῖστον ἐπὶ τοῖς ἀνθρώποις κεῖσθαι, βοηθεῖν δὲ εἰς ἕκαστον καὶ τὴν εἱμαρμένην· ψυχήν τε πᾶσαν μὲν ἄφθαρτον, μεταβαίνειν δὲ εἰς ἕτερον σῶμα τὴν τῶν ἀγαθῶν μόνην, τὰς δὲ τῶν φαύλων ἀιδίῳ τιμωρίᾳ κολάζεσθαι. Σαδδουκαῖοι δέ, τὸ δεύτερον τάγμα, τὴν μὲν εἱμαρμένην παντάπασιν ἀναιροῦσιν καὶ τὸν θεὸν ἔξω τοῦ δρᾶν τι κακὸν ἢ ἐφορᾶν τίθενται· φασὶν δ’ ἐπ’ ἀνθρώπων ἐκλογῇ τό τε καλὸν καὶ τὸ κακὸν προκεῖσθαι καὶ κατὰ γνώμην ἑκάστου τούτων ἑκατέρῳ προσιέναι. ψυχῆς τε τὴν διαμονὴν καὶ τὰς καθ’ ᾅδου τιμωρίας καὶ τιμὰς ἀναιροῦσιν. καὶ Φαρισαῖοι μὲν φιλάλληλοί τε καὶ τὴν εἰς τὸ κοινὸν ὁμόνοιαν ἀσκοῦντες, Σαδδουκαίων δὲ καὶ πρὸς ἀλλήλους τὸ ἦθος ἀγριώτερον αἵ τε ἐπιμιξίαι πρὸς τοὺς ὁμοίους ἀπηνεῖς ὡς πρὸς ἀλλοτρίους. τοιαῦτα μὲν περὶ τῶν ἐν Ἰουδαίοις φιλοσοφούντων εἶχον εἰπεῖν.", "st": "2.8.14"}, {"sp": "N", "t": "Τῆς Ἀρχελάου δ’ ἐθναρχίας μεταπεσούσης εἰς ἐπαρχίαν οἱ λοιποί, Φίλιππος καὶ Ἡρώδης ὁ κληθεὶς Ἀντίπας, διῴκουν τὰς ἑαυτῶν τετραρχίας· Σαλώμη γὰρ τελευτῶσα Ἰουλίᾳ τῇ τοῦ Σεβαστοῦ γυναικὶ τήν τε αὐτῆς τοπαρχίαν καὶ Ἰάμνειαν καὶ τοὺς ἐν Φασαηλίδι φοινικῶνας κατέλιπεν. μεταβάσης δὲ εἰς Τιβέριον τὸν Ἰουλίας υἱὸν τῆς Ῥωμαίων ἡγεμονίας μετὰ τὴν Αὐγούστου τελευτήν, ἀφηγησαμένου τῶν πραγμάτων ἔτεσιν ἑπτὰ καὶ πεντήκοντα πρὸς δὲ μησὶν ἓξ καὶ ἡμέραις δύο, διαμείναντες ἐν ταῖς τετραρχίαις ὅ τε Ἡρώδης καὶ ὁ Φίλιππος, ὁ μὲν πρὸς ταῖς τοῦ Ἰορδάνου πηγαῖς ἐν Πανεάδι πόλιν κτίζει Καισάρειαν κἀν τῇ κάτω Γαυλανιτικῇ Ἰουλιάδα, Ἡρώδης δ’ ἐν μὲν τῇ Γαλιλαίᾳ Τιβεριάδα, ἐν δὲ τῇ Περαίᾳ φερώνυμον Ἰουλίας.", "st": "2.9.1"}, {"sp": "N", "t": "Πεμφθεὶς δὲ εἰς Ἰουδαίαν ἐπίτροπος ὑπὸ Τιβερίου Πιλᾶτος νύκτωρ κεκαλυμμένας εἰς Ἱεροσόλυμα εἰσκομίζει τὰς Καίσαρος εἰκόνας, αἳ σημαῖαι καλοῦνται. τοῦτο μεθ’ ἡμέραν μεγίστην ταραχὴν ἤγειρεν Ἰουδαίοις· οἵ τε γὰρ ἐγγὺς πρὸς τὴν ὄψιν ἐξεπλάγησαν ὡς πεπατημένων αὐτοῖς τῶν νόμων, οὐδὲν γὰρ ἀξιοῦσιν ἐν τῇ πόλει δείκηλον τίθεσθαι, καὶ πρὸς τὴν ἀγανάκτησιν τῶν κατὰ τὴν πόλιν ἄθρους ὁ ἐκ τῆς χώρας λαὸς συνέρρευσεν. ὁρμήσαντες δὲ πρὸς Πιλᾶτον εἰς Καισάρειαν ἱκέτευον ἐξενεγκεῖν ἐξ Ἱεροσολύμων τὰς σημαίας καὶ τηρεῖν αὐτοῖς τὰ πάτρια. Πιλάτου δὲ ἀρνουμένου περὶ τὴν οἰκίαν πρηνεῖς καταπεσόντες ἐπὶ πέντε ἡμέρας καὶ νύκτας ἴσας ἀκίνητοι διεκαρτέρουν.", "st": "2.9.2"}, {"sp": "N", "t": "Τῇ δ’ ἑξῆς ὁ Πιλᾶτος καθίσας ἐπὶ βήματος ἐν τῷ μεγάλῳ σταδίῳ καὶ προσκαλεσάμενος τὸ πλῆθος ὡς ἀποκρίνασθαι δῆθεν αὐτοῖς θέλων, δίδωσιν τοῖς στρατιώταις σημεῖον ἐκ συντάγματος κυκλώσασθαι τοὺς Ἰουδαίους ἐν τοῖς ὅπλοις. περιστάσης δὲ τριστιχεὶ τῆς φάλαγγος Ἰουδαῖοι μὲν ἀχανεῖς ἦσαν πρὸς τὸ ἀδόκητον τῆς ὄψεως, Πιλᾶτος δὲ κατακόψειν εἰπὼν αὐτούς, εἰ μὴ προσδέξαιντο τὰς Καίσαρος εἰκόνας, γυμνοῦν τὰ ξίφη τοῖς στρατιώταις ἔνευσεν. οἱ δὲ Ἰουδαῖοι καθάπερ ἐκ συνθήματος ἀθρόοι καταπεσόντες καὶ τοὺς αὐχένας παρακλίναντες ἑτοίμους ἀναιρεῖν σφᾶς ἐβόων μᾶλλον ἢ τὸν νόμον παραβῆναι. ὑπερθαυμάσας δὲ ὁ Πιλᾶτος τὸ τῆς δεισιδαιμονίας ἄκρατον ἐκκομίσαι μὲν αὐτίκα τὰς σημαίας Ἱεροσολύμων κελεύει.", "st": "2.9.3"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα ταραχὴν ἑτέραν ἐκίνει τὸν ἱερὸν θησαυρόν, καλεῖται δὲ κορβωνᾶς, εἰς καταγωγὴν ὑδάτων ἐξαναλίσκων· κατῆγεν δὲ ἀπὸ τετρακοσίων σταδίων. πρὸς τοῦτο τοῦ πλήθους ἀγανάκτησις ἦν, καὶ τοῦ Πιλάτου παρόντος εἰς Ἱεροσόλυμα περιστάντες τὸ βῆμα κατεβόων. ὁ δέ, προῄδει γὰρ αὐτῶν τὴν ταραχήν, τῷ πλήθει τοὺς στρατιώτας ἐνόπλους ἐσθῆσιν ἰδιωτικαῖς κεκαλυμμένους ἐγκαταμίξας καὶ ξίφει μὲν χρήσασθαι κωλύσας, ξύλοις δὲ παίειν τοὺς κεκραγότας ἐγκελευσάμενος σύνθημα δίδωσιν ἀπὸ τοῦ βήματος. τυπτόμενοι δὲ οἱ Ἰουδαῖοι πολλοὶ μὲν ὑπὸ τῶν πληγῶν, πολλοὶ δὲ ὑπὸ σφῶν αὐτῶν ἐν τῇ φυγῇ καταπατηθέντες ἀπώλοντο. πρὸς δὲ τὴν συμφορὰν τῶν ἀνῃρημένων καταπλαγὲν τὸ πλῆθος ἐσιώπησεν.", "st": "2.9.4"}, {"sp": "N", "t": "Κἀν τούτῳ κατήγορος Ἡρώδου τοῦ τετραρχοῦντος Ἀγρίππας υἱὸς Ἀριστοβούλου, ὃν ὁ πατὴρ Ἡρώδης ἀπέκτεινεν, παραγίνεται πρὸς Τιβέριον. τοῦ δὲ μὴ προσδεξαμένου τὴν κατηγορίαν μένων ἐπὶ Ῥώμης τούς τε ἄλλους τῶν γνωρίμων ἐθεράπευεν καὶ μάλιστα τὸν Γερμανικοῦ παῖδα Γάιον ἰδιώτην ἔτι ὄντα. καὶ δή ποτε ἑστιῶν αὐτὸν τά τε ἄλλα ποικίλως ἐφιλοφρονεῖτο καὶ τελευταῖον τὰς χεῖρας ἀνατείνας φανερῶς ηὔξατο θᾶττον αὐτὸν θεάσασθαι τῶν ὅλων δεσπότην ἀποθανόντος Τιβερίου. τοῦτό τις τῶν οἰκετῶν αὐτοῦ διαγγέλλει τῷ Τιβερίῳ, καὶ ὃς ἀγανακτήσας εἵργνυσιν τὸν Ἀγρίππαν καὶ μετ’ αἰκίας εἶχεν αὐτὸν ἐπὶ μῆνας ἓξ ἐν δεσμωτηρίῳ, μέχρις αὐτὸς ἐτελεύτησεν ἡγεμονεύσας ἔτη δύο πρὸς τοῖς εἴκοσι καὶ τρεῖς ἡμέρας ἐπὶ μησὶν ἕξ.", "st": "2.9.5"}, {"sp": "N", "t": "Ἀποδειχθεὶς δὲ Γάιος Καῖσαρ ἀνίησίν τε τῶν δεσμῶν τὸν Ἀγρίππαν καὶ τῆς Φιλίππου τετραρχίας, θνήσκει γὰρ οὗτος, καθίστησι βασιλέα. παραγενόμενος δὲ εἰς τὴν ἀρχὴν Ἀγρίππας φθόνῳ τὰς Ἡρώδου τοῦ τετράρχου διήγειρεν ἐπιθυμίας. ἐνῆγε δὲ μάλιστα τοῦτον εἰς ἐλπίδα βασιλείας Ἡρωδιὰς ἡ γυνὴ κατονειδίζουσα τὴν ἀργίαν καὶ φαμένη παρὰ τὸ μὴ βούλεσθαι πλεῖν ἐπὶ Καίσαρα στερίσκεσθαι μείζονος ἀρχῆς· ὅπου μὲν γὰρ Ἀγρίππαν ἐξ ἰδιώτου βασιλέα πεποίηκεν, ἦπου γ’ ἂν ἐκεῖνον διστάσειεν ἐκ τετράρχου; τούτοις ἀναπεισθεὶς Ἡρώδης ἧκεν πρὸς Γάιον, ὑφ’ οὗ τῆς πλεονεξίας ἐπιτιμᾶται φυγῇ εἰς Γαλλίαν· ἠκολούθησεν γὰρ αὐτῷ κατήγορος Ἀγρίππας, ᾧ καὶ τὴν τετραρχίαν τὴν ἐκείνου προσέθηκεν Γάιος. καὶ Ἡρώδης μὲν ἐν Γαλλίᾳ συμφυγούσης αὐτῷ καὶ τῆς γυναικὸς τελευτᾷ.", "st": "2.9.6"}, {"sp": "N", "t": "Γάιος δὲ Καῖσαρ ἐπὶ τοσοῦτον ἐξύβρισεν εἰς τὴν τύχην, ὥστε θεὸν ἑαυτὸν καὶ δοκεῖν βούλεσθαι καὶ καλεῖσθαι τῶν τε εὐγενεστάτων ἀνδρῶν ἀκροτομῆσαι τὴν πατρίδα, ἐκτεῖναι δὲ τὴν ἀσέβειαν καὶ ἐπὶ Ἰουδαίαν. Πετρώνιον μὲν οὖν μετὰ στρατιᾶς ἐπὶ Ἱεροσολύμων ἔπεμψεν ἐγκαθιδρύσοντα τῷ ναῷ τοὺς ἀνδριάντας αὐτοῦ, προστάξας, εἰ μὴ δέχοιντο Ἰουδαῖοι, τούς τε κωλύοντας ἀνελεῖν καὶ πᾶν τὸ λοιπὸν ἔθνος ἐξανδραποδίσασθαι. θεῷ δ’ ἄρα τῶν προσταγμάτων ἔμελεν. καὶ Πετρώνιος μὲν σὺν τρισὶ τάγμασι καὶ πολλοῖς ἐκ τῆς Συρίας συμμάχοις εἰς τὴν Ἰουδαίαν ἤλαυνεν ἐκ τῆς Ἀντιοχείας, Ἰουδαίων δὲ οἱ μὲν ἠπίστουν ἐπὶ ταῖς τοῦ πολέμου φήμαις, οἱ δὲ πιστεύοντες ἦσαν ἐν ἀμηχάνῳ πρὸς τὴν ἄμυναν· ταχὺ δ’ ἐχώρει διὰ πάντων τὸ δέος ἤδη παρούσης εἰς Πτολεμαΐδα τῆς στρατιᾶς.", "st": "2.10.1"}, {"sp": "N", "t": "Πόλις δ’ ἐστὶν αὕτη τῆς Γαλιλαίας παράλιος κατὰ τὸ μέγα πεδίον ἐκτισμένη, περιέχεται δὲ ὄρεσιν ἐκ μὲν τοῦ πρὸς ἀνατολὴν κλίματος ἀπὸ σταδίων ἑξήκοντα τῷ τῆς Γαλιλαίας, ἀπὸ δὲ τοῦ μεσημβρινοῦ τῷ Καρμήλῳ διέχοντι σταδίους ἑκατὸν εἴκοσι, τῷ δ’ ὑψηλοτάτῳ κατ’ ἄρκτον, ὃ καλοῦσιν κλίμακα Τυρίων οἱ ἐπιχώριοι· καὶ τοῦτο δὲ σταδίους ἀφέστηκεν ἑκατόν. τοῦ δ’ ἄστεος ὅσον ἀπὸ δύο σταδίων ὁ καλούμενος Βήλεος ποταμὸς παραρρεῖ παντάπασιν ὀλίγος, παρ’ ᾧ τὸ Μέμνονος μνημεῖόν ἐστιν ἔχον ἐγγὺς αὐτοῦ τόπον ἑκατονταπήχη θαύματος ἄξιον· κυκλοτερὴς μὲν γάρ ἐστιν καὶ κοῖλος, ἀναδίδωσιν δὲ τὴν ὑελίνην ψάμμον, ἣν ὅταν ἐκκενώσῃ πολλὰ πλοῖα προσσχόντα, πάλιν ἀντιπληροῦται τὸ χωρίον, κατασυρόντων μὲν ὥσπερ ἐπίτηδες τότε τῶν ἀνέμων εἰς αὐτὸ τὴν ἔξωθεν ἀργὴν ψάμμον, τοῦ δὲ μετάλλου πᾶσαν εὐθέως μεταβάλλοντος εἰς ὕελον. θαυμασιώτερον δὲ τούτου μοι δοκεῖ τὸ τὴν ὑπερχυθεῖσαν ὕελον ἐκ τοῦ τόπου πάλιν ψάμμον γίνεσθαι εἰκαίαν. τὸ μὲν οὖν χωρίον τοῦτο τοιαύτην εἴληχεν φύσιν.", "st": "2.10.2"}, {"sp": "N", "t": "Ἰουδαῖοι δὲ μετὰ γυναικῶν καὶ τέκνων ἀθροισθέντες εἰς τὸ πεδίον τὸ πρὸς Πτολεμαΐδι καθικέτευον τὸν Πετρώνιον ὑπὲρ τῶν πατρίων νόμων πρῶτον, ἔπειτα ὑπὲρ αὑτῶν. ὁ δὲ πρός τε τὸ πλῆθος καὶ τὰς δεήσεις ἐνδοὺς τοὺς μὲν ἀνδριάντας καὶ τὰς στρατιὰς ἐν Πτολεμαΐδι λείπει, προελθὼν δὲ εἰς τὴν Γαλιλαίαν καὶ συγκαλέσας τό τε πλῆθος καὶ τοὺς γνωρίμους πάντας εἰς Τιβεριάδα τήν τε Ῥωμαίων διεξῄει δύναμιν καὶ τὰς Καίσαρος ἀπειλάς, ἔτι δὲ τὴν ἀξίωσιν ἀπέφαινεν ἀγνώμονα· πάντων γὰρ τῶν ὑποτεταγμένων ἐθνῶν κατὰ πόλιν συγκαθιδρυκότων τοῖς ἄλλοις θεοῖς καὶ τὰς Καίσαρος εἰκόνας τὸ μόνους ἐκείνους ἀντιτάσσεσθαι πρὸς τοῦτο σχεδὸν ἀφισταμένων εἶναι καὶ μεθ’ ὕβρεως.", "st": "2.10.3"}, {"sp": "N", "t": "Τῶν δὲ τὸν νόμον καὶ τὸ πάτριον ἔθος προτεινομένων καὶ ὡς οὐδὲ θεοῦ τι δείκηλον, οὐχ ὅπως ἀνδρός, οὐ κατὰ τὸν ναὸν μόνον ἀλλ’ οὐδὲ ἐν εἰκαίῳ τινὶ τόπῳ τῆς χώρας θέσθαι θεμιτὸν εἴη, ὑπολαβὼν ὁ Πετρώνιος ἀλλὰ μὴν καὶ ἐμοὶ φυλακτέος ὁ τοὐμοῦ δεσπότου νόμος, ἔφη· παραβὰς γὰρ αὐτὸν καὶ φεισάμενος ὑμῶν ἀπολοῦμαι δικαίως. πολεμήσει δ’ ὑμᾶς ὁ πέμψας με καὶ οὐκ ἐγώ· καὶ γὰρ αὐτός, ὥσπερ ὑμεῖς, ἐπιτάσσομαι. πρὸς ταῦτα τὸ πλῆθος πάντ’ ἐβόα πρὸ τοῦ νόμου πάσχειν ἑτοίμως ἔχειν. καταστείλας δ’ αὐτῶν ὁ Πετρώνιος τὴν βοήν, πολεμήσετε, εἶπεν, ἄρα Καίσαρι; καὶ Ἰουδαῖοι περὶ μὲν Καίσαρος καὶ τοῦ δήμου τῶν Ῥωμαίων δὶς τῆς ἡμέρας θύειν ἔφασαν, εἰ δὲ βούλεται τὰς εἰκόνας ἐγκαθιδρύειν, πρότερον αὐτὸν δεῖν ἅπαν τὸ Ἰουδαίων ἔθνος προθύσασθαι· παρέχειν δὲ σφᾶς αὐτοὺς ἑτοίμους εἰς τὴν σφαγὴν ἅμα τέκνοις καὶ γυναιξίν. ἐπὶ τούτοις θαῦμα καὶ οἶκτος εἰσῄει τὸν Πετρώνιον τῆς τε ἀνυπερβλήτου θρησκείας τῶν ἀνδρῶν καὶ τοῦ πρὸς θάνατον ἑτοίμου παραστήματος. καὶ τότε μὲν ἄπρακτοι διελύθησαν.", "st": "2.10.4"}, {"sp": "N", "t": "Ταῖς δ’ ἑξῆς ἀθρόους τε τοὺς δυνατοὺς κατ’ ἰδίαν καὶ τὸ πλῆθος ἐν κοινῷ συλλέγων ποτὲ μὲν παρεκάλει, ποτὲ δὲ συνεβούλευεν, τὸ πλέον μέντοι διηπείλει τήν τε Ῥωμαίων ἐπανατεινόμενος ἰσχὺν καὶ τοὺς Γαΐου θυμοὺς τήν τε ἰδίαν πρὸς τούτοις ἀνάγκην. πρὸς δὲ μηδεμίαν πεῖραν ἐνδιδόντων ὡς ἑώρα καὶ τὴν χώραν κινδυνεύουσαν ἄσπορον μεῖναι, κατὰ γὰρ ὥραν σπόρου πεντήκοντα ἡμέρας ἀργὰ προσδιέτριβεν αὐτῷ τὰ πλήθη, τελευταῖον ἀθροίσας αὐτοὺς καὶ παρακινδυνευτέον ἐμοὶ μᾶλλον, εἰπών, ἢ γὰρ τοῦ θεοῦ συνεργοῦντος πείσας Καίσαρα σωθήσομαι μεθ’ ὑμῶν ἡδέως ἢ παροξυνθέντος ὑπὲρ τοσούτων ἑτοίμως ἐπιδώσω τὴν ἐμαυτοῦ ψυχήν, διαφῆκεν τὸ πλῆθος πολλὰ κατευχομένων αὐτῷ, καὶ παραλαβὼν τὴν στρατιὰν ἐκ τῆς Πτολεμαΐδος ὑπέστρεψεν εἰς τὴν Ἀντιόχειαν. ἔνθεν εὐθέως ἐπέστελλεν Καίσαρι τήν τε ἐμβολὴν τὴν εἰς Ἰουδαίαν ἑαυτοῦ καὶ τὰς ἱκεσίας τοῦ ἔθνους, ὅτι τε, εἰ μὴ βούλεται πρὸς τοῖς ἀνδράσιν καὶ τὴν χώραν ἀπολέσαι, δέοι φυλάττειν τε αὐτοὺς τὸν νόμον καὶ παριέναι τὸ πρόσταγμα. ταύταις ταῖς ἐπιστολαῖς οὐ σφόδρα μετρίως ἀντέγραψεν ὁ Γάιος, ἀπειλῶν Πετρωνίῳ θάνατον, ὅτι τῶν προσταγμάτων αὐτοῦ βραδὺς ὑπηρέτης ἐγίνετο. ἀλλὰ τοὺς μὲν τούτων γραμματοφόρους συνέβη χειμασθῆναι τρεῖς μῆνας ἐν τῇ θαλάσσῃ, τὸν δὲ Γαΐου θάνατον ἄλλοι καταγγέλλοντες εὐπλόουν. ἔφθη γοῦν τὰς περὶ τούτων Πετρώνιος λαβὼν ἐπιστολὰς ἑπτὰ καὶ εἴκοσιν ἡμέραις ἢ τὰς καθ’ ἑαυτοῦ.", "st": "2.10.5"}, {"sp": "N", "t": "Γαΐου δὲ ἡγεμονεύσαντος ἔτη τρία καὶ μῆνας ὀκτὼ καὶ δολοφονηθέντος ἁρπάζεται μὲν ὑπὸ τῶν ἐν Ῥώμῃ στρατευμάτων [εἰς τὴν ἀρχὴν] Κλαύδιος, ἡ δὲ σύγκλητος ἐξηγουμένων τῶν ὑπάτων Σεντίου Σατορνίνου καὶ Πομπωνίου Σεκούνδου τρισὶν ταῖς συμμενούσαις σπείραις ἐπιτρέψασα φυλάττειν τὴν πόλιν εἰς τὸ Καπετώλιον ἠθροίσθη καὶ διὰ τὴν ὠμότητα τὴν Γαΐου Κλαυδίῳ πολεμεῖν ἐψηφίζετο· καταστήσεσθαι γὰρ δι’ ἀριστοκρατίας, ὥσπερ οὖν πάλαι διῳκεῖτο, τὴν ἀρχὴν ἢ κρινεῖν ψήφῳ τὸν ἄξιον τῆς ἡγεμονίας.", "st": "2.11.1"}, {"sp": "N", "t": "Συνέβη τηνικαῦτα πρὸς ἐπιδημοῦντα τὸν Ἀγρίππαν τήν τε σύγκλητον καλοῦσαν εἰς συμβουλίαν πέμψαι καὶ Κλαύδιον ἐκ τῆς παρεμβολῆς, ὅπως πρὸς ἃ δέοι χρήσιμος αὐτοῖς γένοιτο. κἀκεῖνος συνιδὼν τὸν ἤδη τῇ δυνάμει Καίσαρα πρὸς Κλαύδιον ἄπεισιν. ὁ δ’ αὐτὸν πρεσβευτὴν πρὸς τὴν σύγκλητον ἀναπέμπει δηλοῦντα τὴν ἑαυτοῦ προαίρεσιν, ὅτι πρῶτον μὲν ἄκων ὑπὸ τῶν στρατιωτῶν ἁρπαγείη, καὶ οὔτε τὴν ἐκείνων σπουδὴν ἐγκαταλιπεῖν δίκαιον οὔτε ἀσφαλὲς τὴν ἑαυτοῦ τύχην κρίνοι· καὶ γὰρ τὸ τυχεῖν τῆς ἡγεμονικῆς κλήσεως ἐπικίνδυνον εἶναι· ἔπειθ’ ὅτι διοικήσει τὴν ἀρχὴν ὥσπερ ἀγαθὸς προστάτης, οὐχ ὡς τύραννος· ἀρκεῖσθαι γὰρ τῇ τιμῇ τῆς προσηγορίας, τὴν δ’ ἐφ’ ἑκάστῳ τῶν πραγμάτων βουλὴν πᾶσιν ἀποδώσειν. καὶ γὰρ εἰ μὴ φύσει μέτριος ἦν, ἱκανὸν ὑπόδειγμα σωφροσύνης αὐτῷ προκεῖσθαι τὸν Γαΐου θάνατον.", "st": "2.11.2"}, {"sp": "N", "t": "Ταῦτ’ ἀπήγγειλεν Ἀγρίππας. ἡ δὲ βουλὴ ἀπεκρίνατο καὶ στρατῷ καὶ γνώμαις ἀγαθαῖς πεποιθυῖα δουλείαν ἑκούσιον οὐχ ὑπομενεῖν. καὶ Κλαύδιος ὡς ἤκουσεν τὰ παρὰ τῆς βουλῆς, πάλιν ἔπεμψεν τὸν Ἀγρίππαν ἀπαγγελοῦντα αὐτοῖς ὅτι προδοῦναι μὲν τοὺς εἰς αὐτὸν ὁμονοήσαντας οὐχ ὑπομένοι, πολεμήσειν δ’ ἄκων πρὸς οὓς ἥκιστα βούλοιτο. δεῖν μέντοι προαποδειχθῆναι τῷ πολέμῳ χωρίον ἔξω τῆς πόλεως· οὐ γὰρ ὅσιον διὰ τὴν αὐτῶν κακοβουλίαν ὁμοφύλῳ φόνῳ μιαίνεσθαι τὰ τεμένη τῆς πατρίδος. ὁ μὲν οὖν ἀκούσας ταῦτα τοῖς βουλευταῖς ἀπήγγειλεν.", "st": "2.11.3"}, {"sp": "N", "t": "Μεταξὺ δὲ τῶν μετὰ τῆς συγκλήτου στρατιωτῶν τις σπασάμενος τὸ ξίφος ἄνδρες, ἐβόησεν, συστρατιῶται, τί παθόντες ἀδελφοκτονεῖν βουλόμεθα καὶ κατὰ τῶν μετὰ Κλαυδίου συγγενῶν ὁρμᾶν, ἔχοντες μὲν αὐτοκράτορα μηδὲν μεμφθῆναι δυνάμενον, τοσαῦτα δὲ τὰ δίκαια πρὸς οὓς μετὰ τῶν ὅπλων χωρεῖν μέλλομεν; ταῦτα εἰπὼν διὰ μέσης ὥρμησεν τῆς βουλῆς πάντας τοὺς συστρατιώτας ἐφελκόμενος. οἱ δ’ εὐπατρίδαι παραχρῆμα μὲν πρὸς τὴν ἀπόλειψιν περιδεῶς ἔσχον, αὖθις δ’ ὡς ἀποστροφὴ σωτήριος οὐ κατεφαίνετο, τὴν τῶν στρατιωτῶν ὁδὸν ἠπείγοντο πρὸς Κλαύδιον. ὑπήντων δ’ αὐτοῖς πρὸ τοῦ τείχους γυμνοῖς τοῖς ξίφεσιν οἱ σφοδρότερον κολακεύοντες τὴν τύχην· κἂν συνέβη κινδυνεῦσαι τοὺς προάγοντας πρὶν γνῶναι τὴν ὁρμὴν τῶν στρατιωτῶν Κλαύδιον, εἰ μὴ προσδραμὼν Ἀγρίππας αὐτῷ τὸ κινδύνευμα τῆς πράξεως ἐδήλωσεν, ὅτι τε εἰ μὴ κατάσχοι τὴν ὁρμὴν τῶν ἐπὶ τοὺς εὐπατρίδας λελυσσηκότων, ἀπολέσας δι’ οὓς τὸ κρατεῖν ἐστι περίοπτον ἐρημίας ἔσοιτο βασιλεύς.", "st": "2.11.4"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας Κλαύδιος κατέσχεν τὰς ὁρμὰς τοῦ στρατιωτικοῦ προσδέχεταί τε τὴν σύγκλητον εἰς τὸ στρατόπεδον καὶ φιλοφρονησάμενος ἐξῄει σὺν αὐτοῖς αὐτίκα θύσων τῷ θεῷ τὰ περὶ τῆς ἡγεμονίας χαριστήρια. καὶ τὸν Ἀγρίππαν εὐθέως ἐδωρεῖτο τῇ πατρῴᾳ βασιλείᾳ πάσῃ προστιθεὶς ἔξωθεν καὶ τὰς ὑπ’ Αὐγούστου δοθείσας Ἡρώδῃ Τραχωνῖτιν καὶ Αὐρανῖτιν, χωρὶς δὲ τούτων ἑτέραν βασιλείαν τὴν Λυσανίου καλουμένην. καὶ τῷ μὲν δήμῳ διατάγματι τὴν δωρεὰν ἐδήλου, τοῖς ἄρχουσιν δὲ προσέταξεν ἐγχαράξαντας δέλτοις χαλκαῖς τὴν δόσιν εἰς τὸ Καπετώλιον ἀναθεῖναι· δωρεῖται δ’ αὐτοῦ καὶ τὸν ἀδελφὸν Ἡρώδην, ὁ δ’ αὐτὸς καὶ γαμβρὸς ἦν Βερνίκῃ συνοικῶν, βασιλείᾳ τῇ Χαλκίδι.", "st": "2.11.5"}, {"sp": "N", "t": "Ταχέως δ’ ὡς ἂν ἐκ τοσαύτης ἀρχῆς πλοῦτος Ἀγρίππᾳ προσέρρει, καὶ τοῖς χρήμασιν αὐτὸς οὐκ εἰς μακρὰν κατεχρήσατο· τηλικοῦτον γὰρ τοῖς Ἱεροσολύμοις περιβαλεῖν ἤρξατο τεῖχος, ἡλίκον ἂν τελεσθὲν ἀνήνυτον Ῥωμαίοις ἐποίησεν τὴν πολιορκίαν. ἀλλ’ ἔφθη πρὶν ὑψῶσαι τὸ ἔργον τελευτήσας ἐν Καισαρείᾳ, βεβασιλευκὼς μὲν ἔτη τρία, πρότερον δὲ τῶν τετραρχιῶν τρισὶν ἑτέροις ἔτεσιν ἀφηγησάμενος. καταλείπει δὲ τρεῖς μὲν θυγατέρας ἐκ Κύπρου γεγενημένας, Βερνίκην καὶ Μαριάμμην καὶ Δρουσίλλαν, υἱὸν δὲ ἐκ τῆς αὐτῆς Ἀγρίππαν. οὗ παντάπασιν ὄντος νηπίου πάλιν τὰς βασιλείας Κλαύδιος ἐπαρχίαν ποιήσας ἐπίτροπον πέμπει Κούσπιον Φᾶδον, ἔπειτα Τιβέριον Ἀλέξανδρον, οἳ μηδὲν παρακινοῦντες τῶν ἐπιχωρίων ἐθῶν ἐν εἰρήνῃ τὸ ἔθνος διεφύλαξαν. μετὰ ταῦτα καὶ ὁ βασιλεύων τῆς Χαλκίδος Ἡρώδης τελευτᾷ, καταλιπὼν ἐκ μὲν τῆς ἀδελφιδῆς Βερνίκης δύο παῖδας Βερνικιανόν τε καὶ Ὑρκανόν, ἐκ δὲ τῆς προτέρας Μαριάμμης Ἀριστόβουλον. τεθνήκει δ’ αὐτῷ καὶ ἕτερος ἀδελφὸς Ἀριστόβουλος ἰδιώτης καταλιπὼν Ἰωτάπην θυγατέρα. οὗτοι μὲν οὖν ἦσαν, ὡς προεῖπον, Ἀριστοβούλου τοῦ Ἡρώδου παῖδες, Ἀριστόβουλος δὲ καὶ Ἀλέξανδρος ἐκ Μαριάμμης Ἡρώδῃ γεγόνεισαν υἱεῖς, οὓς ὁ πατὴρ ἀνεῖλεν· ἡ δὲ Ἀλεξάνδρου γενεὰ τῆς μεγάλης Ἀρμενίας ἐβασίλευσεν.", "st": "2.11.6"}, {"sp": "N", "t": "Μετὰ δὲ τὴν Ἡρώδου τελευτήν, ὃς ἦρχε τῆς Χαλκίδος, καθίστησιν Κλαύδιος εἰς τὴν βασιλείαν τοῦ θείου τὸν Ἀγρίππαν υἱὸν Ἀγρίππα· τῆς δ’ ἄλλης ἐπαρχίας διαδέχεται τὴν ἐπιτροπὴν ἀπὸ Ἀλεξάνδρου Κουμανός, ἐφ’ οὗ θόρυβοί τε ἤρξαντο καὶ φθορὰ πάλιν Ἰουδαίων ἐγένετο. συνεληλυθότος γὰρ τοῦ πλήθους ἐπὶ τὴν ἑορτὴν τῶν ἀζύμων εἰς Ἱεροσόλυμα καὶ τῆς Ῥωμαϊκῆς σπείρας ὑπὲρ τὴν τοῦ ἱεροῦ στοὰν ἐφεστώσης, ἔνοπλοι δ’ ἀεὶ τὰς ἑορτὰς παραφυλάττουσιν, ὡς μή τι νεωτερίζοι τὸ πλῆθος ἠθροισμένον, εἷς τις τῶν στρατιωτῶν ἀνασυράμενος τὴν ἐσθῆτα καὶ κατακύψας ἀσχημόνως προσαπέστρεψεν τοῖς Ἰουδαίοις τὴν ἕδραν καὶ τῷ σχήματι φωνὴν ὁμοίαν ἐπεφθέγξατο. πρὸς τοῦτο ἅπαν μὲν τὸ πλῆθος ἠγανάκτησεν, καὶ κατεβόων τοῦ Κουμανοῦ κολάζειν τὸν στρατιώτην, οἱ δὲ ἧττον νήφοντες τῶν νέων καὶ τὸ φύσει στασιῶδες ἐκ τοῦ ἔθνους ἐχώρουν ἐπὶ μάχην λίθους τε ἁρπάσαντες ἐπὶ τοὺς στρατιώτας ἔβαλλον. καὶ Κουμανὸς δείσας μὴ τοῦ λαοῦ παντὸς ἐπ’ αὐτὸν ὁρμὴ γένοιτο, πλείους ὁπλίτας μεταπέμπεται. τῶν δὲ ταῖς στοαῖς ἐπιχεομένων φόβος ἐμπίπτει τοῖς Ἰουδαίοις ἀκατάσχετος, καὶ τραπέντες ἐκ τοῦ ἱεροῦ διέφευγον εἰς τὴν πόλιν. τοσαύτη δὲ περὶ τὰς ἐξόδους βία συνωθουμένων ἐγένετο, ὥστε πατηθέντας ὑπ’ ἀλλήλων καὶ συντριβέντας ὑπὲρ τρισμυρίους ἀποθανεῖν, γενέσθαι δὲ τὴν ἑορτὴν πένθος μὲν ὅλῳ τῷ ἔθνει θρῆνον δὲ καθ’ ἑκάστην οἰκίαν.", "st": "2.12.1"}, {"sp": "N", "t": "Μετελάμβανεν δὲ ταύτην τὴν συμφορὰν ἄλλος λῃστρικὸς θόρυβος. κατὰ γὰρ τὴν Βαιθωρὼ δημοσίαν ὁδὸν Στεφάνου τινὸς δούλου Καίσαρος ἀποσκευὴν κομιζομένην διήρπασαν λῃσταὶ προσπεσόντες. Κουμανὸς δὲ περιπέμψας τοὺς ἐκ τῶν πλησίον κωμῶν δεσμώτας ἐκέλευσεν ἀνάγεσθαι πρὸς αὐτόν, ἐπικαλῶν ὅτι μὴ διώξαντες τοὺς λῃστὰς συλλάβοιεν. ἔνθα τῶν στρατιωτῶν τις εὑρὼν ἔν τινι κώμῃ τὸν ἱερὸν νόμον διέρρηξέν τε τὸ βιβλίον καὶ εἰς πῦρ κατέβαλεν. Ἰουδαῖοι δὲ ὡς ὅλης αὐτοῖς τῆς χώρας καταφλεγείσης συνεχύθησαν, καὶ καθάπερ ὀργάνῳ τινὶ τῇ δεισιδαιμονίᾳ συνελκόμενοι πρὸς ἓν κήρυγμα πάντες εἰς Καισάρειαν ἐπὶ Κουμανὸν συνέδραμον ἱκετεύοντες τὸν οὕτως εἰς τὸν θεὸν καὶ τὸν νόμον αὐτῶν ἐξυβρίσαντα μὴ περιιδεῖν ἀτιμώρητον. ὁ δέ, οὐ γὰρ ἠρέμει τὸ πλῆθος, εἰ μὴ τύχοι παραμυθίας, ἠξίου τε προάγειν τὸν στρατιώτην καὶ διὰ μέσων τῶν αἰτιωμένων ἀπαχθῆναι τὴν ἐπὶ θανάτῳ κελεύει. καὶ Ἰουδαῖοι μὲν ἀνεχώρουν.", "st": "2.12.2"}, {"sp": "N", "t": "Αὖθις δὲ Γαλιλαίων καὶ Σαμαρέων γίνεται συμβολή. κατὰ γὰρ Γήμαν καλουμένην κώμην, ἥτις ἐν τῷ μεγάλῳ πεδίῳ κεῖται τῆς Σαμαρείτιδος, πολλῶν ἀναβαινόντων Ἰουδαίων ἐπὶ τὴν ἑορτὴν ἀναιρεῖταί τις Γαλιλαῖος. πρὸς τοῦτο πλεῖστοι μὲν ἐκ τῆς Γαλιλαίας συνέδραμον ὡς πολεμήσοντες τοῖς Σαμαρεῦσιν, οἱ γνώριμοι δ’ αὐτῶν ἐλθόντες πρὸς Κουμανὸν ἠντιβόλουν πρὶν ἀνηκέστου πάθους εἰς τὴν Γαλιλαίαν διαβάντα τιμωρήσασθαι τοὺς αἰτίους τοῦ φόνου· μόνως γὰρ ἂν οὕτως διαλυθῆναι πρὸ πολέμου τὸ πλῆθος. Κουμανὸς μὲν οὖν ἐν δευτέρῳ τὰς ἐκείνων ἱκεσίας τῶν ἐν χειρὶ πραγμάτων θέμενος ἀπράκτους ἀπέπεμψεν τοὺς ἱκέτας.", "st": "2.12.3"}, {"sp": "N", "t": "Ἀγγελθὲν δὲ εἰς Ἱεροσόλυμα τὸ πάθος τοῦ πεφονευμένου τὰ πλήθη συνετάραξεν καὶ τῆς ἑορτῆς ἀφέμενοι πρὸς τὴν Σαμάρειαν ἐξώρμων ἀστρατήγητοι καὶ μηδενὶ τῶν ἀρχόντων κατέχοντι πειθόμενοι. τοῦ λῃστρικοῦ δ’ αὐτῶν καὶ στασιώδους Δειναίου τις υἱὸς Ἐλεάζαρος καὶ Ἀλέξανδρος ἐξῆρχον, οἳ τοῖς ὁμόροις τῆς Ἀκραβατηνῆς τοπαρχίας προσπεσόντες αὐτούς τε ἀνῄρουν μηδεμιᾶς ἡλικίας φειδὼ ποιούμενοι καὶ τὰς κώμας ἐνεπίμπρασαν.", "st": "2.12.4"}, {"sp": "N", "t": "Κουμανὸς δὲ ἀναλαβὼν ἀπὸ τῆς Καισαρείας μίαν ἴλην ἱππέων καλουμένην Σεβαστηνῶν ἐξεβοήθει τοῖς πορθουμένοις καὶ τῶν περὶ τὸν Ἐλεάζαρον πολλοὺς μὲν συνέλαβεν, πλείστους δ’ ἀπέκτεινεν. πρὸς δὲ τὸ λοιπὸν πλῆθος τῶν πολεμεῖν τοῖς Σαμαρεῦσιν ὡρμημένων οἱ ἄρχοντες τῶν Ἱεροσολύμων ἐκδραμόντες σάκκους ἀμπεχόμενοι καὶ τέφραν τῶν κεφαλῶν καταχέοντες ἱκέτευον ἀναχωρεῖν καὶ μὴ διὰ τὴν εἰς Σαμαρεῖς ἄμυναν ἐπὶ Ἱεροσόλυμα Ῥωμαίους παροξύνειν, ἐλεῆσαί τε τὴν πατρίδα καὶ τὸν ναὸν τέκνα τε καὶ γυναῖκας ἰδίας, ἃ πάντα κινδυνεύειν δι’ ἑνὸς ἐκδικίαν Γαλιλαίου παραπολέσθαι. τούτοις πεισθέντες Ἰουδαῖοι διελύθησαν. ἐτράποντο δὲ πολλοὶ πρὸς λῃστείαν διὰ τὴν ἄδειαν, καὶ κατὰ πᾶσαν τὴν χώραν ἁρπαγαί τε ἦσαν καὶ τῶν θρασυτέρων ἐπαναστάσεις. καὶ τῶν Σαμαρέων οἱ δυνατοὶ πρὸς Οὐμμίδιον Κουαδρᾶτον, ὃς ἦν ἡγεμὼν τῆς Συρίας, εἰς Τύρον παραγενόμενοι δίκην τινὰ παρὰ τῶν πορθησάντων τὴν χώραν ἠξίουν λαβεῖν. παρόντες δὲ καὶ οἱ γνώριμοι τῶν Ἰουδαίων καὶ ὁ ἀρχιερεὺς Ἰωνάθης υἱὸς Ἀνάνου κατάρξαι μὲν ἔλεγον τῆς ταραχῆς Σαμαρέας διὰ τὸν φόνον, αἴτιον δὲ τῶν ἀποβεβηκότων Κουμανὸν γεγονέναι μὴ θελήσαντα τοὺς αὐθέντας τοῦ σφαγέντος ἐπεξελθεῖν.", "st": "2.12.5"}, {"sp": "N", "t": "Κουαδρᾶτος δὲ τότε μὲν ἑκατέρους ὑπερτίθεται φήσας, ἐπειδὰν εἰς τοὺς τόπους παραγένηται, διερευνήσειν ἕκαστα, αὖθις δὲ παρελθὼν εἰς Καισάρειαν τοὺς ὑπὸ Κουμανοῦ ζωγρηθέντας ἀνεσταύρωσεν πάντας. ἐκεῖθεν εἰς Λύδδα παραγενόμενος πάλιν διήκουσεν τῶν Σαμαρέων, καὶ μεταπεμψάμενος ὀκτωκαίδεκα τῶν Ἰουδαίων, οὓς ἐπέπυστο μετεσχηκέναι τῆς μάχης, πελέκει διεχειρίσατο· δύο δ’ ἑτέρους τῶν δυνατωτάτων καὶ τοὺς ἀρχιερεῖς Ἰωνάθην καὶ Ἀνανίαν τόν τε τούτου παῖδα Ἄνανον καί τινας ἄλλους Ἰουδαίων γνωρίμους ἀνέπεμψεν ἐπὶ Καίσαρα, ὁμοίως δὲ καὶ Σαμαρέων τοὺς ἐπιφανεστάτους. παρήγγειλεν δὲ καὶ Κουμανῷ καὶ Κέλερι τῷ χιλιάρχῳ πλεῖν ἐπὶ Ῥώμης δώσοντας Κλαυδίῳ λόγον ὑπὲρ τῶν γεγενημένων. ταῦτα διαπραξάμενος ἀπὸ Λύδδων ἀνέβαινεν εἰς Ἱεροσόλυμα, καὶ καταλαβὼν τὸ πλῆθος ἄγον τὴν τῶν ἀζύμων ἑορτὴν ἀθορύβως εἰς Ἀντιόχειαν ἐπανῄει.", "st": "2.12.6"}, {"sp": "N", "t": "Κατὰ δὲ τὴν Ῥώμην Καῖσαρ ἀκούσας Κουμανοῦ καὶ Σαμαρέων, παρῆν δὲ καὶ Ἀγρίππας ἐκθύμως ὑπεραγωνιζόμενος Ἰουδαίων ἐπειδὴ καὶ Κουμανῷ πολλοὶ τῶν δυνατῶν παρίσταντο, Σαμαρέων μὲν καταγνοὺς τρεῖς ἀνελεῖν προσέταξεν τοὺς δυνατωτάτους, Κουμανὸν δὲ ἐφυγάδευσεν. Κέλερα δὲ δεσμώτην ἀναπέμψας εἰς Ἱεροσόλυμα παραδοθῆναι Ἰουδαίοις πρὸς αἰκίαν ἐκέλευσεν καὶ περισυρέντα τὴν πόλιν οὕτω τὴν κεφαλὴν ἀποκοπῆναι.", "st": "2.12.7"}, {"sp": "N", "t": "Μετὰ ταῦτα Ἰουδαίας μὲν ἐπίτροπον Φήλικα τὸν Πάλλαντος ἀδελφὸν ἐκπέμπει τῆς τε Σαμαρείας καὶ Γαλιλαίας καὶ Περαίας, ἐκ δὲ τῆς Χαλκίδος Ἀγρίππαν εἰς μείζονα βασιλείαν μετατίθησιν, δοὺς αὐτῷ τήν τε Φιλίππου γενομένην ἐπαρχίαν, αὕτη δ’ ἦν Τραχωνῖτις καὶ Βατανέα καὶ Γαυλανῖτις, προσέθηκεν δὲ τήν τε Λυσανίου βασιλείαν καὶ τὴν Οὐάρου γενομένην τετραρχίαν. αὐτὸς δὲ διοικήσας τὴν ἡγεμονίαν ἔτεσι τρισκαίδεκα, πρὸς δὲ μησὶν ὀκτὼ καὶ εἴκοσιν ἡμέραις τελευτᾷ καταλιπὼν Νέρωνα τῆς ἀρχῆς διάδοχον, ὃν ταῖς Ἀγριππίνης τῆς γυναικὸς ἀπάταις ἐπὶ κληρονομίᾳ τῆς ἀρχῆς εἰσεποιήσατο καίπερ υἱὸν ἔχων γνήσιον Βρεττανικὸν ἐκ Μεσσαλίνης τῆς προτέρας γυναικὸς καὶ Ὀκταουίαν θυγατέρα τὴν ὑπ’ αὐτοῦ ζευχθεῖσαν Νέρωνι· γεγόνει δ’ αὐτῷ καὶ ἐκ Παιτίνης Ἀντωνία.", "st": "2.12.8"}, {"sp": "N", "t": "Ὅσα μὲν οὖν Νέρων δι’ ὑπερβολὴν εὐδαιμονίας τε καὶ πλούτου παραφρονήσας ἐξύβρισεν εἰς τὴν τύχην, ἢ τίνα τρόπον τόν τε ἀδελφὸν καὶ τὴν γυναῖκα καὶ τὴν μητέρα διεξῆλθεν, ἀφ’ ὧν ἐπὶ τοὺς εὐγενεστάτους μετήνεγκεν τὴν ὠμότητα, καὶ ὡς τελευταῖον ὑπὸ φρενοβλαβείας ἐξώκειλεν εἰς σκηνὴν καὶ θέατρον, ἐπειδὴ δι’ ὄχλου πᾶσίν ἐστιν, παραλείψω, τρέψομαι δὲ ἐπὶ τὰ Ἰουδαίοις κατ’ αὐτὸν γενόμενα.", "st": "2.13.1"}, {"sp": "N", "t": "Τὴν μὲν οὖν μικρὰν Ἀρμενίαν δίδωσιν βασιλεύειν Ἀριστοβούλῳ τῷ Ἡρώδου, τῇ δ’ Ἀγρίππα βασιλείᾳ τέσσαρας πόλεις προστίθησιν σὺν ταῖς τοπαρχίαις, Ἄβελα μὲν καὶ Ἰουλιάδα κατὰ τὴν Περαίαν, Ταριχέας δὲ καὶ Τιβεριάδα τῆς Γαλιλαίας, εἰς δὲ τὴν λοιπὴν Ἰουδαίαν Φήλικα κατέστησεν ἐπίτροπον. οὗτος τόν τε ἀρχιλῃστὴν Ἐλεάζαρον ἔτεσιν εἴκοσι τὴν χώραν λῃσάμενον καὶ πολλοὺς τῶν σὺν αὐτῷ ζωγρήσας ἀνέπεμψεν εἰς Ῥώμην· τῶν δ’ ἀνασταυρωθέντων ὑπ’ αὐτοῦ λῃστῶν καὶ τῶν ἐπὶ κοινωνίᾳ φωραθέντων δημοτῶν οὓς ἐκόλασεν, ἄπειρόν τι πλῆθος ἦν.", "st": "2.13.2"}, {"sp": "N", "t": "Καθαρθείσης δὲ τῆς χώρας ἕτερον εἶδος λῃστῶν ἐν Ἱεροσολύμοις ἐπεφύετο, οἱ καλούμενοι σικάριοι, μεθ’ ἡμέραν καὶ ἐν μέσῃ τῇ πόλει φονεύοντες ἀνθρώπους, μάλιστα [δὲ] ἐν ταῖς ἑορταῖς μισγόμενοι τῷ πλήθει καὶ ταῖς ἐσθῆσιν ὑποκρύπτοντες μικρὰ ξιφίδια, τούτοις ἔνυττον τοὺς διαφόρους, ἔπειτα πεσόντων μέρος ἐγίνοντο τῶν ἐπαγανακτούντων οἱ πεφονευκότες, διὸ καὶ παντάπασιν ὑπὸ ἀξιοπιστίας ἦσαν ἀνεύρετοι. πρῶτος μὲν οὖν ὑπ’ αὐτῶν Ἰωνάθης ὁ ἀρχιερεὺς ἀποσφάττεται, μετὰ δ’ αὐτὸν καθ’ ἡμέραν ἀνῃροῦντο πολλοί· καὶ τῶν συμφορῶν ὁ φόβος ἦν χαλεπώτερος, ἑκάστου καθάπερ ἐν πολέμῳ καθ’ ὥραν τὸν θάνατον προσδεχομένου. προεσκοποῦντο δὲ πόρρωθεν τοὺς διαφόρους, καὶ οὐδὲ τοῖς φίλοις προσιοῦσιν πίστις ἦν, ἐν μέσαις δὲ ταῖς ὑπονοίαις καὶ ταῖς φυλακαῖς ἀνῃροῦντο· τοσοῦτον τῶν ἐπιβουλευόντων τὸ τάχος ἦν καὶ τοῦ λαθεῖν ἡ τέχνη.", "st": "2.13.3"}, {"sp": "N", "t": "Συνέστη δὲ πρὸς τούτοις στῖφος ἕτερον πονηρῶν χειρὶ μὲν καθαρώτερον, ταῖς γνώμαις δὲ ἀσεβέστερον, ὅπερ οὐδὲν ἧττον τῶν σφαγέων τὴν εὐδαιμονίαν τῆς πόλεως ἐλυμήνατο. πλάνοι γὰρ ἄνθρωποι καὶ ἀπατεῶνες προσχήματι θειασμοῦ νεωτερισμοὺς καὶ μεταβολὰς πραγματευόμενοι δαιμονᾶν τὸ πλῆθος ἔπειθον καὶ προῆγον εἰς τὴν ἐρημίαν ὡς ἐκεῖ τοῦ θεοῦ δείξοντος αὐτοῖς σημεῖα ἐλευθερίας. ἐπὶ τούτοις Φῆλιξ, ἐδόκει γὰρ ἀποστάσεως εἶναι καταβολή, πέμψας ἱππεῖς καὶ πεζοὺς ὁπλίτας πολὺ πλῆθος διέφθειρεν.", "st": "2.13.4"}, {"sp": "N", "t": "Μείζονι δὲ τούτου πληγῇ Ἰουδαίους ἐκάκωσεν ὁ Αἰγύπτιος ψευδοπροφήτης· παραγενόμενος γὰρ εἰς τὴν χώραν ἄνθρωπος γόης καὶ προφήτου πίστιν ἐπιθεὶς ἑαυτῷ περὶ τρισμυρίους μὲν ἀθροίζει τῶν ἠπατημένων, περιαγαγὼν δὲ αὐτοὺς ἐκ τῆς ἐρημίας εἰς τὸ ἐλαιῶν καλούμενον ὄρος ἐκεῖθεν οἷός τε ἦν εἰς Ἱεροσόλυμα παρελθεῖν βιάζεσθαι καὶ κρατήσας τῆς τε Ῥωμαϊκῆς φρουρᾶς καὶ τοῦ δήμου τυραννεῖν χρώμενος τοῖς συνεισπεσοῦσιν δορυφόροις. φθάνει δ’ αὐτοῦ τὴν ὁρμὴν Φῆλιξ ὑπαντήσας μετὰ τῶν Ῥωμαϊκῶν ὁπλιτῶν, καὶ πᾶς ὁ δῆμος συνεφήψατο τῆς ἀμύνης, ὥστε συμβολῆς γενομένης τὸν μὲν Αἰγύπτιον φυγεῖν μετ’ ὀλίγων, διαφθαρῆναι δὲ καὶ ζωγρηθῆναι πλείστους τῶν σὺν αὐτῷ, τὸ δὲ λοιπὸν πλῆθος σκεδασθὲν ἐπὶ τὴν ἑαυτῶν ἕκαστον διαλαθεῖν.", "st": "2.13.5"}, {"sp": "N", "t": "Κατεσταλμένων δὲ καὶ τούτων ὥσπερ ἐν νοσοῦντι σώματι πάλιν ἕτερον μέρος ἐφλέγμαινεν. οἱ γὰρ γόητες καὶ λῃστρικοὶ συναχθέντες πολλοὺς εἰς ἀπόστασιν ἐνῆγον καὶ πρὸς ἐλευθερίαν παρεκρότουν θάνατον ἐπιτιμῶντες τοῖς πειθαρχοῦσιν τῇ Ῥωμαίων ἡγεμονίᾳ καὶ πρὸς βίαν ἀφαιρήσεσθαι λέγοντες τοὺς ἑκουσίως δουλεύειν προαιρουμένους. μεριζόμενοι δὲ εἰς τὴν χώραν κατὰ λόχους διήρπαζόν τε τὰς τῶν δυνατῶν οἰκίας καὶ αὐτοὺς ἀνῄρουν καὶ τὰς κώμας ἐνεπίμπρασαν, ὥστε τῆς ἀπονοίας αὐτῶν πᾶσαν τὴν Ἰουδαίαν ἀναπίμπλασθαι. καὶ οὗτος μὲν ὁ πόλεμος καθ’ ἡμέραν ἀνερριπίζετο.", "st": "2.13.6"}, {"sp": "N", "t": "Ἑτέρα δὲ ταραχὴ συνίσταται περὶ Καισάρειαν τῶν ἀναμεμιγμένων Ἰουδαίων πρὸς τοὺς ἐν αὐτῇ Σύρους στασιασάντων. οἱ μὲν γὰρ ἠξίουν σφετέραν εἶναι τὴν πόλιν Ἰουδαῖον γεγονέναι τὸν κτίστην αὐτῆς λέγοντες· ἦν δὲ Ἡρώδης ὁ βασιλεύς· οἱ δὲ ἕτεροι τὸν οἰκιστὴν μὲν προσωμολόγουν Ἰουδαῖον, αὐτὴν μέντοι γε τὴν πόλιν Ἑλλήνων ἔφασαν· οὐ γὰρ ἂν ἀνδριάντας καὶ ναοὺς ἐγκαθιδρῦσαι Ἰουδαίοις αὐτὴν ἀνατιθέντα. διὰ ταῦτα δὲ ἠμφισβήτουν ἑκάτεροι· προῄει δ’ αὐτοῖς τὸ φιλόνεικον εἰς ὅπλα καὶ καθ’ ἡμέραν οἱ θρασύτεροι παρ’ ἀμφοῖν προεπήδων ἐπὶ μάχην· οὔτε γὰρ Ἰουδαίων οἱ γεραιοὶ τοὺς ἰδίους στασιαστὰς κατέχειν οἷοί τε ἦσαν καὶ τοῖς Ἕλλησιν αἶσχος ἐδόκει Ἰουδαίων ἐλαττοῦσθαι. προεῖχον δ’ οἱ μὲν πλούτῳ καὶ σωμάτων ἀλκῇ, τὸ δὲ Ἑλληνικὸν τῇ παρὰ τῶν στρατιωτῶν ἀμύνῃ· τὸ γὰρ πλέον Ῥωμαίοις τῆς ἐκεῖ δυνάμεως ἐκ Συρίας ἦν κατειλεγμένον καὶ καθάπερ συγγενεῖς ἦσαν πρὸς τὰς βοηθείας ἕτοιμοι. τοῖς γε μὴν ἐπάρχοις φροντὶς ἦν ἀναστέλλειν τὴν ταραχὴν καὶ τοὺς μαχιμωτέρους ἀεὶ συλλαμβάνοντες ἐκόλαζον μάστιξι καὶ δεσμοῖς. οὐ μὴν τὰ πάθη τῶν συλλαμβανομένων ἐνεποίει τοῖς καταλειπομένοις ἀνακοπὴν ἢ δέος, ἀλλ’ ἔτι μᾶλλον παρωξύνοντο πρὸς τὴν στάσιν. νικῶντας δέ ποτε τοὺς Ἰουδαίους προελθὼν εἰς τὴν ἀγορὰν ὁ Φῆλιξ μετ’ ἀπειλῆς ἐκέλευσεν ἀναχωρεῖν. τῶν δὲ μὴ πειθομένων ἐπιπέμψας τοὺς στρατιώτας ἀναιρεῖ συχνούς, ὧν διαρπαγῆναι συνέβη καὶ τὰς οὐσίας. μενούσης δὲ τῆς στάσεως ἐπιλέξας ἑκατέρωθεν τοὺς γνωρίμους ἔπεμψεν πρέσβεις ἐπὶ Νέρωνα διαλεξομένους περὶ τῶν δικαίων.", "st": "2.13.7"}, {"sp": "N", "t": "Διαδεξάμενος δὲ παρὰ τούτου τὴν ἐπιτροπὴν ὁ Φῆστος τὸ μάλιστα λυμαινόμενον τὴν χώραν ἐπεξῄει· τῶν γοῦν λῃστῶν συνέλαβέν τε πλείστους καὶ διέφθειρεν οὐκ ὀλίγους. ἀλλ’ οὐχ ὁ μετὰ Φῆστον Ἀλβῖνος τὸν αὐτὸν τρόπον ἐξηγήσατο τῶν πραγμάτων, οὐκ ἔστιν δὲ ἥντινα κακουργίας ἰδέαν παρέλειπεν. οὐ μόνον γοῦν ἐν τοῖς πολιτικοῖς πράγμασιν ἔκλεπτεν καὶ διήρπαζεν τὰς ἑκάστων οὐσίας, οὐδὲ τὸ πᾶν ἔθνος ἐβάρει ταῖς εἰσφοραῖς, ἀλλὰ καὶ τοὺς ἐπὶ λῃστείᾳ δεδεμένους ὑπὸ τῆς παρ’ ἑκάστοις βουλῆς ἢ τῶν προτέρων ἐπιτρόπων ἀπελύτρου τοῖς συγγενέσιν, καὶ μόνος ὁ μὴ δοὺς τοῖς δεσμωτηρίοις ὡς πονηρὸς ἐγκατελείπετο. τηνικαῦτα καὶ τῶν νεωτερίζειν βουλομένων ἐν Ἱεροσολύμοις ἐθάρσησαν αἱ τόλμαι, καὶ χρήμασιν μὲν οἱ δυνατοὶ τὸν Ἀλβῖνον προσελάμβανον ὥστε τοῦ στασιάζειν αὐτοῖς παρέχειν ἄδειαν, τοῦ δημοτικοῦ δὲ τὸ μὴ χαῖρον ἡσυχίᾳ πρὸς τοὺς Ἀλβίνου κοινωνοὺς ἀπέκλινεν. ἕκαστος δὲ τῶν πονηρῶν ἴδιον στῖφος ὑπεζωσμένος αὐτὸς μὲν ὥσπερ ἀρχιλῃστὴς ἢ τύραννος προανεῖχεν ἐκ τοῦ λόχου, τοῖς δορυφοροῦσι δὲ πρὸς ἁρπαγὰς τῶν μετρίων κατεχρῆτο. συνέβαινεν δὲ τοὺς μὲν ἀφῃρημένους ὑπὲρ ὧν ἀγανακτεῖν ἐχρῆν σιωπᾶν, τοὺς ἄπληγας δὲ δέει τοῦ μὴ τὰ αὐτὰ παθεῖν καὶ κολακεύειν τὸν ἄξιον κολάσεως. καθόλου δὲ ἡ μὲν παρρησία πάντων περικέκοπτο, τυραννὶς δ’ ἦν διὰ πλειόνων, καὶ τὰ σπέρματα τῆς μελλούσης ἁλώσεως ἔκτοτε τῇ πόλει κατεβάλλετο.", "st": "2.14.1"}, {"sp": "N", "t": "Τοιοῦτον δ’ ὄντα τὸν Ἀλβῖνον ἀπέδειξεν ὁ μετ’ αὐτὸν ἐλθὼν Γέσσιος Φλῶρος ἀγαθώτατον κατὰ σύγκρισιν. ὁ μέν γε λάθρα τὰ πολλὰ καὶ μεθ’ ὑποστολῆς ἐκακούργησεν, Γέσσιος δὲ τὰς εἰς τὸ ἔθνος παρανομίας ἐπόμπευσεν καὶ ὥσπερ ἐπὶ τιμωρίᾳ κατακρίτων πεμφθεὶς δήμιος οὔτε ἁρπαγῆς τινα τρόπον οὔτε αἰκίας παρέλιπεν. ἦν δὲ ἐν μὲν τοῖς ἐλεεινοῖς ὠμότατος, ἐν δὲ τοῖς αἰσχροῖς ἀναιδέστατος. οὔτε δὲ πλείω τις ἀπιστίαν τῆς ἀληθείας κατέχεεν οὔτε ἐν τῷ πανουργεῖν δολιωτέρας ὁδοὺς ἐπενόησεν. ᾧ τὸ μὲν κατ’ ἄνδρα κερδαίνειν μικρὸν ἐδόκει, πόλεις δ’ ὅλας ἐξεδίδυσκε καὶ δήμους ἀθρόους ἐλυμαίνετο καὶ μόνον οὐκ ἐκήρυξεν ἀνὰ τὴν χώραν πᾶσιν ἐξεῖναι λῃστεύειν ἐφ’ ᾧ μέρος αὐτὸς λήψεται τῶν λαφύρων. διὰ γοῦν τὴν ἐκείνου πλεονεξίαν πάσας ἐρημωθῆναι συνέβη τὰς πόλεις καὶ πολλοὺς τῶν πατρίων ἠθῶν ἐξαναστάντας φυγεῖν εἰς τὰς ἀλλοφύλους ἐπαρχίας.", "st": "2.14.2"}, {"sp": "N", "t": "Μέχρι μὲν οὖν ἐν Συρίᾳ Κέστιος Γάλλος ἦν διέπων τὴν ἐπαρχίαν, οὐδὲ πρεσβεύσασθαί τις πρὸς αὐτὸν ἐτόλμησεν κατὰ τοῦ Φλώρου· παραγενόμενον δὲ εἰς Ἱεροσόλυμα τῆς τῶν ἀζύμων ἑορτῆς ἐνεστώσης περιστὰς ὁ δῆμος οὐκ ἐλάττους τριακοσίων μυριάδων ἱκέτευον ἐλεῆσαι τὰς τοῦ ἔθνους συμφορὰς καὶ τὸν λυμεῶνα τῆς χώρας Φλῶρον ἐκεκράγεσαν· ὁ δὲ παρὼν καὶ τῷ Κεστίῳ παρεστὼς διεχλεύαζεν τὰς φωνάς. ὅ γε μὴν Κέστιος τὴν ὁρμὴν τοῦ πλήθους καταστείλας καὶ δοὺς ἔμφασιν ὡς πρὸς τὸ μέλλον αὐτοῖς τὸν Φλῶρον κατασκευάσειεν μετριώτερον, ὑπέστρεφεν εἰς Ἀντιόχειαν. προέπεμπε δὲ αὐτὸν μέχρι Καισαρείας Φλῶρος ἐξαπατῶν καὶ πόλεμον ἤδη τῷ ἔθνει σκοπούμενος, ᾧ μόνῳ συγκρύψειν τὰς ἑαυτοῦ παρανομίας ὑπελάμβανεν· εἰρήνης μὲν γὰρ οὔσης κατηγόρους ἕξειν ἐπὶ Καίσαρος Ἰουδαίους προσεδόκα, πραγματευσάμενος δὲ ἀπόστασιν αὐτῶν τῷ μείζονι κακῷ περισπάσειν τὸν ἔλεγχον ἀπὸ τῶν μετριωτέρων. ὁ μὲν οὖν, ὡς ἂν ἀπορραγείη τὸ ἔθνος, καθ’ ἡμέραν ἐπέτεινεν αὐτοῖς τὰς συμφοράς.", "st": "2.14.3"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ οἱ Καισαρέων Ἕλληνες νικήσαντες παρὰ Νέρωνι τῆς πόλεως ἄρχειν τὰ τῆς κρίσεως ἐκόμισαν γράμματα, καὶ προσελάμβανεν τὴν ἀρχὴν ὁ πόλεμος δωδεκάτῳ μὲν ἔτει τῆς Νέρωνος ἡγεμονίας, ἑπτακαιδεκάτῳ δὲ τῆς Ἀγρίππα βασιλείας, Ἀρτεμισίου μηνός. πρὸς δὲ τὸ μέγεθος τῶν ἐξ αὐτοῦ συμφορῶν οὐκ ἀξίαν ἔσχεν πρόφασιν· οἱ γὰρ ἐν Καισαρείᾳ Ἰουδαῖοι, συναγωγὴν ἔχοντες παρὰ χωρίον, οὗ δεσπότης ἦν τις Ἕλλην Καισαρεύς, πολλάκις μὲν κτήσασθαι τὸν τόπον ἐσπούδασαν τιμὴν πολλαπλασίονα τῆς ἀξίας διδόντες· ὡς δ’ ὑπερορῶν τὰς δεήσεις πρὸς ἐπήρειαν ἔτι καὶ παρῳκοδόμει τὸ χωρίον ἐκεῖνος ἐργαστήρια κατασκευαζόμενος στενήν τε καὶ παντάπασιν βιαίαν πάροδον ἀπέλειπεν αὐτοῖς, τὸ μὲν πρῶτον οἱ θερμότεροι τῶν νέων προπηδῶντες οἰκοδομεῖν ἐκώλυον. ὡς δὲ τούτους εἶργεν τῆς βίας Φλῶρος, ἀμηχανοῦντες οἱ δυνατοὶ τῶν Ἰουδαίων, σὺν οἷς Ἰωάννης ὁ τελώνης. πείθουσι τὸν Φλῶρον ἀργυρίου ταλάντοις ὀκτὼ διακωλῦσαι τὸ ἔργον. ὁ δὲ πρὸς μόνον τὸ λαβεῖν ὑποσχόμενος πάντα συμπράξειν, λαβὼν ἔξεισιν τῆς Καισαρείας εἰς Σεβαστὴν καὶ καταλείπει τὴν στάσιν αὐτεξούσιον, ὥσπερ ἄδειαν πεπρακὼς Ἰουδαίοις τοῦ μάχεσθαι.", "st": "2.14.4"}, {"sp": "N", "t": "Τῆς δ’ ἐπιούσης ἡμέρας ἑβδομάδος οὔσης τῶν Ἰουδαίων εἰς τὴν συναγωγὴν συναθροισθέντων στασιαστής τις Καισαρεὺς γάστραν καταστρέψας καὶ παρὰ τὴν εἴσοδον αὐτῶν θέμενος ἐπέθυεν ὄρνεις. τοῦτο τοὺς Ἰουδαίους ἀνηκέστως παρώξυνεν ὡς ὑβρισμένων μὲν αὐτοῖς τῶν νόμων, μεμιασμένου δὲ τοῦ χωρίου. τὸ μὲν οὖν εὐσταθὲς καὶ πρᾷον ἐπὶ τοὺς ἡγεμόνας ἀναφεύγειν ᾤετο χρῆναι, τὸ στασιῶδες δὲ καὶ ἐν νεότητι φλεγμαῖνον ἐξεκαίετο πρὸς μάχην. παρεσκευασμένοι δὲ εἱστήκεσαν οἱ τῶν Καισαρέων στασιασταί, τὸν γὰρ ἐπιθύσοντα προπεπόμφεσαν ἐκ συντάγματος, καὶ ταχέως ἐγένετο συμβολή. προσελθὼν δὲ Ἰούκουνδος ὁ διακωλύειν τεταγμένος ἱππάρχης τήν τε γάστραν αἴρει καὶ καταπαύειν ἐπειρᾶτο τὴν στάσιν. ἡττωμένου δ’ αὐτοῦ τῆς τῶν Καισαρέων βίας Ἰουδαῖοι τοὺς νόμους ἁρπάσαντες ἀνεχώρησαν εἰς Νάρβατα· χώρα τις αὐτῶν οὕτω καλεῖται σταδίους ἑξήκοντα διέχουσα τῆς Καισαρείας· οἱ δὲ περὶ τὸν Ἰωάννην δυνατοὶ δώδεκα πρὸς Φλῶρον ἐλθόντες εἰς Σεβαστὴν ἀπωδύροντο περὶ τῶν πεπραγμένων καὶ βοηθεῖν ἱκέτευον, αἰδημόνως ὑπομιμνήσκοντες τῶν ὀκτὼ ταλάντων. ὁ δὲ καὶ συλλαβὼν ἔδησεν τοὺς ἄνδρας αἰτιώμενος ὑπὲρ τοῦ τοὺς νόμους ἐξενεγκεῖν τῆς Καισαρείας.", "st": "2.14.5"}, {"sp": "N", "t": "Πρὸς τοῦτο τῶν ἐν Ἱεροσολύμοις ἀγανάκτησις ἦν, ἔτι μέντοι τοὺς θυμοὺς κατεῖχον. ὁ δὲ Φλῶρος ὥσπερ ἠργολαβηκὼς ἐκριπίζειν τὸν πόλεμον, πέμψας εἰς τὸν ἱερὸν θησαυρὸν ἐξαιρεῖ δεκαεπτὰ τάλαντα σκηψάμενος εἰς τὰς Καίσαρος χρείας. σύγχυσις δ’ εὐθέως εἶχεν τὸν δῆμον, καὶ συνδραμόντες εἰς τὸ ἱερὸν βοαῖς διαπρυσίοις τὸ Καίσαρος ἀνεκάλουν ὄνομα καὶ τῆς Φλώρου τυραννίδος ἐλευθεροῦν σφᾶς ἱκέτευον. ἔνιοι δὲ τῶν στασιαστῶν λοιδορίας αἰσχίστους εἰς τὸν Φλῶρον ἐκεκράγεσαν καὶ κανοῦν περιφέροντες ἀπῄτουν αὐτῷ κέρματα καθάπερ ἀκλήρῳ καὶ ταλαιπώρῳ. τούτοις οὐκ ἀνετράπη τὴν φιλαργυρίαν, ἀλλ’ ἐπὶ τὸ μᾶλλον χρηματίσασθαι παρωργίσθη. δέον γοῦν εἰς Καισάρειαν ἐλθόντα σβέσαι τὸ τοῦ πολέμου πῦρ ἐκεῖθεν ἀρχόμενον καὶ τῆς ταραχῆς ἀνελεῖν τὰς αἰτίας, ἐφ’ ᾧ καὶ μισθὸν ἔλαβεν, ὁ δὲ μετὰ στρατιᾶς ἱππικῆς τε καὶ πεζικῆς ἐπὶ Ἱεροσολύμων ὥρμησεν, ἵνα τοῖς Ῥωμαίων ὅπλοις ἐργάσηται καὶ τῷ δέει καὶ ταῖς ἀπειλαῖς περιδύσῃ τὴν πόλιν.", "st": "2.14.6"}, {"sp": "N", "t": "Ὁ δὲ δῆμος προδυσωπῆσαι τὴν ὁρμὴν αὐτοῦ βουλόμενος ὑπαντᾷ τοῖς στρατιώταις μετ’ εὐφημίας καὶ τὸν Φλῶρον θεραπευτικῶς ἐκδέχεσθαι παρεσκευάσατο. κἀκεῖνος προπέμψας σὺν ἱππεῦσιν πεντήκοντα Καπίτωνα ἑκατοντάρχην ἀναχωρεῖν αὐτοὺς ἐκέλευσεν καὶ μὴ πρὸς ὃν οὕτως ἐλοιδόρησαν αἰσχρῶς εἰρωνεύεσθαι τὰς νῦν φιλοφρονήσεις· δεῖν γὰρ αὐτούς, εἴπερ γενναῖοί εἰσιν καὶ παρρησιασταί, σκώπτειν μὲν αὐτὸν καὶ παρόντα, φαίνεσθαι δὲ μὴ μόνον ἐν τοῖς λόγοις, ἀλλὰ κἀν τοῖς ὅπλοις φιλελευθέρους. τούτοις καταπλαγὲν τὸ πλῆθος, ἅμα καὶ τῶν περὶ Καπίτωνα ἱππέων εἰς μέσον φερομένων, διεσκεδάσθη πρὶν ἀσπάσασθαι τὸν Φλῶρον ἢ τοῖς στρατιώταις φανερὸν ποιῆσαι τὸ πειθήνιον. ἀναχωρήσαντες δὲ εἰς τὰς οἰκίας μετὰ δέους καὶ ταπεινότητος ἐνυκτέρευσαν.", "st": "2.14.7"}, {"sp": "N", "t": "Φλῶρος δὲ τότε μὲν ἐν τοῖς βασιλείοις αὐλίζεται, τῇ δ’ ὑστεραίᾳ βῆμα πρὸ αὐτῶν θέμενος καθέζεται, καὶ προσελθόντες οἵ τε ἀρχιερεῖς καὶ δυνατοὶ τό τε γνωριμώτατον τῆς πόλεως παρέστησαν τῷ βήματι. τούτοις ὁ Φλῶρος ἐκέλευσεν τοὺς λοιδορήσαντας αὐτὸν ἐκδοῦναι, φάμενος αὐτοὺς ἀπολαύσειν τῆς ἀμύνης, εἰ μὴ προάγοιεν τοὺς αἰτίους. οἱ δὲ τὸν μὲν δῆμον ἀπέφηναν εἰρηνικὰ φρονοῦντα, τοῖς δὲ παραφθεγξαμένοις ᾐτοῦντο συγγνώμην· ἐν γὰρ τοσούτῳ πλήθει θαυμαστὸν μὲν οὐδὲν εἶναί τινας θρασυτέρους καὶ δι’ ἡλικίαν ἄφρονας, ἀμήχανον δὲ τῶν ἡμαρτηκότων τὴν διάκρισιν ἑκάστου μετανοοῦντος καὶ δι’ ἃ δέδρακεν ἀρνουμένου. δεῖν μέντοι γε ἐκεῖνον, εἰ προνοεῖ τῆς κατὰ τὸ ἔθνος εἰρήνης καὶ βούλεται Ῥωμαίοις περισώζειν τὴν πόλιν, μᾶλλον διὰ τοὺς πολλοὺς ἀκαταιτιάτους συγγνῶναι καὶ τοῖς ὀλίγοις πλημμελήσασιν ἢ δι’ ὀλίγους πονηροὺς ταράξαι δῆμον ἀγαθὸν τοσοῦτον.", "st": "2.14.8"}, {"sp": "N", "t": "Πρὸς ταῦτα μᾶλλον παροξυνθεὶς ἐμβοᾷ τοῖς στρατιώταις διαρπάζειν τὴν ἄνω καλουμένην ἀγορὰν καὶ κτείνειν τοὺς ἐντυγχάνοντας. οἱ δ’ ἐπιθυμίᾳ κέρδους προσλαβόντες ἡγεμονικὴν παρακέλευσιν οὐ μόνον ἐφ’ ὃν ἐπέμφθησαν τόπον ἥρπαζον, ἀλλ’ εἰς πάσας ἐμπηδῶντες τὰς οἰκίας ἔσφαζον τοὺς οἰκήτορας. φυγὴ δ’ ἦν ἐκ τῶν στενωπῶν καὶ φόνος τῶν καταλαμβανομένων, τρόπος τε ἁρπαγῆς οὐδεὶς παρελείπετο, καὶ πολλοὺς τῶν μετρίων συλλαβόντες ἐπὶ τὸν Φλῶρον ἀνῆγον· οὓς μάστιξιν προαικισάμενος ἀνεσταύρωσεν. ὁ δὲ σύμπας τῶν ἐκείνης ἀπολομένων τῆς ἡμέρας ἀριθμὸς σὺν γυναιξὶν καὶ τέκνοις, οὐδὲ γὰρ νηπίων ἀπέσχοντο, περὶ τριάκοντα καὶ ἑξακοσίους συνήχθη. βαρυτέραν τε ἐποίει τὴν συμφορὰν τὸ καινὸν τῆς Ῥωμαίων ὠμότητος· ὃ γὰρ μηδεὶς πρότερον τότε Φλῶρος ἐτόλμησεν, ἄνδρας ἱππικοῦ τάγματος μαστιγῶσαί τε πρὸ τοῦ βήματος καὶ σταυρῷ προσηλῶσαι, ὧν εἰ καὶ τὸ γένος Ἰουδαίων ἀλλὰ γοῦν τὸ ἀξίωμα Ῥωμαϊκὸν ἦν.", "st": "2.14.9"}, {"sp": "N", "t": "Κατὰ τοῦτον τὸν καιρὸν ὁ μὲν βασιλεὺς Ἀγρίππας ἔτυχεν εἰς τὴν Ἀλεξάνδρειαν πεπορευμένος, ὅπως Ἀλεξάνδρῳ συνησθείη πεπιστευμένῳ τὴν Αἴγυπτον ὑπὸ Νέρωνος καὶ πεμφθέντι διέπειν. τὴν ἀδελφὴν δὲ αὐτοῦ Βερνίκην παροῦσαν ἐν Ἱεροσολύμοις καὶ τὴν παρανομίαν τῶν στρατιωτῶν θεωμένην δεινὸν εἰσῄει πάθος, καὶ πολλάκις τούς τε ἱππάρχους ἑαυτῆς καὶ σωματοφύλακας πέμπουσα πρὸς Φλῶρον ἐδέετο παύσασθαι τοῦ φόνου. καὶ ὁ μὲν οὔτε εἰς τὸ πλῆθος τῶν ἀναιρουμένων οὔτε εἰς τὴν εὐγένειαν τῆς παρακαλούσης, ἀλλ’ εἰς μόνον τὸ λυσιτελὲς τὸ ἐκ τῶν ἁρπαγῶν ἀποβλέπων παρήκουσεν. ἡ δ’ ὁρμὴ τῶν στρατιωτῶν ἐλύσσησεν καὶ κατὰ τῆς βασιλίδος· οὐ μόνον γοῦν ἐν ὄμμασιν αὐτῆς ᾐκίζοντο τοὺς ἁλισκομένους καὶ διέφθειρον, ἀλλὰ κἂν αὐτὴν ἀνεῖλον, εἰ μὴ καταφυγεῖν εἰς τὴν βασιλικὴν αὐλὴν ἔφθη, κἀκεῖ διενυκτέρευσεν μετὰ φυλακῆς δεδοικυῖα τὴν τῶν στρατιωτῶν ἔφοδον. ἐπεδήμει δ’ ἐν τοῖς Ἱεροσολύμοις εὐχὴν ἐκτελοῦσα τῷ θεῷ· τοὺς γὰρ ἢ νόσῳ καταπονουμένους ἤ τισιν ἄλλαις ἀνάγκαις ἔθος εὔχεσθαι πρὸ τριάκοντα ἡμερῶν ἧς ἀποδώσειν μέλλοιεν θυσίας οἴνου τε ἀφέξεσθαι καὶ ξυρήσεσθαι τὰς κόμας. ἃ δὴ καὶ τότε τελοῦσα Βερνίκη γυμνόπους τε πρὸ τοῦ βήματος ἱκέτευε τὸν Φλῶρον καὶ πρὸς τῷ μὴ τυχεῖν αἰδοῦς αὐτὴν τὸν περὶ τοῦ ζῆν κίνδυνον ἐπείρασεν.", "st": "2.15.1"}, {"sp": "N", "t": "Ταῦτα μὲν οὖν ἑξκαιδεκάτῃ μηνὸς Ἀρτεμισίου συνηνέχθη, τῇ δ’ ἐπιούσῃ τὸ μὲν πλῆθος ὑπερπαθῆσαν εἰς τὴν ἄνω συνέρρευσεν ἀγορὰν καὶ βοαῖς ἐξαισίοις περὶ τῶν ἀπολωλότων ἀνωδύρετο· τὸ πλέον δὲ ἦσαν εἰς τὸν Φλῶρον ἐπίφθονοι φωναί. πρὸς ὃ δείσαντες οἱ δυνατοὶ σὺν τοῖς ἀρχιερεῦσιν τὰς ἐσθῆτας περιερρήξαντο καὶ προσπίπτοντες ἕκαστος ἐδέοντο παύσασθαι καὶ μὴ πρὸς οἷς πεπόνθασιν εἰς ἀνήκεστόν τι τὸν Φλῶρον ἐρεθίζειν. ἐπείσθη δὲ τὸ πλῆθος ταχέως αἰδοῖ τε τῶν παρακαλούντων καὶ κατ’ ἐλπίδα τοῦ μηδὲν ἔτι τὸν Φλῶρον εἰς αὐτοὺς παρανομήσειν.", "st": "2.15.2"}, {"sp": "N", "t": "Ὁ δὲ σβεσθείσης τῆς ταραχῆς ἤχθετο καὶ πάλιν αὐτὴν ἀνάψαι πραγματευόμενος τούς τε ἀρχιερεῖς σὺν τοῖς γνωρίμοις μεταπέμπεται καὶ μόνον ἔφη τεκμήριον ἔσεσθαι τοῦ μηδὲν ἔτι τὸν δῆμον νεωτερίσειν, εἰ προελθόντες ὑπαντήσουσιν τοῖς ἀπὸ Καισαρείας ἀνιοῦσιν στρατιώταις· παρεγίνοντο δὲ δύο σπεῖραι. τῶν δ’ ἔτι συγκαλούντων τὸ πλῆθος προπέμψας διεδήλου τοῖς τῶν σπειρῶν ἑκατοντάρχοις, ὅπως παραγγείλωσιν τοῖς ὑφ’ ἑαυτοὺς μήτε ἀντασπάσασθαι τοὺς Ἰουδαίους κἄν τι κατ’ αὐτοῦ φθέγξωνται, χρήσασθαι τοῖς ὅπλοις. οἱ δ’ ἀρχιερεῖς εἰς τὸ ἱερὸν τὴν πληθὺν συναγαγόντες ὑπαντᾶν τοῖς Ῥωμαίοις παρεκάλουν καὶ πρὸ ἀνηκέστου πάθους τὰς σπείρας δεξιοῦσθαι. τούτοις τὸ στασιῶδες ἠπείθει, καὶ διὰ τοὺς ἀπολωλότας τὸ πλῆθος ἔρρεπεν πρὸς τοὺς θρασυτέρους.", "st": "2.15.3"}, {"sp": "N", "t": "Ἔνθα δὴ πᾶς μὲν ἱερεὺς πᾶς δ’ ὑπηρέτης τοῦ θεοῦ τὰ ἅγια σκεύη προκομίσαντες καὶ τὸν κόσμον, ἐν ᾧ λειτουργεῖν ἔθος ἦν αὐτοῖς, ἀναλαβόντες κιθαρισταί τε καὶ ὑμνῳδοὶ μετὰ τῶν ὀργάνων προσέπιπτον καὶ κατηντιβόλουν φυλάξαι τὸν ἱερὸν κόσμον αὐτοῖς καὶ μὴ πρὸς ἁρπαγὴν τῶν θείων κειμηλίων Ῥωμαίους ἐρεθίσαι. τοὺς δ’ ἀρχιερεῖς αὐτοὺς ἦν ἰδεῖν καταμωμένους μὲν τὴν κεφαλὴν κόνει, γυμνοὺς δὲ τὰ στέρνα τῶν ἐσθήτων διερρηγμένων. ὀνομαστὶ δ’ ἕκαστον τῶν γνωρίμων καὶ κοινῇ τὸ πλῆθος ἱκέτευον μὴ δι’ ἐλαχίστης πλημμελείας προδοῦναι τὴν πατρίδα τοῖς ἐπιθυμοῦσιν πορθῆσαι· τίνα γὰρ ἢ τοῖς στρατιώταις φέρειν ὠφέλειαν τὸν ἀπὸ Ἰουδαίων ἀσπασμὸν ἢ διόρθωσιν αὐτοῖς τῶν συμβεβηκότων τὸ μὴ νῦν προελθεῖν; εἰ δὲ δὴ δεξιώσαιντο τοὺς προσιόντας ὡς ἔθος, Φλώρῳ μὲν ἀποκοπήσεσθαι τὴν ἀφορμὴν τοῦ πολέμου, κερδήσειν δ’ αὐτοὺς τὴν πατρίδα καὶ τὸ μηδὲν παθεῖν πλέον. ἄλλως τε καὶ τὸ πείθεσθαι στασιάζουσιν ὀλίγοις, δέον αὐτοὺς δῆμον ὄντας τοσοῦτον συναναγκάζειν κἀκείνους συνευγνωμονεῖν, δεινῆς ἀκρασίας εἶναι.", "st": "2.15.4"}, {"sp": "N", "t": "Τούτοις μειλισσόμενοι τὸ πλῆθος ἅμα καὶ τῶν στασιαστῶν οὓς μὲν ἀπειλαῖς οὓς δὲ αἰδοῖ κατέστειλαν. ἔπειτα ἐξηγούμενοι μεθ’ ἡσυχίας τε καὶ κόσμου τοῖς στρατιώταις ὑπήντων καὶ πλησίον γενομένους ἠσπάσαντο· τῶν δὲ μηδὲν ἀποκριναμένων οἱ στασιασταὶ Φλώρου κατεβόων. τοῦτο ἦν σύνθημα κατ’ αὐτῶν δεδομένον· αὐτίκα γοῦν οἱ στρατιῶται περισχόντες αὐτοὺς ἔπαιον ξύλοις, καὶ φεύγοντας οἱ ἱππεῖς καταδιώκοντες συνεπάτουν. ἔπιπτον δὲ πολλοὶ μὲν ὑπὸ Ῥωμαίων τυπτόμενοι, πλείους δ’ ὑπ’ ἀλλήλων βιαζόμενοι. δεινὸς δὲ περὶ τὰς πύλας ὠθισμὸς ἦν, καὶ φθάνειν ἑκάστου σπεύδοντος βραδυτέρα μὲν ἡ φυγὴ πᾶσιν ἐγίνετο, τῶν δὲ σφαλέντων ἀπώλεια δεινή· πνιγόμενοι γὰρ καὶ κλώμενοι πλήθει τῶν ἐπιβαινόντων ἠφανίζοντο, καὶ οὐδὲ πρὸς ταφήν τις γνώριμος τοῖς ἰδίοις κατελείπετο. συνέπιπτον δὲ καὶ στρατιῶται παίοντες ἀνέδην τοὺς καταλαμβανομένους καὶ διὰ τῆς Βεθεζὰ καλουμένης ἀνεώθουν τὸ πλῆθος βιαζόμενοι παρελθεῖν καὶ κρατῆσαι τοῦ τε ἱεροῦ καὶ τῆς Ἀντωνίας· ὧν καὶ Φλῶρος ἐφιέμενος ἐξῆγε τῆς βασιλικῆς αὐλῆς τοὺς σὺν αὐτῷ καὶ πρὸς τὸ φρούριον ἐλθεῖν ἠγωνίζετο. διήμαρτέν γε μὴν τῆς ἐπιβολῆς· ὁ γὰρ δῆμος ἄντικρυς ἐπιστραφεὶς εἶργεν τῆς ὁρμῆς, καὶ διαστάντες ἐπὶ τῶν τεγῶν τοὺς Ῥωμαίους ἔβαλλον. καταπονούμενοι δὲ τοῖς ὕπερθεν βέλεσιν καὶ διακόψαι τὸ τοὺς στενωποὺς ἐμφράξαν πλῆθος ἀσθενήσαντες ἀνεχώρουν εἰς τὸ πρὸς τοῖς βασιλείοις στρατόπεδον.", "st": "2.15.5"}, {"sp": "N", "t": "Οἱ δὲ στασιασταὶ δείσαντες μὴ πάλιν ἐπελθὼν ὁ Φλῶρος κρατήσῃ τοῦ ἱεροῦ διὰ τῆς Ἀντωνίας, ἀναβάντες εὐθέως τὰς συνεχεῖς στοὰς τοῦ ἱεροῦ πρὸς τὴν Ἀντωνίαν διέκοψαν. τοῦτ’ ἔψυξεν τὴν Φλώρου πλεονεξίαν· τῶν γὰρ τοῦ θεοῦ θησαυρῶν ἐφιέμενος καὶ διὰ τοῦτο παρελθεῖν ἐπιθυμῶν εἰς τὴν Ἀντωνίαν, ὡς ἀπερράγησαν αἱ στοαί, τὴν ὁρμὴν ἀνετράπη, καὶ μεταπεμψάμενος τούς τε ἀρχιερεῖς καὶ τὴν βουλὴν αὐτὸς μὲν ἐξιέναι τῆς πόλεως ἔφη, φρουρὰν δ’ ἐγκαταλείψειν αὐτοῖς ὅσην ἂν ἀξιώσωσιν. τῶν δὲ πάντα περὶ ἀσφαλείας καὶ τοῦ μηδὲν νεωτερίσειν ὑποσχομένων, εἰ μίαν αὐτοῖς καταλείποι σπεῖραν, μὴ μέντοι τὴν μαχεσαμένην· πρὸς γὰρ ταύτην ἀπεχθῶς δι’ ἃ πέπονθεν ἔχειν τὸ πλῆθος· ἀλλάξας τὴν σπεῖραν, ὡς ἠξίουν, μετὰ τῆς λοιπῆς δυνάμεως ὑπέστρεψεν εἰς Καισάρειαν.", "st": "2.15.6"}, {"sp": "N", "t": "Ἑτέραν δὲ ἐπιβολὴν τῷ πολέμῳ ποριζόμενος ἐπέστελλεν Κεστίῳ Ἰουδαίων ἀπόστασιν καταψευδόμενος τήν τε ἀρχὴν τῆς μάχης περιθεὶς αὐτοῖς καὶ δρᾶσαι λέγων ἐκείνους ἃ πεπόνθεσαν. οὐ μὴν οὐδ’ οἱ τῶν Ἱεροσολύμων ἄρχοντες ἐσίγησαν, ἀλλ’ αὐτοί τε καὶ Βερνίκη τῷ Κεστίῳ περὶ ὧν Φλῶρος εἰς τὴν πόλιν παρηνόμησεν ἔγραφον. ὁ δὲ τὰ παρ’ ἀμφοῖν ἀναγνοὺς μετὰ τῶν ἡγεμόνων ἐβουλεύετο. τοῖς μὲν οὖν αὐτὸν ἐδόκει Κέστιον μετὰ στρατιᾶς ἀναβαίνειν ἢ τιμωρησόμενον τὴν ἀπόστασιν, εἰ γέγονεν, ἢ βεβαιοτέρους καταστήσοντα Ἰουδαίους καὶ συμμένοντας, αὐτῷ δὲ προπέμψαι τῶν ἑταίρων τὸν κατασκεψόμενον τὰ πράγματα καὶ τὰ φρονήματα τῶν Ἰουδαίων πιστῶς ἀναγγελοῦντα. πέμπει δή τινα τῶν χιλιάρχων Νεαπολιτανόν, ὃς ἀπὸ τῆς Ἀλεξανδρείας ὑποστρέφοντι περιτυχὼν Ἀγρίππᾳ τῷ βασιλεῖ κατὰ Ἰάμνειαν τόν τε πέμψαντα καὶ τὰς αἰτίας ἐδήλωσεν.", "st": "2.16.1"}, {"sp": "N", "t": "Ἔνθα καὶ Ἰουδαίων οἵ τε ἀρχιερεῖς ἅμα τοῖς δυνατοῖς καὶ ἡ βουλὴ παρῆν δεξιουμένη τὸν βασιλέα. μετὰ δὲ τὴν εἰς ἐκεῖνον θεραπείαν ἀπωδύροντο τὰς ἑαυτῶν συμφορὰς καὶ τὴν Φλώρου διεξῄεσαν ὠμότητα. πρὸς ἣν ἠγανάκτει μὲν Ἀγρίππας, στρατηγικῶς δὲ τὴν ὀργὴν εἰς οὓς ἠλέει Ἰουδαίους μετέφερεν, ταπεινοῦν αὐτῶν βουλόμενος τὰ φρονήματα καὶ τῷ μὴ δοκεῖν ἀδίκως τι παθεῖν τῆς ἀμύνης ἀποτρέπων. οἱ μὲν οὖν, ὡς ἂν ὄντες ἔκκριτοι καὶ διὰ τὰς ἑαυτῶν κτήσεις ἐπιθυμοῦντες εἰρήνης, συνίεσαν εὐνοϊκὴν τὴν ἐπίπληξιν τοῦ βασιλέως· ὁ δὲ δῆμος ἐκ τῶν Ἱεροσολύμων ἐπὶ ἑξήκοντα προελθὼν σταδίους ἐδεξιοῦτο τὸν Ἀγρίππαν καὶ τὸν Νεαπολιτανόν. ἐκώκυον δὲ καὶ τῶν ἀπεσφαγμένων αἱ γυναῖκες προεκθέουσαι, καὶ πρὸς τὴν τούτων οἰμωγὴν ὁ δῆμος εἰς ὀλοφυρμοὺς τραπόμενος ἐπικουρεῖν τὸν Ἀγρίππαν ἱκέτευεν, τοῦ τε Νεαπολιτανοῦ κατεβόων ὅσα πάθοιεν ὑπὸ Φλώρου καὶ παρελθοῦσιν εἰς τὴν πόλιν τήν τε ἀγορὰν ἠρημωμένην ἐπεδείκνυσαν καὶ πεπορθημένας τὰς οἰκίας. ἔπειτα δι’ Ἀγρίππα πείθουσι τὸν Νεαπολιτανὸν σὺν ἑνὶ θεράποντι περιελθεῖν μέχρι τοῦ Σιλωᾶ τὴν πόλιν, ἵνα γνῷ Ἰουδαίους τοῖς μὲν ἄλλοις Ῥωμαίοις ἅπασιν εἴκοντας, μόνῳ δ’ ἀπεχθανομένους Φλώρῳ δι’ ὑπερβολὴν τῆς εἰς αὐτοὺς ὠμότητος. ὁ δὲ ὡς διοδεύσας πεῖραν ἱκανὴν ἔλαβεν τῆς πραότητος αὐτῶν, εἰς τὸ ἱερὸν ἀναβαίνει. ἔνθα συγκαλέσας τὸ πλῆθος, καὶ πολλὰ μὲν εἰς πίστιν αὐτοὺς τὴν πρὸς Ῥωμαίους ἐπαινέσας, πολλὰ δὲ εἰς τὸ τηρεῖν τὴν εἰρήνην προτρεψάμενος καὶ τοῦ θεοῦ προσκυνήσας ὅθεν ἐξῆν τὰ ἅγια πρὸς Κέστιον ἐπανῄει.", "st": "2.16.2"}, {"sp": "N", "t": "Τὸ δὲ πλῆθος τῶν Ἰουδαίων ἐπί τε τὸν βασιλέα καὶ τοὺς ἀρχιερεῖς τραπόμενον πέμπειν κατὰ Φλώρου πρέσβεις ἠξίου πρὸς Νέρωνα καὶ μὴ σιωπῶντας ἐπὶ τοσούτῳ φόνῳ καταλιπεῖν ἑαυτοῖς ὑπόνοιαν ἀποστάσεως· δόξειν γὰρ αὐτοὶ κατάρξαι τῶν ὅπλων, εἰ μὴ φθάσαντες ἐνδείξαιντο τὸν κατάρξαντα· φανεροὶ δ’ ἦσαν οὐκ ἠρεμήσοντες, εἰ τὴν πρεσβείαν τις ἀποκωλύει. Ἀγρίππᾳ δὲ τὸ μὲν χειροτονεῖν Φλώρου κατηγόρους ἐπίφθονον, τὸ περιιδεῖν δὲ Ἰουδαίους εἰς πόλεμον ἐκριπισθέντας οὐδὲ αὐτῷ λυσιτελὲς κατεφαίνετο. προσκαλεσάμενος δὲ εἰς τὸν ξυστὸν τὸ πλῆθος καὶ παραστησάμενος ἐν περιόπτῳ τὴν ἀδελφὴν Βερνίκην ἐπὶ τῆς Ἀσαμωναίων οἰκίας, αὕτη γὰρ ἦν ἐπάνω τοῦ ξυστοῦ πρὸς τὸ πέραν τῆς ἄνω πόλεως, καὶ γέφυρα τῷ ξυστῷ τὸ ἱερὸν συνῆπτεν, Ἀγρίππας ἔλεξεν τοιάδε.", "st": "2.16.3"}, {"sp": "N", "t": "Εἰ μὲν ἑώρων πάντας ὑμᾶς πολεμεῖν Ῥωμαίοις ὡρμημένους καὶ μὴ τοῦ δήμου τὸ καθαρώτατον καὶ εἰλικρινέστατον εἰρήνην ἄγειν προῃρημένους, οὔτ’ ἂν παρῆλθον εἰς ὑμᾶς οὔτε συμβουλεύειν ἐθάρρησα· περισσὸς γὰρ ὑπὲρ τοῦ τὰ δέοντα ποιεῖν πᾶς λόγος, ὅταν ᾖ τῶν ἀκουόντων πάντων [ἡ] πρὸς τὸ χεῖρον ὁμόνοια. ἐπεὶ δὲ τινὰς μὲν ἡλικία τῶν ἐν πολέμῳ κακῶν ἄπειρος, τινὰς δὲ ἐλπὶς ἀλόγιστος ἐλευθερίας, ἐνίους δὲ πλεονεξία τις παροξύνει καὶ τὸ παρὰ τῶν ἀσθενεστέρων, ἐὰν τὰ πράγματα συγχυθῇ, κέρδος, ὅπως αὐτοί τε σωφρονισθέντες μεταβάλωνται καὶ μὴ τῆς ἐνίων κακοβουλίας οἱ ἀγαθοὶ παραπολαύσωσιν, ᾠήθην δεῖν ἐπὶ τὸ αὐτὸ πάντας ὑμᾶς συναγαγὼν εἰπεῖν ἃ νομίζω συμφέρειν. θορυβήσῃ δέ μοι μηδείς, ἐὰν μὴ τὰ πρὸς ἡδονὴν ἀκούῃ· τοῖς μὲν γὰρ ἀνηκέστως ἐπὶ τὴν ἀπόστασιν ὡρμημένοις ἔνεστι καὶ μετὰ τὴν ἐμὴν παραίνεσιν ταῦτα φρονεῖν, ἐμοὶ δὲ διαπίπτει καὶ πρὸς τοὺς ἀκούειν ἐθέλοντας ὁ λόγος, ἐὰν μὴ παρὰ πάντων ἡσυχία γένηται. οἶδα μὲν οὖν ὅτι πολλοὶ τὰς ἐκ τῶν ἐπιτρόπων ὕβρεις καὶ τὰ τῆς ἐλευθερίας ἐγκώμια τραγῳδοῦσιν, ἐγὼ δὲ πρὶν ἐξετάζειν τίνες ὄντες καὶ τίσιν ἐπιχειρεῖτε πολεμεῖν, πρῶτον διαζεύξω τὴν συμπλοκὴν τῶν προφάσεων. εἰ μὲν γὰρ ἀμύνεσθε τοὺς ἀδικοῦντας, τί σεμνύνετε τὴν ἐλευθερίαν; εἰ δὲ τὸ δουλεύειν ἀφόρητον ἡγεῖσθε, περισσὴ πρὸς τοὺς ἡγεμόνας ἡ μέμψις· καὶ γὰρ ἐκείνων μετριαζόντων αἰσχρὸν ὁμοίως τὸ δουλεύειν. σκοπεῖτε δὲ καὶ καθ’ ἕκαστον τούτων ὡς ἔστιν μικρὰ τοῦ πολεμεῖν ἡ ὑπόθεσις, καὶ πρῶτά γε τὰ τῶν ἐπιτρόπων ἐγκλήματα· θεραπεύειν γάρ, οὐκ ἐρεθίζειν χρὴ τὰς ἐξουσίας· ὅταν δὲ τῶν μικρῶν ἁμαρτημάτων τοὺς ἐξονειδισμοὺς ποιῆσθε μεγάλους, καθ’ ἑαυτῶν τοὺς ὀνειδιζομένους ἀπελέγχετε, καὶ παρέντες τὸ λάθρα καὶ μετ’ αἰδοῦς ὑμᾶς βλάπτειν πορθοῦσι φανερῶς. οὐδὲν δὲ οὕτως τὰς πληγὰς ὡς τὸ φέρειν ἀναστέλλει, καὶ τὸ τῶν ἀδικουμένων ἡσύχιον τοῖς ἀδικοῦσι γίνεται διατροπή. φέρε δ’ εἶναι τοὺς Ῥωμαίων ὑπηρέτας ἀνηκέστως χαλεπούς· οὔπω Ῥωμαῖοι πάντες ἀδικοῦσιν ὑμᾶς οὐδὲ Καῖσαρ, πρὸς οὓς αἱρεῖσθε τὸν πόλεμον· οὐδὲ γὰρ ἐξ ἐντολῆς ἥκει τις πονηρὸς ἀπ’ ἐκείνων, οὐδέ γε τοὺς ὑπὸ τὴν ἀνατολὴν οἱ ἀφ’ ἑσπέρας ἐπιβλέπουσιν· ἀλλ’ οὐδὲ ἀκούειν ταχέως τὰ ἐντεῦθεν ἐκεῖ ῥᾴδιον. ἄτοπον δὲ καὶ δι’ ἕνα πολλοῖς καὶ διὰ μικρὰς αἰτίας τηλικούτοις καὶ μηδὲ γινώσκουσιν ἃ μεμφόμεθα πολεμεῖν. καὶ τῶν μὲν ἡμετέρων ἐγκλημάτων ταχεῖα γένοιτ’ ἂν διόρθωσις· οὔτε γὰρ ὁ αὐτὸς ἐπίτροπος μένει διὰ παντός, καὶ τοὺς διαδεξομένους εἰκὸς ἐλεύσεσθαι μετριωτέρους· κινηθέντα δ’ ἅπαξ τὸν πόλεμον οὔτε ἀποθέσθαι ῥᾴδιον δίχα συμφορῶν οὔτε βαστάζειν. ἀλλὰ μὴν τό γε νῦν ἐλευθερίας ἐπιθυμεῖν ἄωρον, δέον ὑπὲρ τοῦ μηδὲ ἀποβαλεῖν αὐτὴν ἀγωνίζεσθαι πρότερον· ἡ γὰρ πεῖρα τῆς δουλείας χαλεπή, καὶ περὶ τοῦ μηδ’ ἄρξασθαι ταύτης ὁ ἀγὼν δίκαιος. ὁ δ’ ἅπαξ χειρωθείς, ἔπειτα ἀφιστάμενος, αὐθάδης δοῦλός ἐστιν, οὐ φιλελεύθερος. τότε τοιγαροῦν ἐχρῆν πάνθ’ ὑπὲρ τοῦ μὴ δέξασθαι Ῥωμαίους ποιεῖν, ὅτε ἐπέβαινεν τῆς χώρας Πομπήιος. ἀλλ’ οἱ μὲν ἡμέτεροι πρόγονοι καὶ οἱ βασιλεῖς αὐτῶν καὶ χρήμασιν καὶ σώμασιν καὶ ψυχαῖς ἄμεινον ὑμῶν πολλῷ διακείμενοι πρὸς μοῖραν ὀλίγην τῆς Ῥωμαίων δυνάμεως οὐκ ἀντέσχον· ὑμεῖς δὲ οἱ τὸ μὲν ὑπακούειν ἐκ διαδοχῆς παρειληφότες, τοῖς πράγμασιν δὲ τῶν πρώτων ὑπακουσάντων τοσοῦτον ἐλαττούμενοι, πρὸς ὅλην ἀνθίστασθε τὴν Ῥωμαίων ἡγεμονίαν; καὶ Ἀθηναῖοι μὲν οἱ περὶ τῆς τῶν Ἑλλήνων ἐλευθερίας παραδόντες ποτὲ καὶ πυρὶ τὴν πόλιν, οἱ τὸν ὑπερήφανον Ξέρξην διὰ γῆς πλεύσαντα καὶ διὰ θαλάσσης ὁδεύσαντα καὶ μὴ χωρούμενον μὲν τοῖς πελάγεσιν, πλατυτέραν δὲ τῆς Εὐρώπης τὴν στρατιὰν ἄγοντα, οἷα δραπέτην ἐπὶ μιᾶς νηὸς διώξαντες, περὶ δὲ τῇ μικρᾷ Σαλαμῖνι τὴν τοσαύτην Ἀσίαν κλάσαντες νῦν δουλεύουσιν Ῥωμαίοις, καὶ τὴν ἡγεμονίδα τῆς Ἑλλάδος πόλιν διοικεῖ τὰ ἀπὸ τῆς Ἰταλίας προστάγματα. Λακεδαιμόνιοι δὲ μετὰ Θερμοπύλας καὶ Πλαταιὰς καὶ τὸν ἐρευνήσαντα τὴν Ἀσίαν Ἀγησίλαον ἀγαπῶσιν τοὺς αὐτοὺς δεσπότας, καὶ Μακεδόνες ἔτι φανταζόμενοι Φίλιππον καὶ τὴν σὺν Ἀλεξάνδρῳ παρασπείρουσαν αὐτοῖς τὴν τῆς οἰκουμένης ἡγεμονίαν ὁρῶντες, φέρουσιν τὴν τοσαύτην μεταβολὴν καὶ πρὸς οὓς μεταβέβηκεν ἡ τύχη προσκυνοῦσιν. ἄλλα τε ἔθνη μυρία πλείονος γέμοντα πρὸς ἐλευθερίαν παρρησίας εἴκει· μόνοι δ’ ὑμεῖς ἀδοξεῖτε δουλεύειν οἷς ὑποτέτακται τὰ πάντα. ποίᾳ στρατιᾷ ποίοις πεποιθότες ὅπλοις; ποῦ μὲν ὁ στόλος ὑμῖν διαληψόμενος τὰς Ῥωμαίων θαλάσσας; ποῦ δ’ οἱ ταῖς ἐπιβολαῖς ἐξαρκέσοντες θησαυροί; πρὸς Αἰγυπτίους ἄρα καὶ πρὸς Ἄραβας οἴεσθε κινεῖν τὸν πόλεμον; οὐ περισκέψεσθε τὴν Ῥωμαίων ἡγεμονίαν; οὐ μετρήσετε τὴν ἑαυτῶν ἀσθένειαν; οὐ τὰ μὲν ἡμέτερα καὶ τῶν προσοίκων ἐθνῶν ἡττήθη πολλάκις, ἡ δὲ ἐκείνων ἰσχὺς διὰ τῆς οἰκουμένης ἀνίκητος; μᾶλλον δὲ καὶ ταύτης ἐζήτησάν τι πλέον· οὐ γὰρ ἐξήρκεσεν αὐτοῖς ὅλος Εὐφράτης ὑπὸ τὴν ἀνατολὴν οὐδὲ τῶν προσαρκτίων ὁ Ἴστρος ἥ τε μεσημβρινὴ μέχρι τῶν ἀοικήτων ἐρευνηθεῖσα Λιβύη καὶ Γάδειρα πρὸς ἑσπέραν, ἀλλ’ ὑπὲρ ὠκεανὸν ἑτέραν ἐζήτησαν οἰκουμένην καὶ μέχρι τῶν ἀνιστορήτων πρότερον Βρεττανῶν διήνεγκαν τὰ ὅπλα. τί οὖν; ὑμεῖς πλουσιώτεροι Γαλατῶν, ἰσχυρότεροι Γερμανῶν, Ἑλλήνων συνετώτεροι, πλείους τῶν κατὰ τὴν οἰκουμένην ἐστὲ πάντων; τί τὸ πεποιθὸς ὑμᾶς κατὰ Ῥωμαίων ἐπαίρει; χαλεπὸν τὸ δουλεύειν, ἐρεῖ τις. πόσῳ μᾶλλον Ἕλλησιν, οἳ τῶν ὑφ’ ἡλίῳ πάντων προύχοντες εὐγενείᾳ καὶ τοσαύτην νεμόμενοι χώραν ἓξ Ῥωμαίων ὑπείκουσιν ῥάβδοις, τοσαύταις δὲ καὶ Μακεδόνες οἱ δικαιότερον ὑμῶν ὀφείλοντες ἐλευθερίας ἀντιποιεῖσθαι. τί δ’ αἱ πεντακόσιαι τῆς Ἀσίας πόλεις; οὐ δίχα φρουρᾶς ἕνα προσκυνοῦσιν ἡγεμόνα καὶ τὰς ὑπατικὰς ῥάβδους; τί χρὴ λέγειν Ἡνιόχους τε καὶ Κόλχους καὶ τὸ τῶν Ταύρων φῦλον, Βοσπορανούς τε καὶ τὰ περίοικα τοῦ Πόντου καὶ τῆς Μαιώτιδος ἔθνη; παρ’ οἷς πρὶν μὲν οὐδ’ οἰκεῖος ἐγιγνώσκετο δεσπότης, νῦν δὲ τρισχιλίοις ὁπλίταις ὑποτάσσεται, καὶ τεσσαράκοντα ναῦς μακραὶ τὴν πρὶν ἄπλωτον καὶ ἀγρίαν εἰρηνεύουσι θάλασσαν. πόσα Βιθυνία καὶ Καππαδοκία καὶ τὸ Παμφύλιον ἔθνος Λύκιοί τε καὶ Κίλικες ὑπὲρ ἐλευθερίας ἔχοντες εἰπεῖν χωρὶς ὅπλων φορολογοῦνται; τί δαί; Θρᾷκες οἱ πέντε μὲν εὖρος ἑπτὰ δὲ μῆκος ἡμερῶν χώραν διειληφότες, τραχυτέραν τε καὶ πολλῷ τῆς ὑμετέρας ὀχυρωτέραν καὶ βαθεῖ κρυμῷ τοὺς ἐπιστρατεύσοντας ἀνακόπτουσαν, οὐχὶ δισχιλίοις Ῥωμαίων ὑπακούουσιν φρουροῖς; οἱ δ’ ἀπὸ τούτων Ἰλλυριοὶ τὴν μέχρι Δαλματίας ἀποτεμνομένην Ἴστρῳ κατοικοῦντες, οὐ δυσὶν μόνοις τάγμασιν ὑπείκουσιν, μεθ’ ὧν αὐτοὶ τὰς Δακῶν ἀνακόπτουσιν ὁρμάς; οἱ δὲ τοσαυτάκις πρὸς ἐλευθερίαν ἀναχαιτίσαντες Δαλμάται καὶ πρὸς τὸ μόνον ἀεὶ χειρωθέντες τότε συλλεξάμενοι τὴν ἰσχὺν πάλιν ἀποστῆναι, νῦν οὐχ ὑφ’ ἑνὶ τάγματι Ῥωμαίων ἡσυχίαν ἄγουσιν; ἀλλὰ μὴν εἴ γέ τινας εἰς ἀπόστασιν ὤφειλον ἀφορμαὶ μεγάλαι παροξύνειν, μάλιστα Γαλάτας ἐχρῆν τοὺς οὕτως ὑπὸ τῆς φύσεως τετειχισμένους, ἐξ ἀνατολῆς μὲν ταῖς Ἄλπεσιν πρὸς ἄρκτῳ δὲ Ῥήνῳ ποταμῷ, μεσημβρινοῖς δὲ τοῖς Πυρηναίοις ὄρεσιν, ὠκεανῷ δὲ πρὸς δυσμῶν. ἀλλὰ καίτοι τηλικαῦτα μὲν ἕρκη περιβεβλημένοι, πέντε δὲ καὶ τριακοσίοις πληθύοντες ἔθνεσιν, τὰς δὲ πηγάς, ὡς ἄν τις εἴποι, τῆς εὐδαιμονίας ἐπιχωρίους ἔχοντες καὶ τοῖς ἀγαθοῖς σχεδὸν ὅλην ἐπικλύζοντες τὴν οἰκουμένην, ἀνέχονται Ῥωμαίων πρόσοδος ὄντες καὶ ταμιευόμενοι παρ’ αὐτῶν τὴν οἰκείαν εὐδαιμονίαν. καὶ τοῦθ’ ὑπομένουσιν οὐ διὰ φρονημάτων μαλακίαν οὐδὲ δι’ ἀγένειαν, οἵ γε διήνεγκαν ὀγδοήκοντα ἔτη πόλεμον ὑπὲρ τῆς ἐλευθερίας, ἀλλὰ μετὰ τῆς δυνάμεως Ῥωμαίων καὶ τὴν τύχην καταπλαγέντες, ἥτις αὐτοῖς κατορθοῖ πλείονα τῶν ὅπλων. τοιγαροῦν ὑπὸ χιλίοις καὶ διακοσίοις στρατιώταις δουλεύουσιν, ὧν ὀλίγου δεῖν πλείους ἔχουσι πόλεις. οὐδὲ Ἴβηρσιν ὁ γεωργούμενος χρυσὸς εἰς τὸν ὑπὲρ τῆς ἐλευθερίας ἐξήρκεσεν πόλεμον οὐδὲ τὸ τοσοῦτον ἀπὸ Ῥωμαίων γῆς καὶ θαλάσσης διάστημα φῦλά τε Λουσιτανῶν καὶ Καντάβρων ἀρειμάνια οὐδὲ γείτων ὠκεανὸς φοβερὰν καὶ τοῖς ἐπιχωρίοις ἄμπωτιν ἐπάγων, ἀλλ’ ὑπὲρ τὰς Ἡρακλείους στήλας ἐκτείναντες τὰ ὅπλα καὶ διὰ νεφῶν ὁδεύσαντες τὰ Πυρηναῖα ὄρη καὶ τούτους ἐδουλώσαντο Ῥωμαῖοι· φρουρὰ δ’ ἤρκεσεν τῶν οὕτως δυσμάχων καὶ τοσοῦτον ἀπῳκισμένων ἓν τάγμα. τίς ὑμῶν οὐκ ἀκοῇ παρείληφεν τὸ Γερμανῶν πλῆθος; ἀλκὴν μὲν γὰρ καὶ μεγέθη σωμάτων εἴδετε δήπου πολλάκις, ἐπεὶ πανταχοῦ Ῥωμαῖοι τοὺς τούτων αἰχμαλώτους ἔχουσιν. ἀλλ’ οὗτοι γῆν μὲν ἄπειρον νεμόμενοι, μείζω δὲ τῶν σωμάτων ἔχοντες τὰ φρονήματα καὶ τὴν μὲν ψυχὴν θανάτου καταφρονοῦσαν, τοὺς δὲ θυμοὺς τῶν ἀγριωτάτων θηρίων σφοδροτέρους, Ῥῆνον τῆς ὁρμῆς ὅρον ἔχουσιν καὶ Ῥωμαίων ὀκτὼ τάγμασιν δαμαζόμενοι δουλεύουσιν μὲν ἁλόντες, τὸ δ’ ὅλον αὐτῶν ἔθνος φυγῇ διασώζεται.", "st": "2.16.4"}, {"sp": "N", "t": "σκέψασθε δὲ καὶ τὸ Βρεττανῶν τεῖχος οἱ τοῖς Ἱεροσολύμων τείχεσιν πεποιθότες· καὶ γὰρ ἐκείνους περιβεβλημένους ὠκεανὸν καὶ τῆς καθ’ ἡμᾶς οἰκουμένης οὐκ ἐλάσσονα νῆσον οἰκοῦντας πλεύσαντες ἐδουλώσαντο Ῥωμαῖοι, τέσσαρα δὲ τάγματα τὴν τοσαύτην νῆσον φυλάσσει. καὶ τί δεῖ πολλὰ λέγειν, ὅπου καὶ Πάρθοι, τὸ πολεμικώτατον φῦλον, τοσούτων ἄρχοντες ἐθνῶν καὶ τηλικαύτην περιβεβλημένοι δύναμιν ὁμήρους πέμπουσιν Ῥωμαίοις, καὶ ἔστιν ἐπὶ τῆς Ἰταλίας ἰδεῖν ἐν εἰρήνης προφάσει δουλεύουσαν τὴν ἀπὸ τῆς ἀνατολῆς εὐγένειαν. πάντων δὴ σχεδὸν τῶν ὑφ’ ἡλίῳ τὰ Ῥωμαίων ὅπλα προσκυνούντων ὑμεῖς μόνοι πολεμήσετε μηδὲ τὸ Καρχηδονίων τέλος σκοποῦντες, οἳ τὸν μέγαν αὐχοῦντες Ἀννίβαν καὶ τὴν ἀπὸ Φοινίκων εὐγένειαν ὑπὸ τὴν Σκιπίωνος δεξιὰν ἔπεσον; οὔτε δὲ Κυρηναῖοι, τὸ Λακώνων γένος, οὔτε Μαρμαρίδαι, τὸ μέχρι τῆς διψάδος ἐκτεταμένον φῦλον, οὔθ’ αἱ φοβεραὶ καὶ τοῖς ἀκούουσιν Σύρτεις Νασαμῶνές τε καὶ Μαῦροι καὶ τὸ Νομάδων ἄπειρον πλῆθος τὰς Ῥωμαίων ἀνέκοψαν ἀρετάς. τὴν δὲ τρίτην τῆς οἰκουμένης μοῖραν, ἧς οὐδὲ ἐξαριθμήσασθαι τὰ ἔθνη ῥᾴδιον, ὁριζομένην Ἀτλαντικῷ τε πελάγει καὶ στήλαις Ἡρακλείοις καὶ μέχρι τῆς Ἐρυθρᾶς θαλάσσης τοὺς ἀπείρους νέμουσαν Αἰθίοπας ἐχειρώσαντο μὲν ὅλην, χωρὶς δὲ τῶν ἐτησίων καρπῶν, οἳ μησὶν ὀκτὼ τὸ κατὰ τὴν Ῥώμην πλῆθος τρέφουσιν, καὶ ἔξωθεν παντοίως φορολογοῦνται καὶ ταῖς χρείαις τῆς ἡγεμονίας παρέχουσιν ἑτοίμους τὰς εἰσφοράς, οὐδὲν τῶν ἐπιταγμάτων ὥσπερ ὑμεῖς ὕβριν ἡγούμενοι καίπερ ἑνὸς τάγματος αὐτοῖς παραμένοντος. καὶ τί δεῖ πόρρωθεν ὑμῖν τὴν Ῥωμαίων ὑποδεικνύναι δύναμιν παρὸν ἐξ Αἰγύπτου τῆς γειτνιώσης, ἥτις ἐκτεινομένη μέχρις Αἰθιόπων καὶ τῆς εὐδαίμονος Ἀραβίας ὅρμος τε οὖσα τῆς Ἰνδικῆς, πεντήκοντα πρὸς ταῖς ἑπτακοσίαις ἔχουσα μυριάδας ἀνθρώπων δίχα τῶν Ἀλεξάνδρειαν κατοικούντων, ὡς ἔνεστιν ἐκ τῆς καθ’ ἑκάστην κεφαλὴν εἰσφορᾶς τεκμήρασθαι, τὴν Ῥωμαίων ἡγεμονίαν οὐκ ἀδοξεῖ, καίτοι πηλίκον ἀποστάσεως κέντρον ἔχουσα τὴν Ἀλεξάνδρειαν πλήθους τε ἀνδρῶν ἕνεκα καὶ πλούτου πρὸς δὲ μεγέθους· μῆκος μέν γε αὐτῆς τριάκοντα σταδίων, εὖρος δ’ οὐκ ἔλαττον δέκα, τοῦ δὲ ἐνιαυσιαίου παρ’ ὑμῶν φόρου καθ’ ἕνα μῆνα πλέον Ῥωμαίοις παρέχει καὶ τῶν χρημάτων ἔξωθεν τῇ Ῥώμῃ σῖτον μηνῶν τεσσάρων· τετείχισται δὲ πάντοθεν ἢ δυσβάτοις ἐρημίαις ἢ θαλάσσαις ἀλιμένοις ἢ ποταμοῖς ἢ ἕλεσιν. ἀλλ’ οὐδὲν τούτων ἰσχυρότερον εὑρέθη τῆς Ῥωμαίων τύχης, δύο δ’ ἐγκαθήμενα τῇ πόλει τάγματα τὴν βαθεῖαν Αἴγυπτον ἅμα τῇ Μακεδόνων εὐγενείᾳ χαλινοῖ. τίνας οὖν ἐπὶ τὸν πόλεμον ἐκ τῆς ἀοικήτου παραλήψεσθε συμμάχους; οἱ μὲν γὰρ ἐπὶ τῆς οἰκουμένης πάντες εἰσὶν Ῥωμαῖοι, εἰ μή τις ὑπὲρ Εὐφράτην ἐκτείνει τὰς ἐλπίδας καὶ τοὺς ἐκ τῆς Ἀδιαβηνῆς ὁμοφύλους οἴεται προσαμυνεῖν, οἱ δ’ οὔτε δι’ αἰτίαν ἄλογον τηλικούτῳ πολέμῳ συνεμπλέξουσιν ἑαυτούς, οὔτε βουλευσαμένοις κακῶς ὁ Πάρθος ἐπιτρέψει· πρόνοια γὰρ αὐτῷ τῆς πρὸς Ῥωμαίους ἐκεχειρίας, καὶ παραβαίνειν οἰήσεται τὰς σπονδάς, ἄν τις τῶν ὑπ’ αὐτὸν ἐπὶ Ῥωμαίους ἴῃ. λοιπὸν οὖν ἐπὶ τὴν τοῦ θεοῦ συμμαχίαν καταφευκτέον. ἀλλὰ καὶ τοῦτο παρὰ Ῥωμαίοις τέτακται· δίχα γὰρ θεοῦ συστῆναι τηλικαύτην ἡγεμονίαν ἀδύνατον. σκέψασθε δ’ ὡς ὑμῖν τὸ τῆς θρησκείας ἄκρατον, εἰ καὶ πρὸς εὐχειρώτους πολεμοίητε, δυσδιοίκητον, καὶ δι’ ἃ μᾶλλον τὸν θεὸν ἐλπίζετε σύμμαχον, ταῦτ’ ἀναγκαζόμενοι παραβαίνειν ἀποστρέψετε. τηροῦντές γε μὴν τὰ τῶν ἑβδομάδων ἔθη καὶ πρὸς μηδεμίαν πρᾶξιν κινούμενοι ῥᾳδίως ἁλώσεσθε, καθάπερ οἱ πρόγονοι Πομπηίῳ ταύτας μάλιστα τὰς ἡμέρας ἐνεργοὺς ποιησαμένῳ τῆς πολιορκίας, ἐν αἷς ἤργουν οἱ πολιορκούμενοι· παραβαίνοντες δὲ ἐν τῷ πολέμῳ τὸν πάτριον νόμον οὐκ οἶδ’ ὑπὲρ ὅτου λοιπὸν ποιήσεσθε τὸν ἀγῶνα· σπουδὴ γὰρ ὑμῖν μία τὸ μὴ τῶν πατρίων τι καταλῦσαι. πῶς δὲ ἐπικαλέσεσθε τὸ θεῖον πρὸς τὴν ἄμυναν οἱ παραβάντες ἑκουσίως τὴν εἰς αὐτὸ θεραπείαν; ἐπαναιροῦνται δὲ ἕκαστοι πόλεμον ἢ θείᾳ πεποιθότες ἢ ἀνθρωπίνῃ βοηθείᾳ· ὅταν δὲ τὴν παρ’ ἀμφοῖν τὸ εἰκὸς ἀποκόπτῃ, φανερὰν ἅλωσιν οἱ πολεμοῦντες αἱροῦνται. τί δὴ κωλύει ταῖς ἑαυτῶν χερσὶν διαχρήσασθαι τέκνα καὶ γυναῖκας καὶ τὴν περικαλλεστάτην πατρίδα ταύτην καταφλέξαι; μανέντες γὰρ οὕτως τό γε τῆς ἥττης ὄνειδος κερδήσετε. καλόν, ὦ φίλοι, καλόν, ἕως ἔτι ἐν ὅρμῳ τὸ σκάφος προσκέπτεσθαι τὸν μέλλοντα χειμῶνα μηδ’ εἰς μέσας τὰς θυέλλας ἀπολουμένους ἀναχθῆναι· τοῖς μὲν γὰρ ἐξ ἀδήλων ἐπιπεσοῦσιν δεινοῖς τὸ γοῦν ἐλεεῖσθαι περίεστιν, ὁ δ’ εἰς πρόδηλον ἀπώλειαν ὁρμήσας καὶ προσονειδίζεται. πλὴν εἰ μή τις ὑπολαμβάνει κατὰ συνθήκας πολεμήσειν καὶ Ῥωμαίους κρατήσαντας ὑμῶν μετριάσειν, ἀλλ’ οὐκ εἰς ὑπόδειγμα τῶν ἄλλων ἐθνῶν καταφλέξειν μὲν τὴν ἱερὰν πόλιν, ἀναιρήσειν δὲ πᾶν ὑμῶν τὸ φῦλον· οὐδὲ γὰρ περιλειφθέντες φυγῆς εὑρήσετε τόπον ἁπάντων ἐχόντων Ῥωμαίους δεσπότας ἢ δεδοικότων σχεῖν. ὁ δὲ κίνδυνος οὐ τῶν ἐνθάδε μόνον, ἀλλὰ καὶ τῶν κατὰ τὰς ἄλλας κατοικούντων πόλεις· οὐ γὰρ ἔστιν ἐπὶ τῆς οἰκουμένης δῆμος ὁ μὴ μοῖραν ἡμετέραν ἔχων. οὓς ἅπαντας πολεμησάντων ὑμῶν κατασφάξουσιν οἱ διάφοροι, καὶ δι’ ὀλίγων ἀνδρῶν κακοβουλίαν πᾶσα πλησθήσεται πόλις Ἰουδαϊκοῦ φόνου. καὶ συγγνώμη μὲν τοῖς τοῦτο πράξασιν· ἂν δὲ μὴ πραχθῇ, λογίσασθε, πῶς πρὸς οὕτω φιλανθρώπους ὅπλα κινεῖν ἀνόσιον. εἰσελθέτω δ’ οἶκτος ὑμᾶς εἰ καὶ μὴ τέκνων καὶ γυναικῶν, ἀλλὰ τῆς γε μητροπόλεως ταύτης καὶ τῶν ἱερῶν περιβόλων. φείσασθε τοῦ ἱεροῦ καὶ τὸν ναὸν ἑαυτοῖς μετὰ τῶν ἁγίων τηρήσατε· ἀφέξονται γὰρ οὐκέτι Ῥωμαῖοι τούτων κρατήσαντες, ὧν φεισάμενοι πρότερον ἠχαρίστηνται. μαρτύρομαι δὲ ἐγὼ μὲν ὑμῶν τὰ ἅγια καὶ τοὺς ἱεροὺς ἀγγέλους τοῦ θεοῦ καὶ πατρίδα τὴν κοινήν, ὡς οὐδὲν τῶν σωτηρίων ὑμῖν καθυφηκάμην, ὑμεῖς δὲ βουλευσάμενοι μὲν τὰ δέοντα κοινὴν σὺν ἐμοὶ τὴν εἰρήνην ἕξετε, προαχθέντες δὲ τοῖς θυμοῖς χωρὶς ἐμοῦ κινδυνεύσετε.", "st": "2.16.4"}, {"sp": "N", "t": "Τοσαῦτα εἰπὼν ἐπεδάκρυσέν τε μετὰ τῆς ἀδελφῆς καὶ πολὺ τῆς ὁρμῆς αὐτῶν ἔπαυσεν τοῖς δακρύοις. ἀνεβόων δὲ οὐ Ῥωμαίοις, ἀλλὰ Φλώρῳ δι’ ἃ πεπόνθασιν πολεμεῖν. πρὸς τοῦτο βασιλεὺς Ἀγρίππας ἀλλὰ τὰ ἔργα, ἔφη, Ῥωμαίοις ἤδη πολεμούντων ἐστίν· οὔτε γὰρ Καίσαρι δεδώκατε τὸν φόρον καὶ τὰς στοὰς ἀπεκόψατε τῆς Ἀντωνίας. ἀποσκευάσαισθε δ’ ἂν τὴν αἰτίαν τῆς ἀποστάσεως, εἰ ταύτας τε συνάψετε πάλιν καὶ τελέσετε τὴν εἰσφοράν· οὐ γὰρ δή γε Φλώρου τὸ φρούριόν ἐστιν ἢ Φλώρῳ τὰ χρήματα δώσετε.", "st": "2.16.5"}, {"sp": "N", "t": "Τούτοις ὁ δῆμος ἐπείθετο, καὶ μετὰ τοῦ βασιλέως τῆς τε Βερνίκης ἀναβάντες εἰς τὸ ἱερὸν κατήρξαντο τῆς τῶν στοῶν δομήσεως, εἰς δὲ τὰς κώμας οἵ τε ἄρχοντες καὶ βουλευταὶ μερισθέντες τοὺς φόρους συνέλεγον. ταχέως δὲ τὰ τεσσαράκοντα τάλαντα, τοσοῦτον γὰρ ἔλειπεν, ἠθροίσθη. καὶ τοῦ μὲν πολέμου τότε οὕτω τὴν ἀπειλὴν κατεῖχεν Ἀγρίππας, αὖθις δὲ ἐπειρᾶτο πείθειν τὸ πλῆθος ὑπακούειν Φλώρῳ, μέχρις ἀντ’ αὐτοῦ πέμψει Καῖσαρ διάδοχον· πρὸς ὃ παροξυνθέντες ἐβλασφήμουν εἰς τὸν βασιλέα καὶ τῆς πόλεως αὐτὸν ἐξεκήρυσσον, ἐτόλμων δέ τινες τῶν στασιαστῶν καὶ λίθους ἐπ’ αὐτὸν βάλλειν. ὁ δὲ βασιλεὺς ἰδὼν τὴν ὁρμὴν ἤδη τῶν νεωτεριζόντων ἀκατάσχετον καὶ χαλεπήνας ἐφ’ οἷς προπεπηλάκισται, τοὺς μὲν ἄρχοντας αὐτῶν ἅμα τοῖς δυνατοῖς ἔπεμπε πρὸς Φλῶρον εἰς Καισάρειαν, ἵν’ ἐκεῖνος ἐξ αὐτῶν ἀποδείξῃ τοὺς τὴν χώραν φορολογήσοντας, αὐτὸς δὲ ἀνεχώρησεν εἰς τὴν βασιλείαν.", "st": "2.17.1"}, {"sp": "N", "t": "Κἀν τούτῳ τινὲς τῶν μάλιστα κινούντων τὸν πόλεμον συνελθόντες ὥρμησαν ἐπὶ φρούριόν τι καλούμενον Μασάδαν, καὶ καταλαβόντες αὐτὸ λάθρα τοὺς μὲν Ῥωμαίων φρουροὺς ἀπέσφαξαν, ἑτέρους δ’ ἐγκατέστησαν ἰδίους. ἅμα δὲ καὶ κατὰ τὸ ἱερὸν Ἐλεάζαρος υἱὸς Ἀνανία τοῦ ἀρχιερέως, νεανίας θρασύτατος, στρατηγῶν τότε τοὺς κατὰ τὴν λατρείαν λειτουργοῦντας ἀναπείθει μηδενὸς ἀλλοτρίου δῶρον ἢ θυσίαν προσδέχεσθαι. τοῦτο δ’ ἦν τοῦ πρὸς Ῥωμαίους πολέμου καταβολή· τὴν γὰρ ὑπὲρ τούτων θυσίαν Καίσαρος ἀπέρριψαν. καὶ πολλὰ τῶν τε ἀρχιερέων καὶ τῶν γνωρίμων παρακαλούντων μὴ παραλιπεῖν τὸ ὑπὲρ τῶν ἡγεμόνων ἔθος οὐκ ἐνέδοσαν, πολὺ μὲν καὶ τῷ σφετέρῳ πλήθει πεποιθότες, καὶ γὰρ τὸ ἀκμαιότατον τῶν νεωτεριζόντων συνήργει, μάλιστα δ’ ἀφορῶντες εἰς τὸν Ἐλεάζαρον στρατηγοῦντα.", "st": "2.17.2"}, {"sp": "N", "t": "Συνελθόντες γοῦν οἱ δυνατοὶ τοῖς ἀρχιερεῦσιν εἰς ταὐτὸ καὶ τοῖς τῶν Φαρισαίων γνωρίμοις ὡς ἐπ’ ἀνηκέστοις ἤδη συμφοραῖς ἐβουλεύοντο περὶ τῶν ὅλων· καὶ δόξαν ἀποπειραθῆναι τῶν στασιαστῶν λόγοις πρὸ τῆς χαλκῆς πύλης ἀθροίζουσι τὸν δῆμον, ἥτις ἦν τοῦ ἔνδον ἱεροῦ τετραμμένη πρὸς ἀνατολὰς ἡλίου. καὶ πρῶτον αὐτῶν πολλὰ πρὸς τὴν τόλμαν τῆς ἀποστάσεως χαλεπήναντες καὶ τὸ τηλικοῦτον ἐπισείειν τῇ πατρίδι πόλεμον, ἔπειτα τὸ τῆς προφάσεως ἄλογον διήλεγχον, φάμενοι τοὺς μὲν προγόνους αὐτῶν κεκοσμηκέναι τὸν ναὸν ἐκ τῶν ἀλλοφύλων τὸ πλέον ἀεὶ προσδεχομένους τὰς ἀπὸ τῶν ἔξωθεν ἐθνῶν δωρεάς, καὶ οὐ μόνον οὐ διακεκωλυκέναι θυσίας τινῶν, τοῦτο μὲν γὰρ ἀσεβέστατον, ἀλλὰ καὶ τὰ βλεπόμενα καὶ τὰ παραμένοντα τοσοῦτον χρόνον ἀναθήματα περὶ τῷ ἱερῷ καθιδρυκέναι. αὐτοὺς δὲ νῦν ἐρεθίζοντας τὰ Ῥωμαίων ὅπλα καὶ μνηστευομένους τὸν ἀπ’ ἐκείνων πόλεμον καινοτομεῖν θρησκείαν ξένην καὶ μετὰ τοῦ κινδύνου καταψηφίσασθαι τῆς πόλεως ἀσέβειαν, εἰ παρὰ μόνοις Ἰουδαίοις οὔτε θύσει τις ἀλλότριος οὔτε προσκυνήσει. κἂν μὲν ἐπὶ ἰδιώτου τις ἑνὸς τοῦτον εἰσφέρῃ τὸν νόμον, ἀγανακτεῖν ὡς ὁριζομένης ἀπανθρωπίας, περιορᾶν δ’ ὅτε Ῥωμαῖοι καὶ ὁ Καῖσαρ ἔκσπονδος γίνεται. δεδοικέναι μέντοι, μὴ τὰς ὑπὲρ ἐκείνων ἀπορρίψαντες θυσίας κωλυθῶσι θύειν καὶ τὰς ὑπὲρ ἑαυτῶν γένηταί τε ἔκσπονδος τῆς ἡγεμονίας ἡ πόλις, εἰ μὴ ταχέως σωφρονήσαντες ἀποδώσουσιν τὰς θυσίας καὶ πρὶν ἐξελθεῖν ἐφ’ οὓς ὑβρίκασιν τὴν φήμην διορθώσονται τὴν ὕβριν.", "st": "2.17.3"}, {"sp": "N", "t": "Ἅμα ταῦτα λέγοντες παρῆγον τοὺς ἐμπείρους τῶν πατρίων ἱερεῖς ἀφηγουμένους, ὅτι πάντες οἱ πρόγονοι τὰς παρὰ τῶν ἀλλογενῶν θυσίας ἀπεδέχοντο. προσεῖχεν δὲ οὐδεὶς τῶν νεωτεριζόντων, ἀλλ’ οὐδὲ προσίεσαν οἱ λῃστρικοὶ καὶ τὴν τοῦ πολέμου καταβολὴν ἐνσκευαζόμενοι. συνιδόντες οὖν οἱ δυνατοὶ τήν τε στάσιν ἤδη δυσκαθαίρετον ὑπ’ αὐτῶν οὖσαν καὶ τὸν ἀπὸ Ῥωμαίων κίνδυνον ἐπὶ πρώτους αὐτοὺς ἀφιξόμενον ἀπεσκευάζοντο τὰς αἰτίας, καὶ πρέσβεις οὓς μὲν πρὸς Φλῶρον ἔπεμπον, ὧν ἦρχεν υἱὸς Ἀνανίου Σίμων, οὓς δὲ πρὸς Ἀγρίππαν, ἐν οἷς ἦσαν ἐπίσημοι Σαῦλός τε καὶ Ἀντίπας καὶ Κοστόβαρος προσήκοντες τῷ βασιλεῖ κατὰ γένος. ἐδέοντο δὲ ἀμφοτέρων ἀναβῆναι μετὰ δυνάμεως εἰς τὴν πόλιν καὶ πρὶν γενέσθαι δυσκαθαίρετον ἐπικόψαι τὴν στάσιν. Φλώρῳ μὲν οὖν δεινὸν εὐαγγέλιον ἦν, καὶ προῃρημένος ἐξάπτειν τὸν πόλεμον οὐδὲν ἀπεκρίνατο τοῖς πρεσβευταῖς· Ἀγρίππας δὲ κηδόμενος ἐπίσης τῶν τε ἀφισταμένων καὶ πρὸς οὓς ὁ πόλεμος ἠγείρετο, βουλόμενός τε Ῥωμαίοις μὲν Ἰουδαίους σώζεσθαι, Ἰουδαίοις δὲ τὸ ἱερὸν καὶ τὴν μητρόπολιν, ἀλλ’ οὐδ’ ἑαυτῷ λυσιτελήσειν τὴν ταραχὴν ἐπιστάμενος, ἔπεμπεν τοὺς ἐπαμυνοῦντας τῷ δήμῳ δισχιλίους ἱππεῖς, Αὐρανίτας τε καὶ Βαταναίους καὶ Τραχωνίτας, ὑπὸ Δαρείῳ μὲν ἱππάρχῃ, στρατηγῷ δὲ τῷ Ἰακίμου Φιλίππῳ.", "st": "2.17.4"}, {"sp": "N", "t": "Τούτοις θαρσήσαντες οἱ δυνατοὶ σὺν τοῖς ἀρχιερεῦσιν καὶ πᾶν ὅσον τοῦ πλήθους εἰρήνην ἠγάπα τὴν ἄνω καταλαμβάνονται πόλιν· τῆς κάτω γὰρ τὸ στασιάζον ἐκράτει καὶ τοῦ ἱεροῦ. χερμάσιν μὲν οὖν καὶ τοῖς ἑκηβόλοις ἀδιαλείπτως ἐχρῶντο, καὶ συνεχεῖς ἦσαν βελῶν ἀφέσεις ἐξ ἑκατέρων τῶν κλιμάτων· ἔστιν δ’ ὅτε καὶ κατὰ λόχους ἐκτρέχοντες συστάδην ἐμάχοντο, τόλμαις μὲν οἱ στασιασταὶ προέχοντες, ἐμπειρίᾳ δὲ οἱ βασιλικοί. καὶ τούτοις μὲν ἦν ἀγὼν τοῦ ἱεροῦ κρατῆσαι μάλιστα καὶ τοὺς μιαίνοντας τὸν ναὸν ἐξελάσαι, τοῖς δὲ περὶ τὸν Ἐλεάζαρον στασιασταῖς πρὸς οἷς ἔσχον καὶ τὴν ἄνω πόλιν προσλαβεῖν. ἑπτὰ μὲν οὖν ἡμέραις συχνὸς ἀμφοτέρων φόνος ἐγίνετο, καὶ οὐδέτεροι τοῦ καταληφθέντος μέρους εἶκον.", "st": "2.17.5"}, {"sp": "N", "t": "Τῇ δ’ ἑξῆς τῆς τῶν ξυλοφορίων ἑορτῆς οὔσης, ἐν ᾗ πᾶσιν ἔθος ἦν ὕλην τῷ βωμῷ προσφέρειν, ὅπως μήποτε τροφὴ τῷ πυρὶ λείποι, διαμένει γὰρ ἄσβεστον ἀεί, τοὺς μὲν διαφόρους τῆς θρησκείας ἐξέκλεισαν, τῷ δ’ ἀσθενεῖ λαῷ συνεισρυέντας πολλοὺς τῶν σικαρίων, οὕτως γὰρ ἐκάλουν τοὺς λῃστὰς ἔχοντας ὑπὸ τοῖς κόλποις ξίφη, προσλαβόντες θαρραλεώτερον ἥπτοντο τῆς ἐπιχειρήσεως. ἡττῶντο δ’ οἱ βασιλικοὶ πλήθει τε καὶ τόλμῃ, καὶ βιασαμένοις εἶκον ἐκ τῆς ἄνω πόλεως. οἱ δὲ ἐπιπεσόντες τήν τε Ἀνανίου τοῦ ἀρχιερέως οἰκίαν καὶ τὰ Ἀγρίππα καὶ Βερνίκης ὑποπιμπρᾶσιν βασίλεια· μεθ’ ἃ τὸ πῦρ ἐπὶ τὰ ἀρχεῖα ἔφερον ἀφανίσαι σπεύδοντες τὰ συμβόλαια τῶν δεδανεικότων καὶ τὰς εἰσπράξεις ἀποκόψαι τῶν χρεῶν, ὅπως αὐτοί τε πλῆθος προσλάβωσιν τῶν ὠφεληθέντων καὶ μετ’ ἀδείας τοῖς εὐπόροις ἐπαναστήσωσι τοὺς ἀπόρους. φυγόντων δὲ τῶν πρὸς τῷ γραμματοφυλακείῳ τὸ πῦρ ἐνίεσαν. ἐπεὶ δὲ τὰ νεῦρα τῆς πόλεως καταφλέξαντες ἐπὶ τοὺς ἐχθροὺς ἐχώρουν, ἔνθα δὴ τῶν δυνατῶν καὶ τῶν ἀρχιερέων οἱ μὲν εἰς τοὺς ὑπονόμους καταδύντες διελάνθανον, οἱ δὲ σὺν τοῖς βασιλικοῖς εἰς τὴν ἀνωτέρω καταφυγόντες αὐλὴν ταχέως ἀπέκλεισαν τὰς θύρας, σὺν οἷς Ἀνανίας ὁ ἀρχιερεὺς Ἐζεκίας τε ὁ ἀδελφὸς αὐτοῦ καὶ οἱ πρεσβεύσαντες πρὸς Ἀγρίππαν ἦσαν. τότε μὲν οὖν τῇ νίκῃ καὶ τοῖς ἐμπρησθεῖσιν ἀρκεσθέντες ἀνεπαύσαντο.", "st": "2.17.6"}, {"sp": "N", "t": "Τῇ δ’ ἑξῆς, πεντεκαιδεκάτη δ’ ἦν Λώου μηνός, ὥρμησαν ἐπὶ τὴν Ἀντωνίαν καὶ τοὺς ἐν αὐτῇ φρουροὺς δυσὶν ἡμέραις πολιορκήσαντες αὐτούς τε εἷλον καὶ κατέσφαξαν καὶ τὸ φρούριον ἐνέπρησαν. ἔπειτα μετέβαινον εἰς τὴν αὐλήν, εἰς ἣν οἱ βασιλικοὶ κατέφυγον, καὶ διανείμαντες σφᾶς αὐτοὺς εἰς τέσσαρα μέρη τῶν τειχῶν ἐπειρῶντο. τῶν δ’ ἔνδον πρὸς ἐκδρομὴν μὲν οὐδεὶς ἐθάρρει διὰ τὸ πλῆθος τῶν ἐφεστώτων, διιστάμενοι δὲ ἐπὶ τὰ θωράκια καὶ τοὺς πύργους ἔβαλλον τοὺς προσιόντας, καὶ συχνοὶ τῶν λῃστῶν ὑπὸ τοῖς τείχεσιν ἔπιπτον. οὔτε δὲ νυκτὸς οὔτε ἡμέρας διέλειπεν ἡ συμβολὴ τῶν μὲν στασιαστῶν ἀπαγορεύσειν τοὺς ἔνδον οἰομένων ἐνδείᾳ τροφῆς, τῶν δ’ ἔνδοθεν καμάτῳ τοὺς πολιορκοῦντας.", "st": "2.17.7"}, {"sp": "N", "t": "Κἀν τούτῳ Μανάημός τις, υἱὸς Ἰούδα τοῦ καλουμένου Γαλιλαίου, σοφιστὴς δεινότατος, ὁ καὶ ἐπὶ Κυρινίου ποτὲ Ἰουδαίους ὀνειδίσας ὅτι Ῥωμαίοις ὑπετάσσοντο μετὰ τὸν θεόν, ἀναλαβὼν τοὺς γνωρίμους ἀνεχώρησεν εἰς Μασάδαν, ἔνθα τὴν Ἡρώδου τοῦ βασιλέως ὁπλοθήκην ἀναρρήξας καὶ πρὸς τοῖς δημόταις ἑτέρους λῃστὰς καθοπλίσας τούτοις τε χρώμενος δορυφόροις, οἷα δὴ βασιλεὺς ἐπάνεισιν εἰς Ἱεροσόλυμα καὶ γενόμενος ἡγεμὼν τῆς στάσεως διέτασσεν τὴν πολιορκίαν. ἀπορία δ’ ἦν ὀργάνων, καὶ φανερῶς ὑπορύττειν τὸ τεῖχος οὐχ οἷόν τε ἦν ἄνωθεν βαλλομένους· ὑπόνομον δὴ πόρρωθεν ἐφ’ ἕνα τῶν πύργων ὑπορύξαντες ἀνεκρήμνισαν αὐτόν, ἔπειτα τὴν ἀνέχουσαν ὕλην ἐμπρήσαντες ἐξῆλθον. ὑποκαέντων δὲ τῶν στηριγμάτων ὁ μὲν πύργος ἐξαίφνης κατασείεται, τεῖχος δ’ ἕτερον ἔνδοθεν ἀνῳκοδομημένον διεφάνη· τὴν γὰρ ἐπιβουλὴν αὐτῶν προαισθόμενοι, τάχα καὶ τοῦ πύργου κινηθέντος ὡς ὑπωρύττετο, δεύτερον ἑαυτοῖς ἔρυμα κατεσκεύασαν. πρὸς ὃ τῶν ἀδοκήτως ἰδόντων καὶ κρατεῖν ἤδη πεπεισμένων κατάπληξις ἦν. οἱ δὲ ἔνδοθεν πρός τε τὸν Μανάημον καὶ τοὺς ἐξάρχοντας τῆς στάσεως ἔπεμπον ἀξιοῦντες ἐξελθεῖν ὑπόσπονδοι, καὶ δοθὲν μόνοις τοῖς βασιλικοῖς καὶ τοῖς ἐπιχωρίοις οἱ μὲν ἐξῄεσαν. ἀθυμία δὲ τοὺς Ῥωμαίους καταλειφθέντας μόνους ὑπέλαβεν· οὔτε γὰρ βιάσασθαι τοσοῦτον πλῆθος ἐδύναντο καὶ τὸ δεξιὰς αἰτεῖν ὄνειδος ὑπελάμβανον, πρὸς τῷ μηδὲ πιστεύειν εἰ διδοῖτο. καταλιπόντες δὴ τὸ στρατόπεδον ὡς εὐάλωτον ἐπὶ τοὺς βασιλικοὺς ἀνέφυγον πύργους, τόν τε Ἱππικὸν καλούμενον καὶ Φασάηλον καὶ Μαριάμμην. οἱ δὲ περὶ τὸν Μανάημον εἰσπεσόντες ὅθεν οἱ στρατιῶται διέφυγον ὅσους τε αὐτῶν κατελάμβανον μὴ φθάσαντας ἐκδραμεῖν διέφθειραν, καὶ τὰς ἀποσκευὰς διαρπάσαντες ἐνέπρησαν τὸ στρατόπεδον. ταῦτα μὲν οὖν ἕκτῃ Γορπιαίου μηνὸς ἐπράχθη.", "st": "2.17.8"}, {"sp": "N", "t": "Κατὰ δὲ τὴν ἐπιοῦσαν ὅ τε ἀρχιερεὺς Ἀνανίας περὶ τὸν τῆς βασιλικῆς αὐλῆς εὔριπον διαλανθάνων ἁλίσκεται καὶ πρὸς τῶν λῃστῶν ἀναιρεῖται σὺν Ἐζεκίᾳ τῷ ἀδελφῷ, καὶ τοὺς πύργους περισχόντες οἱ στασιασταὶ παρεφύλαττον, μή τις τῶν στρατιωτῶν διαφύγοι. τὸν δὲ Μανάημον ἥ τε τῶν ὀχυρῶν καταστροφὴ χωρίων καὶ ὁ τοῦ ἀρχιερέως Ἀνανίου θάνατος ἐτύφωσεν εἰς ὠμότητα καὶ μηδένα νομίζων ἔχειν ἐπὶ τοῖς πράγμασιν ἀντίπαλον ἀφόρητος ἦν τύραννος. ἐπανίστανται δὲ οἱ περὶ τὸν Ἐλεάζαρον αὐτῷ, καὶ λόγον ἀλλήλοις δόντες, ὡς οὐ χρὴ Ῥωμαίων ἀποστάντας δι’ ἐλευθερίας πόθον καταπροέσθαι ταύτην οἰκείῳ δήμῳ καὶ δεσπότην φέρειν, εἰ καὶ μηδὲν πράττοι βίαιον, ἀλλ’ οὖν ἑαυτῶν ταπεινότερον· εἰ γὰρ καὶ δέοι τινὰ τῶν ὅλων ἀφηγεῖσθαι, παντὶ μᾶλλον ἢ ἐκείνῳ προσήκειν, συντίθενται καὶ κατὰ τὸ ἱερὸν ἐπεχείρουν αὐτῷ· σοβαρὸς γὰρ ἀναβεβήκει προσκυνήσων ἐσθῆτί τε βασιλικῇ κεκοσμημένος καὶ τοὺς ζηλωτὰς ἐνόπλους ἐφελκόμενος. ὡς δ’ οἱ περὶ τὸν Ἐλεάζαρον ἐπ’ αὐτὸν ὥρμησαν, ὅ τε λοιπὸς δῆμος ἐπὶ τὰς ὀργὰς λίθους ἁρπάσαντες τὸν σοφιστὴν ἔβαλλον, οἰόμενοι τούτου καταλυθέντος διατρέψειν ὅλην τὴν στάσιν, πρὸς ὀλίγον οἱ περὶ τὸν Μανάημον ἀντισχόντες ὡς εἶδον πᾶν ἐπ’ αὐτοὺς τὸ πλῆθος ὁρμῆσαν, ἔφυγον ὅπη τις ἴσχυσεν, καὶ φόνος μὲν ἦν τῶν καταληφθέντων, ἔρευνα δὲ τῶν ἀποκρυπτομένων. καὶ διεσώθησαν ὀλίγοι λάθρα διαδράντες εἰς Μασάδαν, σὺν οἷς Ἐλεάζαρος υἱὸς Ἰαείρου, προσήκων τῷ Μαναήμῳ κατὰ γένος, ὃς ὕστερον ἐτυράννησεν τῆς Μασάδας. αὐτόν τε τὸν Μανάημον εἰς τὸν καλούμενον Ὀφλᾶν συμφυγόντα κἀκεῖ ταπεινῶς ὑπολανθάνοντα ζωγρήσαντες εἰς τὸ φανερὸν ἐξείλκυσαν καὶ πολλαῖς αἰκισάμενοι βασάνοις ἀνεῖλον, ὁμοίως δὲ καὶ τοὺς ὑπ’ αὐτὸν ἡγεμόνας τόν τε ἐπισημότατον τῆς τυραννίδος ὑπηρέτην Ἀψάλωμον.", "st": "2.17.9"}, {"sp": "N", "t": "Ὁ μὲν οὖν δῆμος, ὡς ἔφην, εἰς ταῦτα συνήργησεν ἐλπίζων τινὰ τῆς ὅλης στάσεως διόρθωσιν· οἱ δ’ οὐ καταλῦσαι τὸν πόλεμον σπεύδοντες, ἀλλ’ ἀδεέστερον πολεμεῖν Μανάημον ἀνῃρήκεσαν. ἀμέλει πολλὰ τοῦ δήμου τοῖς στρατιώταις ἀνεῖναι τὴν πολιορκίαν παρακαλοῦντος, οἱ δὲ προσέκειντο χαλεπώτερον, μέχρι μηκέτι ἀντέχοντες οἱ περὶ τὸν Μετίλιον, οὗτος γὰρ ἦν τῶν Ῥωμαίων ἔπαρχος, διαπέμπονται πρὸς τοὺς περὶ τὸν Ἐλεάζαρον ἐξαιτούμενοι μόνας τὰς ψυχὰς ὑποσπόνδους, τὰ δ’ ὅπλα καὶ τὴν λοιπὴν κτῆσιν παραδώσειν λέγοντες. οἱ δὲ καὶ τὴν ἱκεσίαν ἁρπάσαντες ἀνέπεμψαν πρὸς αὐτοὺς Γωρίονά τε Νικομήδους υἱὸν καὶ Ἀνανίαν Σαδούκι καὶ Ἰούδαν Ἰωνάθου δεξιάν τε καὶ ὅρκους δώσοντας. ὧν γενομένων κατῆγεν τοὺς στρατιώτας ὁ Μετίλιος. οἱ δὲ μέχρι μὲν ἦσαν ἐν τοῖς ὅπλοις, οὔτ’ ἐπεχείρει τις τῶν στασιαστῶν αὐτοῖς οὔτ’ ἐνέφαινεν ἐπιβουλήν· ὡς δὲ κατὰ τὰς συνθήκας ἅπαντες ἀπέθεντο τοὺς θυρεοὺς καὶ τὰ ξίφη καὶ μηδὲν ἔτι ὑποπτεύοντες ἀνεχώρουν, ὥρμησαν ἐπ’ αὐτοὺς οἱ περὶ τὸν Ἐλεάζαρον καὶ περισχόντες ἀνῄρουν οὔτε ἀμυνομένους οὔτε ἱκετεύοντας, μόνας δὲ τὰς συνθήκας καὶ τοὺς ὅρκους ἀναβοῶντας. οἱ μὲν οὖν οὕτως ὠμῶς ἀπεσφάγησαν ἅπαντες πλὴν Μετιλίου, τοῦτον γὰρ ἱκετεύσαντα καὶ μέχρι περιτομῆς ἰουδαΐσειν ὑποσχόμενον διέσωσαν μόνον, τὸ δὲ πάθος Ῥωμαίοις μὲν ἦν κοῦφον, ἐκ γὰρ ἀπλέτου δυνάμεως ἀπαναλώθησαν ὀλίγοι, Ἰουδαίων δὲ προοίμιον ἁλώσεως ἔδοξεν. καὶ κατιδόντες ἀνηκέστους μὲν ἤδη τὰς αἰτίας τοῦ πολέμου, τὴν δὲ πόλιν τηλικούτῳ μιάσματι πεφυρμένην, ἐξ οὗ δαιμόνιόν τι μήνιμα προσδοκᾶν εἰκὸς ἦν, εἰ καὶ μὴ τὴν ἐκ Ῥωμαίων ἄμυναν, ἐπένθουν δημοσίᾳ, καὶ πλήρης μὲν κατηφείας ἦν ἡ πόλις, ἕκαστος δὲ τῶν μετρίων ὡς αὐτὸς ὑπὲρ τῶν στασιαστῶν δίκας δώσων τετάρακτο. καὶ γὰρ δὴ σαββάτῳ συνέβη πραχθῆναι τὸν φόνον, ἐν ᾧ διὰ τὴν θρησκείαν καὶ τῶν ὁσίων ἔργων ἔχουσιν ἐκεχειρίαν.", "st": "2.17.10"}, {"sp": "N", "t": "Τῆς δ’ αὐτῆς ἡμέρας καὶ ὥρας ὥσπερ ἐκ δαιμονίου προνοίας ἀνῄρουν Καισαρεῖς τοὺς παρ’ ἑαυτοῖς Ἰουδαίους, ὡς ὑπὸ μίαν ὥραν ἀποσφαγῆναι μὲν ὑπὲρ δισμυρίους, κενωθῆναι δὲ πᾶσαν Ἰουδαίων τὴν Καισάρειαν· καὶ γὰρ τοὺς διαφεύγοντας ὁ Φλῶρος συλλαβὼν κατῆγεν δεσμώτας εἰς τὰ νεώρια. πρὸς δὲ τὴν ἐκ τῆς Καισαρείας πληγὴν ὅλον τὸ ἔθνος ἐξαγριοῦται, καὶ διαμερισθέντες τάς τε κώμας τῶν Σύρων καὶ τὰς προσεχούσας ἐπόρθουν πόλεις, Φιλαδέλφειάν τε καὶ Ἐσεβωνῖτιν καὶ Γέρασα καὶ Πέλλαν καὶ Σκυθόπολιν. ἔπειτα Γαδάροις καὶ Ἵππῳ καὶ τῇ Γαυλανίτιδι προσπεσόντες τὰ μὲν καταστρεψάμενοι, τὰ δ’ ὑποπρήσαντες ἐχώρουν ἐπὶ Κάδασα τὴν Τυρίων καὶ Πτολεμαΐδα Γάβαν τε καὶ Καισάρειαν. ἀντέσχον δὲ οὔτε Σεβαστὴ ταῖς ὁρμαῖς αὐτῶν οὔτε Ἀσκάλων, ἀλλ’ ἐπὶ ταύταις πυρποληθείσαις Ἀνθηδόνα καὶ Γάζαν κατέσκαπτον. πολλαὶ δὲ καθ’ ἑκάστην τούτων τῶν πόλεων ἀνηρπάζοντο κῶμαι, καὶ τῶν ἁλισκομένων ἀνδρῶν φόνος ἦν ἄπειρος.", "st": "2.18.1"}, {"sp": "N", "t": "Οὐ μὴν οἱ Σύροι τῶν Ἰουδαίων ἔλαττον πλῆθος ἀνῄρουν, ἀλλὰ καὶ αὐτοὶ τοὺς ἐν ταῖς πόλεσιν λαμβανομένους ἀπέσφαττον οὐ μόνον κατὰ μῖσος, ὡς πρότερον, ἀλλ’ ἤδη καὶ τὸν ἐφ’ ἑαυτοῖς κίνδυνον φθάνοντες. δεινὴ δὲ ὅλην τὴν Συρίαν ἐπεῖχεν ταραχή, καὶ πᾶσα πόλις εἰς δύο διῄρητο στρατόπεδα, σωτηρία δὲ τοῖς ἑτέροις ἦν τὸ τοὺς ἑτέρους φθάσαι. καὶ τὰς μὲν ἡμέρας ἐν αἵματι διῆγον, τὰς δὲ νύκτας δέει χαλεπωτέρας· καὶ γὰρ ἀπεσκευάσθαι τοὺς Ἰουδαίους δοκοῦντες ἕκαστοι τοὺς ἰουδαΐζοντας εἶχον ἐν ὑποψίᾳ, καὶ τὸ παρ’ ἑκάστοις ἀμφίβολον οὔτε ἀνελεῖν τις προχείρως ὑπέμενεν καὶ μεμιγμένον ὡς βεβαίως ἀλλόφυλον ἐφοβεῖτο. προεκαλεῖτο δὲ ἐπὶ τὰς σφαγὰς τῶν διαφόρων καὶ τοὺς πάλαι πρᾳοτάτους πάνυ δοκοῦντας ἡ πλεονεξία· τὰς γὰρ οὐσίας τῶν ἀναιρεθέντων ἀδεῶς διήρπαζον καὶ καθάπερ ἐκ παρατάξεως τὰ σκῦλα τῶν ἀνῃρημένων εἰς τοὺς σφετέρους οἴκους μετέφερον, ἔνδοξός τε ἦν ὁ πλεῖστα κερδάνας ὡς κατισχύσας πλειόνων. ἦν δὲ ἰδεῖν τὰς πόλεις μεστὰς ἀτάφων σωμάτων καὶ νεκροὺς ἅμα νηπίοις γέροντας ἐρριμμένους γύναιά τε μηδὲ τῆς ἐπ’ αἰδοῖ σκέπης μετειληφότα, καὶ πᾶσαν μὲν τὴν ἐπαρχίαν μεστὴν ἀδιηγήτων συμφορῶν, μείζονα δὲ τῶν ἑκάστοτε τολμωμένων τὴν ἐπὶ τοῖς ἀπειλουμένοις ἀνάτασιν.", "st": "2.18.2"}, {"sp": "N", "t": "Μέχρι μὲν δὴ τούτων Ἰουδαίοις πρὸς τὸ ἀλλόφυλον ἦσαν προσβολαί, κατατρέχοντες δὲ εἰς Σκυθόπολιν τοὺς παρ’ ἐκείνοις Ἰουδαίους ἐπείρασαν πολεμίους· ταξάμενοι γὰρ μετὰ τῶν Σκυθοπολιτῶν καὶ τῆς ἑαυτῶν ἀσφαλείας ἐν δευτέρῳ θέμενοι τὴν συγγένειαν ὁμόσε τοῖς ὁμοφύλοις ἐχώρουν. ὑπωπτεύθη δ’ αὐτῶν καὶ τὸ λίαν πρόθυμον· οἱ γοῦν Σκυθοπολῖται δείσαντες μὴ νύκτωρ ἐπιχειρήσωσι τῇ πόλει καὶ μετὰ μεγάλης αὐτῶν συμφορᾶς τοῖς οἰκείοις ἀπολογήσωνται περὶ τῆς ἀποστάσεως, ἐκέλευον αὐτούς, εἰ βούλονται τὴν ὁμόνοιαν βεβαιῶσαι καὶ τὸ πρὸς τοὺς ἀλλοεθνεῖς πιστὸν ἐπιδείξασθαι, μεταβαίνειν ἅμα ταῖς γενεαῖς εἰς τὸ ἄλσος. τῶν δὲ ποιησάντων τὸ προσταχθὲν χωρὶς ὑποψίας. δύο μὲν ἡμέρας ἠρέμησαν οἱ Σκυθοπολῖται τὴν πίστιν αὐτῶν δελεάζοντες, τῇ δὲ τρίτῃ νυκτὶ παρατηρήσαντες τοὺς μὲν ἀφυλάκτους οὓς δὲ κοιμωμένους ἅπαντας ἀπέσφαξαν ὄντας τὸν ἀριθμὸν ὑπὲρ μυρίους καὶ τρισχιλίους, τὰς δὲ κτήσεις διήρπασαν ἁπάντων.", "st": "2.18.3"}, {"sp": "N", "t": "Ἄξιον δ’ ἀφηγήσασθαι καὶ τὸ Σίμωνος πάθος, ὃς υἱὸς μὲν ἦν Σαούλου τινὸς τῶν οὐκ ἀσήμων, ῥώμῃ δὲ σώματος καὶ τόλμῃ διαφέρων ἐπὶ κακῷ τῶν ὁμοφύλων ἀμφοτέροις κατεχρήσατο· προϊὼν γοῦν ὁσημέραι πολλοὺς μὲν ἀνῄρει τῶν πρὸς τῇ Σκυθοπόλει Ἰουδαίων, τρεπόμενος δὲ πολλάκις αὐτοὺς ἅπαντας μόνος ἦν ῥοπὴ τῆς παρατάξεως. περιέρχεται δ’ αὐτὸν ἀξία ποινὴ τοῦ συγγενικοῦ φόνου· ἐπεὶ γὰρ περισχόντες οἱ Σκυθοπολῖται κατηκόντιζον αὐτοὺς ἀνὰ τὸ ἄλσος, σπασάμενος τὸ ξίφος ἐπ’ οὐδένα μὲν ὥρμησεν τῶν πολεμίων, καὶ γὰρ ἑώρα τὸ πλῆθος ἀνήνυτον, ἀναβοήσας δὲ μάλα ἐκπαθῶς ἄξιά γε ὧν ἔδρασα πάσχω, Σκυθοπολῖται, καθ’ ὑμῶν, οἳ τοσούτῳ φόνῳ συγγενῶν τὴν πρὸς αὐτοὺς εὔνοιαν ἐπιστωσάμεθα. τοιγαροῦν οἷς ἄπιστον μὲν εὐλόγως εὕρηται τὸ ἀλλόφυλον, ἠσέβηται δὲ [εἰς ἔσχατα] τὸ οἰκεῖον, θνήσκωμεν ὡς ἐναγεῖς χερσὶν ἰδίαις· οὐ γὰρ πρέπον ἐν ταῖς τῶν πολεμίων. τὸ αὐτὸ δ’ ἂν εἴη μοι καὶ ποινὴ τοῦ μιάσματος ἀξία καὶ πρὸς ἀνδρείαν ἔπαινος, ἵνα μηδεὶς τῶν ἐχθρῶν τὴν ἐμὴν αὐχήσῃ σφαγὴν μηδ’ ἐπαλαζονεύσηται πεσόντι. ταῦτα εἰπὼν ἐλεοῦσιν ἅμα καὶ τεθυμωμένοις ὄμμασιν περισκέπτεται τὴν ἑαυτοῦ γενεάν· ἦν δ’ αὐτῷ καὶ γυνὴ καὶ τέκνα καὶ γηραιοὶ γονεῖς. ὁ δὲ πρῶτον μὲν τὸν πατέρα τῆς πολιᾶς ἐπισπασάμενος διελαύνει τῷ ξίφει, μεθ’ ὃν οὐκ ἄκουσαν τὴν μητέρα κἀπὶ τούτοις τήν τε γυναῖκα καὶ τὰ τέκνα, μόνον οὐχ ὑπαπαντῶντος ἑκάστου τῷ ξίφει καὶ σπεύδοντος φθάσαι τοὺς πολεμίους. ὁ δὲ διελθὼν πᾶσαν τὴν γενεὰν καὶ περίοπτος ἐπιστὰς τοῖς σώμασιν τήν τε δεξιὰν ἀνατείνας, ὡς μηδένα λαθεῖν, ὅλον εἰς τὴν ἑαυτοῦ σφαγὴν ἐβάπτισεν τὸ ξίφος, ἄξιος μὲν ἐλέους νεανίας δι’ ἀλκὴν σώματος καὶ ψυχῆς παράστημα, τῆς δὲ πρὸς ἀλλοφύλους πίστεως ἕνεκεν ἀκολούθοις πάθεσι χρησάμενος.", "st": "2.18.4"}, {"sp": "N", "t": "Πρὸς δὲ τὴν ἐν Σκυθοπόλει φθορὰν αἱ λοιπαὶ πόλεις ἐπανίσταντο τοῖς καθ’ ἑαυτὴν Ἰουδαίοις ἑκάστη, καὶ πεντακοσίους μὲν ἐπὶ δισχιλίοις Ἀσκαλωνῖται, Πτολεμαεῖς δὲ δισχιλίους ἀνεῖλον ἔδησάν τ’ οὐκ ὀλίγους. καὶ Τύριοι συχνοὺς μὲν διεχειρίσαντο, πλείστους δ’ αὐτῶν δεσμώτας ἐφρούρουν, Ἱππηνοί τε καὶ Γαδαρεῖς ὁμοίως τοὺς μὲν θρασυτέρους ἀπεσκευάσαντο, τοὺς δὲ φοβεροὺς διὰ φυλακῆς εἶχον, αἵ τε λοιπαὶ πόλεις τῆς Συρίας, ὅπως ἑκάστη πρὸς τὸ Ἰουδαϊκὸν ἢ μίσους ἢ δέους εἶχον. μόνοι δὲ Ἀντιοχεῖς καὶ Σιδώνιοι καὶ Ἀπαμεῖς ἐφείσαντο τῶν μετοικούντων καὶ οὔτε ἀνελεῖν τινας Ἰουδαίων ὑπέμειναν οὔτε δῆσαι, τάχα μὲν καὶ διὰ τὸ σφέτερον πλῆθος ὑπερορῶντες αὐτῶν πρὸς τὰ κινήματα, τὸ πλέον δὲ ἔμοιγε δοκεῖν οἴκτῳ πρὸς οὓς οὐδὲν ἑώρων νεωτερίζοντας. Γερασηνοί τε οὔτε εἰς τοὺς ἐμμείναντας ἐπλημμέλησαν καὶ τοὺς ἐξελθεῖν ἐθελήσαντας προέπεμψαν μέχρι τῶν ὅρων.", "st": "2.18.5"}, {"sp": "N", "t": "Συνέστη δὲ καὶ κατὰ τὴν Ἀγρίππα βασιλείαν ἐπιβουλὴ κατὰ Ἰουδαίων. αὐτὸς γὰρ ἐπεπόρευτο πρὸς Κέστιον Γάλλον εἰς Ἀντιόχειαν, καταλέλειπτο δὲ διοικεῖν τὰ πράγματα τούτου τῶν ἑταίρων τις τοὔνομα Νόαρος, Σοαίμῳ τῷ βασιλεῖ προσήκων κατὰ γένος. ἧκον δ’ ἐκ τῆς Βαταναίας ἑβδομήκοντα τὸν ἀριθμὸν ἄνδρες οἱ κατὰ γένος καὶ σύνεσιν τῶν πολιτῶν δοκιμώτατοι στρατιὰν αἰτοῦντες, ἵν’ εἴ τι γένοιτο κίνημα καὶ περὶ σφᾶς, ἔχοιεν ἀξιόχρεω φυλακὴν κωλύειν τοὺς ἐπανισταμένους. τούτους ὁ Νόαρος ἐκπέμψας νύκτωρ τῶν βασιλικῶν τινας ὁπλιτῶν ἅπαντας ἀναιρεῖ, τολμήσας μὲν τοὖργον δίχα τῆς Ἀγρίππα γνώμης, διὰ δὲ φιλαργυρίαν ἄμετρον εἰς τοὺς ὁμοφύλους ἑλόμενος ἀσεβεῖν τὴν βασιλείαν διέφθειρεν· διετέλει τε ὠμῶς εἰς τὸ ἔθνος παρανομῶν, μέχρι πυθόμενος Ἀγρίππας ἀνελεῖν μὲν αὐτὸν ᾐδέσθη διὰ Σόαιμον, ἔπαυσεν δὲ τῆς ἐπιτροπῆς. οἱ δὲ στασιασταὶ καταλαβόμενοί τι φρούριον, ὃ καλεῖται μὲν Κύπρος, καθύπερθεν δ’ ἦν Ἱεριχοῦντος, τοὺς μὲν φρουροὺς ἀπέσφαξαν, τὰ δ’ ἐρύματα κατέρριψαν εἰς γῆν. κατὰ δὲ τὰς αὐτὰς ἡμέρας καὶ τῶν ἐν Μαχαιροῦντι Ἰουδαίων τὸ πλῆθος ἔπειθεν τοὺς φρουροῦντας Ῥωμαίους ἐκλείπειν τὸ φρούριον καὶ παραδιδόναι σφίσιν. οἱ δὲ τὴν ἐκ βίας ἀφαίρεσιν εὐλαβηθέντες συντίθενται πρὸς αὐτοὺς ἐκχωρήσειν ὑπόσπονδοι, καὶ λαβόντες τὰ πιστὰ παραδιδόασι τὸ φρούριον, ὅπερ φυλακῇ κρατυνάμενοι κατεῖχον οἱ Μαχαιρῖται.", "st": "2.18.6"}, {"sp": "N", "t": "Κατὰ δὲ τὴν Ἀλεξάνδρειαν ἀεὶ μὲν ἦν στάσις πρὸς τὸ Ἰουδαϊκὸν τοῖς ἐπιχωρίοις ἀφ’ οὗ χρησάμενος προθυμοτάτοις κατὰ τῶν Αἰγυπτίων Ἰουδαίοις Ἀλέξανδρος γέρας τῆς συμμαχίας ἔδωκεν τὸ μετοικεῖν κατὰ τὴν πόλιν ἐξ ἴσου † μοίρας πρὸς τοὺς Ἕλληνας. διέμεινεν δ’ αὐτοῖς ἡ τιμὴ καὶ παρὰ τῶν διαδόχων, οἳ καὶ τόπον ἴδιον αὐτοῖς ἀφώρισαν, ὅπως καθαρωτέραν ἔχοιεν τὴν δίαιταν ἧττον ἐπιμισγομένων τῶν ἀλλοφύλων, καὶ χρηματίζειν ἐπέτρεψαν Μακεδόνας, ἐπεί τε Ῥωμαῖοι κατεκτήσαντο τὴν Αἴγυπτον, οὔτε Καῖσαρ ὁ πρῶτος οὔτε τῶν μετ’ αὐτόν τις ὑπέμεινεν τὰς ἀπ’ Ἀλεξάνδρου τιμὰς Ἰουδαίων ἐλαττῶσαι. συμβολαὶ δ’ ἦσαν αὐτῶν ἀδιάλειπτοι πρὸς τοὺς Ἕλληνας, καὶ τῶν ἡγεμόνων πολλοὺς ὁσημέραι παρ’ ἀμφοῖν κολαζόντων ἡ στάσις μᾶλλον παρωξύνετο. τότε δ’ ὡς καὶ παρὰ τοῖς ἄλλοις ἐτετάρακτο, μᾶλλον ἐξήφθη τὰ παρ’ ἐκείνοις. καὶ δὴ τῶν Ἀλεξανδρέων ἐκκλησιαζόντων περὶ ἧς ἔμελλον ἐκπέμπειν πρεσβείας ἐπὶ Νέρωνα συνερρύησαν μὲν εἰς τὸ ἀμφιθέατρον ἅμα τοῖς Ἕλλησιν συχνοὶ Ἰουδαίων, κατιδόντες δὲ αὐτοὺς οἱ διάφοροι παραχρῆμα ἀνεβόων πολεμίους καὶ κατασκόπους λέγοντες· ἔπειτα ἀναπηδήσαντες ἐπέβαλλον τὰς χεῖρας αὐτοῖς. οἱ μὲν οὖν λοιποὶ φεύγοντες διεσπάρησαν, τρεῖς δὲ ἄνδρας συλλαβόντες ἔσυρον ὡς ζῶντας καταφλέξοντες. ἤρθη δὲ πᾶν τὸ Ἰουδαϊκὸν ἐπὶ τὴν ἄμυναν, καὶ τὸ μὲν πρῶτον λίθοις τοὺς Ἕλληνας ἔβαλλον, αὖθις δὲ λαμπάδας ἁρπασάμενοι πρὸς τὸ ἀμφιθέατρον ὥρμησαν ἀπειλοῦντες ἐν αὐτῷ καταφλέξειν τὸν δῆμον αὔτανδρον. κἂν ἔφθησαν τοῦτο δράσαντες, εἰ μὴ τοὺς θυμοὺς αὐτῶν ἀνέκοψεν Τιβέριος Ἀλέξανδρος ὁ τῆς πόλεως ἡγεμών. οὐ μὴν οὗτός γε ἀπὸ τῶν ὅπλων ἤρξατο σωφρονίζειν, ἀλλ’ ὑποπέμψας τοὺς γνωρίμους αὐτοῖς παύσασθαι παρεκάλει καὶ μὴ καθ’ ἑαυτῶν ἐρεθίζειν τὸ Ῥωμαίων στράτευμα. καταχλευάζοντες δὲ τῆς παρακλήσεως οἱ στασιώδεις ἐβλασφήμουν τὸν Τιβέριον.", "st": "2.18.7"}, {"sp": "N", "t": "Κἀκεῖνος συνιδὼν ὡς χωρὶς μεγάλης συμφορᾶς οὐκ ἂν παύσαιντο νεωτερίζοντες, ἐπαφίησιν αὐτοῖς τὰ κατὰ τὴν πόλιν Ῥωμαίων δύο τάγματα καὶ σὺν αὐτοῖς δισχιλίους στρατιώτας κατὰ τύχην παρόντας εἰς τὸν Ἰουδαίων ὄλεθρον ἐκ Λιβύης· ἐπέτρεψεν δὲ οὐ μόνον ἀναιρεῖν, ἀλλὰ καὶ τὰς κτήσεις αὐτῶν διαρπάζειν καὶ τὰς οἰκίας καταφλέγειν. οἱ δ’ ὁρμήσαντες εἰς τὸ καλούμενον Δέλτα, συνῴκιστο γὰρ ἐκεῖ τὸ Ἰουδαϊκόν, ἐτέλουν τὰς ἐντολάς, οὐ μὴν ἀναιμωτί· συστραφέντες γὰρ οἱ Ἰουδαῖοι καὶ τοὺς ἄμεινον ὡπλισμένους ἑαυτῶν προταξάμενοι μέχρι πλείστου μὲν ἀντέσχον, ἅπαξ δ’ ἐγκλίναντες ἀνέδην διεφθείροντο. καὶ παντοῖος ἦν αὐτῶν ὄλεθρος, τῶν μὲν ἐν τῷ πεδίῳ καταλαμβανομένων, τῶν δ’ εἰς τὰς οἰκίας συνωθουμένων. ὑπεπίμπρασαν δὲ καὶ ταύτας οἱ Ῥωμαῖοι προδιαρπάζοντες τὰ ἔνδον, καὶ οὔτε νηπίων ἔλεος αὐτοὺς οὔτε αἰδὼς εἰσῄει γερόντων, ἀλλὰ διὰ πάσης ἡλικίας ἐχώρουν κτείνοντες, ὡς ἐπικλυσθῆναι μὲν αἵματι πάντα τὸν χῶρον, πέντε δὲ μυριάδες ἐσωρεύθησαν νεκρῶν, περιελείφθη δ’ ἂν οὐδὲ τὸ λοιπόν, εἰ μὴ πρὸς ἱκετηρίας ἐτράποντο. κατοικτείρας δ’ αὐτοὺς Ἀλέξανδρος ἀναχωρεῖν τοὺς Ῥωμαίους ἐκέλευσεν. οἱ μὲν οὖν ἐξ ἔθους τὸ πειθήνιον ἔχοντες ἅμα νεύματι τοῦ φονεύειν ἐπαύσαντο, τὸ δημοτικὸν δὲ τῶν Ἀλεξανδρέων δι’ ὑπερβολὴν μίσους δυσανάκλητον ἦν καὶ μόλις ἀπεσπᾶτο τῶν σωμάτων.", "st": "2.18.8"}, {"sp": "N", "t": "Τοιοῦτον μὲν τὸ κατὰ τὴν Ἀλεξάνδρειαν πάθος συνηνέχθη· Κεστίῳ δὲ οὐκέτι ἠρεμεῖν ἐδόκει πανταχοῦ τῶν Ἰουδαίων ἐκπεπολεμωμένων. ἀναλαβὼν δὲ ἀπὸ τῆς Ἀντιοχείας τὸ μὲν δωδέκατον τάγμα πλῆρες, ἀπὸ δὲ τῶν λοιπῶν ἀνὰ δισχιλίους ἐπιλέκτους, πεζῶν τε ἓξ σπείρας καὶ τέσσαρας ἴλας ἱππέων, πρὸς αἷς τὰς παρὰ τῶν βασιλέων συμμαχίας, Ἀντιόχου μὲν δισχιλίους ἱππεῖς καὶ πεζοὺς τρισχιλίους τοξότας πάντας, Ἀγρίππα δὲ πεζοὺς μὲν τοὺς ἴσους ἱππεῖς δὲ δισχιλίων ἐλάττους, εἵπετο δὲ καὶ Σόαιμος μετὰ τετρακισχιλίων, ὧν ἦσαν ἱππεῖς ἡ τρίτη μοῖρα καὶ τὸ πλέον τοξόται, προῆλθεν εἰς Πτολεμαΐδα. πλεῖστοι δὲ κἀκ τῶν πόλεων ἐπίκουροι συνελέγησαν, ἐμπειρίᾳ μὲν ἡττώμενοι τῶν στρατιωτῶν, ταῖς δὲ προθυμίαις καὶ τῷ κατὰ Ἰουδαίων μίσει τὸ λεῖπον ἐν ταῖς ἐπιστήμαις ἀντιπληροῦντες. παρῆν δὲ καὶ αὐτὸς Ἀγρίππας Κεστίῳ τῆς τε ὁδοῦ καὶ τῶν συμφερόντων ἐξηγούμενος. ἀναλαβὼν δὲ μέρος τῆς δυνάμεως Κέστιος ὥρμησεν ἐπὶ πόλιν καρτερὰν τῆς Γαλιλαίας Χαβουλών, ἣ καλεῖται ἀνδρῶν, διορίζει δὲ ἀπὸ τοῦ ἔθνους τὴν Πτολεμαΐδα. καὶ καταλαβὼν αὐτὴν ἔρημον μὲν ἀνδρῶν, ἀναπεφεύγει γὰρ τὸ πλῆθος εἰς τὰ ὄρη, πλήρη δὲ παντοίων κτημάτων, τὰ μὲν ἐφῆκεν τοῖς στρατιώταις διαρπάζειν, τὸ δὲ ἄστυ καίτοι θαυμάσας τοῦ κάλλους ἔχον τὰς οἰκίας ὁμοίως ταῖς ἐν Τύρῳ καὶ Σιδῶνι καὶ Βηρυτῷ δεδομημένας, ἐνέπρησεν. ἔπειτα τὴν χώραν καταδραμὼν καὶ διαρπάσας μὲν πᾶν τὸ προσπῖπτον καταφλέξας δὲ τὰς πέριξ κώμας ὑπέστρεψεν εἰς τὴν Πτολεμαΐδα. πρὸς δὲ ταῖς ἁρπαγαῖς ἔτι τῶν Σύρων ὄντων καὶ τὸ πλέον Βηρυτίων ἀναθαρσήσαντες οἱ Ἰουδαῖοι, καὶ γὰρ ἀποκεχωρηκότα συνίεσαν Κέστιον, τοῖς ἀπολειφθεῖσιν ἀδοκήτως ἐπέπεσον καὶ περὶ δισχιλίους αὐτῶν διέφθειραν.", "st": "2.18.9"}, {"sp": "N", "t": "Ὁ δὲ Κέστιος ἀναζεύξας ἀπὸ τῆς Πτολεμαΐδος αὐτὸς μὲν εἰς Καισάρειαν ἀφικνεῖται, μοῖραν δὲ τῆς στρατιᾶς προέπεμψεν εἰς Ἰόππην, προστάξας, εἰ μὲν καταλαβέσθαι δυνηθεῖεν τὴν πόλιν, φρουρεῖν, εἰ δὲ προαίσθοιντο τὴν ἔφοδον, περιμένειν αὐτόν τε καὶ τὴν ἄλλην δύναμιν. τῶν δὲ οἱ μὲν κατὰ θάλασσαν οἱ δὲ κατὰ γῆν ἐπειχθέντες ἀμφοτέρωθεν αἱροῦσιν τὴν πόλιν ῥᾳδίως· καὶ μηδὲ φυγεῖν φθασάντων τῶν οἰκητόρων, οὐχ ὅπως παρασκευάσασθαι πρὸς μάχην, ἐμπεσόντες ἅπαντας ἀνεῖλον σὺν ταῖς γενεαῖς καὶ τὴν πόλιν διαρπάσαντες ἐνέπρησαν· ὁ δὲ ἀριθμὸς τῶν φονευθέντων τετρακόσιοι πρὸς ὀκτακισχιλίοις. ὁμοίως δὲ καὶ εἰς τὴν ὅμορον τῆς Καισαρείας Ναρβατηνὴν τοπαρχίαν ἔπεμψεν συχνοὺς τῶν ἱππέων, οἳ τήν τε γῆν ἔτεμον καὶ πολὺ πλῆθος διέφθειραν τῶν ἐπιχωρίων τάς τε κτήσεις διήρπασαν καὶ τὰς κώμας κατέφλεξαν.", "st": "2.18.10"}, {"sp": "N", "t": "Εἰς δὲ τὴν Γαλιλαίαν ἀπέστειλεν Καισέννιον Γάλλον ἡγεμόνα τοῦ δωδεκάτου τάγματος παραδοὺς δύναμιν ὅσην ἀρκέσειν πρὸς τὸ ἔθνος ὑπελάμβανεν. τοῦτον ἡ καρτερωτάτη τῆς Γαλιλαίας πόλις Σέπφωρις μετ’ εὐφημίας δέχεται, καὶ πρὸς τὴν ταύτης εὐβουλίαν αἱ λοιπαὶ πόλεις ἠρέμουν. τὸ δὲ στασιῶδες καὶ λῃστρικὸν πᾶν ἔφυγεν εἰς τὸ μεσαίτατον τῆς Γαλιλαίας ὄρος, ὃ κεῖται μὲν ἀντικρὺ τῆς Σεπφώρεως, καλεῖται δὲ Ἀσαμών. τούτοις ὁ Γάλλος ἐπῆγε τὴν δύναμιν. οἱ δὲ ἕως μὲν ἦσαν ὑπερδέξιοι, ῥᾳδίως τοὺς Ῥωμαίους ἠμύναντο προσιόντας καὶ πρὸς διακοσίους αὐτῶν ἀνεῖλον, περιελθόντων δὲ καὶ γενομένων ἐν τοῖς ὑψηλοτέροις ἡττῶντο ταχέως, καὶ οὔτε γυμνῆτες ὁπλίτας συστάδην ἔφερον οὔτε ἐν τῇ τροπῇ τοὺς ἱππεῖς ἐξέφευγον, ὥστε ὀλίγους μὲν ἐν ταῖς δυσχωρίαις διαλαθεῖν, ἀναιρεθῆναι δὲ ὑπὲρ δισχιλίους.", "st": "2.18.11"}, {"sp": "N", "t": "Γάλλος μὲν οὖν ὡς οὐδὲν ἔτι ἑώρα κατὰ τὴν Γαλιλαίαν νεωτεριζόμενον, ὑπέστρεφεν μετὰ τῆς στρατιᾶς εἰς Καισάρειαν· Κέστιος δὲ μετὰ πάσης τῆς δυνάμεως ἀναζεύξας ἐνέβαλεν εἰς Ἀντιπατρίδα, καὶ πυθόμενος ἔν τινι πύργῳ Ἀφεκοῦ καλουμένῳ συνηθροῖσθαι Ἰουδαίων δύναμιν οὐκ ὀλίγην προέπεμπεν τοὺς συμβαλοῦντας. οἱ δὲ πρὶν εἰς χεῖρας ἐλθεῖν δέει τοὺς Ἰουδαίους διεσκέδασαν, ἐπελθόντες δὲ ἔρημον τὸ στρατόπεδον καὶ τὰς πέριξ κώμας ἐνέπρησαν. ἀπὸ δὲ τῆς Ἀντιπατρίδος Κέστιος εἰς Λύδδα προελθὼν κενὴν ἀνδρῶν τὴν πόλιν καταλαμβάνει· διὰ γὰρ τὴν τῆς σκηνοπηγίας ἑορτὴν ἀναβεβήκει πᾶν τὸ πλῆθος εἰς Ἱεροσόλυμα. πεντήκοντα δὲ τῶν παραφανέντων διαφθείρας καὶ τὸ ἄστυ κατακαύσας ἐχώρει πρόσω, καὶ διὰ Βαιθώρων ἀναβὰς στρατοπεδεύεται κατά τινα χῶρον Γαβαὼ καλούμενον, ἀπέχοντα τῶν Ἱεροσολύμων πεντήκοντα σταδίους.", "st": "2.19.1"}, {"sp": "N", "t": "Οἱ δὲ Ἰουδαῖοι κατιδόντες ἤδη πλησιάζοντα τῇ μητροπόλει τὸν πόλεμον, ἀφέμενοι τὴν ἑορτὴν ἐχώρουν ἐπὶ τὰ ὅπλα, καὶ μέγα τῷ πλήθει θαρροῦντες ἄτακτοι μετὰ κραυγῆς ἐξεπήδων ἐπὶ τὴν μάχην μηδὲ τῆς ἀργῆς ἑβδομάδος ἔννοιαν λαβόντες· ἦν γὰρ δὴ τὸ μάλιστα παρ’ αὐτοῖς θρησκευόμενον σάββατον. ὁ δ’ ἐκσείσας αὐτοὺς τῆς εὐσεβείας θυμὸς ἐποίησεν πλεονεκτῆσαι καὶ κατὰ τὴν μάχην· μετὰ τοσαύτης γοῦν ὁρμῆς τοῖς Ῥωμαίοις προσέπεσον, ὡς διαρρῆξαι τὰς τάξεις αὐτῶν καὶ διὰ μέσων χωρεῖν ἀναιροῦντας. εἰ δὲ μὴ τῷ χαλασθέντι τῆς φάλαγγος οἵ τε ἱππεῖς ἐκπεριελθόντες ἐπήμυναν καὶ τοῦ πεζοῦ τὸ μὴ σφόδρα κάμνον, κἂν ἐκινδύνευσεν ὅλῃ τῇ δυνάμει Κέστιος. ἀπέθανον δὲ Ῥωμαίων πεντακόσιοι δεκαπέντε· τούτων ἦσαν οἱ τετρακόσιοι πεζοί, τὸ δὲ λοιπὸν ἱππεῖς· τῶν δὲ Ἰουδαίων δύο πρὸς τοῖς εἴκοσι. γενναιότατοι δ’ αὐτῶν ἔδοξαν οἱ Μονοβάζου τοῦ τῆς Ἀδιαβηνῆς βασιλέως συγγενεῖς, Μονόβαζός τε καὶ Κενεδαῖος, μεθ’ οὓς ὁ Περαΐτης Νίγερ καὶ Σίλας ὁ Βαβυλώνιος αὐτομολήσας εἰς τοὺς Ἰουδαίους ἀπ’ Ἀγρίππα τοῦ βασιλέως· ἐστρατεύετο γὰρ παρ’ αὐτῷ. κατὰ πρόσωπον μὲν οὖν ἀνακοπέντες Ἰουδαῖοι πρὸς τὴν πόλιν ὑπέστρεφον, κατόπιν δὲ τοῖς Ῥωμαίοις ἐπὶ τὴν Βεθώραν ἀνιοῦσιν προσπεσὼν ὁ τοῦ Γιώρα Σίμων πολὺ τῆς οὐραγίας ἐσπάραξεν καὶ συχνὰ τῶν σκευοφόρων ἀποσπάσας ἤγαγεν εἰς τὴν πόλιν. μένοντος δὲ τοῦ Κεστίου κατὰ χώραν τρισὶν ἡμέραις οἱ Ἰουδαῖοι τὰ μετέωρα κατειληφότες ἐπετήρουν τὰς παρόδους δῆλοί τε ἦσαν οὐκ ἠρεμήσοντες ἀρξαμένων τῶν Ῥωμαίων ὁδεύειν.", "st": "2.19.2"}, {"sp": "N", "t": "Ἔνθα δὴ κατιδὼν Ἀγρίππας οὐδὲ τὰ Ῥωμαίων ἀκίνδυνα πλήθους ἀπείρου πολεμίων τὰ ὄρη περισχόντος ἔκρινεν ἀποπειραθῆναι τῶν Ἰουδαίων λόγοις· ἢ γὰρ πάντας πείσειν καταθέσθαι τὸν πόλεμον ἢ τῶν ἐναντιωθέντων ἀποστήσειν τὸ μὴ συμφρονοῦν. ἔπεμψεν οὖν τῶν παρ’ ἑαυτῷ τοὺς μάλιστα γνωρίμους ἐκείνοις Βόρκιόν τε καὶ Φοῖβον, δεξιάς τε παρὰ Κεστίου καὶ συγγνώμην παρὰ Ῥωμαίοις ἀσφαλῆ περὶ τῶν ἡμαρτημένων ὑπισχνούμενος, εἰ τὰ ὅπλα ῥίψαντες πρὸς αὐτοὺς μεταβάλοιντο. δείσαντες δὲ οἱ στασιασταὶ μὴ πᾶν τὸ πλῆθος ἀδείας ἐλπίδι πρὸς τὸν Ἀγρίππαν μεταβάληται, τοὺς ἀπ’ αὐτοῦ πρεσβεύοντας ὥρμησαν ἀνελεῖν. καὶ πρὶν ἢ φθέγξασθαι τὸν μὲν Φοῖβον διέφθειραν, ὁ δὲ Βόρκιος τρωθεὶς ἔφθη διαφυγεῖν· τοῦ δήμου δὲ τοὺς ἀγανακτήσαντας λίθοις καὶ ξύλοις παίοντες εἰς τὸ ἄστυ συνήλασαν.", "st": "2.19.3"}, {"sp": "N", "t": "Κέστιος δὲ τὴν πρὸς ἀλλήλους αὐτῶν ταραχὴν εὔκαιρον ἰδὼν εἰς ἐπίθεσιν ἅπασαν ἐπῆγεν τὴν δύναμιν καὶ τραπέντας μέχρι Ἱεροσολύμων κατεδίωξεν. στρατοπεδευσάμενος δὲ ἐπὶ τοῦ καλουμένου Σκοποῦ, διέχει δ’ οὗτος ἑπτὰ τῆς πόλεως σταδίους, τρισὶ μὲν ἡμέραις οὐκ ἐπεχείρει τῇ πόλει τάχα τι παρὰ τῶν ἔνδον ἐνδοθήσεσθαι προσδοκῶν, εἰς δὲ τὰς πέριξ κώμας ἐφ’ ἁρπαγὴν σίτου πολλοὺς διαφῆκεν τῶν στρατιωτῶν· τῇ τετάρτῃ δέ, ἥτις ἦν τριακὰς Ὑπερβερεταίου μηνός, διατάξας τὴν στρατιὰν εἰσῆγεν εἰς τὴν πόλιν. ὁ μὲν οὖν δῆμος ὑπὸ τοῖς στασιασταῖς ἔμφρουρος ἦν, οἱ δὲ στασιασταὶ τὴν εὐταξίαν τῶν Ῥωμαίων καταπλαγέντες τῶν μὲν ἔξω τῆς πόλεως μερῶν εἶκον, εἰς δὲ τὴν ἐνδοτέρω καὶ τὸ ἱερὸν ἀνεχώρουν. Κέστιος δὲ παρελθὼν ὑποπίμπρησιν τήν τε Βεθεζὰν προσαγορευομένην καὶ τὴν Καινόπολιν καὶ τὸ καλούμενον Δοκῶν ἀγοράν, ἔπειτα πρὸς τὴν ἄνω πόλιν ἐλθὼν ἀντικρὺ τῆς βασιλικῆς αὐλῆς ἐστρατοπεδεύετο. κἂν εἴπερ ἠθέλησεν κατ’ αὐτὴν ἐκείνην τὴν ὥραν ἐντὸς τῶν τειχέων βιάσασθαι, παραυτίκα τὴν πόλιν ἔσχεν καὶ τὸν πόλεμον συνέβη καταλελύσθαι· ἀλλὰ γὰρ ὅ τε στρατοπεδάρχης Τυράννιος Πρῖσκος καὶ τῶν ἱππάρχων οἱ πλεῖστοι χρήμασιν ὑπὸ Φλώρου δεκασθέντες ἀπέστρεψαν αὐτὸν τῆς ἐπιχειρήσεως. καὶ παρὰ τὴν αἰτίαν ταύτην ὅ τε πόλεμος ἐπὶ τοσοῦτον μῆκος προύβη καὶ ἀνηκέστων Ἰουδαίους συμφορῶν ἀναπλησθῆναι συνέπεσεν.", "st": "2.19.4"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ πολλοὶ τῶν γνωρίμων δημοτῶν Ἀνάνῳ τῷ Ἰωνάθου παιδὶ πεισθέντες ἐκάλουν τὸν Κέστιον ὡς ἀνοίξοντες αὐτῷ τὰς πύλας. ὁ δὲ καὶ πρὸς ὀργὴν ὑπεριδὼν καὶ μὴ πάνυ πιστεύσας διεμέλλησεν, ἕως οἱ στασιασταὶ τὴν προδοσίαν αἰσθόμενοι τοὺς μὲν περὶ τὸν Ἄνανον ἀπὸ τοῦ τείχους κατέβαλον καὶ λίθοις παίοντες συνήλασαν εἰς τὰς οἰκίας, αὐτοὶ δὲ διαστάντες ἀπὸ τῶν πύργων τοὺς ἀποπειρωμένους τοῦ τείχους ἔβαλλον. πέντε μὲν οὖν ἡμέραις πάντοθεν ἐπιχειροῦσιν τοῖς Ῥωμαίοις ἀμήχανος ἦν ἡ προσβολή, τῇ δ’ ἐπιούσῃ ἀναλαβὼν ὁ Κέστιος τῶν τε ἐπιλέκτων συχνοὺς καὶ τοὺς τοξότας κατὰ τὸ προσάρκτιον ἐπεχείρει κλίμα τῷ ἱερῷ. Ἰουδαῖοι δὲ ἀπὸ τῆς στοᾶς εἶργον, καὶ πολλάκις μὲν ἀπεκρούσαντο τοὺς τῷ τείχει προσελθόντας, τέλος δὲ τῷ πλήθει τῶν βελῶν ἀνακοπέντες ὑπεχώρησαν. τῶν δὲ Ῥωμαίων οἱ πρῶτοι τοὺς θυρεοὺς ἐξερείσαντες εἰς τὸ τεῖχος καὶ κατὰ τούτων οἱ κατόπιν ἄλλους οἵ τε ἑξῆς ὁμοίως τὴν καλουμένην παρ’ αὐτοῖς χελώνην ἐφράξαντο, καθ’ ἧς τὰ βέλη φερόμενα περιωλίσθανεν ἄπρακτα, μηδὲν δὲ οἱ στρατιῶται κακούμενοι τὸ τεῖχος ὑπέσυρον καὶ τοῦ ἱεροῦ τὴν πύλην ὑποπιμπράναι παρεσκευάζοντο.", "st": "2.19.5"}, {"sp": "N", "t": "Δεινὴ δὲ τοὺς στασιαστὰς ἔκπληξις κατέλαβεν· ἤδη δὲ πολλοὶ διεδίδρασκον ἀπὸ τῆς πόλεως ὡς ἁλωσομένης αὐτίκα. τὸν δὲ δῆμον ἐπὶ τούτοις συνέβαινεν θαρρεῖν, καὶ καθὸ παρείκοιεν οἱ πονηροί, προσῄεσαν αὐτοὶ τὰς πύλας ἀνοίξοντες καὶ δεξόμενοι τὸν Κέστιον ὡς εὐεργέτην. ὃς εἰ βραχὺ τῇ πολιορκίᾳ προσελιπάρησεν, κἂν εὐθέως τὴν πόλιν παρέλαβεν· ἀλλ’ οἶμαι διὰ τοὺς πονηροὺς ἀπεστραμμένος ὁ θεὸς ἤδη καὶ τὰ ἅγια τέλος λαβεῖν ἐπ’ ἐκείνης τῆς ἡμέρας ἐκώλυσεν τὸν πόλεμον.", "st": "2.19.6"}, {"sp": "N", "t": "Ὁ γοῦν Κέστιος οὔτε τὴν τῶν πολιορκουμένων ἀπόγνωσιν οὔτε τοῦ δήμου τὸ φρόνημα συνιδὼν ἐξαίφνης ἀνεκάλεσεν τοὺς στρατιώτας καὶ καταγνοὺς ἐπ’ οὐδεμιᾷ πληγῇ τῶν ἐλπίδων παραλογώτατα ἀπὸ τῆς πόλεως ἀνέζευξεν. πρὸς δὲ τὴν ἀδόκητον αὐτοῦ τροπὴν ἀναθαρσήσαντες οἱ λῃσταὶ κατὰ τῶν ὑστάτων ἐπεξέδραμον καὶ συχνοὺς τῶν ἱππέων καὶ πεζῶν διέφθειραν. τότε μὲν οὖν ἐν τῷ κατὰ τὸν Σκοπὸν αὐλίζεται στρατοπέδῳ Κέστιος, τῇ δ’ ἐπιούσῃ προσωτέρω χωριζόμενος μᾶλλον ἐξεκαλέσατο τοὺς πολεμίους, καὶ τοὺς ὑστάτους αὐτῶν προσκείμενοι διέφθειρον καὶ καθ’ ἑκάτερον τῆς ὁδοῦ περιιόντες ἠκόντιζον εἰς πλαγίους. οὔτε δὲ ἐπιστραφῆναι πρὸς τοὺς κατόπιν τιτρώσκοντας ἐθάρρουν οἱ τελευταῖοι ἄπειρόν τι πλῆθος οἰόμενοι διώκειν καὶ τοὺς κατὰ πλευρὸν ἐγκειμένους ἀναστέλλειν οὐχ ὑπέμενον, αὐτοὶ μὲν ὄντες βαρεῖς καὶ δεδοικότες τὴν τάξιν διασπᾶν, τοὺς δὲ Ἰουδαίους ὁρῶντες κούφους καὶ πρὸς τὰς ἐπιδρομὰς εὐκόλους· ὥστε συνέβαινεν αὐτοῖς πολλὰ κακοῦσθαι μηδὲν ἀντιβλάπτουσιν τοὺς ἐχθρούς. παρ’ ὅλην δὲ τὴν ὁδὸν παιόμενοι καὶ τῆς φάλαγγος ἐκσειόμενοι κατέπιπτον, μέχρι πολλῶν διαφθαρέντων, ἐν οἷς ἦν Πρῖσκος μὲν στρατάρχης τάγματος ἕκτου, Λογγῖνος δὲ χιλίαρχος, ἔπαρχος δὲ ἴλης Αἰμίλιος Ἰούκουνδος ὄνομα, μόλις εἰς Γαβαὼν κατήντησαν ἐπὶ τὸ πρότερον στρατόπεδον, τὰ πολλὰ καὶ τῶν σκευῶν ἀποβαλόντες. ἔνθα δύο μὲν ἡμέρας ἐπέμεινεν ὁ Κέστιος ἀμηχανῶν, ὅ τι χρὴ ποιεῖν, τῇ τρίτῃ δὲ πολλῷ πλείους τοὺς πολεμίους θεασάμενος καὶ πάντα τὰ κύκλῳ μεστὰ Ἰουδαίων ἔγνω καθ’ ἑαυτοῦ τε βραδύνας κἂν ἔτι μείνῃ πλείοσιν χρησόμενος ἐχθροῖς.", "st": "2.19.7"}, {"sp": "N", "t": "Ἵνα δὲ συντονωτέρᾳ χρήσαιτο φυγῇ, τὰ τὴν στρατιὰν ἀνθέλκοντα περικόπτειν προσέταξεν. διαφθαρέντων δὲ τῶν τε ὀρέων καὶ τῶν ὄνων ἔτι δὲ καὶ τῶν ὑποζυγίων πλὴν ὅσα βέλη παρεκόμιζεν καὶ μηχανάς, τούτων γὰρ διὰ τὴν χρείαν περιείχοντο καὶ μάλιστα δεδοικότες, μὴ Ἰουδαίοις κατ’ αὐτῶν ἁλῷ, προῆγε τὴν δύναμιν ἐπὶ Βεθώρων. οἱ δὲ Ἰουδαῖοι κατὰ μὲν τὰς εὐρυχωρίας ἧττον ἐπέκειντο, συνειληθέντων δὲ εἰς τὰ στενὰ καὶ τὴν κατάβασιν οἱ μὲν φθάσαντες εἶργον αὐτοὺς τῆς ἐξόδου, ἄλλοι δὲ τοὺς ὑστάτους κατεώθουν εἰς τὴν φάραγγα, τὸ δὲ πᾶν πλῆθος παρεκταθὲν ὑπὲρ τὸν αὐχένα τῆς ὁδοῦ κατεκάλυπτε τὴν φάλαγγα τοῖς βέλεσιν. ἔνθα καὶ τῶν πεζῶν ἀμηχανούντων προσαμύνειν ἑαυτοῖς ἐπισφαλέστερος τοῖς ἱππεῦσιν ὁ κίνδυνος ἦν· οὔτε γὰρ ἐν τάξει κατὰ τῆς ὁδοῦ βαδίζειν ἐδύναντο βαλλόμενοι, καὶ τὸ πρόσαντες ἐπὶ τοὺς πολεμίους ἱππάσιμον οὐκ ἦν· τὸ δὲ ἐπὶ θάτερα κρημνοὶ καὶ φάραγγες, εἰς οὓς ἀποσφαλέντες κατεφθείροντο, καὶ οὔτε φυγῆς τις τόπον οὔτε ἀμύνης εἶχεν ἐπίνοιαν, ἀλλ’ ὑπ’ ἀμηχανίας ἐπ’ οἰμωγὴν ἐτράποντο καὶ τοὺς ἐν ἀπογνώσεσιν ὀδυρμούς· ἀντήχει δ’ αὐτοῖς τὸ παρὰ Ἰουδαίων ἐγκέλευσμα καὶ κραυγὴ χαιρόντων ἅμα καὶ τεθυμωμένων. ὀλίγου δὲ δεῖν πᾶσαν ἀνήρπασαν τὴν ἅμα Κεστίῳ δύναμιν, εἰ μὴ νὺξ ἐπέλαβεν, ἐν ᾗ Ῥωμαῖοι μὲν εἰς τὴν Βεθώραν κατέφυγον, Ἰουδαῖοι δὲ πάντα τὰ κύκλῳ περισχόντες ἐφρούρουν αὐτῶν τὴν ἔξοδον.", "st": "2.19.8"}, {"sp": "N", "t": "Ἔνθα δὴ Κέστιος τὴν φανερὰν ὁδὸν ἀπογνοὺς δρασμὸν ἐβουλεύετο καὶ διακρίνας τοὺς εὐψυχοτάτους στρατιώτας ὡσεὶ τετρακοσίους ἐπέστησεν τῶν δωμάτων, προστάξας ἀναβοᾶν τὰ σημεῖα τῶν ἐν τοῖς στρατοπέδοις φυλάκων, ὅπως Ἰουδαῖοι πᾶσαν οἴωνται τὴν δύναμιν κατὰ χώραν μένειν· αὐτὸς δὲ τοὺς λοιποὺς ἀναλαβὼν ἡσυχῆ τριάκοντα πρόεισιν σταδίους. ἕωθεν δὲ Ἰουδαῖοι κατιδόντες ἔρημον τὴν ἔπαυλιν αὐτῶν ἐπὶ τοὺς ἐξαπατήσαντας τετρακοσίους ἔδραμον, κἀκείνους μὲν ταχέως κατηκόντισαν, ἐδίωκον δὲ τὸν Κέστιον. ὁ δὲ τῆς τε νυκτὸς οὐκ ὀλίγον προειλήφει καὶ συντονώτερον ἔφευγεν μεθ’ ἡμέραν, ὥστε τοὺς στρατιώτας ὑπ’ ἐκπλήξεως καὶ δέους τάς τε ἑλεπόλεις καὶ τοὺς ὀξυβελεῖς καὶ τὰ πολλὰ τῶν ἄλλων ὀργάνων καταλιπεῖν, ἃ τότε Ἰουδαῖοι λαβόντες αὖθις ἐχρήσαντο κατὰ τῶν ἀφέντων. προῆλθον δὲ τοὺς Ῥωμαίους διώκοντες μέχρι Ἀντιπατρίδος. ἔπειθ’ ὡς οὐ κατελάμβανον, ὑποστρέφοντες τάς τε μηχανὰς ᾖρον καὶ τοὺς νεκροὺς ἐσύλων τήν τε ἀπολειφθεῖσαν λείαν συνῆγον καὶ μετὰ παιάνων εἰς τὴν μητρόπολιν ἐπαλινδρόμουν, αὐτοὶ μὲν ὀλίγους ἀποβεβλημένοι παντάπασιν, τῶν δὲ Ῥωμαίων καὶ τῶν συμμάχων πεζοὺς μὲν πεντακισχιλίους καὶ τριακοσίους ἀνῃρηκότες, ἱππεῖς δὲ ὀγδοήκοντα καὶ τετρακοσίους. τάδε μὲν οὖν ἐπράχθη Δίου μηνὸς ὀγδόῃ δωδεκάτῳ τῆς Νέρωνος ἡγεμονίας ἔτει.", "st": "2.19.9"}, {"sp": "N", "t": "Μετὰ δὲ τὴν Κεστίου συμφορὰν πολλοὶ τῶν ἐπιφανῶν Ἰουδαίων ὥσπερ βαπτιζομένης νηὸς ἀπενήχοντο τῆς πόλεως. Κοστόβαρος γοῦν καὶ Σάουλος ἀδελφοὶ σὺν Φιλίππῳ τῷ Ἰακίμου, στρατοπεδάρχης δ’ ἦν οὗτος Ἀγρίππα τοῦ βασιλέως, διαδράντες ἐκ τῆς πόλεως ᾤχοντο πρὸς Κέστιον· ὁ δὲ σὺν τούτοις κατὰ τὴν βασιλικὴν αὐλὴν πολιορκηθεὶς Ἀντίπας ὑπεριδὼν τὴν φυγὴν αὖθις ὡς ὑπὸ τῶν στασιαστῶν διεφθάρη δηλώσομεν. Κέστιος δὲ τοὺς περὶ Σάουλον ἀξιώσαντας ἀνέπεμψεν εἰς Ἀχαΐαν πρὸς Νέρωνα τήν τε αὐτῶν δηλώσοντας ἀνάγκην καὶ τὰς αἰτίας τοῦ πολέμου τρέψοντας εἰς Φλῶρον· τὴν γὰρ ἐπ’ ἐκεῖνον ὀργὴν κουφίσειν καὶ τοὺς ἑαυτοῦ κινδύνους ἤλπισεν.", "st": "2.20.1"}, {"sp": "N", "t": "Κἀν τούτῳ Δαμασκηνοὶ τὴν τῶν Ῥωμαίων φθορὰν πυθόμενοι τοὺς παρ’ ἑαυτοῖς Ἰουδαίους ἀνελεῖν ἐσπούδασαν. καὶ καθὸ μὲν εἶχον αὐτοὺς ἐν τῷ γυμνασίῳ συνηθροισμένους πάλαι διὰ τὰς ὑποψίας τοῦτο πραγματευσάμενοι, ῥᾴστην τὴν ἐπιχείρησιν ἐδόκουν· ἐδεδοίκεισαν δὲ τὰς ἑαυτῶν γυναῖκας ἁπάσας πλὴν ὀλίγων ὑπηγμένας τῇ Ἰουδαϊκῇ θρησκείᾳ· διὸ μέγιστος αὐτοῖς ἀγὼν ἐγένετο λαθεῖν ἐκείνας. τοὺς δὲ Ἰουδαίους ὡς ἂν ἐν στενῷ χωρίῳ τὸν ἀριθμὸν μυρίους καὶ πεντακοσίους πάντας ἀνόπλους ἐπελθόντες ὑπὸ μίαν ὥραν ἀδεῶς ἀπέσφαξαν.", "st": "2.20.2"}, {"sp": "N", "t": "Οἱ δὲ διώξαντες τὸν Κέστιον ὡς ὑπέστρεψαν εἰς Ἱεροσόλυμα, τοὺς μὲν βίᾳ τῶν ἔτι ῥωμαϊζόντων τοὺς δὲ πειθοῖ προσήγοντο, καὶ συναθροισθέντες εἰς τὸ ἱερὸν στρατηγοὺς ἀπεδείκνυσαν τοῦ πολέμου πλείονας. ᾑρέθη δὲ Ἰώσηπός τε υἱὸς Γωρίονος καὶ ὁ ἀρχιερεὺς Ἄνανος τῶν τε κατὰ τὴν πόλιν ἁπάντων αὐτοκράτορες καὶ μάλιστα τὰ τείχη τῆς πόλεως ἀνεγείρειν· τὸν γὰρ τοῦ Σίμωνος υἱὸν Ἐλεάζαρον καίπερ ὑφ’ ἑαυτῷ πεποιημένον τὴν Ῥωμαίων λείαν καὶ τὰ ἁρπαγέντα Κεστίου χρήματα, πρὸς οἷς πολλὰ τῶν δημοσίων θησαυρῶν, ὅμως οὐκ ἐπέστησαν ταῖς χρείαις αὐτόν τε τυραννικὸν ὁρῶντες καὶ τοὺς ὑπ’ αὐτῷ ζηλωτὰς δορυφόρων ἔθεσι χρωμένους. κατ’ ὀλίγον γε μὴν ἥ τε χρεία τῶν χρημάτων καὶ γοητεύων Ἐλεάζαρος ἐκπεριῆλθε τὸν δῆμον ὥστε αὐτῷ πειθαρχεῖν περὶ τῶν ὅλων.", "st": "2.20.3"}, {"sp": "N", "t": "Εἰς δὲ τὴν Ἰδουμαίαν ἑτέρους ἐπελέξαντο στρατηγοὺς Ἰησοῦν υἱὸν Σαπφᾶ τῶν ἀρχιερέων ἕνα καὶ Ἐλεάζαρον ἀρχιερέως υἱὸν Νέου· τῷ δ’ ἄρχοντι τότε τῆς Ἰδουμαίας Νίγερι, γένος δ’ ἦν ἐκ τῆς περὶ Ἰορδάνην Περαίας, διὸ καὶ Περαΐτης ἐκαλεῖτο, προσέταξαν ὑποτάσσεσθαι τοῖς στρατηγοῖς. ἠμέλουν δὲ οὐδὲ τῆς ἄλλης χώρας, ἀλλ’ εἰς μὲν Ἱεριχοῦν Ἰώσηπος ὁ Σίμωνος, εἰς δὲ τὴν Περαίαν Μανασσῆς, Θαμνᾶ δὲ τοπαρχίας Ἰωάννης ὁ Ἐσσαῖος στρατηγήσων ἐπέμφθη· προσκεκλήρωτο δ’ αὐτῷ Λύδδα καὶ Ἰόππη καὶ Ἀμμαοῦς. τῆς δὲ Γοφνιτικῆς καὶ Ἀκραβεττηνῆς ὁ Ἀνανίου Ἰωάννης ἡγεμὼν ἀποδείκνυται καὶ τῆς Γαλιλαίας ἑκατέρας Ἰώσηπος Ματθίου· προσώριστο δὲ τῇ τούτου στρατηγίᾳ καὶ Γάμαλα τῶν ταύτῃ πόλεων ὀχυρωτάτη.", "st": "2.20.4"}, {"sp": "N", "t": "Τῶν μὲν οὖν ἄλλων στρατηγῶν ἕκαστος ὡς εἶχεν προθυμίας ἢ συνέσεως διῴκει τὰ πεπιστευμένα· Ἰώσηπος δὲ εἰς τὴν Γαλιλαίαν ἐλθὼν πρῶτον ἐφρόντισεν τῆς εἰς ἑαυτὸν εὐνοίας τῶν ἐπιχωρίων, εἰδὼς ὅτι ταύτῃ πλεῖστα κατορθώσει, κἂν τἆλλα διαμαρτάνῃ. συνιδὼν δὲ ὅτι τοὺς μὲν δυνατοὺς οἰκειώσεται μεταδιδοὺς τῆς ἐξουσίας αὐτοῖς, τὸ δὲ πᾶν πλῆθος εἰ δι’ ἐπιχωρίων καὶ συνήθων τὰ πολλὰ προστάσσοι, τῶν μὲν γηραιῶν ἑβδομήκοντα τοὺς σωφρονεστάτους ἐπιλέξας ἐκ τοῦ ἔθνους κατέστησεν ἄρχοντας ὅλης τῆς Γαλιλαίας, ἑπτὰ δὲ ἐν ἑκάστῃ πόλει δικαστὰς τῶν εὐτελεστέρων διαφόρων· τὰ γὰρ μείζω πράγματα καὶ τὰς φονικὰς δίκας ἐφ’ ἑαυτὸν ἀναπέμπειν ἐκέλευσεν καὶ τοὺς ἑβδομήκοντα.", "st": "2.20.5"}, {"sp": "N", "t": "Καταστησάμενος δὲ τὰ πρὸς ἀλλήλους νόμιμα τῶν κατὰ πόλιν ἐπὶ τὴν ἔξωθεν αὐτῶν ἀσφάλειαν ἐχώρει. καὶ γινώσκων Ῥωμαίους προεμβαλοῦντας εἰς τὴν Γαλιλαίαν τὰ ἐπιτήδεια τῶν χωρίων ἐτείχιζεν, Ἰωτάπατα μὲν καὶ Βηρσαβὲ καὶ Σελάμην, ἔτι δὲ Καφαρεκχὼ καὶ Ἰαφὰ καὶ Σιγὼφ τό τε Ἰταβύριον καλούμενον ὄρος καὶ Ταριχέας καὶ Τιβεριάδα, πρὸς δὲ τούτοις τὰ περὶ Γεννησὰρ τὴν λίμνην σπήλαια κατὰ τὴν κάτω καλουμένην Γαλιλαίαν ἐτειχίσατο, τῆς δὲ ἄνω Γαλιλαίας τήν τε προσαγορευομένην Ἀκχαβάρων πέτραν καὶ Σὲπφ καὶ Ἰαμνεὶθ καὶ Μηρώ. κατὰ δὲ τὴν Γαυλανιτικὴν Σελεύκειάν τε καὶ Σωγαναίαν καὶ Γάμαλαν ὠχύρωσεν· μόνοις δὲ Σεπφωρίταις ἐφῆκε καθ’ ἑαυτοὺς τεῖχος ἀναδείμασθαι χρημάτων τε εὐπόρους ὁρῶν ὄντας καὶ προθύμους ἐπὶ τὸν πόλεμον δίχα προστάγματος. ὁμοίως δὲ καὶ Γίσχαλα Ἰωάννης ὁ Ληΐου καθ’ ἑαυτὸν ἐτείχιζεν Ἰωσήπου κελεύσαντος· τοῖς δ’ ἄλλοις ἐρύμασιν ἅπασιν αὐτὸς συμπονῶν ἅμα καὶ προστάσσων παρῆν. κατέλεξεν δὲ καὶ δύναμιν ἐκ τῆς Γαλιλαίας ὑπὲρ δέκα μυριάδας νέων ἀνδρῶν, οὓς πάντας ἔκ τε τῶν συλλεγομένων παλαιῶν ὅπλων ἐγκατασκευαζόμενος ὥπλιζεν.", "st": "2.20.6"}, {"sp": "N", "t": "Ἔπειτα συνιδὼν ἀήττητον τὴν Ῥωμαίων ἰσχὺν γεγενημένην εὐπειθείᾳ μάλιστα καὶ μελέτῃ τῶν ὅπλων, τὴν μὲν διδασκαλίαν ἀπέγνω τῇ χρείᾳ διωκομένην, τὸ δ’ εὐπειθὲς ὁρῶν περιγινόμενον ἐκ τοῦ πλήθους τῶν ἡγεμόνων ῥωμαϊκώτερον ἔτεμνεν τὴν στρατιὰν καὶ πλείους καθίστατο ταξιάρχους. στρατιωτῶν τε γὰρ ἀπεδείκνυεν διαφοράς, καὶ τούτους μὲν ὑπέτασσεν δεκαδάρχαις καὶ ἑκατοντάρχαις ἔπειτα χιλιάρχοις, κἀπὶ τούτοις ἡγεμόνας ταγμάτων ἁδροτέρων ἀφηγουμένους. ἐδίδασκεν δὲ σημείων παραδόσεις καὶ σάλπιγγος προκλήσεις τε καὶ ἀνακλήσεις προσβολάς τε κεράτων καὶ περιαγωγάς, καὶ πῶς δεῖ πρὸς μὲν τὸ κάμνον ἐπιστρέφειν ἐκ τοῦ περιόντος, ἐν δὲ τῷ πονοῦντι συμπαθεῖν. ὅσα τε εἰς παράστασιν ψυχῆς ἢ καρτερίαν συνετέλει σώματος ἀφηγεῖτο· μάλιστα δ’ αὐτοὺς ἤσκει πρὸς τὸν πόλεμον παρ’ ἕκαστα τὴν Ῥωμαίων εὐταξίαν διηγούμενος, καὶ ὡς πολεμήσουσιν πρὸς ἄνδρας, οἳ δι’ ἀλκὴν σώματος καὶ ψυχῆς παράστημα πάσης ὀλίγου δεῖν τῆς οἰκουμένης κρατοῦσιν. ἔφη δὲ πεῖραν αὐτῶν λήψεσθαι τῆς κατὰ τὸν πόλεμον πειθαρχίας καὶ πρὸ παρατάξεως, εἰ τῶν συνήθων ἀδικημάτων ἀπόσχοιντο, κλοπῆς τε καὶ λῃστείας καὶ ἁρπαγῆς τοῦ τε ἐξαπατᾶν τὸ ὁμόφυλον τοῦ τε κέρδος οἰκεῖον ἡγεῖσθαι τὴν βλάβην τῶν συνηθεστάτων· διοικεῖσθαι γὰρ κάλλιστα τοὺς πολέμους παρ’ οἷς ἂν ἀγαθὸν τὸ συνειδὸς ἔχωσιν πάντες οἱ στρατευόμενοι, τοὺς δὲ οἴκοθεν φαύλους οὐ μόνον τοῖς ἐπιοῦσιν ἐχθροῖς ἀλλὰ καὶ τῷ θεῷ χρῆσθαι πολεμίῳ.", "st": "2.20.7"}, {"sp": "N", "t": "Πολλὰ τοιαῦτα παραινῶν διετέλει. καὶ τὸ μὲν ἕτοιμον εἰς παράταξιν αὐτῷ συνεκεκρότητο πεζῶν μὲν ἓξ μυριάδες, ἱππεῖς δὲ πεντήκοντα καὶ τριακόσιοι, χωρὶς δὲ τούτων οἷς ἐπεποίθει μάλιστα μισθοφόροι περὶ τετρακισχιλίους καὶ πεντακοσίους· ἐπιλέκτους δὲ περὶ αὑτὸν εἶχεν ἑξακοσίους φύλακας τοῦ σώματος. ἔτρεφον δὲ πλὴν τῶν μισθοφόρων τὴν ἄλλην στρατιὰν αἱ πόλεις ῥᾳδίως· τῶν γὰρ καταλεγέντων ἑκάστη τοὺς ἡμίσεις ἐπὶ τὴν στρατιὰν ἐκπέμπουσα τοὺς λοιποὺς ἐπὶ συμπορισμὸν αὐτοῖς τῶν ἐπιτηδείων κατεῖχον, ὡς τοὺς μὲν εἰς ὅπλα, τοὺς δὲ εἰς ἐργασίαν διῃρῆσθαι, καὶ τοῖς τὰ σῖτα πέμπουσιν ἀντιχορηγεῖσθαι παρὰ τῶν ὁπλιτῶν τὴν ἀσφάλειαν.", "st": "2.20.8"}, {"sp": "N", "t": "Διοικοῦντι δ’ οὕτως τῷ Ἰωσήπῳ τὰ κατὰ τὴν Γαλιλαίαν παρανίσταταί τις ἐπίβουλος ἀνὴρ ἀπὸ Γισχάλων, υἱὸς Ληΐου, Ἰωάννης ὄνομα, πανουργότατος μὲν καὶ δολιώτατος τῶν ἐπισήμων ἐν τοῖσδε τοῖς πονηρεύμασιν ἁπάντων, πένης δὲ τὰ πρῶτα καὶ μέχρι πολλοῦ κώλυμα σχὼν τῆς κακίας τὴν ἀπορίαν, ἕτοιμος μὲν ψεύσασθαι, δεινὸς δ’ ἐπιθεῖναι πίστιν τοῖς ἐψευσμένοις, ἀρετὴν ἡγούμενος τὴν ἀπάτην καὶ ταύτῃ κατὰ τῶν φιλτάτων χρώμενος, ὑποκριτὴς φιλανθρωπίας καὶ δι’ ἐλπίδα κέρδους φονικώτατος, ἀεὶ μὲν ἐπιθυμήσας μεγάλων, τρέφων δὲ τὰς ἐλπίδας ἐκ τῶν ταπεινῶν κακουργημάτων· λῃστὴς γὰρ ἦν μονότροπος, ἔπειτα καὶ συνοδίαν εὗρεν τῆς τόλμης τὸ μὲν πρῶτον ὀλίγην, προκόπτων δ’ ἀεὶ πλείονα. φροντὶς δ’ ἦν αὐτῷ μηδένα προσλαμβάνειν εὐάλωτον, ἀλλὰ τοὺς εὐεξίᾳ σώματος καὶ ψυχῆς παραστήματι καὶ πολέμων ἐμπειρίᾳ διαφέροντας ἐξελέγετο, μέχρι καὶ τετρακοσίων ἀνδρῶν στῖφος συνεκρότησεν, οἳ τὸ πλέον ἐκ τῆς Τυρίων χώρας καὶ τῶν ἐν αὐτῇ κωμῶν φυγάδες ἦσαν· δι’ ὧν πᾶσαν ἐλῄζετο τὴν Γαλιλαίαν καὶ μετεώρους ὄντας ἐπὶ τῷ μέλλοντι πολέμῳ τοὺς πολλοὺς ἐσπάρασσεν.", "st": "2.21.1"}, {"sp": "N", "t": "Ἤδη δ’ αὐτὸν στρατηγιῶντα καὶ μειζόνων ἐφιέμενον ἔνδεια χρημάτων κατεῖχεν. ἐπεὶ δὲ τὸν Ἰώσηπον ὁρῶν αὐτοῦ [σφόδρα] χαίροντα τῷ δραστηρίῳ πείθει πρῶτον μὲν αὐτῷ πιστεῦσαι τὸ τεῖχος ἀνοικοδομῆσαι τῆς πατρίδος, ἐν ᾧ πολλὰ παρὰ τῶν πλουσίων ἐκέρδανεν· ἔπειτα συνθεὶς σκηνὴν πανουργοτάτην, ὡς ἄρα φυλάττοιντο πάντες οἱ κατὰ τὴν Συρίαν Ἰουδαῖοι ἐλαίῳ χρῆσθαι μὴ δι’ ὁμοφύλων ἐγκεχειρισμένῳ, πέμπειν αὐτοῖς ἐπὶ τὴν μεθορίαν ἐξῃτήσατο. συνωνούμενος δὲ τοῦ Τυρίου νομίσματος, ὃ τέσσαρας Ἀττικὰς δύναται, τέσσαρας ἀμφορεῖς, τῆς αὐτῆς ἐπίπρασκεν τιμῆς ἡμιαμφόριον. οὔσης δὲ τῆς Γαλιλαίας ἐλαιοφόρου μάλιστα καὶ τότε εὐφορηκυίας, εἰς σπανίζοντας εἰσπέμπων πολὺ καὶ μόνος ἄπειρόν τι πλῆθος συνῆγεν χρημάτων, οἷς εὐθέως ἐχρῆτο κατὰ τοῦ τὴν ἐργασίαν παρασχόντος. καὶ ὑπολαβών, εἰ καταλύσειεν τὸν Ἰώσηπον, αὐτὸς ἡγήσεσθαι τῆς Γαλιλαίας, τοῖς μὲν ὑφ’ ἑαυτὸν λῃσταῖς προσέταξεν εὐτονώτερον ἐγχειρεῖν ταῖς ἁρπαγαῖς, ὅπως πολλῶν νεωτεριζομένων κατὰ τὴν χώραν ἢ διαχρήσαιτό που τὸν στρατηγὸν ἐκβοηθοῦντα λοχήσας ἢ περιορῶντα τοὺς λῃστὰς διαβάλλοι πρὸς τοὺς ἐπιχωρίους. ἔπειτα διεφήμιζεν πόρρωθεν, ὡς ἄρα προδιδοίη τὰ πράγματα Ῥωμαίοις Ἰώσηπος, καὶ πολλὰ τοιαῦτα πρὸς κατάλυσιν τἀνδρὸς ἐπραγματεύετο.", "st": "2.21.2"}, {"sp": "N", "t": "Καθ’ ὃν καιρὸν ἀπὸ Δεβαρίθθων κώμης νεανίσκοι τινὲς τῶν ἐν τῷ μεγάλῳ πεδίῳ καθεζομένων φυλάκων ἐνεδρεύσαντες Πτολεμαῖον τὸν Ἀγρίππα καὶ Βερνίκης ἐπίτροπον ἀφείλοντο πᾶσαν ὅσην ἦγεν ἀποσκευήν, ἐν ᾗ πολυτελεῖς τε ἐσθῆτες οὐκ ὀλίγαι καὶ πλῆθος ἐκπωμάτων ἀργυρῶν χρυσοῖ τε ἦσαν ἑξακόσιοι. μὴ δυνάμενοι δὲ διαθέσθαι κρύφα τὴν ἁρπαγὴν πάντα πρὸς Ἰώσηπον εἰς Ταριχέας ἐκόμισαν. ὁ δὲ μεμψάμενος αὐτῶν τὸ πρὸς τοὺς βασιλικοὺς βίαιον τίθησιν τὰ κομισθέντα παρὰ τῷ δυνατωτάτῳ τῶν Ταριχεατῶν Ἀνναίῳ, πέμψαι κατὰ καιρὸν τοῖς δεσπόταις προαιρούμενος· ὃ δὴ μέγιστον αὐτῷ κίνδυνον ἐπήγαγεν. οἱ γὰρ ἁρπάσαντες ἅμα μὲν ἐπὶ τῷ μηδεμιᾶς τυχεῖν μερίδος ἐκ τῶν κεκομισμένων ἀγανακτοῦντες, ἅμα δὲ καὶ προσκεψάμενοι τοῦ Ἰωσήπου τὴν διάνοιαν, ὅτι μέλλοι τὸν πόνον αὐτῶν τοῖς βασιλεῦσιν χαρίζεσθαι. νύκτωρ εἰς τὰς κώμας διέδραμον καὶ πᾶσιν ἐνεδείκνυντο τὸν Ἰώσηπον ὡς προδότην· ἐνέπλησαν δὲ καὶ τὰς πλησίον πόλεις ταραχῆς, ὥστε ὑπὸ τὴν ἕω δέκα μυριάδας ὁπλιτῶν ἐπ’ αὐτὸν συνδραμεῖν. καὶ τὸ μὲν πλῆθος ἐν τῷ κατὰ Ταριχέας ἱπποδρόμῳ συνηθροισμένον πολλὰ πρὸς ὀργὴν ἀνεβόα καὶ καταλεύειν οἱ δὲ καίειν τὸν προδότην ἐκεκράγεσαν· παρώξυνεν δὲ τοὺς πολλοὺς ὁ Ἰωάννης καὶ σὺν αὐτῷ Ἰησοῦς τις υἱὸς Σαπφία, τότε ἄρχων τῆς Τιβεριάδος. οἱ μὲν οὖν φίλοι καὶ σωματοφύλακες τοῦ Ἰωσήπου καταπλαγέντες τὴν ὁρμὴν τοῦ πλήθους ἔφυγον πλὴν τεσσάρων πάντες, αὐτὸς δὲ κοιμώμενος ἤδη προσφερομένου τοῦ πυρὸς διανίσταται, καὶ παραινούντων φεύγειν τῶν τεσσάρων, οἳ παρέμειναν, οὔτε πρὸς τὴν καθ’ ἑαυτὸν ἐρημίαν οὔτε πρὸς τὸ πλῆθος τῶν ἐφεστώτων καταπλαγεὶς προπηδᾷ, περιρρηξάμενος μὲν τὴν ἐσθῆτα, καταπασάμενος δὲ τῆς κεφαλῆς κόνιν, ἀποστρέψας δὲ ὀπίσω τὰς χεῖρας καὶ τὸ ἴδιον ξίφος ἐπιδήσας τῷ τένοντι. πρὸς ταῦτα τῶν μὲν οἰκείως ἐχόντων, καὶ μάλιστα τῶν Ταριχεατῶν, οἶκτος ἦν, οἱ δ’ ἀπὸ τῆς χώρας καὶ τῶν πλησίον ὅσοις ἐδόκει φορτικὸς ἐβλασφήμουν, προφέρειν τε τὰ κοινὰ χρήματα θᾶττον ἐκέλευον καὶ τὰς προδοτικὰς συνθήκας ἐξομολογεῖσθαι· προειλήφεσαν γὰρ ἐκ τοῦ σχήματος οὐδὲν αὐτὸν ἀρνήσεσθαι τῶν ὑπονοηθέντων, ἀλλ’ ἐπὶ συγγνώμης πορισμῷ πάντα πεποιηκέναι τὰ πρὸς τὸν ἔλεον. τῷ δ’ ἦν ἡ ταπείνωσις προπαρασκευὴ στρατηγήματος, καὶ τεχνιτεύων τοὺς ἀγανακτοῦντας κατ’ αὐτοῦ κατ’ ἀλλήλων στασιάσαι, ἐφ’ οἷς ὠργίζοντο πάνθ’ ὁμολογήσων, ἔπειτα δοθὲν αὐτῷ λέγειν, ἐγὼ ταῦτα, ἔφη, τὰ χρήματα οὔτε ἀναπέμπειν Ἀγρίππᾳ προῃρούμην οὔτε κερδαίνειν αὐτός· μὴ γὰρ ἡγησαίμην ποτὲ ἢ φίλον τὸν ὑμῖν διάφορον ἢ κέρδος τὸ φέρον τῷ κοινῷ βλάβην. ὁρῶν δέ, ὦ Ταριχεᾶται, μάλιστα τὴν ὑμετέραν πόλιν ἀσφαλείας δεομένην καὶ πρὸς κατασκευὴν τείχους χρῄζουσαν ἀργυρίου, δεδοικὼς δὲ τὸν Τιβεριέων δῆμον καὶ τὰς ἄλλας πόλεις ἐφεδρευούσας τοῖς ἡρπαγμένοις, κατασχεῖν ἡσυχῆ τὰ χρήματα προειλόμην, ἵνα ὑμῖν περιβάλωμαι τεῖχος. εἰ μὴ δοκεῖ, προφέρω τὰ κεκομισμένα καὶ παρέχω διαρπάζειν· εἰ μὴ καλῶς ὑμῖν ἐβουλευσάμην, κολάζετε τὸν εὐεργέτην.", "st": "2.21.3"}, {"sp": "N", "t": "Ἐπὶ τούτοις οἱ Ταριχεῶται μὲν αὐτὸν ἀνευφήμουν, οἱ δ’ ἀπὸ τῆς Τιβεριάδος σὺν τοῖς ἄλλοις ἐκάκιζον καὶ διηπείλουν· καταλιπόντες δ’ ἑκάτεροι τὸν Ἰώσηπον ἀλλήλοις διεφέροντο. κἀκεῖνος θαρρῶν ἤδη τοῖς ᾠκειωμένοις, ἦσαν δὲ εἰς τετρακισμυρίους Ταριχεᾶται, παντὶ τῷ πλήθει παρρησιαστικώτερον ὡμίλει. καὶ πολλὰ τὴν προπέτειαν αὐτῶν κατονειδίσας ἐκ μὲν τῶν παρόντων Ταριχέας ἔφη τειχίσειν, ἀσφαλιεῖσθαι δὲ ὁμοίως καὶ τὰς ἄλλας πόλεις· οὐ γὰρ ἀπορήσειν χρημάτων, ἐὰν ὁμονοῶσιν ἐφ’ οὓς δεῖ πορίζειν καὶ μὴ παροξύνωνται κατὰ τοῦ πορίζοντος.", "st": "2.21.4"}, {"sp": "N", "t": "Ἔνθα δὴ τὸ μὲν ἄλλο πλῆθος τῶν ἠπατημένων ἀνεχώρει καίτοι διωργισμένον, δισχίλιοι δ’ ἐπ’ αὐτὸν ὥρμησαν ἔνοπλοι, καὶ φθάσαντος εἰς τὸ δωμάτιον παρελθεῖν ἀπειλοῦντες ἐφεστήκεσαν. ἐπὶ τούτοις Ἰώσηπος ἀπάτῃ δευτέρᾳ χρῆται· ἀναβὰς γὰρ ἐπὶ τὸ τέγος καὶ τῇ δεξιᾷ καταστείλας τὸν θόρυβον αὐτῶν ἀγνοεῖν ἔφη τίνων ἀξιοῦσιν τυχεῖν· οὐ γὰρ κατακούειν διὰ τὴν τῆς βοῆς σύγχυσιν· ὅσα δ’ ἂν κελεύσωσιν πάντα ποιήσειν, εἰ τοὺς διαλεξομένους ἡσυχῆ πέμψειαν εἴσω πρὸς αὐτόν. ταῦτα ἀκούσαντες οἱ γνώριμοι σὺν τοῖς ἄρχουσιν εἰσῄεσαν. ὁ δὲ σύρας αὐτοὺς εἰς τὸ μυχαίτατον τῆς οἰκίας καὶ τὴν αὔλειον ἀποκλείσας ἐμαστίγωσεν, μέχρι πάντων τὰ σπλάγχνα γυμνῶσαι· περιειστήκει δὲ τέως τὸ πλῆθος δικαιολογεῖσθαι μακρότερα τοὺς εἰσελθόντας οἰόμενον. ὁ δὲ τὰς θύρας ἐξαπίνης ἀνοίξας ᾑμαγμένους ἐξαφῆκεν τοὺς ἄνδρας καὶ τοσαύτην τοῖς ἀπειλοῦσιν ἐνειργάσατο κατάπληξιν, ὥστε ῥίψαντας τὰ ὅπλα φεύγειν.", "st": "2.21.5"}, {"sp": "N", "t": "Πρὸς ταῦτα Ἰωάννης ἐπέτεινεν τὸν φθόνον καὶ δευτέραν ἤρτυσεν ἐπιβουλὴν κατὰ τοῦ Ἰωσήπου. σκηψάμενος δὴ νόσον ἱκέτευσεν δι’ ἐπιστολῆς τὸν Ἰώσηπον ἐπιτρέψαι πρὸς θεραπείαν αὐτῷ χρήσασθαι τοῖς ἐν Τιβεριάδι θερμοῖς ὕδασιν. ὁ δέ, οὔπω γὰρ ὑπώπτευεν τὸν ἐπίβουλον, γράφει τοῖς κατὰ τὴν πόλιν ὑπάρχοις ξενίαν τε καὶ τὰ ἐπιτήδεια Ἰωάννῃ παρασχεῖν. ὧν ἀπολαύσας μετὰ δύο ἡμέρας ἐφ’ ὃ παρῆν διεπράττετο, καὶ τοὺς μὲν ἀπάταις τοὺς δὲ χρήμασι διαφθείρων ἀνέπειθεν ἀποστῆναι Ἰωσήπου. καὶ γνοὺς ταῦτα Σίλας ὁ φυλάσσειν τὴν πόλιν ὑπὸ Ἰωσήπου καθεσταμένος γράφει τὰ περὶ τὴν ἐπιβουλὴν αὐτῷ κατὰ τάχος. ὁ δὲ Ἰώσηπος ὡς ἔλαβεν τὴν ἐπιστολήν, νυκτὸς ὁδεύσας συντόνως ἑωθινὸς παρῆν πρὸς τὴν Τιβεριάδα. καὶ τὸ μὲν ἄλλο πλῆθος αὐτῷ ὑπήντα, Ἰωάννης δὲ καίτοι τὴν παρουσίαν ὑποπτεύσας ἐπ’ αὐτὸν ὅμως πέμψας τινὰ τῶν γνωρίμων ὑπεκρίνατο τὴν ἀσθένειαν καὶ κλινήρης ὢν ὑστερῆσαι τῆς θεραπείας ἔλεγεν. ὡς δὲ εἰς τὸ στάδιον τοὺς Τιβεριεῖς ἀθροίσας ὁ Ἰώσηπος ἐπειρᾶτο διαλέγεσθαι περὶ τῶν ἐπεσταλμένων, ὑποπέμψας ὁπλίτας προσέταξεν αὐτὸν ἀνελεῖν. τούτους τὰ ξίφη γυμνοῦντας ὁ δῆμος προϊδὼν ἀνεβόησεν· πρὸς δὲ τὴν κραυγὴν ὁ Ἰώσηπος ἐπιστραφεὶς καὶ θεασάμενος ἐπὶ τῆς σφαγῆς ἤδη τὸν σίδηρον ἀπεπήδησεν εἰς τὸν αἰγιαλόν· εἱστήκει δὲ δημηγορῶν ἐπὶ βουνοῦ τινος ἑξαπήχους τὸ ὕψος· καὶ παρορμοῦντος ἐπιπηδήσας σκάφους σὺν δυσὶν σωματοφύλαξιν εἰς μέσην τὴν λίμνην ἀνέφυγεν.", "st": "2.21.6"}, {"sp": "N", "t": "Οἱ στρατιῶται δ’ αὐτοῦ ταχέως ἁρπάσαντες τὰ ὅπλα κατὰ τῶν ἐπιβούλων ἐχώρουν. ἔνθα δείσας ὁ Ἰώσηπος, μὴ πολέμου κινηθέντος ἐμφυλίου δι’ ὀλίγων φθόνον παραναλώσῃ τὴν πόλιν, πέμπει τοῖς σφετέροις ἄγγελον μόνης προνοεῖν τῆς ἑαυτῶν ἀσφαλείας, μήτε δὲ κτείνειν τινὰ μήτ’ ἀπελέγχειν τῶν αἰτίων. καὶ οἱ μὲν τῷ παραγγέλματι πεισθέντες ἠρέμησαν, οἱ δ’ ἀνὰ τὴν πέριξ χώραν πυθόμενοι τήν τε ἐπιβουλὴν καὶ τὸν συσκευάσαντα συνηθροίζοντο κατὰ Ἰωάννου· φθάνει δ’ ἐκεῖνος εἰς Γίσχαλα φυγὼν τὴν πατρίδα. συνέρρεον δὲ πρὸς τὸν Ἰώσηπον οἱ Γαλιλαῖοι κατὰ πόλεις, καὶ πολλαὶ μυριάδες ὁπλιτῶν γενόμεναι παρεῖναι σφᾶς ἐπὶ τὸν Ἰωάννην τὸν κοινὸν ἐπίβουλον ἐβόων· συγκαταφλέξειν γὰρ αὐτῷ καὶ τὴν ὑποδεξαμένην πατρίδα. ὁ δὲ ἀποδέχεσθαι μὲν αὐτῶν ἔφασκεν τὴν εὔνοιαν, ἀνεῖργεν δὲ τὴν ὁρμήν, χειρώσασθαι συνέσει τοὺς ἐχθροὺς μᾶλλον ἢ κτεῖναι προαιρούμενος. ἐκλαβὼν δὲ τοὺς ἀφ’ ἑκάστης πόλεως Ἰωάννῃ συναφεστῶτας κατ’ ὄνομα, προθύμως δὲ ἐνεδείκνυντο τοὺς σφετέρους οἱ δημόται, καὶ διὰ κηρύκων ἀπειλήσας ἐντὸς ἡμέρας πέμπτης τῶν μὴ καταλιπόντων Ἰωάννην τάς τε οὐσίας διαρπάσειν καὶ τὰς οἰκίας ἅμα ταῖς γενεαῖς καταφλέξειν, τρισχιλίους μὲν ἀπέστησεν εὐθέως, οἳ παραγενόμενοι τὰ ὅπλα παρὰ τοῖς ποσὶν ἔρριψαν αὐτοῦ, σὺν δὲ τοῖς καταλειφθεῖσιν, ἦσαν δ’ ὅσον εἰς δισχιλίους Σύρων φυγάδες, ἀνέστελλεν Ἰωάννης πάλιν ἐπὶ τὰς λαθραίους ἐπιβουλὰς ἐκ τῶν φανερωτέρων. κρύφα γοῦν ἔπεμπεν ἀγγέλους εἰς Ἱεροσόλυμα διαβάλλων τὸν Ἰώσηπον ἐπὶ τῷ μεγέθει τῆς δυνάμεως, φάσκων ὅσον οὐδέπω τύραννον ἐλεύσεσθαι τῆς μητροπόλεως, εἰ μὴ προκαταληφθείη. ταῦθ’ ὁ μὲν δῆμος προειδὼς οὐ προσεῖχεν, οἱ δυνατοὶ δὲ κατὰ φθόνον καὶ τῶν ἀρχόντων τινὲς λάθρα τῷ Ἰωάννῃ χρήματα πρὸς συλλογὴν μισθοφόρων ἔπεμψαν, ὅπως πολεμῇ πρὸς Ἰώσηπον· ἐψηφίσαντο δὲ καθ’ ἑαυτοὺς καὶ μετακαλεῖν αὐτὸν ἀπὸ τῆς στρατηγίας. οὐ μὴν ἠξίουν ἀποχρήσειν τὸ δόγμα· δισχιλίους δὲ καὶ πεντακοσίους ὁπλίτας καὶ τέσσαρας τῶν ἐπιφανῶν ἄνδρας ἔστειλαν, τόν τε τοῦ Νομικοῦ Ἰώεσδρον καὶ Ἀνανίαν Σαδούκι καὶ Σίμωνα καὶ Ἰούδην Ἰωνάθου, πάντας εἰπεῖν δυνατωτάτους, ἵν’ οὗτοι τὴν πρὸς τὸν Ἰώσηπον εὔνοιαν ἀποστρέψωσιν, κἂν μὲν ἑκὼν παραγένηται, λόγον ὑποσχεῖν ἐᾶν αὐτόν, εἰ δὲ βιάζοιτο μένειν, ὡς πολεμίῳ χρῆσθαι. Ἰωσήπῳ δὲ παραγίνεσθαι μὲν στρατιὰν ἐπεστάλκεσαν οἱ φίλοι, τὴν δ’ αἰτίαν οὐ προεδήλουν ἅτε δὴ λάθρα τῶν ἐχθρῶν βεβουλευμένων. διὸ καὶ μὴ προφυλαξαμένου τέσσαρες πόλεις εὐθέως πρὸς τοὺς διαφόρους ἀπέστησαν ἐλθόντας, Σέπφωρίς τε καὶ Γάβαρα καὶ Γίσχαλα καὶ Τιβεριάς. ταχέως δὲ καὶ ταύτας προσηγάγετο δίχα τῶν ὅπλων καὶ χειρωσάμενος στρατηγήμασιν τοὺς τέσσαρας ἡγεμόνας τῶν τε ὁπλιτῶν τοὺς δυνατωτάτους ἀνέπεμψεν εἰς Ἱεροσόλυμα. πρὸς οὓς ὁ δῆμος οὐ μετρίως ἠγανάκτησεν καὶ σὺν αὐτοῖς ὥρμησεν τοὺς προπέμψαντας ἀνελεῖν, εἰ μὴ φθάσαντες ἀπέδρασαν.", "st": "2.21.7"}, {"sp": "N", "t": "Ἰωάννην δὲ λοιπὸν ἐντὸς τοῦ Γισχάλων τείχους ὁ παρὰ Ἰωσήπου φόβος ἐφρούρει. καὶ μετ’ ὀλίγας ἡμέρας πάλιν ἀπέστη Τιβεριὰς ἐπικαλεσαμένων τῶν ἔνδον Ἀγρίππαν τὸν βασιλέα. καὶ τοῦ μὲν μὴ καταντήσαντος ἐφ’ ἣν συντέτακτο προθεσμίαν, Ῥωμαϊκῶν δ’ ὀλίγων ἱππέων κατ’ ἐκείνην τὴν ἡμέραν παραφανέντων, τὸν Ἰώσηπον ἐξεκήρυσσον. τῶν δ’ ἠγγέλη μὲν εἰς Ταριχέας ἡ ἀπόστασις εὐθέως, ἐκπεπομφὼς δὲ πάντας τοὺς στρατιώτας ἐπὶ σίτου συλλογὴν οὔτε μόνος ἐξορμᾶν ἐπὶ τοὺς ἀποστάντας οὔτε μένειν ὑπέμενεν, δεδοικὼς μὴ βραδύναντος αὐτοῦ φθάσωσιν οἱ βασιλικοὶ παρελθεῖν εἰς τὴν πόλιν· οὐδὲ γὰρ τὴν ἐπιοῦσαν ἡμέραν ἐνεργὸν ἕξειν ἔμελλεν ἐπέχοντος σαββάτου. δόλῳ δὴ περιελθεῖν ἐπενόει τοὺς ἀποστάντας. καὶ τὰς μὲν πύλας τῶν Ταριχεῶν ἀποκλεῖσαι κελεύσας, ὡς μὴ προεξαγγείλειέ τις τὸ σκέμμα τοῖς ἐπιχειρουμένοις, τὰ δ’ ἐπὶ τῆς λίμνης σκάφη πάντα συναθροίσας, τριάκοντα δ’ εὑρέθησαν καὶ τριακόσια, καὶ ναῦται τεσσάρων οὐ πλείους ἦσαν ἐν ἑκάστῳ, διὰ τάχους ἐλαύνει πρὸς τὴν Τιβεριάδα. καὶ τοσοῦτον ἀποσχὼν τῆς πόλεως ἐξ ὅσου συνιδεῖν οὐ ῥᾴδιον ἦν κενὰς τὰς ἁλιάδας μετεώρους σαλεύειν ἐκέλευσεν, αὐτὸς δὲ μόνους ἑπτὰ τῶν σωματοφυλάκων ἀνόπλους ἔχων ἔγγιον ὀφθῆναι προσῄει. θεασάμενοι δ’ αὐτὸν ἀπὸ τῶν τειχῶν ἔτι βλασφημοῦντες οἱ διάφοροι καὶ διὰ τὴν ἔκπληξιν πάντα τὰ σκάφη γέμειν ὁπλιτῶν νομίσαντες ἔρριψαν τὰ ὅπλα καὶ κατασείοντες ἱκετηρίας ἐδέοντο φείσασθαι τῆς πόλεως.", "st": "2.21.8"}, {"sp": "N", "t": "Ὁ δὲ Ἰώσηπος πολλὰ διαπειλησάμενος αὐτοῖς καὶ κατονειδίσας, εἰ πρῶτον μὲν ἀράμενοι τὸν πρὸς Ῥωμαίους πόλεμον εἰς στάσεις ἐμφυλίους προαναλίσκουσιν τὴν ἰσχὺν καὶ τὰ εὐκταιότατα δρῶσιν τοῖς ἐχθροῖς, ἔπειτα τὸν κηδεμόνα τῆς ἀσφαλείας αὐτῶν ἀναρπάσαι σπεύδουσιν καὶ κλείειν οὐκ αἰδοῦνται τὴν πόλιν αὐτῷ τῷ τειχίσαντι, προσδέχεσθαι τοὺς ἀπολογησομένους ἔφασκεν καὶ δι’ ὧν βεβαιώσεται τὴν πόλιν. κατέβαινον δ’ εὐθέως δέκα τῶν Τιβεριέων οἱ δυνατώτατοι· καὶ τοὺς μὲν ἀναλαβὼν μιᾷ τῶν ἁλιάδων ἀνήγαγεν πορρωτέρω, πεντήκοντα δ’ ἑτέρους τῆς βουλῆς τοὺς μάλιστα γνωρίμους κελεύει προελθεῖν ὡς καὶ παρ’ ἐκείνων πίστιν τινὰ βουλόμενος λαβεῖν. ἔπειτα καινοτέρας σκήψεις ἐπινοῶν ἄλλους ἐπ’ ἄλλοις ὡς ἐπὶ συνθήκαις προυκαλεῖτο. τοῖς δὲ κυβερνήταις ἐκέλευσεν τῶν πληρουμένων διὰ τάχους εἰς Ταριχέας ἀναπλεῖν καὶ συγκλείειν τοὺς ἄνδρας εἰς τὸ δεσμωτήριον, μέχρι πᾶσαν μὲν τὴν βουλὴν οὖσαν ἑξακοσίων, περὶ δὲ δισχιλίους τῶν ἀπὸ τοῦ δήμου συλλαβὼν ἀνήγαγεν σκάφεσιν εἰς Ταριχέας.", "st": "2.21.9"}, {"sp": "N", "t": "Βοώντων δὲ τῶν λοιπῶν αἴτιον εἶναι μάλιστα τῆς ἀποστάσεως Κλεῖτόν τινα καὶ παρακαλούντων εἰς ἐκεῖνον ἀπερείδεσθαι τὴν ὀργήν, ὁ Ἰώσηπος ἀνελεῖν μὲν οὐδένα προῄρητο, Ληουὶν δέ τινα τῶν ἑαυτοῦ φυλάκων ἐκέλευσεν ἐξελθεῖν, ἵνα ἀποκόψῃ τὰς χεῖρας τοῦ Κλείτου. δείσας δὲ ἐκεῖνος εἰς ἐχθρῶν στῖφος ἀποβήσεσθαι μόνος οὐκ ἔφη. σχετλιάζοντα δὲ τὸν Ἰώσηπον ἐπὶ τοῦ σκάφους ὁ Κλεῖτος ὁρῶν καὶ προθυμούμενον αὐτὸν ἐπιπηδᾶν ἐπὶ τὴν τιμωρίαν ἱκέτευεν ἀπὸ τῆς ἀκτῆς τὴν ἑτέραν τῶν χειρῶν καταλιπεῖν. κἀκείνου κατανεύσαντος ἐφ’ ᾧ τὴν ἑτέραν αὐτὸς ἀποκόψειεν ἑαυτοῦ, σπασάμενος τῇ δεξιᾷ τὸ ξίφος ἀπέκοψεν τὴν λαιάν· εἰς τοσοῦτον δέους ὑπὸ τοῦ Ἰωσήπου προήχθη. τότε μὲν δὴ κενοῖς σκάφεσιν καὶ δορυφόροις ἑπτὰ τὸν δῆμον αἰχμαλωτισάμενος πάλιν Τιβεριάδα προσηγάγετο, μετὰ δ’ ἡμέρας ὀλίγας Σεπφωρίταις συναποστᾶσαν εὑρὼν ἐπέτρεψεν διαρπάσαι τοῖς στρατιώταις. συναγαγὼν μέντοι πάντα τοῖς δημόταις ἔδωκεν τοῖς τε κατὰ Σέπφωριν ὁμοίως· καὶ γὰρ ἐκείνους χειρωσάμενος νουθετῆσαι διὰ τῆς ἁρπαγῆς ἠθέλησεν, τῇ δ’ ἀποδόσει τῶν χρημάτων πάλιν εἰς εὔνοιαν προσηγάγετο.", "st": "2.21.10"}, {"sp": "N", "t": "Τὰ μὲν οὖν κατὰ Γαλιλαίαν ἐπέπαυτο κινήματα, καὶ τῶν ἐμφυλίων παυσάμενοι θορύβων ἐπὶ τὰς πρὸς Ῥωμαίους ἐτράποντο παρασκευάς· ἐν δὲ τοῖς Ἱεροσολύμοις Ἄνανός τε ὁ ἀρχιερεὺς καὶ τῶν δυνατῶν ὅσοι μὴ τὰ Ῥωμαίων ἐφρόνουν τό τε τεῖχος ἐπεσκεύαζον καὶ πολλὰ τῶν πολεμιστηρίων ὀργάνων. καὶ διὰ πάσης μὲν τῆς πόλεως ἐχαλκεύετο βέλη καὶ πανοπλία, πρὸς ἀτάκτοις δὲ γυμνασίαις τὸ τῶν νέων πλῆθος ἦν, καὶ μεστὰ πάντα θορύβου, δεινὴ δὲ κατήφεια τῶν μετρίων, καὶ πολλοὶ τὰς μελλούσας προορώμενοι συμφορὰς ἀπωλοφύροντο. θειασμοί τε τοῖς εἰρήνην ἀγαπῶσιν δύσφημοι, τοῖς δὲ τὸν πόλεμον ἐξάψασιν ἐσχεδιάζοντο πρὸς ἡδονήν, καὶ τὸ κατάστημα τῆς πόλεως πρὶν ἐπελθεῖν Ῥωμαίους ἦν οἷον ἀπολουμένης. Ἀνάνῳ γε μὴν φροντὶς ἦν κατὰ μικρὸν ἀφισταμένῳ τῶν εἰς τὸν πόλεμον παρασκευῶν κάμψαι πρὸς τὸ συμφέρον τούς τε στασιαστὰς καὶ τὴν τῶν κληθέντων ζηλωτῶν ἀφροσύνην, ἡττήθη δὲ τῆς βίας, κἀν τοῖς ἑξῆς οἵου τέλους ἔτυχεν δηλώσομεν.", "st": "2.22.1"}, {"sp": "N", "t": "Κατὰ δὲ τὴν Ἀκραβετηνὴν τοπαρχίαν ὁ Γιώρα Σίμων πολλοὺς τῶν νεωτεριζόντων συστησάμενος ἐφ’ ἁρπαγὰς ἐτράπετο καὶ οὐ μόνον τὰς οἰκίας ἐσπάρασσεν τῶν πλουσίων, ἀλλὰ καὶ τὰ σώματα κατῃκίζετο δῆλός τε ἦν ἤδη πόρρωθεν ἀρχόμενος τυραννεῖν. πεμφθείσης δ’ ἐπ’ αὐτὸν ὑπ’ Ἀνάνου καὶ τῶν ἀρχόντων στρατιᾶς πρὸς τοὺς ἐν Μασάδᾳ λῃστὰς μεθ’ ὧν εἶχεν κατέφυγεν, κἀκεῖ μέχρι τῆς Ἀνάνου καὶ τῆς τῶν ἄλλων ἐχθρῶν ἀναιρέσεως μένων συνελῄζετο τὴν Ἰδουμαίαν· ὥστε τοὺς ἄρχοντας τοῦ ἔθνους διὰ τὸ πλῆθος τῶν φονευομένων καὶ τὰς συνεχεῖς ἁρπαγὰς στρατιὰν ἀθροίσαντας ἐμφρούρους τὰς κώμας ἔχειν. καὶ τὰ μὲν κατὰ τὴν Ἰδουμαίαν ἐν τούτοις ἦν.", "st": "2.22.2"}], []);})();
